function opsPct(load,cap){return cap>0?100*Number(load||0)/cap:0}
function opsUtilCell(load,cap){const u=opsPct(load,cap);return `<div class="ops-util-cell"><div><strong>${Number(load).toFixed(1)} h</strong><span>/ ${Number(cap).toFixed(1)} h</span><b class="${u>100?'bad-text':u>85?'warn-text':'good-text'}">${u.toFixed(0)}%</b></div><div class="capacity-track"><span style="width:${Math.min(100,u).toFixed(1)}%"></span></div></div>`}
