function renderRouteCards(route){if(!route||!route.steps.length)return '<div class="empty">No route defined. Insert a standard process or start controlled process development.</div>';let html='';for(let i=0;i<route.steps.length;){const s=route.steps[i];if(s.parallelGroup){const group=[];let j=i;while(j<route.steps.length&&route.steps[j].parallelGroup===s.parallelGroup){group.push([route.steps[j],j]);j++}html+=`<div class="merge-node" title="Split into parallel controlled branches">⇉</div><div class="parallel-block">${group.map(([x,idx])=>processCard(x,idx)).join('')}</div><div class="merge-node" title="Merge after parallel branches">⇥</div>`;i=j;if(i<route.steps.length)html+=`<div class="flow-arrow">→</div>`;continue}html+=processCard(s,i);i++;if(i<route.steps.length)html+=`<div class="flow-arrow">→</div>`}if(route.reworkLoops?.length)html+=`<div class="process-card"><div class="step">Controlled loop</div><h3>↺ Rework / reinspection</h3><div class="meta">${route.reworkLoops.map(l=>`${esc(l.reason)} · ${esc(l.status)}`).join('<br>')}</div></div>`;return html}
