function workspaceVerify(r){const profile=P.ensureAssuranceProfile(r),all=App.state.measurements.filter(m=>m.requestId===r.id),endMs=all.filter(m=>measurementKind(r,m)!=='control-plan'),holds=App.state.deviations.filter(d=>d.requestId===r.id&&d.releaseHold&&d.status!=='CLOSED'),needs=(r.characterisation||[]).length>0,ready=(!needs||endMs.length>0)&&!holds.length,released=['RELEASED','DELIVERED','CLOSED'].includes(r.status);const finish=profile.formalLevel<2&&ready&&!released&&(can('release:review')||can('release:approve')||can('triage')||currentRole()==='administrator')?`<div class="card"><div class="section-title-row"><div><span class="eyebrow">ENGINEERING COMPLETION</span><h2>Close the build execution loop</h2><div class="subtle">This is not a customer/production release. It records that the engineering build and requested end-characterisation are complete and can be handed back to Engineering.</div></div>${btn('Complete engineering build',`data-complete-engineering="${r.id}"`,'button primary')}</div></div>`:'';return `<div class="section-stack">${workspaceCharacterisation(r)}${workspaceQuality(r)}${finish}</div>`}
function workspaceQuality(r){const ds=App.state.deviations.filter(d=>d.requestId===r.id);return `<div class="card"><div class="section-title-row"><div><h2>Quality / deviation / rework</h2><div class="subtle">Issues remain connected to build, serial, step and measurement.</div></div>${can('quality:disposition')?btn('+ New issue','data-new-deviation','button small primary'):''}</div>${ds.length?ds.map(d=>`<div class="callout ${d.releaseHold?'bad':'warn'}" style="margin-bottom:10px"><h3>${esc(d.id)} · ${esc(d.type)} · ${esc(d.status)}</h3><p><strong>Sample:</strong> ${esc(sampleDisplayFromRef(r.id,d.serial))} · <strong>Step:</strong> ${esc(d.step)}</p><p style="margin-top:6px"><strong>Detected:</strong> ${esc(d.measurement)}</p><p style="margin-top:6px"><strong>Contain:</strong> ${esc(d.containment)}</p><p style="margin-top:6px"><strong>Disposition:</strong> ${esc(d.disposition)}</p><p style="margin-top:6px"><strong>Release hold:</strong> ${d.releaseHold?'YES':'No'}</p>${d.status!=='CLOSED'&&can('quality:disposition')?`<div style="margin-top:10px">${btn('Open disposition →',`data-disposition="${d.id}"`,'button small primary')}</div>`:''}</div>`).join(''):'<div class="empty">No quality issues linked to this request.</div>'}</div>`}
function roleIdForLabel(label){return P.ROLES.find(x=>x.label===label)?.id||({'Process Engineer':'process_engineer','Quality Engineer':'quality','Product Safety Representative':'product_safety','Lab Manager':'lab_manager','Approver / Reviewer':'approver'}[label])}
function canApproveRecord(a){const required=roleIdForLabel(a.role);return currentRole()==='administrator'||currentRole()===required||(currentRole()==='approver'&&!required)}
function controlPlanApprovalState(cp){
 if(!cp)return {canApprove:false,reason:'Control Plan not found.'};
 if(cp.status==='Approved')return {canApprove:false,approved:true,reason:`Approved by ${cp.approvedBy||'authorised reviewer'}.`};
 const r=cp.buildSpecific?requestById(cp.buildRequestId):null;
 if(cp.buildSpecific&&r&&!P.buildChangeApprovalsComplete(App.state,r,'Control Plan'))return {canApprove:false,reason:'Complete the build-specific Process Engineering / Quality review first.',stage:'delta'};
 const invalid=(cp.characteristics||[]).filter(c=>c.classification&&!P.controlCharacteristicReady(c));
 if(invalid.length)return {canApprove:false,reason:`Complete the controlled definition for ${invalid.map(c=>c.characteristic||c.id).join(', ')} first.`,stage:'definition',invalidCharacteristicIds:invalid.map(c=>c.id)};
 if(cp.status!=='Review requested')return {canApprove:false,reason:'Definition is complete. The Control Plan author must explicitly submit this revision for independent review before it can be approved.',stage:'submit-review'};
 const authorised=can('controlplan:approve')||currentRole()==='administrator',selfBlocked=!!(App.state.settings?.separationOfDuties&&cp.owner===App.state.identity.name),candidates=(App.state.users||[]).filter(u=>u.name!==cp.owner&&P.can(u.role,'controlplan:approve')),preferred=candidates.find(u=>u.role==='quality')||candidates.find(u=>u.role==='approver')||candidates[0];
 if(selfBlocked)return {canApprove:false,selfBlocked:true,reason:'Separation of duties prevents the Control Plan owner/author from formally approving the same revision.',switchRole:preferred?.role||'approver',switchName:preferred?.name||'independent Approver / Reviewer'};
 if(!authorised)return {canApprove:false,reason:'Formal Control Plan approval requires an authorised Quality Engineer or Approver / Reviewer.',switchRole:preferred?.role||'approver',switchName:preferred?.name||'authorised approver'};
 return {canApprove:true,reason:'Formal Control Plan approval is ready.',approver:App.state.identity.name};
}
function workspaceApprovals(r,controlOnly=false){P.ensureApprovalRecords(App.state,r);let a=App.state.approvals.filter(x=>x.requestId===r.id);a=controlOnly?a.filter(x=>x.type==='Product Safety'):a.filter(x=>x.stage==='release'||(!x.stage&&x.type!=='Product Safety'&&x.type!=='Build Report Approval'));const releaseAction=!controlOnly&&(can('release:review')||can('release:approve'))&&['QUALITY REVIEW','ENGINEERING REVIEW','RELEASE APPROVAL','BUILD READINESS REVIEW','READY TO BUILD'].includes(r.status)?btn('Run final release check',`data-release-request="${r.id}"`,'button primary'):'';return `<div class="card"><div class="section-title-row"><div><span class="eyebrow">${controlOnly?'SPECIAL / SAFETY APPROVALS':'RELEASE APPROVALS'}</span><h2>${controlOnly?'Applicable controlled approvals':'Required release sign-offs'}</h2></div><div>${releaseAction}</div></div>${a.length?a.map(x=>`<div class="action-item"><div class="action-stripe ${x.status==='Approved'?'good':'warn'}"></div><div><h3>${esc(x.type)}</h3><div class="subtle">Required role: ${esc(x.role)} · Assigned: ${esc(x.person)}</div><div class="action-meta"><span>${x.timestamp?P.formatDateTime(x.timestamp):'Pending'}</span><span>${esc(x.comment||'')}</span></div></div><div>${x.status==='Pending'&&canApproveRecord(x)?btn('Approve',`data-approve-record="${x.id}"`,'button small primary'):x.status==='Pending'&&currentRole()!=='administrator'?btn(`Switch to ${x.person} →`,`data-switch-role="${roleIdForLabel(x.role)}"`,'button small secondary'):status(x.status)}</div></div>`).join(''):`<div class="callout"><h3>${controlOnly?'No special approval required':'No additional release approval configured'}</h3><p>${controlOnly?'This request is not configured for a separate product-safety/readiness approval.':'Release will still enforce Control Plan approval, quality disposition and release-hold rules.'}</p></div>`}</div>`}
function workspaceDelivery(r){const ss=App.state.serials.filter(s=>s.requestId===r.id&&s.releaseState==='Released');return `<div class="card"><h2>Delivery / handover</h2>${r.status==='RELEASED'||r.status==='DELIVERED'||r.status==='CLOSED'?`<div class="callout"><h3>${r.status==='RELEASED'?'READY FOR COLLECTION / DELIVERY':'Delivered / acknowledged'}</h3><p>${ss.length} released serial(s) are available for the controlled handover package.</p></div><div style="height:12px"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Serial</th><th>Recipient</th><th>Date</th><th>Reference</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${esc(s.serial)}</td><td>${esc(s.delivery?.recipient||r.deliveryLocation)}</td><td>${P.formatDate(s.delivery?.date||'')}</td><td>${esc(s.delivery?.reference||'Pending')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Delivery becomes available after formal release approval.</div>'}</div>`}
function workspaceCost(r){const c=new P.CostService().estimate(App.state,r.id);r.costEstimate=Number(c.total.toFixed(2));const rows=[['Materials',c.material],['Labour',c.labour],['Equipment',c.equipment],['Process charges',c.process],['Standard tests',c.tests],['Consumables',c.consumables],['Process / test development',c.development],['External services',c.external],['Contingency',c.contingency]];return `<div class="card"><div class="section-title-row"><div><h2>Prototype cost</h2><div class="subtle">Resource plan + BOM + optional consumables + controlled finance rates.</div></div><div class="route-toolbar">${btn(r.consumablesEnabled?'Consumables on':'Consumables optional',`data-configure-consumables="${r.id}"`,'button small secondary')}${btn('Cost master →','data-nav="process-library"','button small secondary')}</div></div><div class="grid cols-3">${metric('Estimate',P.currency(c.total))+metric('Consumables',P.currency(c.consumables),r.consumablesEnabled?'BOM + build + process/test':'Only process/test defaults')+metric('Actual',r.costActual?P.currency(r.costActual):'Open')}</div><div style="height:12px"></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Category</th><th>Estimate</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x[0])}</td><td>${P.currency(x[1])}</td></tr>`).join('')}</tbody></table></div>${c.consumableLines?.length?`<details class="planning-details"><summary>Consumable detail · ${c.consumableLines.length} line(s)</summary><div class="table-wrap"><table class="data-table"><thead><tr><th>Source</th><th>Consumable</th><th>Qty</th><th>Cost</th></tr></thead><tbody>${c.consumableLines.map(x=>`<tr><td>${esc(x.source)}</td><td>${esc(x.description)}</td><td>${Number(x.qty).toFixed(2)} ${esc(x.unit)}</td><td>${P.currency(x.cost)}</td></tr>`).join('')}</tbody></table></div></details>`:''}</div>`}
function configureConsumablesModal(requestId){const r=requestById(requestId),product=App.state.products.find(p=>p.id===r.productId),bom=(product?.bom||[]).filter(x=>String(x.kind||'component').toLowerCase()==='consumable'),existing=r.buildConsumables||[],byBom=new Map(existing.filter(x=>x.bomItemId).map(x=>[x.bomItemId,x]));let draft=[...bom.map(x=>({...P.deepClone(x),id:byBom.get(x.id)?.id||P.uid('CONS'),bomItemId:x.id,description:byBom.get(x.id)?.description||x.description,qty:byBom.get(x.id)?.qty??x.qtyPerUnit,basis:byBom.get(x.id)?.basis||x.basis||'unit',unitCost:byBom.get(x.id)?.unitCost??x.unitCost,wastePct:byBom.get(x.id)?.wastePct??x.wastePct})),...existing.filter(x=>!x.bomItemId).map(P.deepClone)];const redraw=()=>{const body=$('#consumableRows');if(!body)return;body.innerHTML=draft.map((x,i)=>`<tr><td><strong>${esc(x.bomItemId?'BOM':'Build')}</strong></td><td><input data-cons-desc="${i}" value="${esc(x.description||'')}"></td><td><input data-cons-qty="${i}" type="number" step="any" min="0" value="${Number(x.qty??x.qtyPerUnit??0)}"></td><td><select data-cons-basis="${i}"><option value="unit" ${x.basis==='unit'?'selected':''}>per unit</option><option value="build" ${x.basis==='build'?'selected':''}>per build</option></select></td><td><input data-cons-unit="${i}" value="${esc(x.unit||'pcs')}"></td><td><input data-cons-cost="${i}" type="number" step="any" min="0" value="${Number(x.unitCost||0)}"></td><td><input data-cons-waste="${i}" type="number" step="any" min="0" value="${Number(x.wastePct||0)}"></td><td>${x.bomItemId?'Inherited':btn('Remove',`data-remove-cons="${i}"`,'button tiny danger')}</td></tr>`).join('');$$('[data-remove-cons]').forEach(el=>el.onclick=()=>{collect();draft.splice(Number(el.dataset.removeCons),1);redraw()})};const collect=()=>{draft.forEach((x,i)=>{const q=$(`[data-cons-qty="${i}"]`);if(!q)return;x.description=$(`[data-cons-desc="${i}"]`).value.trim();x.qty=Number(q.value||0);x.basis=$(`[data-cons-basis="${i}"]`).value;x.unit=$(`[data-cons-unit="${i}"]`).value.trim()||'pcs';x.unitCost=Number($(`[data-cons-cost="${i}"]`).value||0);x.wastePct=Number($(`[data-cons-waste="${i}"]`).value||0)})};openModal('Consumables & build costing',`<div class="callout"><h3>Optional by design</h3><p>Enable only when useful. Product-BOM consumables are inherited per unit; add one-off build consumables separately. Nothing here is required to release a build.</p></div><label class="plan-switch" style="margin:12px 0"><input id="consEnabled" type="checkbox" ${r.consumablesEnabled?'checked':''}><span>Track BOM/build consumables and include their cost</span></label><div class="table-wrap"><table class="data-table"><thead><tr><th>Source</th><th>Consumable</th><th>Qty</th><th>Basis</th><th>Unit</th><th>€/unit</th><th>Waste %</th><th></th></tr></thead><tbody id="consumableRows"></tbody></table></div><div style="margin-top:10px">${btn('+ Build consumable','data-add-consumable','button small secondary')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save consumables','data-save-consumables','button primary')}`,true);setTimeout(()=>{redraw();$('[data-add-consumable]').onclick=()=>{collect();draft.push({id:P.uid('CONS'),description:'',qty:1,basis:'build',unit:'pcs',unitCost:0,wastePct:0});redraw()};$('[data-save-consumables]').onclick=async()=>{collect();r.consumablesEnabled=$('#consEnabled').checked;r.buildConsumables=draft.map(x=>({id:x.id||P.uid('CONS'),...(x.bomItemId?{bomItemId:x.bomItemId}:{}),description:x.description,qty:x.qty,basis:x.basis,unit:x.unit,unitCost:x.unitCost,wastePct:x.wastePct}));const c=new P.CostService().estimate(App.state,r.id);r.costEstimate=Number(c.total.toFixed(2));P.audit(App.state,'Consumable costing updated','Request',r.id,'Previous consumable plan',`${r.buildConsumables.length} line(s)`,r.consumablesEnabled?'Enabled':'Disabled');await persist();closeModal();render();toast('Consumable plan and cost roll-up updated.')}},0)}
function planWeekStart(date=new Date()){const d=new Date(date);d.setHours(0,0,0,0);const day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d}
function planAddDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function planningSituationEvents(){return (App.state.planningEvents||[]).filter(x=>x.active!==false).map(x=>({...x,kind:'situation',requestId:null,stepName:x.title||x.type,durationHours:Math.max(.25,(new Date(x.end)-new Date(x.start))/3600000)}))}
function planningSituationLabel(ev){const target=ev.scope==='staff'?App.state.staff.find(x=>x.id===ev.staffId)?.name:ev.scope==='equipment'?App.state.equipment.find(x=>x.id===ev.equipmentId)?.name:'Whole lab';return `${ev.type} · ${target||'Resource'}`}
function planningSituationReasonCategory(ev){if(!ev)return 'Other';if(/vacation|absence|leave|sick/i.test(ev.type))return 'Vacation / staff absence';if(/outage|equipment|shutdown/i.test(ev.type))return 'Equipment outage';if(/closure|lab/i.test(ev.type))return 'Lab closure / capacity loss';return 'Other capacity constraint'}
function planningSituationBookingEnd(b){return b?.end||planningAddWorkHoursV1064(new Date(b?.start),Number(b?.durationHours||1)).toISOString()}
function planningSituationBlocksBooking(ev,b,state=App.state){if(!ev||ev.active===false||!b?.start||!ev.start||!ev.end)return false;const end=planningSituationBookingEnd(b),over=new Date(b.start)<new Date(ev.end)&&new Date(ev.start)<new Date(end);if(!over)return false;const bookingSite=b.siteId||(state.requests||[]).find(r=>r.id===b.requestId)?.executionSiteId||(state.equipment||[]).find(e=>e.id===b.equipmentId)?.siteId||(state.staff||[]).find(st=>st.id===b.staffId)?.siteId||state.settings?.activeLabId||state.settings?.primaryLabId;return ev.scope==='lab'?(!ev.siteId||!bookingSite||ev.siteId===bookingSite):ev.scope==='equipment'?!!ev.equipmentId&&ev.equipmentId===b.equipmentId:ev.scope==='staff'?!!ev.staffId&&ev.staffId===b.staffId:false}
function planningSituationConstraintKey(ev){if(!ev)return '';const site=ev.siteId||App.state?.settings?.activeLabId||App.state?.settings?.primaryLabId||'';return `${ev.scope||''}|${site}|${ev.scope==='staff'?ev.staffId||'':ev.scope==='equipment'?ev.equipmentId||'':''}`}
function planningSituationConstraintEquivalent(a,b){return !!a&&!!b&&a.active!==false&&b.active!==false&&planningSituationConstraintKey(a)===planningSituationConstraintKey(b)&&new Date(a.start).getTime()===new Date(b.start).getTime()&&new Date(a.end).getTime()===new Date(b.end).getTime()}
function planningSituationIsRelaxation(existing,draft){if(!existing||existing.active===false||!draft)return false;if(draft.active===false)return true;if(planningSituationConstraintKey(existing)!==planningSituationConstraintKey(draft))return false;const os=+new Date(existing.start),oe=+new Date(existing.end),ns=+new Date(draft.start),ne=+new Date(draft.end);return [os,oe,ns,ne].every(Number.isFinite)&&ns>=os&&ne<=oe&&(ns>os||ne<oe)}
function planningSituationReleasedWork(existing,draft,state=App.state){const open=new Set((state.requests||[]).filter(r=>!['DELIVERED','CLOSED','RELEASED'].includes(r.status)).map(r=>r.id)),rows=[];for(const b of state.bookings||[]){if(!open.has(b.requestId)||v1080BookingIsHistorical(b))continue;if(planningSituationBlocksBooking(existing,b,state)&&!planningSituationBlocksBooking(draft,b,state))rows.push(b)}return rows}
function planningSituationChangeLabel(existing,draft){if(draft?.active===false)return 'revoked';if(planningSituationIsRelaxation(existing,draft))return 'relaxed';return 'updated'}
async function applyPlanningSituationMetadataEdit(existing,draft){const target=(App.state.planningEvents||[]).find(x=>x.id===existing.id);if(!target)return;const before=P.deepClone(target);Object.assign(target,P.deepClone(draft));P.audit(App.state,'Planning situation details updated','Planning Situation',target.id,planningSituationLabel(before),planningSituationLabel(target),'Constraint footprint unchanged; no portfolio replan required.');await persist();closeModal();render();toast('Planning situation details updated. Existing schedule was not changed.')}
function planningSituationRelaxationModal(existing,draft,opts={}){const released=planningSituationReleasedWork(existing,draft),builds=new Set(released.map(x=>x.requestId)),action=planningSituationChangeLabel(existing,draft),isRevoke=action==='revoked',verb=isRevoke?'Revoke':'Apply relaxed constraint';const eventName=planningSituationLabel(existing);openModal(isRevoke?'Revoke planning situation?':'Relax planning situation?',`<div class="resolution-focus"><span class="eyebrow">CAPACITY RELEASE</span><h2>${isRevoke?'Remove the constraint without blocking on the old conflict':'Release capacity without forcing a portfolio replan'}</h2><p>${esc(eventName)} will be ${action}. Because this only releases capacity, unrelated planning blockers cannot stop the change.</p></div><div class="grid cols-3" style="margin-top:12px"><div class="mini-kpi"><span>Bookings gaining capacity</span><strong>${released.length}</strong></div><div class="mini-kpi"><span>Builds potentially earlier</span><strong>${builds.size}</strong></div><div class="mini-kpi"><span>Existing accepted schedule</span><strong>Protected</strong></div></div><div class="callout info" style="margin-top:12px"><h3>No accepted booking is moved automatically</h3><p>${isRevoke?'The planning event is revoked immediately when you confirm.':'The reduced constraint is applied immediately when you confirm.'} You may keep the current schedule, or ask LabOS to preview how the newly released capacity could improve it. Rejecting that optimization later does <strong>not</strong> restore the old constraint.</p></div><details class="fold compact"><summary>What happens to previous replanning?</summary><p>Previously accepted movements remain where they are. Historical reason codes and commitment decisions are retained. Revoke is therefore different from Undo: it removes the constraint from the current plan; it does not restore an old planning snapshot.</p></details>`,`${btn('Cancel','data-modal-close','button')}${btn(`${verb} only`,'data-apply-situation-relaxation="keep"','button secondary')}${btn(`${verb} & preview optimization`,'data-apply-situation-relaxation="optimize"','button primary')}`,true);setTimeout(()=>{$$('[data-apply-situation-relaxation]').forEach(b=>b.onclick=()=>applyPlanningSituationRelaxation(existing,draft,{...opts,previewOptimize:b.dataset.applySituationRelaxation==='optimize'}))},0)}
async function applyPlanningSituationRelaxation(existing,draft,opts={}){const target=(App.state.planningEvents||[]).find(x=>x.id===existing.id);if(!target)return;const before=P.deepClone(target),action=planningSituationChangeLabel(before,draft),released=planningSituationReleasedWork(before,draft);Object.assign(target,P.deepClone(draft));if(action==='revoked'){target.active=false;target.revokedAt=target.revokedAt||P.now();target.revokedBy=App.state.identity?.name||target.owner||'Unknown';target.removedAt=target.removedAt||target.revokedAt}else{delete target.revokedAt;delete target.revokedBy;delete target.removedAt}App.pendingPlanningSituationResolution=null;P.audit(App.state,action==='revoked'?'Planning situation revoked':'Planning situation relaxed','Planning Situation',target.id,planningSituationLabel(before),action==='revoked'?'Revoked':planningSituationLabel(target),`${released.length} future booking${released.length===1?'':'s'} gained capacity; accepted schedule retained until a separate optimization is accepted.`);await persist();closeModal();render();toast(`${planningSituationLabel(before)} ${action}. Existing accepted schedule retained.`);if(opts.previewOptimize)setTimeout(()=>previewReleasedCapacityOptimization({...P.deepClone(target),planningChangeAction:'capacity-release',previousType:before.type,previousReason:before.reason}),30)}
function planningReleasedCapacityOptimizationBlockedModal(results,contextEvent){const blocked=results.filter(x=>!x.ok),resolvable=new Set(['ZERO_REQUIRED_SKILL','ZERO_EQUIPMENT_CAPABILITY','STAFF_UNAVAILABLE','CAPACITY_UNRESOLVABLE','READINESS_SLOT_UNRESOLVABLE']);openModal('Capacity released · optimization needs attention',`<div class="resolution-focus"><span class="eyebrow">CONSTRAINT CHANGE ALREADY APPLIED</span><h2>${blocked.length} unrelated blocker${blocked.length===1?'':'s'} prevent a complete optimization preview</h2><p>The revoked or relaxed planning situation remains changed. The current accepted schedule is still valid and has not been moved. Resolve these items only if you want a fresh whole-portfolio optimization.</p></div><div class="audit-guided-list">${blocked.map((x,i)=>`<div class="audit-guided-row"><div><strong>${esc(x.requestId)}</strong><small>${esc(x.error||'No feasible controlled plan.')}</small></div>${resolvable.has(x.code)?btn('Resolve →',`data-resolve-release-blocker="${i}"`,'button small primary'):''}</div>`).join('')}</div><div class="callout info"><strong>Important:</strong> closing this window does not reinstate the old planning constraint.</div>`,btn('Close','data-modal-close','button'),true);setTimeout(()=>{$$('[data-resolve-release-blocker]').forEach(b=>b.onclick=()=>{const x=blocked[Number(b.dataset.resolveReleaseBlocker)];if(!x)return;closeModal();planningStructuralBlockerModal(x.requestId,{code:x.code,message:x.error,...(x.details||{})})})},0)}
function previewReleasedCapacityOptimization(contextEvent){const proposed=P.deepClone(App.state),out=portfolioProposalOnState(proposed,contextEvent),closureResidual=v1080LabClosureConflicts(proposed);if(closureResidual.length){for(const c of closureResidual.slice(0,20))out.results.push({requestId:c.requestId,ok:false,error:`${c.stepName} is still planned inside ${c.closureLabel}. This does not undo the capacity release; resolve the remaining closure conflict before whole-portfolio optimization.`,code:'LAB_CLOSURE_RESIDUAL',details:{taskName:c.stepName}})}if(out.results.some(x=>!x.ok)){planningReleasedCapacityOptimizationBlockedModal(out.results,contextEvent);return}showPlanProposal({mode:'portfolio',proposedState:proposed,requestIds:out.ids,results:out.results,contextEvent})}
function planningSituationModal(id=null){
 P.ensureEnterpriseModel(App.state);const ev=id?(App.state.planningEvents||[]).find(x=>x.id===id):null,start=ev?.start?String(ev.start).slice(0,16):new Date(Date.now()+86400000).toISOString().slice(0,16),end=ev?.end?String(ev.end).slice(0,16):new Date(Date.now()+2*86400000).toISOString().slice(0,16),siteId=ev?.siteId||App.state.settings?.activeLabId||App.state.settings?.primaryLabId||null;
 openModal(ev?'Edit planning situation':'Add planning situation',`<div class="resolution-focus"><span class="eyebrow">CAPACITY CHANGE</span><h2>${ev?'Change the constraint and its schedule together':'Preview the constraint and complete replan'}</h2><p>${ev?'Tightening a constraint requires a complete feasible portfolio proposal. Shortening or revoking it releases capacity and is always allowed; existing accepted bookings stay protected unless you separately accept an optimization.':'LabOS will calculate the full portfolio solution first. Nothing changes until you accept it.'}</p></div><div class="form-grid"><div class="field"><label>Situation type</label><select id="sitType">${['Vacation','Staff absence','Equipment outage','Planned equipment shutdown','Lab closure','Other capacity block'].map(x=>`<option ${ev?.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Applies to</label><select id="sitScope"><option value="staff" ${ev?.scope==='staff'?'selected':''}>Person</option><option value="equipment" ${ev?.scope==='equipment'?'selected':''}>Equipment</option><option value="lab" ${ev?.scope==='lab'?'selected':''}>Whole lab</option></select></div><div class="field"><label>Person</label><select id="sitStaff"><option value="">— select —</option>${App.state.staff.map(x=>`<option value="${x.id}" ${ev?.staffId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Equipment</label><select id="sitEquipment"><option value="">— select —</option>${App.state.equipment.map(x=>`<option value="${x.id}" ${ev?.equipmentId===x.id?'selected':''}>${esc(x.id)} · ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Start</label><input id="sitStart" type="datetime-local" value="${esc(start)}"></div><div class="field"><label>End</label><input id="sitEnd" type="datetime-local" value="${esc(end)}"></div><div class="field full"><label>Reason <small>required</small></label><textarea id="sitReason">${esc(ev?.reason||'')}</textarea></div><div class="field"><label>Owner</label><input id="sitOwner" value="${esc(ev?.owner||App.state.identity.name)}"></div><div class="field"><label>Reference / note</label><input id="sitRef" value="${esc(ev?.reference||'')}"></div></div>`,`${ev?btn('Revoke situation','data-revoke-planning-situation','button danger'):''}${btn('Cancel','data-modal-close','button')}${btn(ev?'Review change':'Preview complete solution','data-save-planning-situation','button primary')}`,true);
 setTimeout(()=>{const type=$('#sitType'),scope=$('#sitScope'),sync=()=>{if(/Vacation|Staff absence/.test(type.value))scope.value='staff';else if(/Equipment/.test(type.value))scope.value='equipment';else if(type.value==='Lab closure')scope.value='lab'};type.onchange=sync;sync();const revoke=$('[data-revoke-planning-situation]');if(revoke)revoke.onclick=()=>removePlanningSituation(ev.id);$('[data-save-planning-situation]').onclick=()=>{const sc=scope.value,staffId=$('#sitStaff').value,equipmentId=$('#sitEquipment').value,reason=$('#sitReason').value.trim(),st=$('#sitStart').value,en=$('#sitEnd').value;if(!reason||!st||!en){toast('Start, end and a reason are required.',true);return}if(new Date(en)<=new Date(st)){toast('End must be after start.',true);return}if(sc==='staff'&&!staffId){toast('Select the affected person.',true);return}if(sc==='equipment'&&!equipmentId){toast('Select the affected equipment.',true);return}const draft={id:ev?.id||P.uid('SIT'),createdAt:ev?.createdAt||P.now(),active:true,type:type.value,scope:sc,siteId,staffId:sc==='staff'?staffId:null,equipmentId:sc==='equipment'?equipmentId:null,start:new Date(st).toISOString(),end:new Date(en).toISOString(),reason,owner:$('#sitOwner').value.trim()||App.state.identity.name,reference:$('#sitRef').value.trim(),updatedAt:P.now()};if(ev&&planningSituationConstraintEquivalent(ev,draft)){applyPlanningSituationMetadataEdit(ev,draft);return}if(ev&&planningSituationIsRelaxation(ev,draft)){planningSituationRelaxationModal(ev,draft,{existingId:ev.id});return}previewPlanningSituationChange(draft,{existingId:ev?.id||null})}},0)
}
async function replanAfterPlanningSituation(ev,action='updated'){return previewPlanningSituationChange(P.deepClone(ev),{existingId:ev.id})}
async function removePlanningSituation(id){const ev=(App.state.planningEvents||[]).find(x=>x.id===id);if(!ev||ev.active===false)return;const draft={...P.deepClone(ev),active:false,revokedAt:P.now(),removedAt:P.now(),updatedAt:P.now()};planningSituationRelaxationModal(ev,draft,{existingId:id,remove:true})}
function commitmentHistoryPanel(r){const m=P.commitmentMetrics(r),rows=(r.commitmentHistory||[]).slice().reverse();return `<div class="card commitment-card"><div class="section-title-row"><div><span class="eyebrow">COMMITMENT CONTROL</span><h2>Promise → replans → actual delivery</h2><div class="subtle">The original lab commitment is immutable. Every accepted date movement is reason-coded and retained for KPI analysis.</div></div>${m.replanCount?status(`${m.replanCount} replan${m.replanCount===1?'':'s'}`):status(m.original?'No replans':'Not committed')}</div><div class="grid cols-5"><div class="mini-kpi"><span>Original commitment</span><strong>${P.formatDate(m.original)}</strong></div><div class="mini-kpi"><span>Current commitment</span><strong>${P.formatDate(m.current)}</strong></div><div class="mini-kpi"><span>Net movement</span><strong>${m.original?`${m.netReplanDays>0?'+':''}${m.netReplanDays} d`:'—'}</strong></div><div class="mini-kpi"><span>Replan churn</span><strong>${m.original?`${m.churnDays} d`:'—'}</strong></div><div class="mini-kpi"><span>Actual delivery</span><strong>${P.formatDate(m.actual)}</strong></div></div>${r.pendingReplanContext?`<div class="callout warn" style="margin-top:12px"><h3>Replan decision required</h3><p>Latest forecast ${P.formatDate(r.forecastDate)} differs from committed ${P.formatDate(m.current)}. Suggested reason: <strong>${esc(r.pendingReplanContext.reasonCategory)}</strong> · ${esc(r.pendingReplanContext.reason)}</p></div>`:''}<details class="planning-details" ${m.replanCount?'open':''}><summary>Commitment history (${rows.length})</summary>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>#</th><th>When</th><th>From → to</th><th>Movement</th><th>Reason category</th><th>Reason / actor</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.seq}</td><td>${P.formatDateTime(x.at)}</td><td>${P.formatDate(x.oldDate)} → ${P.formatDate(x.newDate)}</td><td>${x.type==='initial'?'Initial':`${Number(x.deltaDays)>0?'+':''}${Number(x.deltaDays||0)} d`}<br><small>vs original ${Number(x.cumulativeDays)>0?'+':''}${Number(x.cumulativeDays||0)} d</small></td><td>${esc(x.reasonCategory||'—')}</td><td>${esc(x.reason||'—')}<br><small>${esc(x.actor||'—')}</small></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty compact">No commitment history yet.</div>'}</details></div>`}
function planningPotentialEvents(start,end){const out=[];for(const project of App.state.pipelineProjects||[]){let cursor=new Date(`${project.startDate}T09:00:00`);if(cursor>end)continue;const route=P.getDefaultRoute(project.productId)||[];route.forEach((pid,i)=>{const pr=App.state.processes.find(p=>p.id===pid);if(!pr)return;const hours=Math.max(.5,(Number(pr.setupTime||0)+Number(pr.cycleTime||0)*(pr.basis==='Batch'?1:Number(project.quantity||1)))/60),st=new Date(cursor),en=new Date(st.getTime()+hours*3600000);out.push({id:`PIPE-${project.id}-${i}`,kind:'pipeline',pipelineId:project.id,requestId:project.id,stepName:pr.name,start:st.toISOString(),end:en.toISOString(),durationHours:hours,probability:Number(project.probability||0),equipmentCapability:pr.equipmentCapability,skillId:pr.competency,productId:project.productId,projectName:project.name});cursor=new Date(en.getTime()+2*3600000);});}return out}
function assignTracks(events){const ends=[];return events.slice().sort((a,b)=>new Date(a.start)-new Date(b.start)).map(ev=>{const st=+new Date(ev.start);let track=ends.findIndex(x=>x<=st);if(track<0){track=ends.length;ends.push(+new Date(ev.end))}else ends[track]=+new Date(ev.end);return {...ev,track}})}
function bookingDetailTable(bookings){return bookings.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Task</th><th>Start</th><th>Hours</th><th>Equipment</th><th>Person / skill</th><th>Estimate basis</th><th>Status</th></tr></thead><tbody>${bookings.map(x=>`<tr><td>${esc(x.stepName||x.description||'Planned task')}</td><td>${P.formatDateTime(x.start)}</td><td>${Number(x.durationHours||0).toFixed(1)}</td><td>${esc(App.state.equipment.find(e=>e.id===x.equipmentId)?.name||'—')}</td><td>${esc(App.state.staff.find(st=>st.id===x.staffId)?.name||'—')}<br><small>${esc(App.state.competencies?.find(c=>c.id===x.skillId)?.name||x.skillId||'—')}</small></td><td><small>${esc(x.estimateBasis||'Planning standard')}</small></td><td>${status(x.status||'Planned')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No booking detail yet.</div>'}
function planningSwimlane({view='portfolio',requestId=null,weeks=8,includePotential=true}={}){
 weeks=Math.max(2,Math.min(13,Number(weeks||8)));const today=planWeekStart(new Date()),builds=(App.state.bookings||[]).map(x=>({...x,kind:'build'})),care=(App.state.resourceCareBookings||[]).filter(x=>x.status==='Scheduled').map(x=>({...x,kind:'care',stepName:x.type,requestId:x.sourceRequestId||'READINESS',durationHours:(new Date(x.end)-new Date(x.start))/3600000})),potential=includePotential?planningPotentialEvents(today,planAddDays(today,weeks*7)):[],situations=planningSituationEvents(),all=[...builds,...care,...potential,...situations];
 let relevant=all;if(view==='build'&&requestId)relevant=all.filter(x=>x.kind==='situation'||x.requestId===requestId||x.sourceRequestId===requestId);let earliest=relevant.length?new Date(Math.min(...relevant.map(x=>+new Date(x.start)))):today;let start=planWeekStart(earliest<today?earliest:today),days=weeks*7,end=planAddDays(start,days),span=end-start;relevant=relevant.filter(x=>new Date(x.end)>start&&new Date(x.start)<end);
 const lanes=[];const addLane=(id,label,sub='')=>{let l=lanes.find(x=>x.id===id);if(!l){l={id,label,sub,events:[]};lanes.push(l)}return l};
 if(view==='portfolio'){for(const ev of relevant){if(ev.kind==='pipeline'){const p=(App.state.pipelineProjects||[]).find(x=>x.id===ev.pipelineId);addLane(`pipe-${ev.pipelineId}`,`Potential · ${p?.name||ev.pipelineId}`,`${Math.round((p?.probability||0)*100)}% · ${P.currency(p?.estimatedCost||P.pipelineProjectCost(App.state,p||{}))}`).events.push(ev)}else if(ev.kind==='care'){addLane('readiness','Lab readiness','Calibration · maintenance · training').events.push(ev)}else if(ev.kind==='situation'){addLane('situations','Planning situations','Vacations · outages · closures').events.push(ev)}else{const r=requestById(ev.requestId);addLane(ev.requestId,`${ev.requestId} · ${r?.productFamily||''}`,`Due ${P.formatDate(r?.requiredDate)}`).events.push(ev)}}}
 else if(view==='build'){const req=requestById(requestId);for(const ev of relevant){if(ev.kind==='situation'){addLane('situations','Planning situations','Capacity blocks in this horizon').events.push(ev);continue}const id=ev.kind==='care'?`care-${ev.id}`:`task-${ev.stepId||ev.id}`,label=ev.kind==='care'?`${ev.type} readiness`:ev.stepName||'Task';addLane(id,label,ev.kind==='care'?'Auto recovery':`${App.state.equipment.find(e=>e.id===ev.equipmentId)?.name||'No equipment'} · ${App.state.staff.find(st=>st.id===ev.staffId)?.name||'Unassigned'}`).events.push(ev)}if(!lanes.length)addLane('empty',req?`${req.id} · not planned`:'No build selected','Run AUTO-PLAN to create timing')}
 else if(view==='equipment'){for(const e of App.state.equipment||[])addLane(e.id,e.name,P.equipmentPlanningCapability?P.equipmentPlanningCapability(e):e.capability);for(const ev of relevant){if(ev.kind==='pipeline'){const candidates=(App.state.equipment||[]).filter(e=>(P.equipmentPlanningCapability?P.equipmentPlanningCapability(e):e.capability)===ev.equipmentCapability);if(candidates.length){const idx=Math.abs(String(ev.pipelineId).split('').reduce((n,c)=>n+c.charCodeAt(0),0))%candidates.length;addLane(candidates[idx].id,candidates[idx].name,candidates[idx].capability).events.push(ev)}}else if(ev.kind==='situation'){if(ev.scope==='equipment'&&ev.equipmentId){const e=App.state.equipment.find(x=>x.id===ev.equipmentId);addLane(ev.equipmentId,e?.name||ev.equipmentId,e?.capability||'').events.push(ev)}else if(ev.scope==='lab')addLane('lab-situations','Lab-wide situations','All equipment affected').events.push(ev)}else if(ev.equipmentId){const e=App.state.equipment.find(x=>x.id===ev.equipmentId);addLane(ev.equipmentId,e?.name||ev.equipmentId,e?.capability||'').events.push(ev)}}}
 else if(view==='people'){for(const st of App.state.staff||[])addLane(st.id,st.name,roleLabel(st.role));for(const ev of relevant){if(ev.kind==='situation'){if(ev.scope==='staff'&&ev.staffId){const st=App.state.staff.find(x=>x.id===ev.staffId);addLane(ev.staffId,st?.name||ev.staffId,roleLabel(st?.role||'')).events.push(ev)}else if(ev.scope==='lab')addLane('lab-situations','Lab-wide situations','All people affected').events.push(ev)}else if(ev.staffId){const st=App.state.staff.find(x=>x.id===ev.staffId);addLane(ev.staffId,st?.name||ev.staffId,roleLabel(st?.role||'')).events.push(ev)}}}
 const dayHeads=Array.from({length:days},(_,i)=>{const d=planAddDays(start,i),weekend=!v1072WeekendsEnabled()&&[0,6].includes(d.getDay()),isToday=d.toDateString()===new Date().toDateString();return `<div class="swim-day ${weekend?'weekend':''} ${isToday?'today':''}" style="left:${i/days*100}%;width:${100/days}%"><small class="swim-month-v1080">${d.toLocaleDateString(undefined,{month:'short'})}</small><b class="swim-cw-v1080">CW${isoWeekV1080(d)}</b><strong>${d.toLocaleDateString(undefined,{weekday:'short'})}</strong><span>${d.toLocaleDateString(undefined,{day:'numeric'})}</span></div>`}).join('');
 const weekendBands=!v1072WeekendsEnabled()?Array.from({length:days},(_,i)=>{const d=planAddDays(start,i);return [0,6].includes(d.getDay())?`<i class="swim-weekend-band-v1080" aria-hidden="true" style="left:${i/days*100}%;width:${100/days}%"></i>`:''}).join(''):'';
 const laneHtml=lanes.map(lane=>{const evs=assignTracks(lane.events),tracks=Math.max(1,...evs.map(x=>x.track+1)),h=Math.max(54,13+tracks*29),bars=evs.map(ev=>{const st=Math.max(+new Date(ev.start),+start),en=Math.min(+new Date(ev.end),+end),left=(st-start)/span*100,width=Math.max(.18,(en-st)/span*100),cls=ev.kind==='pipeline'?'pipeline':ev.kind==='care'?'care':ev.kind==='situation'?'situation':/conflict|action/i.test(ev.status||'')?'conflict':`series-${Math.abs(String(ev.requestId||'x').split('').reduce((n,c)=>n+c.charCodeAt(0),0))%6}`,label=ev.kind==='pipeline'?`${ev.projectName} · ${Math.round(ev.probability*100)}% · ${P.currency((App.state.pipelineProjects||[]).find(p=>p.id===ev.pipelineId)?.estimatedCost||0)}`:ev.kind==='care'?`${ev.type} · ${ev.targetName||App.state.equipment.find(e=>e.id===ev.equipmentId)?.name||App.state.staff.find(s=>s.id===ev.staffId)?.name||''}`:ev.kind==='situation'?`✕ ${planningSituationLabel(ev)} · ${ev.reason}`:`${ev.requestId} · ${ev.stepName}`;const openAttr=ev.kind==='build'&&ev.requestId?` data-open-request="${esc(ev.requestId)}" data-tab="schedule" data-planning-booking-v1061="${esc(ev.id)}" role="button" tabindex="0" aria-label="Open or move build plan ${esc(ev.requestId)}"`:ev.kind==='pipeline'?` data-pipeline-impact="${esc(ev.pipelineId)}" role="button" tabindex="0"`:'';return `<div class="swim-bar ${cls}${openAttr?' interactive':''}"${openAttr} style="left:${left}%;width:${width}%;top:${7+ev.track*29}px" title="${esc(label)} · ${P.formatDateTime(ev.start)} → ${P.formatDateTime(ev.end)}"><span>${esc(label)}</span></div>`}).join(''),req=view==='portfolio'?requestById(lane.id):null,due=req?.requiredDate?Math.max(0,Math.min(100,(+new Date(`${req.requiredDate}T12:00:00`)-start)/span*100)):null;const laneOpen=req?` data-open-request="${esc(req.id)}" data-tab="schedule" role="button" tabindex="0" aria-label="Open build plan ${esc(req.id)}"`:'';return `<div class="swim-label${laneOpen?' interactive':''}"${laneOpen} style="height:${h}px"><strong>${esc(lane.label)}</strong><span>${esc(lane.sub||'')}</span></div><div class="swim-track" style="height:${h}px">${weekendBands}${due!==null?`<div class="swim-due" style="left:${due}%" title="Required delivery ${esc(req.requiredDate)} · end of planned workday (17:00)"></div>`:''}${bars}</div>`}).join('');
 const timelineWidth=Math.max(900,days*86),boardWidth=190+timelineWidth;return `<div class="swim-scroll"><div class="swim-board" style="grid-template-columns:190px ${timelineWidth}px;min-width:${boardWidth}px"><div class="swim-label swim-head"><strong>${view==='portfolio'?'Build / project':view==='equipment'?'Equipment':view==='people'?'Person':'Task'}</strong><span>${weeks}-week horizon · day scale</span></div><div class="swim-track swim-head-track">${dayHeads}</div>${laneHtml||'<div class="swim-empty">No events in this planning horizon.</div>'}</div></div><div class="swim-legend"><span><i class="legend-build"></i>Committed / provisional build</span><span><i class="legend-care"></i>Calibration / maintenance / training</span><span><i class="legend-situation"></i>Planning situation / unavailable capacity</span>${includePotential?'<span><i class="legend-pipeline"></i>Potential project (probability overlay)</span>':''}<span><i class="legend-due"></i>Required delivery</span></div>`;
}
function renderPlanning(){
 P.ensurePlanningModel(App.state);P.ensureEnterpriseModel(App.state);const b=(App.state.bookings||[]).slice().sort((a,b)=>new Date(a.start)-new Date(b.start)),care=(App.state.resourceCareBookings||[]).filter(x=>x.status==='Scheduled'),situations=(App.state.planningEvents||[]).filter(x=>x.active!==false),open=App.state.requests.filter(r=>!['DELIVERED','CLOSED','RELEASED'].includes(r.status)),view=App.filters.planView||'portfolio',weeks=Number(App.filters.planWeeks||8),includePotential=App.filters.planPotential!==false,selected=App.filters.planBuild||open[0]?.id||null,structuralGaps=open.filter(r=>r.triage?.planQuality==='Structural gap').length,late=open.filter(r=>r.triage?.slackDays<0).length,provisional=open.filter(r=>r.triage?.planQuality&&r.triage.planQuality!=='Best feasible').length,pending=open.filter(r=>r.originalCommitmentDate&&r.currentCommitmentDate&&r.forecastDate&&r.forecastDate!==r.currentCommitmentDate).length;
 const controls=`<div class="planning-controls"><div class="filter-row plan-view-tabs">${[['portfolio','Overall'],['build','Per build'],['equipment','Per equipment'],['people','Per person']].map(([id,l])=>`<button type="button" class="filter-chip ${view===id?'active':''}" data-plan-view="${id}">${l}</button>`).join('')}</div><div class="planning-control-grid">${view==='build'?`<label class="compact-select">Build<select id="planBuild">${open.map(r=>`<option value="${r.id}" ${selected===r.id?'selected':''}>${esc(r.id)} · ${esc(r.productFamily)}</option>`).join('')}</select></label>`:''}<label class="compact-select">Horizon<select id="planWeeks">${[4,8,13].map(n=>`<option value="${n}" ${weeks===n?'selected':''}>${n} weeks</option>`).join('')}</select></label><label class="plan-switch"><input id="planPotential" type="checkbox" ${includePotential?'checked':''}><span>Show potential projects</span></label></div></div>`;
 const situationCards=situations.slice().sort((a,b)=>new Date(a.start)-new Date(b.start)).map(x=>`<div class="situation-row"><span class="situation-x">✕</span><div><strong>${esc(planningSituationLabel(x))}</strong><small>${P.formatDateTime(x.start)} → ${P.formatDateTime(x.end)} · ${esc(x.reason)}</small></div><div class="route-toolbar">${btn('Edit',`data-edit-planning-situation="${x.id}"`,'button tiny secondary')}${btn('Revoke',`data-remove-planning-situation="${x.id}"`,'button tiny danger')}</div></div>`).join('')||'<div class="empty compact">No vacations, outages or lab closures entered.</div>';
 return pageHeader('Visual Resource Planning','Best-feasible scheduling across builds, equipment, certified people and explicit capacity situations. Forecasts can move automatically; committed dates only move through a reasoned replan decision.',can('plan')?`${btn('+ Planning situation','data-new-planning-situation','button secondary')}${btn('+ Potential project','data-new-pipeline','button secondary')}${btn('PREVIEW OPTIMIZED PORTFOLIO','data-plan-portfolio','button primary')}`:'')+`<div class="grid cols-6">${metric('Open builds',open.length)+metric('Build bookings',b.length)+metric('Active situations',situations.length)+(pending?`<button type="button" class="card metric warn metric-action" data-review-commitments><div class="label">Commitment decisions</div><div class="value">${pending}</div><div class="trend warn">${pending} build${pending===1?' has':'s have'} a forecast different from the current commitment · Review →</div></button>`:metric('Commitment decisions',0,'No commitment changes awaiting a decision','good'))+metric('Forecast late',late)+metric('Provisional / recovery',provisional)}</div><div style="height:14px"></div><div class="card planning-visual-main"><div class="section-title-row"><div><span class="eyebrow">SWIMLANE PLANNER</span><h2>${view==='portfolio'?'Overall portfolio':view==='build'?'Build detail':view==='equipment'?'Equipment loading':'People / qualification loading'}</h2><div class="subtle">The date scale is shown once across the top. Red ✕ situation bars remove capacity from AUTO-PLAN. Existing commitments remain visible separately from the latest forecast.</div></div>${status(structuralGaps?'Structural gap':'Optimizer active')}</div>${controls}${planningSwimlane({view,requestId:view==='build'?selected:null,weeks,includePotential})}</div><div style="height:14px"></div><div class="grid cols-2"><div class="card"><div class="section-title-row"><div><span class="eyebrow">CAPACITY SITUATIONS</span><h2>Vacations, outages & closures</h2></div>${can('plan')?btn('+ Add situation','data-new-planning-situation','button small primary'):''}</div><div class="situation-list">${situationCards}</div></div><div class="card"><div class="section-title-row"><h2>Build commitment health</h2><span class="pill">Original promise never overwritten</span></div>${open.map(r=>{const q=r.triage?.planQuality||'Not planned',m=P.commitmentMetrics(r),delta=m.original?m.netReplanDays:null,pendingMove=m.current&&r.forecastDate&&m.current!==r.forecastDate;return `<button type="button" class="planning-build-row ${pendingMove?'replan-pending':''}" data-open-request="${r.id}" data-tab="schedule"><span><strong>${esc(r.id)} · ${esc(r.productFamily)}</strong><small>Original ${P.formatDate(m.original)} · current ${P.formatDate(m.current)} · ${m.replanCount} replan(s)</small></span><span>${r.forecastDate?P.formatDate(r.forecastDate):'Not planned'}<small>${pendingMove?'Replan decision required':delta===null?'Not committed':`${delta>0?'+':''}${delta} d vs original`} · ${esc(q)}</small></span></button>`}).join('')}</div></div>`;
}

function productHistoricalCount(productId){return (App.state.buildHistory||[]).filter(h=>h.productId===productId).length}
function renderProducts(){
 P.ensureEnterpriseModel(App.state);const editable=can('product:manage')||currentRole()==='administrator';
 const cards=App.state.products.map(p=>{const route=(p.defaultRoute||[]).map(id=>App.state.processes.find(x=>x.id===id)?.name||id),bom=p.bom||[],used=App.state.requests.filter(r=>r.productId===p.id).length,hist=productHistoricalCount(p.id);return `<div class="card product-master-card"><div class="section-title-row"><div><span class="pill">${esc(p.id)}</span><h2>${esc(p.family)}</h2><div class="subtle">${esc(p.partNumber)} · Product Rev ${esc(p.revision)} · HW ${esc(p.hw||'—')} · SW ${esc(p.sw||'—')}</div></div>${p.safety?status('Product safety'):status('Standard')}</div><div class="grid cols-3 product-master-kpis"><div><span class="subtle">BOM</span><strong>${bom.length} controlled items</strong></div><div><span class="subtle">Default route</span><strong>${route.length} process steps</strong></div><div><span class="subtle">Learning history</span><strong>${hist} completed builds</strong></div></div><details><summary>Controlled BOM & default route</summary><div class="table-wrap"><table class="data-table"><thead><tr><th>Type</th><th>Part number</th><th>Revision</th><th>Description</th><th>Qty/unit</th><th>€/unit</th><th>Waste</th></tr></thead><tbody>${bom.map(b=>`<tr><td>${String(b.kind||'component').toLowerCase()==='consumable'?'<span class="pill warn">Consumable</span>':'<span class="pill">Component</span>'}</td><td>${esc(b.partNumber)}</td><td>${esc(b.revision)}</td><td>${esc(b.description)}</td><td>${Number(b.qtyPerUnit||1)} ${esc(b.unit||'pcs')}</td><td>${P.currency(b.unitCost||0)}</td><td>${Number(b.wastePct||0)}%</td></tr>`).join('')||'<tr><td colspan="7">No controlled BOM defined.</td></tr>'}</tbody></table></div><div class="route-sequence">${route.map((n,i)=>`<span>${i+1}. ${esc(n)}</span>`).join('')||'<span>No default process route defined.</span>'}</div></details><div class="route-toolbar"><span class="subtle">Used by ${used} request(s). Changes affect new requests; existing controlled requests retain their captured configuration.</span>${editable?btn('Edit product',`data-edit-product="${p.id}"`,'button small secondary'):''}</div></div>`}).join('');
 return pageHeader('Products & BOM','Controlled product master data used by prototype requests, exact material requirements, default process-route proposals and same-product learning.',editable?btn('+ New product','data-new-product','button primary'):'')+`<div class="callout"><h3>Product master governance</h3><p>Engineering Project Lead / Administrator owns product definitions. Editing the product master does not silently rewrite an existing prototype request; new requests inherit the current product revision, BOM and default route.</p></div><div style="height:14px"></div><div class="grid cols-2 product-master-grid">${cards}</div>`;
}
function nextProductId(){let n=1;while(App.state.products.some(p=>p.id===`PRD-${String(n).padStart(3,'0')}`))n++;return `PRD-${String(n).padStart(3,'0')}`}
function productWizard(productId=null){
 const existing=productId?App.state.products.find(p=>p.id===productId):null;if(productId&&!existing){toast('Product not found.',true);return}const draft=P.deepClone(existing||{id:nextProductId(),family:'',category:'Uncategorised',partNumber:'',revision:'A',hw:'HW1',sw:'—',safety:false,bom:[],defaultRoute:[]}),original=P.deepClone(existing),steps=['PRODUCT DEFINITION','CONTROLLED BOM','DEFAULT PROCESS ROUTE','REVIEW & SAVE'];let step=0;
 const collect=()=>{if(step===0){draft.family=$('#pmFamily')?.value.trim()||draft.family;draft.category=$('#pmCategory')?.value.trim()||draft.category||'Uncategorised';draft.partNumber=$('#pmPart')?.value.trim()||draft.partNumber;draft.revision=$('#pmRev')?.value.trim()||draft.revision;draft.hw=$('#pmHw')?.value.trim()||draft.hw;draft.sw=$('#pmSw')?.value.trim()||draft.sw;draft.safety=!!$('#pmSafety')?.checked;}else if(step===1){draft.bom=$$('[data-pm-bom-row]').map((row,i)=>({id:row.dataset.id||`BOM-${draft.id}-${i+1}`,kind:row.querySelector('[data-bom-kind]')?.value||'component',partNumber:row.querySelector('[data-bom-part]')?.value.trim(),description:row.querySelector('[data-bom-desc]')?.value.trim(),revision:row.querySelector('[data-bom-rev]')?.value.trim()||'A',qtyPerUnit:Number(row.querySelector('[data-bom-qty]')?.value||1),unit:row.querySelector('[data-bom-unit]')?.value.trim()||'pcs',unitCost:Number(row.querySelector('[data-bom-cost]')?.value||0),wastePct:Number(row.querySelector('[data-bom-waste]')?.value||0),basis:'unit'})).filter(x=>x.partNumber&&x.description);}else if(step===2){draft.defaultRoute=$$('[data-pm-route-row]').map(row=>row.querySelector('select')?.value).filter(Boolean);}};
 const bomRows=()=>draft.bom.map((b,i)=>`<div class="product-bom-edit-row" data-pm-bom-row data-id="${esc(b.id||'')}"><select data-bom-kind><option value="component" ${String(b.kind||'component').toLowerCase()!=='consumable'?'selected':''}>Component</option><option value="consumable" ${String(b.kind||'component').toLowerCase()==='consumable'?'selected':''}>Consumable</option></select><input data-bom-part placeholder="Part number" value="${esc(b.partNumber||'')}"><input data-bom-desc placeholder="Description" value="${esc(b.description||'')}"><input data-bom-rev placeholder="Rev" value="${esc(b.revision||'A')}"><input data-bom-qty type="number" min="0.001" step="0.001" value="${Number(b.qtyPerUnit||1)}"><input data-bom-unit placeholder="Unit" value="${esc(b.unit||'pcs')}"><input data-bom-cost type="number" min="0" step="any" value="${Number(b.unitCost||0)}"><input data-bom-waste type="number" min="0" step="any" value="${Number(b.wastePct||0)}"><button type="button" class="button tiny danger" data-remove-bom="${i}">×</button></div>`).join('');
 const routeRows=()=>draft.defaultRoute.map((id,i)=>`<div class="product-route-edit-row" data-pm-route-row><span>${i+1}</span><select>${App.state.processes.filter(p=>p.status==='Released'||p.id===id).map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.id)} · ${esc(p.name)} · Rev ${esc(p.revision)}</option>`).join('')}</select><button type="button" class="button tiny" data-route-up="${i}" ${i===0?'disabled':''}>↑</button><button type="button" class="button tiny" data-route-down="${i}" ${i===draft.defaultRoute.length-1?'disabled':''}>↓</button><button type="button" class="button tiny danger" data-route-remove="${i}">×</button></div>`).join('');
 const draw=()=>{let body='';if(step===0)body=`<div class="form-grid"><div class="field"><label>Product ID</label><input value="${esc(draft.id)}" disabled></div><div class="field"><label>Product/device family</label><input id="pmFamily" value="${esc(draft.family)}"></div><div class="field"><label>Product category</label><input id="pmCategory" value="${esc(draft.category||'Uncategorised')}" placeholder="e.g. Pressure sensing, Current sensing, Actuators"></div><div class="field"><label>Part number</label><input id="pmPart" value="${esc(draft.partNumber)}"></div><div class="field"><label>Product revision</label><input id="pmRev" value="${esc(draft.revision)}"></div><div class="field"><label>Hardware revision</label><input id="pmHw" value="${esc(draft.hw||'')}"></div><div class="field"><label>Software revision</label><input id="pmSw" value="${esc(draft.sw||'')}"></div><div class="field full"><label><input id="pmSafety" type="checkbox" style="width:auto;min-height:auto" ${draft.safety?'checked':''}> Product-safety relevant by default</label></div></div>`;else if(step===1)body=`<div class="callout"><h3>Exact material definition</h3><p>Component lines generate controlled material requirements. Consumable lines stay optional and can carry unit cost/waste for build costing.</p></div><div class="product-bom-editor" style="margin-top:12px"><div class="product-bom-edit-head"><span>Type</span><span>Part</span><span>Description</span><span>Rev</span><span>Qty/unit</span><span>Unit</span><span>€/unit</span><span>Waste %</span><span></span></div>${bomRows()}</div><div style="margin-top:10px">${btn('+ Add BOM item','data-add-bom','button secondary')}</div>`;else if(step===2)body=`<div class="callout"><h3>Default route proposal</h3><p>New requests inherit this released-process sequence as a <strong>proposal</strong>. Process Engineering must still assess and confirm the actual route before timing is committed.</p></div><div class="product-route-editor" style="margin-top:12px">${routeRows()}</div><div style="margin-top:10px">${btn('+ Add process step','data-add-route','button secondary')}</div>`;else body=`<div class="grid cols-2"><div class="card"><span class="subtle">Product</span><h3>${esc(draft.family||'—')}</h3><p>${esc(draft.partNumber||'—')} · Rev ${esc(draft.revision||'—')} · ${draft.safety?'Product safety relevant':'Standard'}</p></div><div class="card"><span class="subtle">Controlled definition</span><h3>${draft.bom.length} BOM items · ${draft.defaultRoute.length} route steps</h3><p>Existing requests retain their captured configuration. This master becomes the basis for new requests.</p></div></div><div class="route-sequence" style="margin-top:12px">${draft.defaultRoute.map((id,i)=>`<span>${i+1}. ${esc(App.state.processes.find(p=>p.id===id)?.name||id)}</span>`).join('')}</div>`;
  openModal(`${existing?'Edit':'New'} product · ${steps[step]}`,`<div class="wizard-shell"><div class="wizard-progress">${steps.map((_,i)=>`<div class="wizard-step ${i<step?'done':''} ${i===step?'active':''}"></div>`).join('')}</div>${body}</div>`,`${step?btn('Back','data-pm-back','button'):btn('Cancel','data-modal-close','button')}${step<steps.length-1?btn('Next →','data-pm-next','button primary'):btn(existing?'Save controlled update':'Create product','data-pm-save','button primary')}`,true);
  setTimeout(()=>{const next=$('[data-pm-next]'),back=$('[data-pm-back]'),save=$('[data-pm-save]');if(next)next.onclick=()=>{collect();if(step===0&&(!draft.family||!draft.partNumber||!draft.revision)){toast('Product family, part number and revision are required.',true);return}if(step===1&&!draft.bom.length){toast('Define at least one controlled BOM item.',true);return}if(step===2&&!draft.defaultRoute.length){toast('Define at least one released process in the default route.',true);return}step++;draw()};if(back)back.onclick=()=>{collect();step--;draw()};if(save)save.onclick=async()=>{const duplicate=App.state.products.find(p=>p.id!==draft.id&&p.partNumber===draft.partNumber&&p.revision===draft.revision);if(duplicate){toast(`Part ${draft.partNumber} Rev ${draft.revision} already exists as ${duplicate.id}.`,true);return}draft.revisionHistory=draft.revisionHistory||[];if(existing&&original.revision!==draft.revision)draft.revisionHistory.push({revision:original.revision,replacedAt:P.now(),reason:'Product master updated'});if(existing)Object.assign(existing,draft);else App.state.products.push(draft);P.ensureMaterialModel(App.state);P.audit(App.state,existing?'Product master updated':'Product master created','Product',draft.id,existing?`${original.partNumber} Rev ${original.revision}`:'—',`${draft.partNumber} Rev ${draft.revision}`,`${draft.bom.length} BOM items; ${draft.defaultRoute.length} default route steps`);await persist();closeModal();render();toast(`${draft.family} product master saved.`)};$$('[data-remove-bom]').forEach(el=>el.onclick=()=>{collect();draft.bom.splice(Number(el.dataset.removeBom),1);draw()});const addBom=$('[data-add-bom]');if(addBom)addBom.onclick=()=>{collect();draft.bom.push({id:P.uid('BOM'),kind:'component',partNumber:'',description:'',revision:'A',qtyPerUnit:1,unit:'pcs',unitCost:0,wastePct:0,basis:'unit'});draw()};$$('[data-route-up]').forEach(el=>el.onclick=()=>{collect();const i=Number(el.dataset.routeUp);[draft.defaultRoute[i-1],draft.defaultRoute[i]]=[draft.defaultRoute[i],draft.defaultRoute[i-1]];draw()});$$('[data-route-down]').forEach(el=>el.onclick=()=>{collect();const i=Number(el.dataset.routeDown);[draft.defaultRoute[i+1],draft.defaultRoute[i]]=[draft.defaultRoute[i],draft.defaultRoute[i+1]];draw()});$$('[data-route-remove]').forEach(el=>el.onclick=()=>{collect();draft.defaultRoute.splice(Number(el.dataset.routeRemove),1);draw()});const addRoute=$('[data-add-route]');if(addRoute)addRoute.onclick=()=>{collect();const id=App.state.processes.find(p=>p.status==='Released'&&!draft.defaultRoute.includes(p.id))?.id||App.state.processes.find(p=>p.status==='Released')?.id;if(!id){toast('No released process exists to add.',true);return}draft.defaultRoute.push(id);draw()};},0);
 };
 draw();
}
function pct(n,d){return d>0?Math.max(0,100*Number(n||0)/d):0}
function capacityState(forward){const eq=Object.values(forward.equipment||{}),sk=Object.values(forward.skills||{}),eqCap=eq.reduce((n,s)=>n+Number(s.capacity||0),0),skCap=sk.reduce((n,s)=>n+Number(s.capacity||0),0),eqNow=eq.reduce((n,s)=>n+Number(s.committed?.[0]||0),0),skNow=sk.reduce((n,s)=>n+Number(s.committed?.[0]||0),0),eqPeak=Math.max(0,...eq.flatMap(s=>(s.committed||[]).map((v,i)=>pct(Number(v||0)+Number(s.pipeline?.[i]||0),Number(s.capacity||0))))),skPeak=Math.max(0,...sk.flatMap(s=>(s.committed||[]).map((v,i)=>pct(Number(v||0)+Number(s.pipeline?.[i]||0),Number(s.capacity||0)))));return {eqCap,skCap,eqNow,skNow,eqAvail:Math.max(0,eqCap-eqNow),skAvail:Math.max(0,skCap-skNow),eqUtil:pct(eqNow,eqCap),skUtil:pct(skNow,skCap),eqPeak,skPeak};}
function capacityMetric(label,demand,capacity,unit='h/wk'){const u=pct(demand,capacity);return `<div class="card metric capacity-metric"><div class="label">${esc(label)}</div><div class="value">${u.toFixed(0)}%</div><div class="capacity-track"><span style="width:${Math.min(100,u).toFixed(1)}%"></span></div><div class="trend ${u>100?'bad':u>85?'warn':'good'}">${Number(demand).toFixed(1)} / ${Number(capacity).toFixed(1)} ${esc(unit)} · ${Math.max(0,Number(capacity)-Number(demand)).toFixed(1)} available</div></div>`}
function capacityLoadTable(seriesMap,index=0,includePipeline=false){const rows=Object.values(seriesMap||{}).map(s=>{const committed=Number(s.committed?.[index]||0),pipeline=includePipeline?Number(s.pipeline?.[index]||0):0,demand=committed+pipeline,cap=Number(s.capacity||0),util=pct(demand,cap);return {label:s.label,demand,cap,util}}).sort((a,b)=>b.util-a.util);return `<div class="table-wrap"><table class="data-table capacity-table"><thead><tr><th>Resource</th><th>Demand</th><th>Current available capacity</th><th>Utilization</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.label)}</strong></td><td>${r.demand.toFixed(1)} h/wk</td><td>${r.cap.toFixed(1)} h/wk</td><td><strong class="${r.util>100?'bad-text':r.util>85?'warn-text':'good-text'}">${r.util.toFixed(0)}%</strong><div class="capacity-track small"><span style="width:${Math.min(100,r.util).toFixed(1)}%"></span></div></td></tr>`).join('')||'<tr><td colspan="4">No resource master data.</td></tr>'}</tbody></table></div>`}

function testFamilyName(id){return (App.state.testFamilies||[]).find(x=>x.id===id)?.name||id||'Other'}
function testFamiliesModal(){
 P.ensureEnterpriseModel(App.state);const rows=(App.state.testFamilies||[]).map(x=>`<tr><td><strong>${esc(x.id)}</strong></td><td><input data-tf-name="${x.id}" value="${esc(x.name||'')}"></td><td><input data-tf-desc="${x.id}" value="${esc(x.description||'')}"></td><td>${(App.state.standardTests||[]).filter(t=>t.familyId===x.id).length}</td></tr>`).join('');
 openModal('Configure test families',`<div class="callout"><strong>One controlled family list</strong><p>Use families for navigation, analytics and planning filters. Tests reference the family master; family names are not free text.</p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Family</th><th>Description</th><th>Tests</th></tr></thead><tbody>${rows}</tbody></table></div><details class="fold compact"><summary>+ Add test family</summary><div class="form-grid"><div class="field"><label>Family name</label><input id="tfNewName"></div><div class="field"><label>Description</label><input id="tfNewDesc"></div></div></details>`,`${btn('Cancel','data-modal-close','button')}${btn('Save families','data-save-test-families','button primary')}`,true);
 setTimeout(()=>{$('[data-save-test-families]').onclick=async()=>{for(const f of App.state.testFamilies||[]){f.name=$$('[data-tf-name]').find(x=>x.dataset.tfName===f.id)?.value.trim()||f.name;f.description=$$('[data-tf-desc]').find(x=>x.dataset.tfDesc===f.id)?.value.trim()||''}const n=$('#tfNewName')?.value.trim(),d=$('#tfNewDesc')?.value.trim();if(n){let id='TF-'+n.toUpperCase().replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,24);let k=2,base=id;while(App.state.testFamilies.some(x=>x.id===id))id=`${base}-${k++}`;App.state.testFamilies.push({id,name:n,description:d,status:'Active'})}P.audit(App.state,'Test-family master updated','Test Family','MASTER','Previous master',`${App.state.testFamilies.length} family records`,App.state.identity.name);await persist();closeModal();render();toast('Test families updated.')}},0)
}
const FIVE_S_PILLARS=[
 ['sort','Sort','Remove what is not needed; red-tag or disposition abnormal items.'],
 ['set','Set in order','Give required items a defined, visible and ergonomic location.'],
 ['shine','Shine','Clean while checking for abnormal conditions and deterioration.'],
 ['standardize','Standardize','Maintain visual standards, ownership and repeatable checks.'],
 ['sustain','Sustain','Demonstrate adherence, follow-up and continued discipline.']
];
function fiveSZoneModal(id=null){
 P.ensureEnterpriseModel(App.state);const z=id?(App.state.fiveSZones||[]).find(x=>x.id===id):null,people=(App.state.staff||[]).filter(x=>x.available!==false);
 openModal(z?'Edit 5S zone':'Add 5S zone',`<div class="form-grid"><div class="field"><label>Zone / workplace</label><input id="fsName" value="${esc(z?.name||'')}"></div><div class="field"><label>Area</label><input id="fsArea" value="${esc(z?.area||'')}"></div><div class="field full"><label>Accountable owner</label><select id="fsOwner">${people.map(x=>`<option ${z?.owner===x.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save zone','data-save-5s-zone','button primary')}`);
 setTimeout(()=>{$('[data-save-5s-zone]').onclick=async()=>{const name=$('#fsName').value.trim(),area=$('#fsArea').value.trim(),owner=$('#fsOwner').value;if(!name||!area||!owner){toast('Zone, area and owner are required.',true);return}const rec=z||{id:P.uid('5S-ZONE'),status:'Active'};Object.assign(rec,{name,area,owner});if(!z)App.state.fiveSZones.push(rec);P.audit(App.state,'5S zone configured','5S Zone',rec.id,z?'Existing':'New',`${name} · ${owner}`,area);await persist();closeModal();render();toast('5S zone saved.')}},0)
}
function fiveSAuditModal(zoneId){
 P.ensureEnterpriseModel(App.state);const z=(App.state.fiveSZones||[]).find(x=>x.id===zoneId);if(!z)return;
 openModal(`5S check · ${z.name}`,`<div class="callout"><strong>${esc(z.area)} · owner ${esc(z.owner)}</strong><p>Score the observed condition, not the intention. Scores below 4 create a guided action assigned to the zone owner.</p></div><div class="five-s-score-list">${FIVE_S_PILLARS.map(([id,label,help])=>`<div class="five-s-score-row"><div><strong>${label}</strong><small>${esc(help)}</small></div><select data-5s-score="${id}"><option value="5">5 · Sustained</option><option value="4">4 · Meets standard</option><option value="3" selected>3 · Improvement needed</option><option value="2">2 · Significant gap</option><option value="1">1 · Major gap</option></select></div>`).join('')}</div><div class="field"><label>Evidence / observation</label><textarea id="fsEvidence" placeholder="What was observed? Link/photo/reference if available."></textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Record 5S check','data-save-5s-audit','button primary')}`,true);
 setTimeout(()=>{$('[data-save-5s-audit]').onclick=async()=>{const restoreScrollY=window.scrollY,scores={};$$('[data-5s-score]').forEach(x=>scores[x.dataset['5sScore']]=Number(x.value));const evidence=$('#fsEvidence').value.trim(),audit={id:P.uid('5S-AUDIT'),zoneId:z.id,date:P.now(),auditor:App.state.identity.name,scores,evidence,average:Object.values(scores).reduce((a,b)=>a+b,0)/5};App.state.fiveSAudits.push(audit);const due=new Date(Date.now()+7*86400000).toISOString().slice(0,10);for(const [key,label,help] of FIVE_S_PILLARS){if(scores[key]>=4)continue;App.state.actions.push({id:P.uid('ACT'),category:'5S',title:`5S · ${z.name} · ${label}`,why:`5S check scored ${scores[key]}/5. ${evidence||help}`,impact:'Workplace standard below target',owner:z.owner,due,severity:scores[key]<=2?'bad':'warn',fiveSAction:{auditId:audit.id,zoneId:z.id,pillar:key,pillarLabel:label,targetScore:4}})}P.audit(App.state,'5S workplace check recorded','5S Audit',audit.id,'—',`${audit.average.toFixed(1)}/5`,`${z.name} · ${App.state.actions.filter(a=>a.fiveSAction?.auditId===audit.id).length} action(s)`);await persist();closeModal();render();requestAnimationFrame(()=>window.scrollTo({top:restoreScrollY,left:0,behavior:'instant'}));toast(`5S check recorded · ${audit.average.toFixed(1)}/5.`)}},0)
}
function resolve5SActionModal(actionId){
 const a=(App.state.actions||[]).find(x=>x.id===actionId),z=(App.state.fiveSZones||[]).find(x=>x.id===a?.fiveSAction?.zoneId);if(!a||!z)return;
 openModal(`Resolve 5S · ${a.fiveSAction.pillarLabel}`,`<div class="resolution-focus"><span class="eyebrow">CURRENT GAP</span><h2>${esc(z.name)}</h2><p>${esc(a.why)}</p></div><div class="resolution-steps compact"><div class="resolution-step complete"><span class="resolution-index">✓</span><div><strong>Gap identified</strong><small>5S check retained</small></div></div><div class="resolution-step current"><span class="resolution-index">2</span><div><strong>Restore the workplace standard</strong><small>Perform the physical corrective action</small></div></div><div class="resolution-step pending"><span class="resolution-index">3</span><div><strong>Verify & close</strong><small>Record objective evidence below</small></div></div></div><div class="field"><label>Resolution evidence</label><textarea id="fsResolveEvidence" placeholder="What changed, where, and what proves the standard is restored?"></textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Verify & close action','data-close-5s-action','button primary')}`);
 setTimeout(()=>{$('[data-close-5s-action]').onclick=async()=>{const restoreScrollY=window.scrollY,ev=$('#fsResolveEvidence').value.trim();if(!ev){toast('Resolution evidence is required.',true);return}a.status='Resolved';a.resolvedAt=P.now();a.resolutionEvidence=ev;P.audit(App.state,'5S action verified and closed','Action',a.id,'Open','Resolved',ev);await persist();closeModal();render();requestAnimationFrame(()=>window.scrollTo({top:restoreScrollY,left:0,behavior:'instant'}));toast('5S action closed with evidence.')}},0)
}
function renderProcessLibrary(){
 P.ensureEnterpriseModel(App.state);const canEdit=can('planning:standards')||currentRole()==='administrator',canSkills=can('skills:manage')||currentRole()==='administrator',finance=App.state.settings.finance||{};
 const procCards=App.state.processes.map(p=>`<div class="card clickable" data-process="${p.id}"><div class="section-title-row"><span class="pill">${esc(p.id)} Rev ${esc(p.revision)}</span>${status(p.status)}</div><h3>${esc(p.name)}</h3><div class="subtle">${esc(p.family)} · ${p.setupTime} min setup · ${p.cycleTime} min/${esc(p.basis)}</div><div class="subtle">Cost: ${P.currency(p.fixedCharge||0)} fixed + ${P.currency(p.consumableCost||0)} consumables/${esc(p.basis)}</div><div style="margin-top:8px"><span class="pill">${esc(p.equipmentCapability)}</span> <span class="pill">${esc(App.state.competencies?.find(c=>c.id===p.competency)?.name||p.competency)}</span></div><div class="callout" style="margin-top:9px"><strong>${esc(p.workInstruction?.id||'No WI')}</strong> · ${esc(p.workInstruction?.status||'Missing')}<br><small>${esc(p.workInstruction?.title||'Released processes require a work instruction.')}</small></div><div class="route-toolbar" style="margin-top:10px">${canEdit||can('process:develop')?btn('Edit process',`data-edit-process-definition="${p.id}"`,'button tiny secondary'):''}${p.status!=='Released'&&can('process:release')?btn('Release process',`data-release-library-process="${p.id}"`,'button tiny primary'):''}</div></div>`).join('');
 const testCards=(App.state.standardTests||[]).map(x=>{const e=x.externalSourcing||{},external=e.enabled&&Number(e.price)>0,proof=!!e.fileData,expired=!!(e.validUntil&&e.validUntil<P.todayISO()),basis=e.pricingBasis==='unit'?' / unit':e.pricingBasis==='batch'?' / batch':'';return `<div class="card"><div class="section-title-row"><span class="pill">${esc(x.id)} Rev ${esc(x.revision)}</span>${status(x.status)}</div><h3>${esc(x.name)}</h3><div class="subtle"><strong>${esc(testFamilyName(x.familyId))}</strong> · ${esc(x.setupTime)} min setup · ${esc(x.cycleTime)} min/${esc(x.basis)}</div><div class="subtle">Output: ${esc(x.output)} · Internal cost ${P.currency(x.fixedCharge||0)} fixed + ${P.currency(x.consumableCost||0)}/${esc(x.basis)}</div><div style="margin-top:8px"><span class="pill">${esc(x.equipmentCapability)}</span> <span class="pill">${esc(App.state.competencies?.find(c=>c.id===x.competency)?.name||x.competency)}</span></div>${external?`<div class="callout ${expired?'warn':'info'}" style="margin-top:10px"><strong>External benchmark · ${P.currency(e.price)}${basis}</strong><p>${esc(e.supplier||'Supplier not named')} · ${Number(e.leadDays||0)} d lead${e.reference?` · ${esc(e.reference)}`:''} · ${proof?'evidence attached':'no file evidence attached'}${expired?' · validity expired':''}</p></div>`:`<div class="subtle" style="margin-top:10px">External benchmark: not configured</div>`}${canEdit?`<div style="margin-top:10px">${btn('Edit standard & external cost',`data-edit-test-standard="${x.id}"`,'button tiny secondary')}</div>`:''}</div>`}).join('');
 const skills=(App.state.competencies||[]).map(c=>{const certs=(App.state.trainingCertificates||[]).filter(x=>x.skillId===c.id&&x.status==='Valid'&&(!x.expiresAt||x.expiresAt>=P.todayISO())).length;return `<div class="card"><div class="section-title-row"><span class="pill">${esc(c.id)}</span>${status(c.status||'Released')}</div><h3>${esc(c.name)}</h3><div class="subtle">${esc(c.description)}</div><div class="score-row"><span>Required certificate</span><strong>${esc(c.requiredCertificate||'Defined training')}</strong></div><div class="score-row"><span>Validity</span><strong>${esc(c.validMonths||24)} months</strong></div><div class="score-row"><span>Renewal training</span><strong>${Number(c.trainingDurationHours||4).toFixed(1)} h</strong></div><div class="score-row"><span>Valid people</span><strong>${certs}</strong></div>${canSkills?`<div class="route-toolbar" style="margin-top:10px">${btn('Edit competency',`data-edit-skill="${c.id}"`,'button tiny secondary')}</div>`:''}</div>`}).join('');
 const roleRates=Object.entries(finance.roleRates||{}).map(([role,rate])=>`<tr><td>${esc(roleLabel(role))}</td><td>${P.currency(rate)} / h</td></tr>`).join('');
 return pageHeader('Lab Standards & Resources','Controlled lab master data drives planning, costing, qualification and execution. Historical actuals refine future estimates without silently changing released standards.')+
 `<div class="card"><div class="section-title-row"><div><span class="eyebrow">STANDARD PROCESS LIBRARY</span><h2>Released build processes & work instructions</h2></div>${can('process:develop')||currentRole()==='administrator'?btn('+ New process','data-new-process-dev','button primary'):''}</div><div class="grid cols-3">${procCards}</div></div>`+
 `<div class="card"><div class="section-title-row"><div><span class="eyebrow">STANDARD TEST LIBRARY</span><h2>Released laboratory tests</h2></div><div class="route-toolbar">${canEdit?btn('Configure test families','data-test-families','button small secondary'):''}<span class="pill">Used by AUTO-PLAN</span></div></div><div class="grid cols-3">${testCards}</div></div>`+
 `<div class="card"><div class="section-title-row"><div><span class="eyebrow">SKILL CATALOGUE</span><h2>Defined competencies & certificate rules</h2></div>${canSkills?btn('+ New skill','data-new-skill','button primary'):''}</div><div class="grid cols-3">${skills}</div></div>`+
 `<div class="card"><div class="section-title-row"><div><span class="eyebrow">LAB STAFF</span><h2>People, availability & certified skills</h2><div class="subtle">Staff records define the people AUTO-PLAN may assign. Skills remain certificate-gated and cannot be granted by editing a person.</div></div>${canSkills?btn('+ Add staff','data-add-staff','button primary'):''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Person</th><th>Role / team</th><th>Availability</th><th>Valid certified skills</th><th>Actions</th></tr></thead><tbody>${App.state.staff.map(st=>{const valid=(App.state.trainingCertificates||[]).filter(c=>c.staffId===st.id&&c.status==='Valid'&&(!c.expiresAt||c.expiresAt>=P.todayISO()));return `<tr><td><strong>${esc(st.name)}</strong><br><small>${esc(st.employeeNo||st.id)}</small></td><td>${esc(roleLabel(st.role))}<br><small>${esc(st.team||'Prototype Lab')}</small></td><td>${status(st.available?'Available':'Unavailable')}</td><td>${valid.map(c=>`<span class="pill">${esc(App.state.competencies.find(x=>x.id===c.skillId)?.name||c.skillId)}</span>`).join(' ')||'—'}</td><td><div class="route-toolbar">${canSkills?btn('Edit person',`data-edit-staff="${st.id}"`,'button tiny secondary'):''}${canSkills?btn('Manage competencies',`data-edit-staff-skills="${st.id}"`,'button tiny secondary'):''}</div></td></tr>`}).join('')}</tbody></table></div></div>`+
 `<div class="card"><div class="section-title-row"><div><span class="eyebrow">5S WORKPLACE CONTROL</span><h2>Workplace standards by zone</h2><div class="subtle">Short workplace checks create evidence-based actions assigned to the accountable zone owner.</div></div><div class="route-toolbar">${canEdit?btn('+ 5S zone','data-new-5s-zone','button small secondary'):''}</div></div><div class="grid cols-3">${(App.state.fiveSZones||[]).map(z=>{const audits=(App.state.fiveSAudits||[]).filter(a=>a.zoneId===z.id).sort((a,b)=>String(b.date).localeCompare(String(a.date))),last=audits[0],open=(App.state.actions||[]).filter(a=>a.fiveSAction?.zoneId===z.id&&actionStillOpen(a)).length;return `<div class="card compact"><div class="section-title-row"><h3>${esc(z.name)}</h3><span class="pill">${last?`${Number(last.average).toFixed(1)}/5`:'Not checked'}</span></div><div class="subtle">${esc(z.area)} · owner ${esc(z.owner)}</div><div class="score-row"><span>Open 5S actions</span><strong>${open}</strong></div><div class="route-toolbar">${btn('Run 5S check',`data-run-five-s-check="${z.id}"`,'button tiny primary')}${canEdit?btn('Edit zone',`data-edit-five-s-zone-action="${z.id}"`,'button tiny secondary'):''}</div>${audits.length?`<details class="fold compact"><summary>Recent checks</summary>${audits.slice(0,5).map(a=>`<div class="score-row"><span>${P.formatDateTime(a.date)}</span><strong>${Number(a.average).toFixed(1)}/5</strong></div>`).join('')}</details>`:''}</div>`}).join('')||'<div class="empty">No 5S zones configured.</div>'}</div></div>`+
`<div class="card"><div class="section-title-row"><div><span class="eyebrow">FINANCE & COSTING</span><h2>Cost master data</h2><div class="subtle">AUTO-PLAN bookings + these rates produce request estimates; actual material, labour, equipment and rework create variance KPIs.</div></div>${can('finance:manage')||currentRole()==='administrator'?btn('Edit finance rates','data-edit-finance','button primary'):''}</div><div class="grid cols-3">${metric('Contingency',`${Number(finance.contingencyPct||0)}%`)+metric('Equipment rates',`${App.state.equipment.length} defined`)+metric('Costed standards',`${App.state.processes.length+(App.state.standardTests||[]).length}`)}</div><div style="height:12px"></div><div class="grid cols-2"><div><h3>Labour rates</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Labour role</th><th>Internal rate</th></tr></thead><tbody>${roleRates}</tbody></table></div></div><div><h3>Material standard costs</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Part / revision</th><th>Material</th><th>€/unit</th><th></th></tr></thead><tbody>${App.state.materials.slice(0,12).map(m=>`<tr><td>${esc(m.partNumber)} Rev ${esc(m.revision)}</td><td>${esc(m.description)}</td><td>${P.currency(m.unitCost||0)}</td><td>${can('finance:manage')||currentRole()==='administrator'?btn('Edit',`data-edit-material-cost="${m.id}"`,'button tiny secondary'):''}</td></tr>`).join('')}</tbody></table></div></div></div><div class="callout" style="margin-top:12px"><strong>Cost formula</strong><br>planned labour + equipment hours + exact BOM material cost + standard process/test charges + development/external services + contingency. Closed builds retain actual cost and cost-of-poor-quality for KPI learning.</div></div>`;
}
function careDueBand(x){const d=Number(x.daysToDue);if(x.status==='Scheduled')return 'Scheduled';if(d<0)return 'Overdue';if(d<=14)return 'Due ≤14 d';if(d<=30)return 'Due ≤30 d';if(d<=60)return 'Due ≤60 d';if(d<=90)return 'Due ≤90 d';return 'Later'}
function careDueVisual(x){const band=careDueBand(x),cls=band==='Overdue'?'bad':band==='Due ≤14 d'?'bad':/≤30|≤60/.test(band)?'warn':band==='Scheduled'?'good':'info';return `<span class="care-due ${cls}">${band==='Scheduled'?'✓':band==='Overdue'?'✕':'●'} ${esc(band)}</span>`}
function careGroupKey(x,mode){if(mode==='activity')return x.type;if(mode==='equipmentType')return x.equipmentType||'Other equipment';if(mode==='capability')return x.capability||'Other capability';if(mode==='competency')return x.skillName||'Other competency';if(mode==='person')return x.personName||x.targetName||'Other person';return x.targetName||'Individual items'}
function careGroupLabel(mode){return ({activity:'Activity type',equipmentType:'Equipment type',capability:'Equipment capability',competency:'Competency',person:'Person',individual:'Individual'})[mode]||'Group'}
function careNextUse(x){return x.nextUseStart?`${P.formatDateTime(x.nextUseStart)}${x.nextUseRequestId?` · ${esc(x.nextUseRequestId)}`:''}`:'No committed use in horizon'}
function carePlanTable(items){return `<div class="table-wrap"><table class="data-table care-table care-select-table"><thead><tr><th class="care-check-col"></th><th>Target</th><th>Due / expiry</th><th>Next committed use</th><th>System suggestion</th><th>Current reservation</th><th>Status</th><th></th></tr></thead><tbody>${items.map(x=>`<tr class="care-row ${x.status==='Overdue'?'care-overdue':''}" data-care-row="${esc(x.id)}"><td><input type="checkbox" aria-label="Select ${esc(x.targetName)}" data-care-select="${esc(x.id)}"></td><td><strong>${esc(x.targetName)}</strong><br><small>${esc(x.type)}${x.capability?` · ${esc(x.capability)}`:''}${x.skillName?` · ${esc(x.skillName)}`:''}</small></td><td><strong>${P.formatDate(x.dueDate)}</strong><br>${careDueVisual(x)}</td><td><small>${careNextUse(x)}</small></td><td><strong>${P.formatDateTime(x.recommendedStart)}</strong><br><small>${Number(x.durationHours).toFixed(1)} h · ${Number(x.loadHours).toFixed(1)}/${Number(x.capacityHours).toFixed(0)} h forecast load</small></td><td>${x.scheduledStart?`<strong>${P.formatDateTime(x.scheduledStart)}</strong><br><small>User-controlled reservation</small>`:'<span class="muted">Not scheduled</span>'}</td><td>${status(x.status)}</td><td><div class="route-toolbar care-actions">${btn(x.scheduledStart?'Change date':'Review & schedule',`data-schedule-care="${esc(x.id)}"`,'button tiny primary')}${x.scheduledStart?btn('Unschedule',`data-unschedule-care="${esc(x.itemKey)}"`,'button tiny secondary'):''}</div></td></tr>`).join('')||'<tr><td colspan="8">Nothing matches these filters.</td></tr>'}</tbody></table></div>`}
function careGroupedBoard(items,groupMode){if(groupMode==='individual')return `<div class="card">${carePlanTable(items)}</div>`;const groups={};items.forEach(x=>{const k=careGroupKey(x,groupMode);(groups[k]||(groups[k]=[])).push(x)});return `<div class="section-stack">${Object.entries(groups).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,rows])=>`<div class="card care-group-card"><div class="section-title-row"><div><span class="eyebrow">${esc(careGroupLabel(groupMode).toUpperCase())}</span><h2>${esc(k)}</h2></div><div class="care-group-summary"><span class="pill">${rows.length} due item${rows.length===1?'':'s'}</span><span class="pill">${rows.filter(x=>x.status==='Overdue').length} overdue</span></div></div>${carePlanTable(rows)}</div>`).join('')}</div>`}
function evidenceDocumentLink(rec,label='Open evidence'){if(!rec)return '—';if(rec.fileData)return `<a class="button tiny secondary" href="${esc(rec.fileData)}" target="_blank" rel="noopener" download="${esc(rec.fileName||'evidence')}">${esc(label)}</a>`;const ev=String(rec.evidence||'').trim();if(/^https?:\/\//i.test(ev))return `<a class="button tiny secondary" href="${esc(ev)}" target="_blank" rel="noopener">${esc(label)}</a>`;return ev?`<span title="${esc(ev)}">${esc(ev)}</span>`:'—'}
function equipmentAssuranceSettingsModal(id){const e=App.state.equipment.find(x=>x.id===id);if(!e)return;openModal(`Readiness timing · ${e.name}`,`<div class="form-grid"><div class="field"><label>Calibration duration (hours)</label><input id="eqCalHours" type="number" min="0.25" step="0.25" value="${Number(e.calibrationDurationHours||4)}"></div><div class="field"><label>Maintenance duration (hours)</label><input id="eqMntHours" type="number" min="0.25" step="0.25" value="${Number(e.maintenanceDurationHours||4)}"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save durations','data-save-equipment-assurance','button primary')}`);setTimeout(()=>{$('[data-save-equipment-assurance]').onclick=async()=>{const cal=Number($('#eqCalHours').value),mnt=Number($('#eqMntHours').value);if(!(cal>0)||!(mnt>0)){toast('Both durations must be greater than zero.',true);return}e.calibrationDurationHours=cal;e.maintenanceDurationHours=mnt;P.audit(App.state,'Resource assurance durations updated','Equipment',id,'Previous durations',`${cal} h calibration · ${mnt} h maintenance`,App.state.identity.name);await persist();closeModal();render();toast('Readiness durations updated and future scheduling will use them.')}},0)}
function careFocus(type){App.filters.careType=type;App.filters.careStatus='Unscheduled';App.filters.careBucket='';render()}
function careNewScheduleModal(type){
 const svc=new P.ResourceCareService(),kind=['Calibration','Maintenance','Training'].includes(type)?type:'Maintenance',isTraining=kind==='Training',equip=App.state.equipment||[],staff=App.state.staff||[],skills=App.state.competencies||[],firstEq=equip[0],firstSkill=skills[0],defaultHours=isTraining?Number(firstSkill?.trainingDurationHours||4):Number(kind==='Calibration'?firstEq?.calibrationDurationHours||4:firstEq?.maintenanceDurationHours||4),start=careLocalDateTimeValue(new Date(Date.now()+24*3600000).toISOString());
 const targetHtml=isTraining?`<div class="field"><label>Person</label><select id="newCarePerson">${staff.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Competency / training</label><select id="newCareSkill">${skills.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div>`:`<div class="field full"><label>Equipment</label><select id="newCareEquipment">${equip.map(x=>`<option value="${x.id}">${esc(x.id)} · ${esc(x.name)} · ${esc(x.capability||'')}</option>`).join('')}</select></div>`;
 openModal(`Schedule ${kind.toLowerCase()}`,`<div class="form-grid">${targetHtml}<div class="field"><label>Start</label><input id="newCareStart" type="datetime-local" value="${start}"></div><div class="field"><label>Duration (hours)</label><input id="newCareHours" type="number" min="0.25" step="0.25" value="${defaultHours}"></div><div class="field full"><label>Planning note <small>optional</small></label><input id="newCareNote" placeholder="Reason, provider or work order"></div></div><div id="newCarePreview" class="care-preview"></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Find resolvable slot','data-new-care-find-slot','button secondary')}${btn('Schedule & update plan',`data-save-new-care="${kind}"`,'button primary')}`);
 setTimeout(()=>{
  const hours=$('#newCareHours'),st=$('#newCareStart'),eq=$('#newCareEquipment'),person=$('#newCarePerson'),skill=$('#newCareSkill');
  const syncDuration=()=>{if(isTraining){const sk=skills.find(x=>x.id===skill?.value);if(sk)hours.value=Number(sk.trainingDurationHours||4)}else{const e=equip.find(x=>x.id===eq?.value);if(e)hours.value=Number(kind==='Calibration'?e.calibrationDurationHours||4:e.maintenanceDurationHours||4)}};
  const buildItem=()=>{const h=Number(hours.value||0),iso=st.value;if(!(h>0)||!iso)throw new Error('Choose a valid start and duration.');if(isTraining){const ps=staff.find(x=>x.id===person.value),sk=skills.find(x=>x.id===skill.value);if(!ps||!sk)throw new Error('Choose a person and competency.');const cert=(App.state.trainingCertificates||[]).filter(c=>c.staffId===ps.id&&c.skillId===sk.id&&c.status!=='Revoked').sort((a,b)=>String(b.expiresAt||'').localeCompare(String(a.expiresAt||'')))[0],key=cert?`Training-${cert.id}-${cert.expiresAt}`:`Training-${ps.id}-${sk.id}-${P.uid('PLAN')}`;return {id:key,itemKey:key,type:'Training',staffId:ps.id,skillId:sk.id,targetId:ps.id,targetName:`${ps.name} · ${sk.name}`,durationHours:h,dueDate:cert?.expiresAt||iso.slice(0,10),validMonths:Number(sk.validMonths||24),owner:(App.state.users||[]).find(u=>u.role==='lab_manager')?.name||'Lab Manager',ownerRoleId:'lab_manager',technicalOwner:sk.owner||null,actionableRoleIds:['lab_manager','administrator'],reason:'User-planned training / qualification activity.'}}const e=equip.find(x=>x.id===eq.value);if(!e)throw new Error('Choose equipment.');const due=kind==='Calibration'?e.calibrationDue:e.maintenanceDue,key=`${kind}-${e.id}-${due||iso.slice(0,10)}`;return {id:key,itemKey:key,type:kind,equipmentId:e.id,targetId:e.id,targetName:e.name,capability:e.capability,durationHours:h,dueDate:due||iso.slice(0,10),intervalDays:kind==='Calibration'?180:120,owner:kind==='Calibration'?'Metrology':'Lab Manager',reason:`User-planned ${kind.toLowerCase()} activity.`}};
  const preview=()=>{const box=$('#newCarePreview');try{const item=buildItem(),pv=svc.previewSlot(App.state,item,st.value);if(pv.careConflicts.length||pv.eventConflicts.length)box.innerHTML=`<span class="status bad">✕ This time overlaps another fixed readiness/lab event</span><small>Use “Find resolvable slot”. LabOS will not create an unresolved collision.</small>`;else if(pv.affectedRequestIds.length)box.innerHTML=`<span class="status warn">● ${pv.affectedRequestIds.length} build plan${pv.affectedRequestIds.length===1?'':'s'} affected</span><small>Saving will automatically replan: ${pv.affectedRequestIds.map(esc).join(', ')}. You do not need to replan manually.</small>`;else box.innerHTML='<span class="status good">✓ Ready to schedule</span><small>No controlled-resource collision.</small>';}catch(e){box.innerHTML=`<span class="status bad">✕ ${esc(e.message)}</span>`}};
  if(eq)eq.onchange=()=>{syncDuration();preview()};if(skill)skill.onchange=()=>{syncDuration();preview()};if(person)person.onchange=preview;if(st)st.onchange=preview;if(hours)hours.onchange=preview;preview();
  const find=$('[data-new-care-find-slot]');if(find)find.onclick=()=>{try{const item=buildItem(),slot=svc.nextResolvableSlot(App.state,item,st.value);st.value=careLocalDateTimeValue(slot.start);preview();toast('Moved to the next resolvable slot.')}catch(e){toast(e.message,true)}};
  const save=$('[data-save-new-care]');if(save)save.onclick=async()=>{try{const item=buildItem(),note=$('#newCareNote').value.trim(),result=svc.scheduleResolved(App.state,item,st.value,{note,durationHours:item.durationHours});await persist();closeModal();App.filters.careType=kind;App.filters.careStatus='Scheduled';render();{const n=(result.replanned||[]).filter(x=>x.ok!==false).length,u=(result.unresolved||[]).length;toast(u?`${kind} scheduled; ${n} build plan${n===1?'':'s'} replanned and ${u} build${u===1?'':'s'} left unplanned / at risk for later recovery.`:n?`${kind} scheduled; ${n} affected build plan${n===1?'':'s'} automatically updated.`:`${kind} scheduled and reserved in the resource plan.`)}}catch(e){toast(e.message,true)}};
 },0)
}
function careSchedulePrintModal(type='All'){const rows=(App.state.resourceCareBookings||[]).filter(x=>x.status==='Scheduled'&&(type==='All'||x.type===type)).sort((a,b)=>String(a.start).localeCompare(String(b.start))),title=type==='All'?'Calibration, maintenance & training schedule':`${type} schedule`;openModal(title,`<article class="report"><div class="report-head"><div class="report-title-block">${reportBrand()}<div><h1>${esc(title)}</h1><div>Generated ${P.formatDateTime(P.now())}</div></div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Date / time</th><th>Activity</th><th>Resource</th><th>Duration</th><th>Owner</th><th>Status</th></tr></thead><tbody>${rows.map(x=>{const eq=App.state.equipment.find(e=>e.id===x.equipmentId),st=App.state.staff.find(p=>p.id===x.staffId),sk=App.state.competencies.find(k=>k.id===x.skillId);return `<tr><td>${P.formatDateTime(x.start)}</td><td><strong>${esc(x.type)}</strong></td><td>${esc(eq?.name||(st?`${st.name}${sk?' · '+sk.name:''}`:'—'))}</td><td>${((new Date(x.end)-new Date(x.start))/3600000).toFixed(1)} h</td><td>${esc(x.owner||'—')}</td><td>${status(x.status)}</td></tr>`}).join('')||`<tr><td colspan="6">No scheduled ${type==='All'?'readiness work':type.toLowerCase()}.</td></tr>`}</tbody></table></div></article>`,`${btn('Close','data-modal-close','button')}${btn('Print / save PDF','onclick="window.print()"','button primary')}`,true)}
