 forwardWeeks=spec.mode==='quarter'?104:spec.mode==='month'?52:26,forward=new P.ForwardDemandService().build(App.state,{product,weeks:forwardWeeks}),fb=forwardBuckets(forward,spec),cs=capacityState(forward),currentLoad=Math.max(cs.eqUtil,cs.skUtil),futurePeak=Math.max(cs.eqPeak,cs.skPeak),pipe=(App.state.pipelineProjects||[]).filter(x=>product==='all'||x.productId===product);
 const eqs=(App.state.equipment||[]),calReq=eqs.filter(e=>e.calibrationRequired!==false),calOk=calReq.filter(e=>!!P.validCalibrationCertificate(App.state,e.id,today)&&e.calibrationStatus==='Valid'&&(!e.calibrationDue||e.calibrationDue>=today)),calPct=calReq.length?100*calOk.length/calReq.length:100,maintReq=eqs.filter(e=>e.maintenanceRequired!==false),maintOk=maintReq.filter(e=>e.maintenanceStatus!=='Overdue'&&(!e.maintenanceDue||e.maintenanceDue>=today)),maintPct=maintReq.length?100*maintOk.length/maintReq.length:100;
 let qualTotal=0,qualOk=0;for(const st of App.state.staff||[])for(const skill of st.competencies||[]){qualTotal++;if(P.staffQualification(App.state,st,typeof skill==='string'?skill:skill.id,today).valid)qualOk++}const qualPct=qualTotal?100*qualOk/qualTotal:100;
 const qualityReqIds=new Set(reqs.map(r=>r.id)),openQuality=(App.state.deviations||[]).filter(d=>qualityReqIds.has(d.requestId)&&d.status!=='CLOSED'),openHolds=openQuality.filter(d=>d.releaseHold).length;
