 const bottlenecks=[];for(const [k,x] of Object.entries(forward.equipment||{})){const peak=Math.max(0,...x.committed.map((v,i)=>pct(Number(v||0)+Number(x.pipeline?.[i]||0),Number(x.capacity||0))));bottlenecks.push({label:k,type:'Equipment',peak})}for(const x of Object.values(forward.skills||{})){const peak=Math.max(0,...x.committed.map((v,i)=>pct(Number(v||0)+Number(x.pipeline?.[i]||0),Number(x.capacity||0))));bottlenecks.push({label:x.label,type:'Skill',peak})}bottlenecks.sort((a,b)=>b.peak-a.peak);const worst=bottlenecks[0];
