  const uncertaintyMissing=auditScopeRows().filter(x=>/measurement|calibration|dimensional|pressure|electrical|leak/i.test(`${x.activity} ${x.capability}`)&&(!x.uncertainty||/N\/A/i.test(x.uncertainty))).length;
  rules.push(auditRule(stat(uncertaintyMissing,true),'Minor','7.6','Measurement uncertainty is defined where relevant',uncertaintyMissing?`${uncertaintyMissing} measurement category scope record(s) need an approved uncertainty statement`:'Scope metadata includes uncertainty references','Link approved uncertainty budgets / statements to applicable scope items','Measurement uncertainty'));
