 const nav=`<div class="setup-stepper">${steps.map((x,i)=>`<button type="button" class="${i===step?'current':x.done?'done':x.locked?'locked':''}" ${x.locked?'disabled aria-disabled="true"':`data-setup-jump="${i}"`}><span>${x.done?'✓':i+1}</span><small>${esc(x.label)}</small></button>`).join('')}</div>`;
