 if(item.id==='integrity'){const inv=P.validateInvariants(App.state),all=steps.filter(x=>x.id!=='integrity'),open=all.filter(x=>!x.done);body=`<div class="setup-current"><strong>${open.length?'Setup still has open areas':'Ready for go-live'}</strong></div>${open.map(x=>`<div class="audit-guided-row"><div><strong>${esc(x.label)}</strong><small>Complete this setup area before go-live.</small></div>${btn('Open',`data-setup-open-step="${steps.findIndex(y=>y.id===x.id)}"`,'button small primary')}</div>`).join('')}${inv.length?`<details class="fold compact"><summary>Data integrity · ${inv.length} issue(s)</summary>${inv.map(x=>`<div class="callout bad">${esc(x)}</div>`).join('')}</details>`:''}${!open.length&&!inv.length?'<div class="callout good"><strong>✓ Master data and system integrity are ready.</strong></div>':''}`}
