 const summary=`<div class="table-wrap"><table class="data-table compact test-summary-table"><thead><tr><th>Specified test / characterisation</th><th>Coverage</th><th>Specification</th><th>Mean / range</th><th>Cpk</th><th>Conclusion</th></tr></thead><tbody>${rows.map(({t,x})=>{if(!x)return `<tr class="report-fail"><td><strong>${esc(t.name)}</strong></td><td>0 / ${samples.length}</td><td>—</td><td>—</td><td>—</td><td><span class="status bad">✕ Missing evidence</span></td></tr>`;return `<tr class="${x.fail?'report-fail':''}"><td><strong>${esc(t.name)}</strong><small>${esc(t.standardTestId||x.type||'Engineering-specific')}</small></td><td>${x.n} result(s)</td><td>${esc(specText(x))}</td><td>${x.mean===null?'—':`${x.mean.toFixed(3)} ${esc(x.unit)} · ${x.min?.toFixed?.(3)??'—'} → ${x.max?.toFixed?.(3)??'—'}`}</td><td><strong>${esc(cpkText(x))}</strong></td><td>${x.fail?'<span class="status bad">✕ Action</span>':'<span class="status good">✓ Acceptable</span>'}</td></tr>`}).join('')}</tbody></table></div>`;
