 setTimeout(()=>{const b=$('[data-modal-route-sheet]'),pr=$('[data-print-build-report]');if(b)b.onclick=()=>showRouteSheet(id);if(pr)pr.onclick=()=>printBuildReport(id);$$('[data-submit-build-report]').forEach(x=>x.onclick=()=>submitBuildReportApproval(id));$$('[data-approve-build-report]').forEach(x=>x.onclick=()=>approveBuildReport(id));},0)
