async function issueReservedMaterials(requestId){const a=App.state.allocations.filter(x=>x.requestId===requestId&&x.status==='Reserved');if(!a.length){toast('No reserved material to issue.',true);return}a.forEach(x=>x.status='Issued');const r=requestById(requestId),lim=syncMaterialOutputLimit(r);P.audit(App.state,'Reserved material issued to build','Request',requestId,'Reserved','Issued',`${a.length} exact BOM allocation(s)${lim.limited?` · output limit ${lim.maxBuildQty}/${lim.requestedQty}`:''}`);await persist();render();toast(lim.limited?`Reserved lots issued. Current material output limit: ${lim.maxBuildQty}/${lim.requestedQty} unit(s).`:'Reserved lots issued to build genealogy.',lim.limited)}
async function reserveAllMaterials(requestId){const r=requestById(requestId);P.ensureMaterialRequirements(App.state,r);if(P.normaliseMaterialSource(r.materialOwnership)!=='Lab supplied'){toast('Bulk reservation is only used for Lab supplied material.',true);return}const created=[],short=[];for(const req of (r.materialRequirements||[])){const already=App.state.allocations.filter(a=>a.requestId===requestId&&a.requirementId===req.id&&['Reserved','Issued'].includes(a.status)).reduce((n,a)=>n+Number(a.qty||0),0);let remaining=Math.max(0,Number(req.requiredQty||0)-already);if(!remaining)continue;const lots=App.state.materials.filter(m=>m.status==='Available'&&m.partNumber===req.partNumber&&m.revision===req.revision&&Number(m.quantity||0)>0).sort((a,b)=>String(a.expiry||'9999').localeCompare(String(b.expiry||'9999'))||String(a.received||'').localeCompare(String(b.received||'')));for(const m of lots){if(!remaining)break;const qty=Math.min(remaining,Number(m.quantity||0));if(qty<=0)continue;App.state.allocations.push({id:P.uid('ALLOC'),requestId,requirementId:req.id,materialId:m.id,lot:m.lot,qty,status:'Reserved'});m.quantity-=qty;remaining-=qty;created.push(`${req.partNumber} Rev ${req.revision} · ${m.lot} × ${qty}`)}if(remaining>0)short.push(`${req.partNumber} Rev ${req.revision}: short ${remaining} ${req.unit||'pc'}`)}P.audit(App.state,'Bulk BOM reservation','Request',requestId,'Unreserved stock',`${created.length} lot allocation(s) reserved`,short.length?`Shortages: ${short.join('; ')}`:'All exact BOM requirements reserved');await persist();render();if(short.length)toast(`Reserved all available exact BOM stock. ${short.join(' · ')}`,true);else toast(`All exact BOM material reserved in ${created.length} lot allocation(s).`)}
function developmentEstimateModal(devId){const d=App.state.processDevelopments.find(x=>x.id===devId);openModal('Process-development planning estimate',`<div class="callout"><h3>Owned planning assumption</h3><p>Define the expected engineering effort needed before this process can be released. Future builds will replace assumptions with actual/historical data where available.</p></div><div class="field" style="margin-top:12px"><label>Development effort (hours)</label><input id="devHours" type="number" min="0.5" step="0.5" value="${esc(d.planningEstimateHours||'')}"></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save estimate','data-save-dev-estimate','button primary')}`);setTimeout(()=>{$('[data-save-dev-estimate]').onclick=async()=>{const h=Number($('#devHours').value);if(!h){toast('Enter a positive development effort.',true);return}d.planningEstimateHours=h;P.audit(App.state,'Process development estimate set','Process Development',devId,'—',`${h} h`,'Planning input owned by Process Engineering');await persist();closeModal();render();toast('Development allowance saved.')}},0)}
function selectEndTestsModal(requestId){const r=requestById(requestId);P.ensurePlanningModel(App.state);const selected=new Set((r.testRequirements||[]).map(x=>x.standardTestId).filter(Boolean)),custom=(r.testRequirements||[]).filter(x=>!x.standardTestId).map(x=>x.name);const tests=(App.state.standardTests||[]).filter(t=>t.status==='Released');openModal('Select end-characterisation tests',`<div class="callout"><h3>Reuse controlled lab test methods where possible</h3><p>Selected standard tests carry their setup/cycle time, equipment capability, certified skill and cost basis into AUTO-PLAN. Add a custom engineering result only when no released method fits.</p></div><div class="test-choice-list" style="margin-top:12px">${tests.map(t=>`<label class="test-choice"><input type="checkbox" data-test-choice value="${esc(t.id)}" ${selected.has(t.id)?'checked':''}><span><strong>${esc(t.id)} Rev ${esc(t.revision)} · ${esc(t.name)}</strong><small>${esc(t.setupTime)} min setup + ${esc(t.cycleTime)} min/${esc(t.basis)} · ${esc(t.equipmentCapability)} · ${esc(App.state.competencies?.find(c=>c.id===t.competency)?.name||t.competency)}</small></span></label>`).join('')}</div><div class="field" style="margin-top:12px"><label>Additional engineering-specific results <small>(one per line)</small></label><textarea id="customEndTests" placeholder="e.g. Visual comparison to reference">${esc(custom.join('\n'))}</textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Apply selected tests','data-save-end-tests','button primary')}`,true);setTimeout(()=>{$('[data-save-end-tests]').onclick=async()=>{const ids=$$('[data-test-choice]:checked').map(x=>x.value),names=ids.map(id=>App.state.standardTests.find(t=>t.id===id)?.name).filter(Boolean),extra=$('#customEndTests').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),before=(r.testRequirements||[]).map(x=>x.name).join('; ');r.characterisation=[...names,...extra];P.ensureTestRequirements(App.state,r);const reconciled=P.reconcilePlanningBookings(App.state,r,{removeObsolete:true});P.syncRequestFlowdown(App.state,r,{incrementRevision:true});r.triage=null;r.forecastDate=null;P.audit(App.state,'End-characterisation selection changed','Request',requestId,before,r.characterisation.join('; '),`Planning definition changed; ${reconciled.removed.length} obsolete future booking(s) removed; planning must be refreshed`);await persist();closeModal();render();toast(`${r.characterisation.length} end-characterisation requirement(s) selected. Re-run AUTO-PLAN.`)}},0)}
function testEstimateModal(requestId,testReqId){const r=requestById(requestId),tr=(r.testRequirements||[]).find(x=>x.id===testReqId);openModal(`Test development · ${tr.name}`,`<div class="callout"><h3>No released standard test matched</h3><p>For timing only, Process Engineering defines development effort and a provisional execution resource/skill. The method must still be released before Build Readiness.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Development effort (h)</label><input id="tdDev" type="number" min="0.5" step="0.5" value="${esc(tr.developmentEstimateHours||'')}"></div><div class="field"><label>Provisional execution time (h/build)</label><input id="tdExec" type="number" min="0.25" step="0.25" value="${esc(tr.executionEstimateHours||'')}"></div><div class="field"><label>Equipment capability</label><select id="tdEq">${[...new Set(App.state.equipment.map(e=>e.capability))].map(x=>`<option ${tr.equipmentCapability===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Required skill</label><select id="tdSkill">${(App.state.competencies||[]).map(x=>`<option value="${x.id}" ${tr.competency===x.id?'selected':''}>${esc(x.id)} · ${esc(x.name)}</option>`).join('')}</select></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save planning basis','data-save-test-estimate','button primary')}`);setTimeout(()=>{$('[data-save-test-estimate]').onclick=async()=>{const dh=Number($('#tdDev').value),eh=Number($('#tdExec').value);if(!dh||!eh){toast('Development and provisional execution hours are required.',true);return}Object.assign(tr,{developmentEstimateHours:dh,executionEstimateHours:eh,equipmentCapability:$('#tdEq').value,competency:$('#tdSkill').value,owner:App.state.identity.name,status:'Development planned'});P.audit(App.state,'Test development planning basis set','Request',requestId,'Unmapped test',tr.name,`${dh} h development + ${eh} h provisional execution`);await persist();closeModal();render();toast('Test development planning basis saved.')}},0)}
async function releaseTestDevelopment(requestId,testReqId){if(!(can('process:develop')||can('route:edit')||currentRole()==='administrator')){toast('Process Engineer permission is required to release a developed test method.',true);return}const r=requestById(requestId),tr=(r?.testRequirements||[]).find(x=>x.id===testReqId);if(!r||!tr){toast('The requested developed test method is no longer available.',true);return}if(!Number(tr.developmentEstimateHours)||!Number(tr.executionEstimateHours)||!tr.competency){toast('Complete the development and execution planning basis before releasing this test method.',true);return}const before=tr.status||'Development planned';tr.developmentReleased=true;tr.status='Released developed method';P.audit(App.state,'Developed test method released','Request',requestId,before,'Released developed method',`${tr.name} · ${tr.developmentEstimateHours} h development · ${tr.executionEstimateHours} h execution`);await persist();render();toast('Developed test method released for this controlled build workflow.')}

function nextProcessRevision(rev){const r=String(rev||'A').trim().toUpperCase();if(/^[A-Y]$/.test(r))return String.fromCharCode(r.charCodeAt(0)+1);if(r==='Z')return 'AA';const m=r.match(/^([A-Z]+)(\d+)$/);if(m)return `${m[1]}${Number(m[2])+1}`;return `${r || 'A'}1`}
function editProcessDefinition(id){const p=App.state.processes.find(x=>x.id===id);if(!p)return;const released=p.status==='Released',wi=p.workInstruction||{id:`WI-${id}`,revision:p.revision||'A',title:`Work instruction · ${p.name}`,status:'Draft',steps:[]};openModal(`${released?'Revise':'Edit'} process · ${p.name}`,`${released?`<div class="callout warn"><h3>Released revision is protected</h3><p>Saving changes creates the next process revision Under review. Existing builds retain the process revision already recorded on their route/execution history.</p></div>`:`<div class="callout"><h3>Edit controlled process definition</h3><p>Update the process, planning basis, required certified skill and executable work instruction before release.</p></div>`}<div class="form-grid" style="margin-top:12px"><div class="field"><label>Process name</label><input id="epName" value="${esc(p.name)}"></div><div class="field"><label>Process family</label><input id="epFamily" value="${esc(p.family||'')}"></div><div class="field"><label>Owner</label><input id="epOwner" value="${esc(p.owner||App.state.identity.name)}"></div><div class="field"><label>Basis</label><select id="epBasis"><option ${p.basis==='Unit'?'selected':''}>Unit</option><option ${p.basis==='Batch'?'selected':''}>Batch</option></select></div><div class="field full"><label>Description / operating scope</label><textarea id="epDesc">${esc(p.description||'')}</textarea></div><div class="field"><label>Setup time (min)</label><input id="epSetup" type="number" min="0" value="${esc(p.setupTime||0)}"></div><div class="field"><label>Cycle time (min)</label><input id="epCycle" type="number" min="0" value="${esc(p.cycleTime||0)}"></div><div class="field"><label>Equipment capability</label><select id="epEq">${[...new Set(App.state.equipment.map(e=>e.capability))].map(x=>`<option ${p.equipmentCapability===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Required certified skill</label><select id="epSkill">${App.state.competencies.map(c=>`<option value="${c.id}" ${p.competency===c.id?'selected':''}>${esc(c.id)} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Fixed process charge (€)</label><input id="epFixed" type="number" min="0" step="0.01" value="${esc(p.fixedCharge||0)}"></div><div class="field"><label>Consumables (€ / ${esc(p.basis||'Unit')})</label><input id="epConsum" type="number" min="0" step="0.01" value="${esc(p.consumableCost||0)}"></div><div class="field full"><label>Work instruction title</label><input id="epWITitle" value="${esc(wi.title||`Work instruction · ${p.name}`)}"></div><div class="field full"><label>Work instruction steps — one per line</label><textarea id="epWI">${esc((wi.steps||[]).join('\n'))}</textarea></div><div class="field full"><label>Required evidence — one per line</label><textarea id="epEvidence">${esc((p.requiredEvidence||[]).join('\n'))}</textarea></div><div class="field full"><label>Controlled execution data · name | target | unit | batch/sample | recipe/machine/setup/measurement/observation | required/optional</label><textarea id="epParams" placeholder="Weld recipe | RCP-17 | | batch | recipe | required\nLaser power | 500 | W | batch | machine | required\nBead width | 0.8 | mm | sample | measurement | required">${esc(controlledProcessFieldsText(p.params||[]))}</textarea><small>These fields appear automatically at this process step. Control Plan characteristics are added separately from the approved CP.</small></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn(released?'Create revised draft':'Save process','data-save-process-definition','button primary')}`,true);setTimeout(()=>{$('[data-save-process-definition]').onclick=async()=>{const name=$('#epName').value.trim(),desc=$('#epDesc').value.trim(),steps=$('#epWI').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),evidence=$('#epEvidence').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!name||!desc||steps.length<1||!$('#epEq').value||!$('#epSkill').value){toast('Name, scope, equipment capability, certified skill and at least one work-instruction step are required.',true);return}const prev=P.deepClone(p),oldRev=p.revision;if(released){p.revisionHistory=p.revisionHistory||[];p.revisionHistory.push({rev:oldRev,status:'Superseded by draft revision',date:P.todayISO(),note:'Controlled edit',snapshot:prev});p.revision=nextProcessRevision(oldRev);p.status='Under review';}Object.assign(p,{name,family:$('#epFamily').value.trim(),owner:$('#epOwner').value.trim(),description:desc,setupTime:Number($('#epSetup').value||0),cycleTime:Number($('#epCycle').value||0),basis:$('#epBasis').value,equipmentCapability:$('#epEq').value,competency:$('#epSkill').value,fixedCharge:Number($('#epFixed').value||0),consumableCost:Number($('#epConsum').value||0),requiredEvidence:evidence,params:parseControlledProcessFields($('#epParams').value)});p.workInstruction={...(p.workInstruction||{}),id:p.workInstruction?.id||`WI-${p.id}`,revision:p.revision,title:$('#epWITitle').value.trim()||`Work instruction · ${name}`,status:released?'Draft':(p.workInstruction?.status||'Draft'),steps};if(released){p.approvals=[]}P.audit(App.state,released?'Process revision created':'Process definition edited','Process',id,`Rev ${oldRev}`,`Rev ${p.revision} · ${p.status}`,released?'Released process changed through controlled revision':'Draft/under-review process updated');await persist();closeModal();render();toast(released?`Process revised to Rev ${p.revision} Under review.`:'Process definition updated.')}},0)}
function staffEditorModal(staffId=null){const existing=staffId?App.state.staff.find(x=>x.id===staffId):null,labRoles=['lab_planner','process_engineer','technician','quality','metrology','product_safety','lab_manager','approver'];const d=existing||{name:'',role:'technician',team:'Prototype Lab',available:true,employeeNo:'',email:'',qualification:'Independent',competencies:[],trainingCertificates:[]};openModal(existing?`Edit lab staff · ${d.name}`:'Add lab staff',`<div class="callout"><h3>Planning resource record</h3><p>This controls whether the person is available to AUTO-PLAN. Skills are not assigned here: each planning skill still requires a valid training certificate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Name</label><input id="stName" value="${esc(d.name||'')}"></div><div class="field"><label>Employee / resource number</label><input id="stNo" value="${esc(d.employeeNo||d.id||'')}" placeholder="EMP-001"></div><div class="field"><label>Lab role</label><select id="stRole">${labRoles.map(r=>`<option value="${r}" ${d.role===r?'selected':''}>${esc(roleLabel(r))}</option>`).join('')}</select></div><div class="field"><label>Team</label><input id="stTeam" value="${esc(d.team||'Prototype Lab')}"></div><div class="field"><label>Email / contact</label><input id="stEmail" type="email" value="${esc(d.email||'')}"></div><div class="field"><label>Qualification level</label><select id="stQual">${['Observer','Supervised','Independent','Reviewer','Trainer'].map(q=>`<option ${d.qualification===q?'selected':''}>${q}</option>`).join('')}</select></div><div class="field full"><label><input id="stAvailable" type="checkbox" style="width:auto;min-height:auto" ${d.available!==false?'checked':''}> Available for lab planning</label><small>Use this for current availability. Training-certificate validity is checked separately by AUTO-PLAN.</small></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn(existing?'Save staff record':'Add staff','data-save-staff','button primary')}`);setTimeout(()=>{$('[data-save-staff]').onclick=async()=>{const name=$('#stName').value.trim();if(!name){toast('Staff name is required.',true);return}const prev=existing?P.deepClone(existing):null;if(existing){Object.assign(existing,{name,employeeNo:$('#stNo').value.trim()||existing.employeeNo||existing.id,role:$('#stRole').value,team:$('#stTeam').value.trim()||'Prototype Lab',email:$('#stEmail').value.trim(),qualification:$('#stQual').value,available:$('#stAvailable').checked});P.audit(App.state,'Lab staff updated','Staff',existing.id,prev.name,existing.name,`${roleLabel(existing.role)} · ${existing.available?'available':'unavailable'}`)}else{let n=1,id;do{id=`STAFF-${String(n++).padStart(3,'0')}`}while(App.state.staff.some(x=>x.id===id));const st={id,name,employeeNo:$('#stNo').value.trim()||id,role:$('#stRole').value,team:$('#stTeam').value.trim()||'Prototype Lab',email:$('#stEmail').value.trim(),qualification:$('#stQual').value,available:$('#stAvailable').checked,competencies:[],trainingCertificates:[]};App.state.staff.push(st);P.audit(App.state,'Lab staff added','Staff',id,'—',name,roleLabel(st.role))}await persist();closeModal();render();toast(existing?'Staff record updated.':'Staff added. Issue training certificates before AUTO-PLAN can use skill-gated work.')}},0)}
function readFileDataUrl(file){return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=()=>reject(fr.error||new Error('Could not read certificate file'));fr.readAsDataURL(file)})}
function addCalibrationCertificateModal(id){const e=App.state.equipment.find(x=>x.id===id);if(!e)return;const defaultDue=new Date();defaultDue.setMonth(defaultDue.getMonth()+6);openModal(`Add calibration certificate · ${e.name}`,`<details class="fold compact"><summary>Certificate rule</summary><p>A passing calibration becomes valid only when its certificate file is stored. History is append-only.</p></details><div class="form-grid" style="margin-top:12px"><div class="field"><label>Certificate number</label><input id="ccNo" placeholder="CAL-${esc(e.id)}-2026"></div><div class="field"><label>Calibration laboratory / issuer</label><input id="ccIssuer" placeholder="Calibration laboratory"></div><div class="field"><label>Calibration date</label><input id="ccDate" type="date" value="${P.todayISO()}"></div><div class="field"><label>Next due date</label><input id="ccDue" type="date" value="${defaultDue.toISOString().slice(0,10)}"></div><div class="field full"><label>Traceability / reference standard</label><input id="ccTrace" placeholder="Reference standard / traceability statement"></div><div class="field"><label>Result</label><select id="ccResult"><option>Pass</option><option>Limited use</option><option>Fail</option></select></div><div class="field"><label>Calibration certificate file <small>(required for valid status)</small></label><input id="ccFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt"></div><div class="field full"><label>Controlled document reference</label><input id="ccEvidence" placeholder="Document ID / SharePoint / PLM reference"></div><div class="field full"><label>Comment</label><textarea id="ccComment">Calibration certificate recorded</textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Add certificate','data-save-cal-certificate','button primary')}`,true);setTimeout(()=>{$('[data-save-cal-certificate]').onclick=async()=>{try{const no=$('#ccNo').value.trim(),issuer=$('#ccIssuer').value.trim(),ev=$('#ccEvidence').value.trim(),file=$('#ccFile').files?.[0],result=$('#ccResult').value;if(!no||!issuer){toast('Certificate number and issuer are required.',true);return}if(result==='Pass'&&!file){toast('A passing calibration is only valid when the certificate file is uploaded.',true);return}const fileData=file?await readFileDataUrl(file):null;App.state.calibrationCertificates=App.state.calibrationCertificates||[];const cert={id:P.uid('CALCERT'),equipmentId:id,certificateNo:no,issuer,referenceStandard:$('#ccTrace').value.trim(),completedAt:$('#ccDate').value,nextDue:$('#ccDue').value,result,status:result==='Pass'?'Valid':'Attention',evidence:ev||file?.name||'',fileName:file?.name||'',fileType:file?.type||'',fileSize:file?.size||0,fileData,documentUploaded:!!fileData,comment:$('#ccComment').value.trim(),person:App.state.identity.name};App.state.calibrationCertificates.push(cert);App.state.maintenanceRecords=App.state.maintenanceRecords||[];App.state.maintenanceRecords.push({id:P.uid('CAL'),equipmentId:id,type:'Calibration',completedAt:cert.completedAt,nextDue:cert.nextDue,evidence:cert.evidence,comment:cert.comment,person:cert.person,certificateId:cert.id});e.calibrationStatus=result==='Pass'&&fileData?'Valid':'Invalid';e.calibrationDue=cert.nextDue;e.calibrationCertificateValid=!!P.validCalibrationCertificate(App.state,id,P.todayISO());if(e.calibrationCertificateValid&&e.status==='Commissioning')e.status='Available';for(const acq of App.state.capacityAcquisitions||[])if(acq.equipmentId===id&&e.calibrationCertificateValid){acq.status='Commissioned';acq.commissionedAt=P.now();acq.commissionedBy=App.state.identity.name}for(const b of App.state.resourceCareBookings||[])if(b.status==='Scheduled'&&b.type==='Calibration'&&b.equipmentId===id)b.status='Completed';App.state.actions=(App.state.actions||[]).filter(a=>!(a.careType==='Calibration'&&a.objectId===id));P.audit(App.state,'Calibration certificate appended','Equipment',id,'Previous certificate history',no,`${issuer} · ${result} · ${file?.name||'no file'}`);await persist();closeModal();render();toast(`Calibration certificate ${no} added to history${e.calibrationCertificateValid?' and equipment is valid':' ; equipment remains unavailable'}.`,!e.calibrationCertificateValid)}catch(err){toast(`Certificate upload failed: ${err.message}`,true)}}},0)}
function editPlanningStandard(kind,id){
 const obj=kind==='process'?App.state.processes.find(x=>x.id===id):App.state.standardTests.find(x=>x.id===id);if(!obj)return;P.ensureEnterpriseModel(App.state);
 const ext=kind==='test'?(obj.externalSourcing||{}):{},hasProof=!!ext.fileData,expired=!!(ext.validUntil&&ext.validUntil<P.todayISO()),notYetValid=!!(ext.validFrom&&ext.validFrom>P.todayISO()),commercialCurrent=!expired&&!notYetValid;
 const externalHtml=kind==='test'?`<div class="card" style="margin-top:14px"><div class="section-title-row"><div><span class="eyebrow">EXTERNAL TEST COST & EVIDENCE</span><h3>External sourcing benchmark</h3><div class="subtle">Used when comparing sister-lab execution with external outsourcing. The generic external-facility rate is used only if this test has no specific external price.</div></div>${ext.enabled?status(expired?'Benchmark expired':notYetValid?'Not valid yet':'Configured'):status('Optional')}</div><label class="plan-switch" style="margin:10px 0"><input id="psExternalEnabled" type="checkbox" ${ext.enabled?'checked':''}><span>Maintain a test-specific external sourcing benchmark</span></label><div class="form-grid"><div class="field full"><label>External supplier / test house</label><input id="psExternalSupplier" value="${esc(ext.supplier||'')}" placeholder="e.g. accredited test laboratory"></div><div class="field"><label>Pricing basis</label><select id="psExternalBasis"><option value="fixed" ${ext.pricingBasis==='fixed'?'selected':''}>Fixed price / test</option><option value="unit" ${ext.pricingBasis==='unit'?'selected':''}>Price / sample</option><option value="batch" ${ext.pricingBasis==='batch'?'selected':''}>Price / batch</option></select></div><div class="field"><label>External price (€)</label><input id="psExternalPrice" type="number" min="0" step="0.01" value="${esc(ext.price||0)}"></div><div class="field"><label>Setup / admin (€)</label><input id="psExternalSetup" type="number" min="0" step="0.01" value="${esc(ext.setupFee||0)}"></div><div class="field"><label>Transport / handling (€)</label><input id="psExternalTransport" type="number" min="0" step="0.01" value="${esc(ext.transportCost||0)}"></div><div class="field"><label>Nominal lead time (days)</label><input id="psExternalLead" type="number" min="0" step="1" value="${esc(ext.leadDays||0)}"></div><div class="field"><label>Evidence type</label><select id="psExternalEvidenceType"><option ${ext.evidenceType==='Quote'?'selected':''}>Quote</option><option ${ext.evidenceType==='Invoice'?'selected':''}>Invoice</option><option ${ext.evidenceType==='Other'?'selected':''}>Other</option></select></div><div class="field full"><label>Quote / invoice reference</label><input id="psExternalReference" value="${esc(ext.reference||'')}" placeholder="Quote no., PO/invoice no. or commercial reference"></div><div class="field"><label>Valid from</label><input id="psExternalValidFrom" type="date" value="${esc(ext.validFrom||'')}"></div><div class="field"><label>Valid until</label><input id="psExternalValidUntil" type="date" value="${esc(ext.validUntil||'')}"></div><div class="field full"><label>Attach quote / invoice proof <small>(PDF, image, Office document or text · max 8 MB)</small></label><input id="psExternalEvidenceFile" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.xls,.xlsx,.txt,application/pdf,image/*"></div></div>${hasProof?`<div class="callout ${commercialCurrent?'good':'warn'}"><strong>${esc(ext.evidenceType||'Evidence')} attached · ${esc(ext.fileName||'document')}</strong><p>${ext.reference?`Reference ${esc(ext.reference)} · `:''}${ext.evidenceUploadedAt?`uploaded ${P.formatDateTime(ext.evidenceUploadedAt)}${ext.evidenceUploadedBy?` by ${esc(ext.evidenceUploadedBy)}`:''}`:'upload metadata retained'}${ext.validUntil?` · valid until ${P.formatDate(ext.validUntil)}`:''}</p><div class="route-toolbar">${evidenceDocumentLink(ext,'Open / download evidence')}<label class="plan-switch"><input id="psExternalRemoveEvidence" type="checkbox"><span>Remove attached evidence</span></label></div></div>`:`<div class="callout info"><strong>No document attached yet.</strong><p>The commercial reference can be saved without a file, but attaching the supplier quote or invoice creates stronger evidence for the benchmark.</p></div>`}${(obj.externalSourcingHistory||[]).length?`<div class="callout info"><strong>${obj.externalSourcingHistory.length} superseded commercial record${obj.externalSourcingHistory.length===1?'':'s'} retained</strong><p>Earlier quote/invoice terms and evidence remain in the audit history and are not used for current sourcing economics.</p></div>`:''}<div class="callout"><strong>Cost logic</strong><p>Fixed: price once per outsourced test. Per sample: price × requested prototype quantity. Per batch: price once per build. Setup/admin and transport are added once. A currently valid controlled value takes precedence over the generic external hourly benchmark. Expired or not-yet-valid commercial evidence is retained for traceability but is not used for active sourcing economics.</p></div></div>`:'';
 openModal(`Planning standard · ${obj.name}`,`<div class="callout"><h3>Planning master data</h3><p>These values drive capacity and cost estimates. Historical actuals refine forecasts without silently changing the released standard.</p></div><div class="form-grid" style="margin-top:12px">${kind==='test'?`<div class="field full"><label>Test family</label><select id="psFamily">${(App.state.testFamilies||[]).map(x=>`<option value="${x.id}" ${obj.familyId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Setup time (min)</label><input id="psSetup" type="number" min="0" value="${esc(obj.setupTime)}"></div><div class="field"><label>Cycle time (min)</label><input id="psCycle" type="number" min="0" value="${esc(obj.cycleTime)}"></div><div class="field"><label>Basis</label><select id="psBasis"><option ${obj.basis==='Unit'?'selected':''}>Unit</option><option ${obj.basis==='Batch'?'selected':''}>Batch</option></select></div><div class="field"><label>Equipment capability</label><select id="psEq">${[...new Set(App.state.equipment.map(e=>e.capability))].map(x=>`<option ${obj.equipmentCapability===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Fixed charge (€)</label><input id="psFixed" type="number" min="0" value="${esc(obj.fixedCharge||0)}"></div><div class="field"><label>Consumables (€ / unit or batch)</label><input id="psConsum" type="number" min="0" value="${esc(obj.consumableCost||0)}"></div><div class="field full"><label>Required competency</label><select id="psSkill">${(App.state.competencies||[]).map(x=>`<option value="${x.id}" ${obj.competency===x.id?'selected':''}>${esc(x.id)} · ${esc(x.name)}</option>`).join('')}</select></div></div>${externalHtml}`,`${btn('Cancel','data-modal-close','button')}${btn('Save planning standard','data-save-planning-standard','button primary')}`,true);
 setTimeout(()=>{$('[data-save-planning-standard]').onclick=async()=>{try{
   Object.assign(obj,{setupTime:Number($('#psSetup').value),cycleTime:Number($('#psCycle').value),basis:$('#psBasis').value,equipmentCapability:$('#psEq').value,competency:$('#psSkill').value,fixedCharge:Number($('#psFixed').value||0),consumableCost:Number($('#psConsum').value||0)});
   if(kind==='test'){
     obj.familyId=$('#psFamily').value;
     const enabled=$('#psExternalEnabled').checked,supplier=$('#psExternalSupplier').value.trim(),price=Number($('#psExternalPrice').value||0),validFrom=$('#psExternalValidFrom').value||null,validUntil=$('#psExternalValidUntil').value||null;
     if(enabled&&(!supplier||price<=0)){toast('An enabled external benchmark needs a supplier and positive external price.',true);return}
     if(validFrom&&validUntil&&validUntil<validFrom){toast('External evidence validity end date cannot be before its start date.',true);return}
     const previous=P.deepClone(obj.externalSourcing||{}),next={...previous,enabled,supplier,currency:'EUR',pricingBasis:$('#psExternalBasis').value,price,setupFee:Number($('#psExternalSetup').value||0),transportCost:Number($('#psExternalTransport').value||0),leadDays:Number($('#psExternalLead').value||0),reference:$('#psExternalReference').value.trim(),evidenceType:$('#psExternalEvidenceType').value,validFrom,validUntil,lastUpdatedAt:P.now(),lastUpdatedBy:App.state.identity.name};
     const removeEvidence=$('#psExternalRemoveEvidence')?.checked,file=$('#psExternalEvidenceFile')?.files?.[0],commercialChanged=P.externalSourcingCommercialSignatureV124(previous)!==P.externalSourcingCommercialSignatureV124(next);
     if(file&&file.size>8*1024*1024){toast('Quote / invoice attachment must be 8 MB or smaller in this browser POC.',true);return}
     const previousMeaningful=!!(previous.enabled||Number(previous.price)>0||previous.supplier||previous.reference||previous.fileData);if((commercialChanged&&previousMeaningful)||(file&&previous.fileData)||((removeEvidence)&&previous.fileData))P.archiveExternalSourcingRevisionV124(obj,previous,{actor:App.state.identity.name,reason:commercialChanged?'External sourcing commercial terms changed':'External sourcing evidence replaced / removed'});
     if(removeEvidence||(commercialChanged&&previous.fileData&&!file))Object.assign(next,{fileName:null,fileType:null,fileSize:0,fileData:null,evidenceUploadedAt:null,evidenceUploadedBy:null});
     if(file){const data=await readFileDataUrl(file);Object.assign(next,{fileName:file.name,fileType:file.type||'application/octet-stream',fileSize:file.size,fileData:data,evidenceUploadedAt:P.now(),evidenceUploadedBy:App.state.identity.name})}
     obj.externalSourcing=next;
   }
   P.audit(App.state,'Lab planning standard updated',kind==='process'?'Process':'Standard Test',id,'Previous planning master data',`${obj.setupTime}/${obj.cycleTime} min`,kind==='test'?`Family ${testFamilyName(obj.familyId)}${obj.externalSourcing?.enabled?` · external ${obj.externalSourcing.supplier} ${P.currency(obj.externalSourcing.price)}`:' · no test-specific external benchmark'}`:App.state.identity.name);
   await persist();closeModal();render();toast(kind==='test'?'Test standard and external sourcing evidence updated.':'Lab planning standard updated.');
 }catch(err){console.error(err);toast(`Could not save planning standard: ${err.message}`,true)}}},0)
}

function editStaffSkills(staffId,preselectSkillId=null){
 const st=App.state.staff.find(x=>x.id===staffId); if(!st)return;
 const certs=(App.state.trainingCertificates||[]).filter(c=>c.staffId===staffId).sort((a,b)=>String(b.issuedAt||'').localeCompare(String(a.issuedAt||'')));
 const expiryFor=(skillId,issued=P.todayISO())=>{const sk=App.state.competencies.find(x=>x.id===skillId),d=new Date(`${issued}T12:00:00`);d.setMonth(d.getMonth()+Number(sk?.validMonths||24));return d.toISOString().slice(0,10)};
 const initialSkill=App.state.competencies[0]?.id||'';
 const rows=certs.map(c=>{const current=c.status==='Valid'&&(!c.expiresAt||c.expiresAt>=P.todayISO());return `<div class="score-row"><span><strong>${esc(App.state.competencies.find(x=>x.id===c.skillId)?.name||c.skillId)}</strong><br><small>${esc(c.certificateNo)} · issuer ${esc(c.issuer||'—')} · issued ${P.formatDate(c.issuedAt)} · expires ${P.formatDate(c.expiresAt)}</small><br><small>${evidenceDocumentLink(c,'Open certificate')}</small></span><span>${status(current?'Valid':c.status==='Valid'?'Expired':c.status||'Historical')} ${current?btn('Revoke',`data-revoke-staff-cert="${c.id}"`,'button tiny danger'):''}</span></div>`}).join('')||'<div class="empty">No competency certificates recorded.</div>';
 openModal(`Manage competencies · ${st.name}`,`<details class="fold compact"><summary>Qualification rule</summary><p>Planning uses only valid, in-date competency certificates.</p></details><div style="margin-top:12px">${rows}</div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Competency</label><select id="certSkill">${App.state.competencies.map(c=>`<option value="${c.id}">${esc(c.id)} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Certificate number</label><input id="certNo" placeholder="TR-2026-001"></div><div class="field"><label>Issuer / trainer</label><input id="certIssuer" value="${esc(App.state.identity.name)}"></div><div class="field"><label>Issue date</label><input id="certIssued" type="date" value="${P.todayISO()}"></div><div class="field"><label>Expiry date</label><input id="certExpiry" type="date" value="${expiryFor(initialSkill)}"></div><div class="field"><label>Evidence / certificate reference</label><input id="certEvidence" placeholder="Certificate / LMS record or URL"></div><div class="field"><label>Certificate file</label><input id="certFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt"></div></div>`,`${btn('Close','data-modal-close','button')}${btn('Issue / renew competency','data-issue-certificate','button primary')}`,true);
 setTimeout(()=>{
  const skill=$('#certSkill'),issued=$('#certIssued'),expiry=$('#certExpiry');
  const syncExpiry=()=>{if(skill&&issued&&expiry&&issued.value)expiry.value=expiryFor(skill.value,issued.value)};
  if(preselectSkillId&&skill){skill.value=preselectSkillId;syncExpiry()}if(skill)skill.onchange=syncExpiry; if(issued)issued.onchange=syncExpiry;
  $$('[data-revoke-staff-cert]').forEach(el=>el.onclick=async()=>{const c=App.state.trainingCertificates.find(x=>x.id===el.dataset.revokeStaffCert);if(!c)return;if(!confirm(`Revoke ${App.state.competencies.find(x=>x.id===c.skillId)?.name||c.skillId} for ${st.name}?`))return;c.status='Revoked';c.revokedAt=P.now();c.revokedBy=App.state.identity.name;P.audit(App.state,'Training certificate revoked','Staff',staffId,c.skillId,'Revoked',`${c.certificateNo}; ${App.state.identity.name}`);await persist();closeModal();render();toast('Competency certificate revoked; AUTO-PLAN will no longer use it.');});
  const issue=$('[data-issue-certificate]');if(issue)issue.onclick=async()=>{const skillId=$('#certSkill').value,no=$('#certNo').value.trim(),ev=$('#certEvidence').value.trim(),file=$('#certFile').files?.[0],issuedAt=$('#certIssued').value,expiresAt=$('#certExpiry').value;if(!no||(!ev&&!file)||!issuedAt||!expiresAt){toast('Certificate number, dates and certificate evidence are required.',true);return}if(expiresAt<issuedAt){toast('Expiry date cannot be before issue date.',true);return}(App.state.trainingCertificates||[]).filter(c=>c.staffId===staffId&&c.skillId===skillId&&c.status==='Valid').forEach(c=>{c.status='Superseded';c.supersededAt=P.now()});const fileData=file?await readFileDataUrl(file):null,c={id:P.uid('CERT'),staffId,skillId,certificateNo:no,issuer:$('#certIssuer').value.trim(),issuedAt,expiresAt,status:'Valid',evidence:ev||file?.name||'',fileName:file?.name||'',fileType:file?.type||'',fileData,documentUploaded:!!fileData};App.state.trainingCertificates.push(c);for(const b of App.state.resourceCareBookings||[])if(b.status==='Scheduled'&&b.type==='Training'&&b.staffId===staffId&&b.skillId===skillId){b.status='Completed';b.completedAt=P.now();b.completionEvidenceId=c.id}App.state.actions=(App.state.actions||[]).filter(a=>!(a.careType==='Training'&&a.objectId===staffId&&(!a.careItemKey||(App.state.resourceCareBookings||[]).some(b=>b.itemKey===a.careItemKey&&b.skillId===skillId))));st.trainingCertificates=st.trainingCertificates||[];st.trainingCertificates.push(c.id);st.competencies=st.competencies||[];if(!st.competencies.includes(skillId))st.competencies.push(skillId);P.audit(App.state,'Training certificate issued / renewed','Staff',staffId,'Previous qualification state',skillId,`${no}; evidence ${ev}; expires ${expiresAt}`);await persist();closeModal();render();toast('Competency certificate saved and planning qualification updated.');};
 },0)
}
function newSkillWizard(skillId=null){const existing=skillId?App.state.competencies.find(x=>x.id===skillId):null;App.skillWizard={step:0,existingId:existing?.id||null,data:existing?P.deepClone(existing):{owner:App.state.identity.name,validMonths:24,trainingDurationHours:4,status:'Released'}};renderSkillWizard()}
function captureSkillWizard(){const w=App.skillWizard,d=w.data;if(w.step===0){d.name=$('#nsName').value.trim();d.owner=$('#nsOwner').value.trim();d.description=$('#nsDesc').value.trim()}else if(w.step===1){d.requiredCertificate=$('#nsCert').value.trim();d.validMonths=Number($('#nsMonths').value||24);d.trainingDurationHours=Number($('#nsHours').value||4);d.trainingEvidence=$('#nsEvidence').value.trim()}}
function renderSkillWizard(){const w=App.skillWizard,d=w.data,editing=!!w.existingId,labels=['Define skill','Training rule','Review'];let body='';if(w.step===0)body=`<div class="callout"><h3>1 · ${editing?'Edit':'Define'} the competency</h3><p>${editing?'The competency ID is protected because processes, bookings and certificates reference it. Edit the controlled definition without breaking those links.':'Define what the person must be able to do independently and who owns the qualification standard.'}</p></div><div class="form-grid" style="margin-top:12px">${editing?`<div class="field"><label>Competency ID</label><input value="${esc(w.existingId)}" disabled></div>`:''}<div class="field"><label>Skill name</label><input id="nsName" value="${esc(d.name||'')}"></div><div class="field"><label>Owner</label><input id="nsOwner" value="${esc(d.owner||App.state.identity.name)}"></div><div class="field full"><label>Description / scope</label><textarea id="nsDesc">${esc(d.description||'')}</textarea></div></div>`;else if(w.step===1)body=`<div class="callout"><h3>2 · Define how competence is proven</h3><p>${editing?'Changes apply to future training/renewal planning. Existing issued certificates retain their recorded issue date, expiry and evidence.':'The skill cannot be assigned directly to a person. A training certificate with evidence and expiry is required.'}</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Required certificate type</label><input id="nsCert" value="${esc(d.requiredCertificate||'')}" placeholder="e.g. LASER-JOIN-L2"></div><div class="field"><label>Validity (months)</label><input id="nsMonths" type="number" min="1" value="${esc(d.validMonths||24)}"></div><div class="field"><label>Renewal training duration (hours)</label><input id="nsHours" type="number" min="0.5" step="0.5" value="${esc(d.trainingDurationHours||4)}"></div><div class="field full"><label>Training / evidence requirement</label><textarea id="nsEvidence">${esc(d.trainingEvidence||'')}</textarea></div></div>`;else body=`<div class="callout"><h3>3 · Review controlled skill</h3><p>${editing?'Saving updates the competency master and records the change in the audit trail. Existing certificates remain historical records.':'After creation, issue a person-specific certificate before AUTO-PLAN may use that person for the skill.'}</p></div><div class="grid cols-2" style="margin-top:12px"><div class="card"><span class="subtle">Skill</span><strong>${esc(d.name)}</strong></div><div class="card"><span class="subtle">Owner</span><strong>${esc(d.owner)}</strong></div><div class="card"><span class="subtle">Certificate</span><strong>${esc(d.requiredCertificate)}</strong></div><div class="card"><span class="subtle">Validity</span><strong>${esc(d.validMonths)} months</strong></div><div class="card"><span class="subtle">Renewal duration</span><strong>${esc(d.trainingDurationHours||4)} h</strong></div></div><div class="card" style="margin-top:10px"><strong>Training evidence</strong><p>${esc(d.trainingEvidence)}</p></div>`;openModal(`${editing?'Edit competency':'New skill'} · ${labels[w.step]}`,`<div class="wizard-progress">${labels.map((_,i)=>`<div class="wizard-step ${i<w.step?'done':''} ${i===w.step?'active':''}"></div>`).join('')}</div>${body}`,w.step===0?`${btn('Cancel','data-modal-close','button')}${btn('Next →','data-skill-next','button primary')}`:w.step<labels.length-1?`${btn('Back','data-skill-back','button')}${btn('Next →','data-skill-next','button primary')}`:`${btn('Back','data-skill-back','button')}${btn(editing?'Save competency':'Create controlled skill','data-save-new-skill','button primary')}`,true);setTimeout(()=>{const n=$('[data-skill-next]'),b=$('[data-skill-back]'),save=$('[data-save-new-skill]');if(n)n.onclick=()=>{captureSkillWizard();if(w.step===0&&(!d.name||!d.description)){toast('Define the skill name and scope.',true);return}if(w.step===1&&(!d.requiredCertificate||!d.trainingEvidence)){toast('Define the certificate type and training evidence.',true);return}w.step++;renderSkillWizard()};if(b)b.onclick=()=>{captureSkillWizard();w.step--;renderSkillWizard()};if(save)save.onclick=async()=>{if(editing){const target=App.state.competencies.find(x=>x.id===w.existingId);if(!target){toast('Competency no longer exists.',true);return}const before=P.deepClone(target);Object.assign(target,{name:d.name,description:d.description,owner:d.owner,requiredCertificate:d.requiredCertificate,validMonths:Number(d.validMonths||24),trainingDurationHours:Number(d.trainingDurationHours||4),trainingEvidence:d.trainingEvidence,status:target.status||'Released'});P.audit(App.state,'Competency updated','Competency',target.id,`${before.name} · ${before.validMonths} months`,`${target.name} · ${target.validMonths} months`,App.state.identity.name);await persist();closeModal();render();toast('Competency updated. Existing certificates were preserved.')}else{const id=`COMP-${String(App.state.competencies.length+1).padStart(2,'0')}`;App.state.competencies.push({id,name:d.name,description:d.description,owner:d.owner,requiredCertificate:d.requiredCertificate,validMonths:Number(d.validMonths||24),trainingDurationHours:Number(d.trainingDurationHours||4),trainingEvidence:d.trainingEvidence,status:'Released'});P.audit(App.state,'Competency defined','Competency',id,'—','Released',d.name);await persist();closeModal();render();toast('Skill defined. Issue a training certificate before assigning it to staff.')}}},0)}
function newProcessWizard(){App.processWizard={step:0,data:{owner:App.state.identity.name,basis:'Unit',setupTime:30,cycleTime:15,equipmentCapability:App.state.equipment[0]?.capability||'',competency:App.state.competencies[0]?.id||'',fixedCharge:20,consumableCost:5,workInstruction:['Verify inputs','Execute operation using controlled parameters','Record required evidence']}};renderProcessWizard()}
function captureProcessWizard(){const w=App.processWizard,d=w.data;if(w.step===0){d.name=$('#npName').value.trim();d.family=$('#npFamily').value.trim();d.description=$('#npDesc').value.trim()}else if(w.step===1){d.setupTime=Number($('#npSetup').value||0);d.cycleTime=Number($('#npCycle').value||0);d.basis=$('#npBasis').value;d.equipmentCapability=$('#npEq').value;d.competency=$('#npSkill').value;d.fixedCharge=Number($('#npFixed').value||0);d.consumableCost=Number($('#npConsum').value||0)}else if(w.step===2){d.workInstruction=$('#npWI').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);d.requiredEvidence=$('#npEvidence').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);d.params=parseControlledProcessFields($('#npParams')?.value||'')}}
function renderProcessWizard(){const w=App.processWizard,d=w.data,labels=['Need & scope','Planning standard','Work instruction','Review'];let body='';if(w.step===0)body=`<div class="callout"><h3>1 · Need & scope</h3><p>Define what the new process does and why it is needed. It will remain controlled and unavailable to AUTO-PLAN until released.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Process name</label><input id="npName" value="${esc(d.name||'')}"></div><div class="field"><label>Family</label><input id="npFamily" value="${esc(d.family||'Assembly')}"></div><div class="field full"><label>Purpose / operating scope</label><textarea id="npDesc">${esc(d.description||'')}</textarea></div></div>`;else if(w.step===1)body=`<div class="callout"><h3>2 · Define planning & resource standard</h3><p>This becomes the controlled basis for timing and cost until enough same-product actuals exist to refine the estimate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Setup time (min)</label><input id="npSetup" type="number" min="0" value="${d.setupTime}"></div><div class="field"><label>Cycle time (min)</label><input id="npCycle" type="number" min="0" value="${d.cycleTime}"></div><div class="field"><label>Basis</label><select id="npBasis"><option ${d.basis==='Unit'?'selected':''}>Unit</option><option ${d.basis==='Batch'?'selected':''}>Batch</option></select></div><div class="field"><label>Equipment capability</label><select id="npEq">${[...new Set(App.state.equipment.map(e=>e.capability))].map(x=>`<option ${d.equipmentCapability===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field full"><label>Required certified skill</label><select id="npSkill">${App.state.competencies.map(c=>`<option value="${c.id}" ${d.competency===c.id?'selected':''}>${esc(c.id)} · ${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Fixed process charge (€)</label><input id="npFixed" type="number" min="0" value="${d.fixedCharge}"></div><div class="field"><label>Consumables (€ / ${esc(d.basis)})</label><input id="npConsum" type="number" min="0" value="${d.consumableCost}"></div></div>`;else if(w.step===2)body=`<div class="callout"><h3>3 · Controlled work instruction</h3><p>A released process must contain executable work instructions and required objective evidence.</p></div><div class="field" style="margin-top:12px"><label>Work instruction steps — one per line</label><textarea id="npWI">${esc((d.workInstruction||[]).join('\n'))}</textarea></div><div class="field" style="margin-top:12px"><label>Required evidence — one per line</label><textarea id="npEvidence">${esc((d.requiredEvidence||['Guided build completion','Equipment ID','Operator record']).join('\n'))}</textarea></div><div class="field" style="margin-top:12px"><label>Controlled execution data · name | target | unit | batch/sample | type | required/optional</label><textarea id="npParams" placeholder="Recipe | RCP-17 | | batch | recipe | required\nTemperature | 85 | °C | batch | machine | required\nResult | Pass | | sample | observation | required">${esc(controlledProcessFieldsText(d.params||[]))}</textarea></div>`;else body=`<div class="callout"><h3>4 · Review before controlled release</h3><p>Creation sets the process to <b>Under review</b>. A Process Engineer must release it before it can be used as a standard route operation.</p></div><div class="grid cols-2" style="margin-top:12px"><div class="card"><span class="subtle">Process</span><strong>${esc(d.name)}</strong><p>${esc(d.description)}</p></div><div class="card"><span class="subtle">Planning standard</span><strong>${d.setupTime} min setup + ${d.cycleTime} min/${esc(d.basis)}</strong><p>${esc(d.equipmentCapability)} · ${esc(App.state.competencies.find(c=>c.id===d.competency)?.name||d.competency)}</p></div><div class="card"><span class="subtle">Cost basis</span><strong>${P.currency(d.fixedCharge)} fixed + ${P.currency(d.consumableCost)} consumables</strong></div><div class="card"><span class="subtle">Work instruction</span><strong>${(d.workInstruction||[]).length} controlled steps</strong></div></div>`;openModal(`New process · ${labels[w.step]}`,`<div class="wizard-progress">${labels.map((_,i)=>`<div class="wizard-step ${i<w.step?'done':''} ${i===w.step?'active':''}"></div>`).join('')}</div>${body}`,w.step===0?`${btn('Cancel','data-modal-close','button')}${btn('Next →','data-process-next','button primary')}`:w.step<labels.length-1?`${btn('Back','data-process-back','button')}${btn('Next →','data-process-next','button primary')}`:`${btn('Back','data-process-back','button')}${btn('Create for review','data-save-new-process','button primary')}`,true);setTimeout(()=>{const n=$('[data-process-next]'),b=$('[data-process-back]'),save=$('[data-save-new-process]');if(n)n.onclick=()=>{captureProcessWizard();if(w.step===0&&(!d.name||!d.description)){toast('Define process name and scope.',true);return}if(w.step===1&&(!d.equipmentCapability||!d.competency)){toast('Define equipment capability and required certified skill.',true);return}if(w.step===2&&((d.workInstruction||[]).length<2||(d.requiredEvidence||[]).length<1)){toast('At least two work-instruction steps and one evidence item are required.',true);return}w.step++;renderProcessWizard()};if(b)b.onclick=()=>{captureProcessWizard();w.step--;renderProcessWizard()};if(save)save.onclick=async()=>{const id=`PROC-${String(App.state.processes.length+1).padStart(3,'0')}`;App.state.processes.push({id,name:d.name,family:d.family,revision:'A',status:'Under review',owner:App.state.identity.name,description:d.description,setupTime:d.setupTime,cycleTime:d.cycleTime,basis:d.basis,equipmentCapability:d.equipmentCapability,competency:d.competency,fixedCharge:d.fixedCharge,consumableCost:d.consumableCost,params:d.params||[],requiredEvidence:d.requiredEvidence,workInstruction:{id:`WI-${id}`,revision:'A',title:`Work instruction · ${d.name}`,status:'Draft',steps:d.workInstruction},revisionHistory:[{rev:'A',status:'Under review',date:P.todayISO(),note:'Guided process definition'}],approvals:[]});P.audit(App.state,'New process defined','Process',id,'—','Under review','Guided process definition complete');await persist();closeModal();render();toast('Process created Under review. Release only after controlled review.')}} ,0)}
async function releaseLibraryProcess(id){const p=App.state.processes.find(x=>x.id===id);if(!p)return;if(!p.workInstruction?.steps?.length||!p.equipmentCapability||!p.competency||!Number.isFinite(Number(p.setupTime))||!Number.isFinite(Number(p.cycleTime))){toast('Cannot release: work instruction, planning time, equipment capability and certified skill are mandatory.',true);return}p.status='Released';p.workInstruction.status='Released';p.approvals=p.approvals||[];p.approvals.push({role:roleLabel(currentRole()),person:App.state.identity.name,date:P.todayISO()});P.audit(App.state,'Process released','Process',id,'Under review','Released','Controlled definition and work instruction complete');await persist();render();toast('Process released and available for future routes.')}
function editFinanceModal(){const f=App.state.settings.finance;openModal('Finance & costing master data',`<div class="callout"><h3>Controlled costing inputs</h3><p>These rates drive request estimates and management finance KPIs; actual build costs remain separate.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Contingency %</label><input id="finCont" type="number" min="0" value="${f.contingencyPct}"></div>${Object.entries(f.roleRates).map(([r,v])=>`<div class="field"><label>${esc(roleLabel(r))} €/h</label><input data-fin-rate="${r}" type="number" min="0" value="${v}"></div>`).join('')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save finance rates','data-save-finance','button primary')}`);setTimeout(()=>{$('[data-save-finance]').onclick=async()=>{f.contingencyPct=Number($('#finCont').value||0);$$('[data-fin-rate]').forEach(x=>f.roleRates[x.dataset.finRate]=Number(x.value||0));P.audit(App.state,'Finance master data updated','Settings','finance','Previous rates','Updated',App.state.identity.name);await persist();closeModal();render();toast('Finance rates updated.')}},0)}
function editEquipmentRate(id){const e=App.state.equipment.find(x=>x.id===id);openModal(`Equipment rate · ${e.name}`,`<div class="field"><label>Internal equipment rate €/h</label><input id="eqRate" type="number" min="0" value="${e.hourlyCost}"></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save rate','data-save-eq-rate','button primary')}`);setTimeout(()=>{$('[data-save-eq-rate]').onclick=async()=>{e.hourlyCost=Number($('#eqRate').value||0);P.audit(App.state,'Equipment rate updated','Equipment',id,'Previous rate',e.hourlyCost,'Finance costing');await persist();closeModal();render();toast('Equipment rate updated.')}},0)}
function editMaterialCost(id){const m=App.state.materials.find(x=>x.id===id);openModal(`Material cost · ${m.partNumber} Rev ${m.revision}`,`<div class="field"><label>Standard material cost €/unit</label><input id="matCost" type="number" min="0" step="0.01" value="${m.unitCost||0}"></div><div class="callout" style="margin-top:10px"><p>This standard cost is used for prototype estimates. Issued-lot actual purchase cost can replace it in the later enterprise integration.</p></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save cost','data-save-mat-cost','button primary')}`);setTimeout(()=>{$('[data-save-mat-cost]').onclick=async()=>{const prev=m.unitCost;m.unitCost=Number($('#matCost').value||0);P.audit(App.state,'Material standard cost updated','Material',id,prev,m.unitCost,'Finance costing');await persist();closeModal();render();toast('Material cost updated.')}},0)}
function equipmentServiceModal(id,type){if(type==='calibration'){addCalibrationCertificateModal(id);return}const e=App.state.equipment.find(x=>x.id===id);if(!e)return;openModal(`Maintenance · ${e.name}`,`<div class="form-grid"><div class="field"><label>Completed date</label><input id="svcDate" type="date" value="${P.todayISO()}"></div><div class="field"><label>Next due date</label><input id="svcDue" type="date" value="${new Date(Date.now()+120*86400000).toISOString().slice(0,10)}"></div><div class="field full"><label>Work-order / controlled reference</label><input id="svcEvidence" placeholder="WO-1234 or controlled URL"></div><div class="field full"><label>Maintenance record / certificate file</label><input id="svcFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.txt"></div><div class="field full"><label>Result / comment</label><textarea id="svcComment">Completed satisfactory</textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Record maintenance','data-save-eq-service','button primary')}`);setTimeout(()=>{$('[data-save-eq-service]').onclick=async()=>{const ev=$('#svcEvidence').value.trim(),file=$('#svcFile').files?.[0];if(!ev&&!file){toast('Add a work-order/reference or upload objective maintenance evidence.',true);return}const fileData=file?await readFileDataUrl(file):null,rec={id:P.uid('MNT'),equipmentId:id,type:'Maintenance',completedAt:$('#svcDate').value,nextDue:$('#svcDue').value,evidence:ev||file?.name||'',fileName:file?.name||'',fileType:file?.type||'',fileData,documentUploaded:!!fileData,comment:$('#svcComment').value.trim(),person:App.state.identity.name};App.state.maintenanceRecords.push(rec);e.maintenanceStatus='Valid';e.lastMaintenance=rec.completedAt;e.maintenanceDue=rec.nextDue;for(const b of App.state.resourceCareBookings||[])if(b.status==='Scheduled'&&b.type==='Maintenance'&&b.equipmentId===id)b.status='Completed';App.state.actions=(App.state.actions||[]).filter(a=>!(a.careType==='Maintenance'&&a.objectId===id));P.audit(App.state,'Maintenance recorded','Equipment',id,'Previous due date',rec.nextDue,rec.evidence);await persist();closeModal();render();toast('Maintenance completion recorded and scheduled action closed.')}},0)}
function viewCalibrationCertificates(id){const e=App.state.equipment.find(x=>x.id===id),rows=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===id).sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt)));const mayAdd=can('calibration:manage')||currentRole()==='administrator';openModal(`Calibration certificates · ${e.name}`,`<div class="table-wrap"><table class="data-table"><thead><tr><th>Certificate</th><th>Issuer</th><th>Completed</th><th>Next due</th><th>Evidence</th><th>Result</th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.certificateNo)}</strong></td><td>${esc(c.issuer||'—')}</td><td>${P.formatDate(c.completedAt)}</td><td>${P.formatDate(c.nextDue)}</td><td>${evidenceDocumentLink(c,'Open certificate')}<small>${esc(c.referenceStandard||'')}</small></td><td>${status(c.result||c.status||'Recorded')}</td></tr>`).join('')||'<tr><td colspan="6">No calibration certificate recorded.</td></tr>'}</tbody></table></div>`,`${btn('Close','data-modal-close','button')}${mayAdd?btn('+ Add certificate',`data-modal-add-cal="${id}"`,'button primary'):''}`,true);setTimeout(()=>{const b=$('[data-modal-add-cal]');if(b)b.onclick=()=>addCalibrationCertificateModal(id)},0)}
function careLocalDateTimeValue(iso){if(!iso)return '';const d=new Date(iso);if(Number.isNaN(d.getTime()))return '';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function careScheduleModal(ids){
 const svc=new P.ResourceCareService(),forecast=svc.forecast(App.state,Number(App.filters.careWeeks||26)),items=ids.map(id=>forecast.find(x=>x.id===id||x.itemKey===id)).filter(Boolean);if(!items.length){toast('The selected readiness items are no longer available. Refresh the board.',true);return}
 const rows=items.map((x,i)=>`<div class="care-schedule-item" data-care-modal-row="${i}"><div class="section-title-row"><div><span class="pill">${esc(x.type)}</span><h3>${esc(x.targetName)}</h3><div class="subtle">Due ${P.formatDate(x.dueDate)}${x.nextUseStart?` · next planned use ${P.formatDateTime(x.nextUseStart)}`:''}</div></div>${careDueVisual(x)}</div><div class="care-suggestion-box"><div><span>Best current slot</span><strong data-care-suggestion-label="${i}">${P.formatDateTime(x.recommendedStart)}</strong></div>${btn('Use best slot',`data-care-use-suggestion="${i}"`,'button tiny secondary')}</div><div class="form-grid"><div class="field"><label>Scheduled start</label><input type="datetime-local" data-care-start="${i}" value="${careLocalDateTimeValue(x.scheduledStart||x.recommendedStart)}"></div><div class="field"><label>Duration (hours)</label><input type="number" min="0.25" step="0.25" data-care-duration="${i}" value="${Number(x.durationHours||4)}"></div><div class="field full"><label>Scheduling note <small>optional</small></label><input data-care-note="${i}" placeholder="Provider, work order or reason"></div></div><div class="care-preview" data-care-preview="${i}"></div></div>`).join('');
 openModal(`Schedule readiness work · ${items.length} item${items.length===1?'':'s'}`,`<div class="callout"><strong>No manual replanning.</strong><p>If your chosen calibration, maintenance or training slot overlaps build work, LabOS will move the affected build bookings automatically. Fixed lab events/readiness reservations are never silently overridden.</p></div><div class="section-stack care-schedule-list">${rows}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Schedule & replan', 'data-apply-care-schedule','button primary')}`,true);
 setTimeout(()=>{
  const itemAt=i=>({...items[i],durationHours:Number($(`[data-care-duration="${i}"]`).value||items[i].durationHours||1)});
  const update=i=>{const item=itemAt(i),input=$(`[data-care-start="${i}"]`),box=$(`[data-care-preview="${i}"]`);if(!input||!box)return;try{const pv=svc.previewSlot(App.state,item,input.value);if(pv.careConflicts.length||pv.eventConflicts.length)box.innerHTML='<span class="status bad">✕ Fixed resource/lab collision</span><small>Use the best slot; LabOS will not save an unresolved collision.</small>';else if(pv.affectedRequestIds.length)box.innerHTML=`<span class="status warn">● Planning consequence</span><small>${pv.affectedRequestIds.length} build${pv.affectedRequestIds.length===1?'':'s'} will be automatically replanned around this reservation. This readiness event is not blocked by those builds: ${pv.affectedRequestIds.map(esc).join(', ')}.</small>`;else box.innerHTML='<span class="status good">✓ Resolvable</span><small>No manual follow-up will be required.</small>';}catch(e){box.innerHTML=`<span class="status bad">✕ ${esc(e.message)}</span>`}};
  const recalc=i=>{try{const h=Number($(`[data-care-duration="${i}"]`).value),best=svc.recommendForDuration(App.state,items[i],h);items[i]={...items[i],...best,durationHours:h};const lab=$(`[data-care-suggestion-label="${i}"]`);if(lab)lab.textContent=P.formatDateTime(items[i].recommendedStart);update(i)}catch(e){toast(e.message,true)}};
  items.forEach((_,i)=>{const inp=$(`[data-care-start="${i}"]`),dur=$(`[data-care-duration="${i}"]`),use=$(`[data-care-use-suggestion="${i}"]`);if(inp){inp.onchange=()=>update(i);update(i)}if(dur)dur.onchange=()=>recalc(i);if(use)use.onclick=()=>{recalc(i);inp.value=careLocalDateTimeValue(items[i].recommendedStart);update(i)}});
  const apply=$('[data-apply-care-schedule]');if(apply)apply.onclick=async()=>{try{const working=P.deepClone(App.state),svc2=new P.ResourceCareService(),summary=[];for(let i=0;i<items.length;i++){const item={...items[i],durationHours:Number($(`[data-care-duration="${i}"]`).value)},start=$(`[data-care-start="${i}"]`).value,note=$(`[data-care-note="${i}"]`).value.trim(),r=svc2.scheduleResolved(working,item,start,{note,durationHours:item.durationHours});summary.push(r)}for(const k of Object.keys(App.state))delete App.state[k];Object.assign(App.state,working);await persist();closeModal();render();const n=summary.reduce((a,r)=>a+(r.replanned||[]).filter(x=>x.ok!==false).length,0),u=summary.reduce((a,r)=>a+(r.unresolved||[]).length,0);toast(u?`${items.length} readiness item${items.length===1?'':'s'} scheduled; ${n} build plan${n===1?'':'s'} replanned and ${u} build${u===1?'':'s'} left unplanned / at risk for later recovery.`:n?`${items.length} readiness item${items.length===1?'':'s'} scheduled; ${n} affected build plan${n===1?'':'s'} automatically updated.`:`${items.length} readiness item${items.length===1?'':'s'} scheduled. Scheduling reserves the work; completion evidence is still required before readiness clears.`)}catch(e){toast(e.message,true)}};
 },0)
}
async function scheduleCare(id){careScheduleModal([id])}
async function unscheduleCare(itemKey){new P.ResourceCareService().unschedule(App.state,itemKey);await persist();render();toast('Readiness slot removed from the planning calendar.')}

async function runDailyOperationsReview(force=true){const service=new P.ImprovementService(),siteId=App.state.settings?.activeLabId||App.state.settings?.primaryLabId,review=service.dailyReview(App.state,{force,siteId}),mine=service.forIdentity(App.state,{siteId});await persist();render();toast(`Operations check complete · ${mine.length} executable action(s) assigned to ${roleLabel(currentRole())} for the active lab.`);return review}
function latestImprovementDecision(id){return (App.state.improvementDecisions||[]).filter(d=>d.proposalId===id).sort((a,b)=>String(b.at||'').localeCompare(String(a.at||'')))[0]||null}
function improvementResolveTarget(x){const t=String(x?.type||'').toLowerCase(),title=String(x?.title||'').toLowerCase();if(t==='skills'||/calibration|maintenance/.test(title)||t==='equipment')return 'resource-assurance';if(t==='staffing'||t==='capacity')return 'planning';if(t==='process')return 'process-library';if(t==='quality')return 'quality';return 'action-centre'}
function improvementImplementationModal(actionId){
 const a=(App.state.actions||[]).find(x=>x.id===actionId&&x.improvementProposalId);if(a)App.state.actions=(App.state.actions||[]).filter(x=>x.id!==a.id);
 toast('This legacy improvement action was withdrawn. Run the improvement scan again; REV 1.0.55 only shows proposals LabOS can implement and verify automatically.',true);persist().then(()=>render());
}
function showAppliedImprovementResult(x,apply){
 const rows=(apply.changes||[]).map(c=>`<div class="score-row"><span>${esc(c.requestId||'Plan')} · ${esc(c.task||'Booking')}</span><strong>${esc(c.from)} → ${esc(c.to)}</strong></div>`).join('');
 openModal('Improvement implemented',`<div class="callout good"><span class="status good">✓ Implemented</span><h3>${esc(x.title)}</h3><p>${esc(apply.summary||'LabOS applied and verified the accepted proposal.')}</p></div>${rows?`<div class="card">${rows}</div>`:''}<details class="fold compact"><summary>Implementation evidence</summary><p>The proposal was prevalidated before display. On acceptance LabOS rechecked qualifications/readiness, collisions and affected controlled records before committing the change. No manual replanning is required.</p></details>`,btn('Done','data-modal-close','button primary'));
}
function improvementDecisionModal(id,decision){
 const service=new P.ImprovementService(),siteId=App.state.settings?.activeLabId||App.state.settings?.primaryLabId,x=service.generate(App.state,{siteId}).find(p=>p.id===id)||latestImprovementDecision(id)?.snapshot;if(!x){toast('This opportunity changed while the dashboard was open. Daily Operations has been refreshed.',false);service.generate(App.state,{siteId});render();return}if(!service.canAct(App.state,x,App.state.identity,{siteId})){toast(`This Daily Operations action is assigned to ${x.owner||'another role'} for another role/lab context.`,true);render();return}
 const defaultDate=new Date(Date.now()+(decision==='Deferred'?7:14)*86400000).toISOString().slice(0,10),label=decision==='Accepted'?'Accept & implement now':decision==='Rejected'?'Reject / not applicable':'Defer review',preview=(x.previewChanges||[]).map(c=>`<div class="score-row"><span>${esc(c.requestId||'Plan')} · ${esc(c.task||'Booking')}</span><strong>${esc(c.from)} → ${esc(c.to)}</strong></div>`).join('');
 openModal(`${label} · ${x.type}`,`<div class="callout ${decision==='Rejected'?'bad':'warn'}"><h3>${esc(x.title)}</h3><p>${esc(x.why)}</p></div><div class="score-row"><span>Action</span><strong>${esc(x.proposal)}</strong></div>${decision==='Accepted'?`${preview?`<div class="card"><span class="eyebrow">PREVALIDATED CHANGES</span>${preview}</div>`:''}<div class="callout"><strong>Accept = implement.</strong><p>LabOS will revalidate these changes, update the controlled bookings and route assignments, and verify the result before committing. If anything has changed and the proposal can no longer be completed, nothing is applied and the proposal is withdrawn.</p></div>`:''}<div class="form-grid" style="margin-top:12px">${decision!=='Accepted'?`<div class="field"><label>${decision==='Deferred'?'Review again':'Decision owner'}</label><input id="impOwner" value="${esc(x.owner||App.state.identity.name)}"></div><div class="field"><label>${decision==='Deferred'?'Review date':'Reference date'}</label><input id="impDue" type="date" value="${defaultDate}"></div>`:''}<div class="field full"><label>Decision rationale</label><textarea id="impNote" placeholder="Why are you ${decision==='Accepted'?'accepting':'making'} this decision?"></textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn(label,`data-save-improvement-decision="${esc(id)}|${decision}"`,'button primary')}`,true);
 setTimeout(()=>{$('[data-save-improvement-decision]').onclick=async()=>{const note=$('#impNote').value.trim();if(!note){toast('Record the decision rationale before continuing.',true);return}let apply=null;if(decision==='Accepted'){apply=service.implementAccepted(App.state,x);if(apply.mode!=='automatic'||!apply.verified){service.generate(App.state);await persist();closeModal();render();toast(`Opportunity changed before implementation. Daily Operations was refreshed: ${apply.reason||'the previous assignment is no longer current.'}`,false);return}}
   const owner=decision==='Accepted'?(x.owner||App.state.identity.name):($('#impOwner')?.value.trim()||x.owner||App.state.identity.name),due=decision==='Accepted'?null:($('#impDue')?.value||defaultDate),rec={id:P.uid('IMPD'),proposalId:id,decision,at:P.now(),actor:App.state.identity.name,owner,note,reviewAfter:due||null,snapshot:P.deepClone(x),implementation:apply?{status:'Implemented & verified',summary:apply.summary,changes:P.deepClone(apply.changes||[]),verifiedAt:P.now()}:null};App.state.improvementDecisions=App.state.improvementDecisions||[];App.state.improvementDecisions.push(rec);P.audit(App.state,decision==='Accepted'?'Improvement accepted and implemented':`Improvement proposal ${decision.toLowerCase()}`,'Improvement',id,'Proposed',decision,`${note}${apply?' · '+apply.summary:''}`);service.generate(App.state);await persist();closeModal();render();if(decision==='Accepted')showAppliedImprovementResult(x,apply);else toast(decision==='Rejected'?'Improvement rejected; rationale retained.':'Improvement deferred; review date retained.');}},0)
}
function improvementModal(id){
 const service=new P.ImprovementService(),siteId=App.state.settings?.activeLabId||App.state.settings?.primaryLabId,x=service.generate(App.state,{siteId}).find(p=>p.id===id)||latestImprovementDecision(id)?.snapshot;if(!x)return;if(!service.canAct(App.state,x,App.state.identity,{siteId})){toast(`This Daily Operations action belongs to ${x.owner||'another role'} in a different role/lab context.`,true);return}const d=latestImprovementDecision(id),implemented=d?.decision==='Accepted'&&d?.implementation?.status==='Implemented & verified',preview=(x.previewChanges||[]).map(c=>`<div class="score-row"><span>${esc(c.requestId||'Plan')} · ${esc(c.task||'Booking')}</span><strong>${esc(c.from)} → ${esc(c.to)}</strong></div>`).join('');
 openModal(`Improvement proposal · ${x.type}`,`${d?`<div class="callout ${implemented?'good':''}"><strong>${implemented?'✓ Implemented & verified':`Latest decision · ${esc(d.decision)}`}</strong><p>${P.formatDateTime(d.at)} · ${esc(d.actor||'')}${d.note?' · '+esc(d.note):''}</p>${implemented?`<p>${esc(d.implementation.summary||'')}</p>`:''}</div>`:''}<div class="callout warn"><h3>${esc(x.title)}</h3><p>${esc(x.why)}</p></div><div class="score-row"><span>Proposed action</span><strong>${esc(x.proposal)}</strong></div><div class="score-row"><span>Expected impact</span><strong>${esc(x.impact)}</strong></div>${preview&&!d?`<details class="fold compact"><summary>Exact prevalidated changes</summary>${preview}</details>`:''}`,`${btn('Close','data-modal-close','button')}${d?'':`${btn('Reject',`data-improvement-decision="${esc(id)}|Rejected"`,'button danger')}${btn('Defer',`data-improvement-decision="${esc(id)}|Deferred"`,'button secondary')}${btn('Accept & implement now',`data-improvement-decision="${esc(id)}|Accepted"`,'button primary')}`}`);
}
function addRiskModal(){toast('Process-risk analysis is maintained in the controlled external risk system. Flow relevant characteristics into the LabOS Control Plan.',true)}
function editRiskModal(){toast('Legacy process-risk records are read-only. Maintain risk analysis in the controlled external system and flow applicable controls into the LabOS Control Plan.',true)}
async function exportJson(){try{const txt=await App.repo.exportJSON(App.state);downloadTextFile(`LabOS_backup_${P.todayISO()}_${P.VERSION.replace('-poc','')}.json`,txt,'application/json');toast('LabOS JSON backup exported.')}catch(e){toast(`Export failed: ${e.message}`,true)}}
function importJson(){const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{try{const txt=await i.files[0].text();App.state=await App.repo.importJSON(txt);App.identity=new P.DemoIdentityProvider(App.state);populateRoles();await persist();nav('dashboard');toast('JSON imported and migrated to current schema.')}catch(e){toast(`Import failed: ${e.message}`,true)}};i.click()}
async function resetDemo(){if(!confirm('Reset all local POC data to seeded demo state?'))return;App.state=await App.repo.reset();App.identity=new P.DemoIdentityProvider(App.state);populateRoles();nav('dashboard');toast('Demo data reset.')}
function renderSearch(q){q=q.trim().toLowerCase();const root=$('#searchResults');if(q.length<2){root.classList.add('hidden');return}const res=[];App.state.products.forEach(p=>{if([p.id,p.family,p.partNumber,p.revision,p.hw,p.sw].join(' ').toLowerCase().includes(q))res.push({type:'Product',id:p.id,label:`${p.family} · ${p.partNumber}`,sub:`${p.id} · Rev ${p.revision}`})});App.state.requests.forEach(r=>{if([r.id,r.title,r.productFamily,r.customerId,r.engineeringTeam].join(' ').toLowerCase().includes(q))res.push({type:'Request',id:r.id,label:`${r.id} · ${r.title}`,sub:r.productFamily})});App.state.serials.forEach(s=>{if([s.serial,s.sampleNumber,s.serialNumber].join(' ').toLowerCase().includes(q))res.push({type:'Serial',id:s.serial,label:`Sample ${s.sampleNumber||'—'} · ${s.sampleId||s.serial}${s.serialNumber?' · SN '+s.serialNumber:''}`,sub:s.requestId})});App.state.processes.forEach(p=>{if([p.id,p.name].join(' ').toLowerCase().includes(q))res.push({type:'Process',id:p.id,label:`${p.id} · ${p.name}`,sub:`Rev ${p.revision} · ${p.status}`})});App.state.materials.forEach(m=>{if([m.partNumber,m.lot,m.description].join(' ').toLowerCase().includes(q))res.push({type:'Material',id:m.id,label:`${m.partNumber} · ${m.lot}`,sub:m.description})});App.state.deviations.forEach(d=>{if([d.id,d.requestId,d.serial,d.measurement].join(' ').toLowerCase().includes(q))res.push({type:'Deviation',id:d.id,label:`${d.id} · ${d.measurement}`,sub:d.requestId})});root.innerHTML=res.slice(0,10).map((x,i)=>`<button class="search-result" data-search-index="${i}"><strong>${esc(x.label)}</strong><small>${esc(x.type)} · ${esc(x.sub)}</small></button>`).join('')||'<div class="empty">No matching controlled record.</div>';root.classList.remove('hidden');$$('[data-search-index]',root).forEach((el,i)=>el.onclick=()=>{const x=res[i];root.classList.add('hidden');if(x.type==='Product'){nav('products');setTimeout(()=>document.querySelector(`[data-edit-product=\"${x.id}\"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),0)}else if(x.type==='Request')openRequest(x.id);else if(x.type==='Serial')showSerial(x.id);else if(x.type==='Process')showProcess(x.id);else if(x.type==='Deviation'){const d=App.state.deviations.find(d=>d.id===x.id);openRequest(d.requestId,'quality')}else toast(`${x.type}: ${x.label}`)})}

/* REV 1.0.56 enhancement layer: MSA, governed setup dossiers, guided resolution,
   controlled exceptions, learning capture, process skipping and fast section navigation. */
const _guidedNextDock1055=guidedNextDock;
guidedNextDock=function(r,steps,step){return _guidedNextDock1055(r,steps,step).replace(/button small primary workflow-dock-button/g,'button small next-action workflow-dock-button').replace(/button small workflow-dock-button" type="button" disabled/g,'button small next-action workflow-dock-button" type="button" disabled')};

const _sampleLabel1055=sampleLabel;
sampleLabel=function(s){if(!s)return 'Build-level';const lab=s.sampleId||s.serial||'',formal=s.serialNumber&&s.serialNumber!==lab?s.serialNumber:'';return `Sample ${s.sampleNumber||'—'}${lab?` · ${lab}`:''}${formal?` · SN ${formal}`:''}`};
sampleDisplayFromRef=function(requestId,ref){const s=sampleByRef(requestId,ref);if(!s)return ref||'Build-level';const lab=s.sampleId||s.serial||'',formal=s.serialNumber&&s.serialNumber!==lab?s.serialNumber:'';return `#${s.sampleNumber||'—'}${lab?` · ${lab}`:''}${formal?` · SN ${formal}`:''}`};
const _stepDoneForSample1055=stepDoneForSample;
stepDoneForSample=function(step,sample){return step?.skipStatus==='Approved'||_stepDoneForSample1055(step,sample)};

function governanceObject(kind,id){if(kind==='process')return App.state.processes.find(x=>x.id===id);if(kind==='test')return (App.state.standardTests||[]).find(x=>x.id===id);if(kind==='equipment')return (App.state.equipment||[]).find(x=>x.id===id);return null}
function governanceKindLabel(kind){return kind==='process'?'Process':kind==='test'?'Standard test':'Equipment / setup'}
function documentEvidenceText(d){if(!d)return 'Missing';return [d.reference,d.fileName,d.description].filter(Boolean).join(' · ')||'No evidence reference'}
function governanceCanApprove(kind){const role=currentRole();return role==='administrator'||role==='approver'||role==='quality'||role==='lab_manager'||(kind==='equipment'&&role==='metrology')||(['process','test'].includes(kind)&&role==='process_engineer')}
function controlledDocStatus(d){return P.controlledDocumentApproved?.(d)?'<span class="status good">✓ Approved</span>':`<span class="status ${d?.status==='Rejected'?'bad':'warn'}">● ${esc(d?.status||'Draft')}</span>`}
async function updateControlledDocFromInputs(obj,key,prefix){const d=obj[key]||(obj[key]={id:`${prefix.toUpperCase()}-${obj.id}`,revision:'A'}),ref=$(`#${prefix}Ref`)?.value?.trim()||'',desc=$(`#${prefix}Desc`)?.value?.trim()||'',file=$(`#${prefix}File`)?.files?.[0]||null,before=JSON.stringify({reference:d.reference,description:d.description,fileName:d.fileName,status:d.status});d.reference=ref;d.description=desc;if(file){d.fileData=await readFileDataUrl(file);d.fileName=file.name;d.fileType=file.type;d.fileSize=file.size;d.documentUploaded=true}const after=JSON.stringify({reference:d.reference,description:d.description,fileName:d.fileName,status:d.status});if(before!==after){d.status='Draft';d.approvedBy='';d.approvedAt=null;d.approvalRationale='';d.updatedBy=App.state.identity.name;d.updatedAt=P.now()}return d}
function governanceDocsModal(kind,id){const obj=governanceObject(kind,id);if(!obj)return;P.ensureEnterpriseModel(App.state);const ehs=obj.ehsRiskAssessment||{},comm=obj.commissioningDocument||{},inhouse=kind==='equipment'&&obj.calibrationMode==='In-house',proc=obj.calibrationProcedure||{};const docBlock=(label,d,prefix,help)=>`<div class="controlled-doc-editor"><div class="section-title-row"><div><strong>${esc(label)}</strong><small>${esc(help)}</small></div>${controlledDocStatus(d)}</div><div class="form-grid"><div class="field"><label>Controlled reference</label><input id="${prefix}Ref" value="${esc(d.reference||'')}" placeholder="Document / QMS / SharePoint reference"></div><div class="field"><label>Upload / replace document</label><input id="${prefix}File" type="file" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.txt"></div><div class="field full"><label>Description / scope</label><textarea id="${prefix}Desc" placeholder="What is assessed/released, boundaries and relevant conditions">${esc(d.description||'')}</textarea></div></div>${d.approvedBy?`<small>Approved by ${esc(d.approvedBy)} · ${P.formatDateTime(d.approvedAt)}</small>`:''}</div>`;const body=`<div class="callout"><h3>Controlled setup dossier</h3><p>Work instructions remain the executable operator document. EHS risk assessment and commissioning/release evidence are separate controlled records and stay linked to this exact ${esc(governanceKindLabel(kind).toLowerCase())}.</p></div>${kind!=='equipment'&&obj.workInstruction?`<div class="score-row"><span><strong>Work instruction</strong><small>${esc(obj.workInstruction.id||'WI')} · Rev ${esc(obj.workInstruction.revision||'A')}</small></span>${status(obj.workInstruction.status||'Draft')}</div>`:''}<div style="height:10px"></div>${docBlock('EHS risk assessment',ehs,'ehs','Hazards, controls, residual risk and operating boundaries.')}${docBlock(kind==='equipment'?'Setup release / commissioning':'Release / commissioning',comm,'comm','Objective evidence that the setup/process is commissioned and released for controlled use.')}${kind==='equipment'?`<div class="card compact" style="margin-top:12px"><div class="field"><label>Calibration route</label><select id="calMode"><option ${obj.calibrationMode==='External'?'selected':''}>External</option><option ${obj.calibrationMode==='Internal service'?'selected':''}>Internal service</option><option ${obj.calibrationMode==='In-house'?'selected':''}>In-house</option></select></div><small>In-house calibration requires an approved calibration procedure before the asset can be readiness-valid.</small></div><div id="calProcedureWrap" style="margin-top:12px;${inhouse?'':'display:none'}">${docBlock('In-house calibration procedure',proc,'calproc','Method, standards, environmental conditions, calculation/acceptance criteria and record requirements.')}</div>`:''}`;const footer=`${btn('Close','data-modal-close','button')}${currentRole()==='administrator'?btn('Administrator exception…',`data-admin-exception="${governanceKindLabel(kind)==='Equipment / setup'?'Equipment':governanceKindLabel(kind)}|${id}|${kind==='equipment'?'Equipment governance':'Process governance'}"`,'button admin-exception'):''}${btn('Save dossier','data-save-governance-docs','button secondary')}${governanceCanApprove(kind)?btn('Review & approve','data-approve-governance-docs','button next-action'):''}`;openModal(`${governanceKindLabel(kind)} dossier · ${obj.name||obj.id}`,body,footer,true);setTimeout(()=>{const mode=$('#calMode'),wrap=$('#calProcedureWrap');if(mode&&wrap)mode.onchange=()=>wrap.style.display=mode.value==='In-house'?'block':'none';const save=$('[data-save-governance-docs]');if(save)save.onclick=async()=>{if(kind==='equipment')obj.calibrationMode=$('#calMode').value;await updateControlledDocFromInputs(obj,'ehsRiskAssessment','ehs');await updateControlledDocFromInputs(obj,'commissioningDocument','comm');if(kind==='equipment'&&obj.calibrationMode==='In-house')await updateControlledDocFromInputs(obj,'calibrationProcedure','calproc');P.audit(App.state,'Controlled setup dossier updated',governanceKindLabel(kind),id,'Previous controlled evidence','Draft / updated',App.state.identity.name);await persist();closeModal();render();toast('Dossier saved. Changed documents require controlled approval.');};const approve=$('[data-approve-governance-docs]');if(approve)approve.onclick=async()=>{if(kind==='equipment')obj.calibrationMode=$('#calMode').value;await updateControlledDocFromInputs(obj,'ehsRiskAssessment','ehs');await updateControlledDocFromInputs(obj,'commissioningDocument','comm');if(kind==='equipment'&&obj.calibrationMode==='In-house')await updateControlledDocFromInputs(obj,'calibrationProcedure','calproc');const docs=[obj.ehsRiskAssessment,obj.commissioningDocument,...(kind==='equipment'&&obj.calibrationMode==='In-house'?[obj.calibrationProcedure]:[])];const missing=docs.filter(d=>!(String(d.reference||'').trim()||d.fileData||String(d.description||'').trim()));if(missing.length){toast('Each controlled document needs a reference, upload or substantive description before approval.',true);return}const now=P.now();docs.forEach(d=>{d.status='Approved';d.approvedBy=App.state.identity.name;d.approvedAt=now;d.approvalRationale='Controlled dossier reviewed and approved for intended use.'});if(kind==='equipment'){obj.calibrationCertificateValid=!!P.validCalibrationCertificate(App.state,obj.id,P.todayISO())}P.audit(App.state,'Controlled setup dossier approved',governanceKindLabel(kind),id,'Draft','Approved',`${App.state.identity.name} · EHS / commissioning${kind==='equipment'&&obj.calibrationMode==='In-house'?' / calibration procedure':''}`);await persist();closeModal();render();toast('Controlled setup dossier approved.');};$$('[data-admin-exception]',$('#modalRoot')).forEach(b=>b.onclick=()=>{const [scopeType,scopeId,condition]=b.dataset.adminException.split('|');closeModal();adminExceptionModal(scopeType,scopeId,condition)});},0)}

function governanceRegister(kind){const items=kind==='equipment'?(App.state.equipment||[]):[...(App.state.processes||[]).map(x=>({...x,_kind:'process'})),...(App.state.standardTests||[]).map(x=>({...x,_kind:'test'}))];if(!items.length)return '';const rows=items.map(x=>{const k=kind==='equipment'?'equipment':x._kind,source=governanceObject(k,x.id)||x,assess=k==='equipment'?P.equipmentGovernanceAssessment(source):P.processGovernanceAssessment(source),extra=k==='equipment'?` · calibration ${esc(source.calibrationMode||'External')}`:` · WI ${esc(source.workInstruction?.status||'Missing')}`;return `<tr><td><strong>${esc(source.name)}</strong><small>${esc(source.id)}${extra}</small></td><td>${controlledDocStatus(source.ehsRiskAssessment)}</td><td>${controlledDocStatus(source.commissioningDocument)}</td>${k==='equipment'?`<td>${source.calibrationMode==='In-house'?controlledDocStatus(source.calibrationProcedure):'<span class="status neutral">n/a</span>'}</td>`:''}<td>${assess.ready?'<span class="status good">✓ Ready</span>':'<span class="status bad">✕ Incomplete</span>'}</td><td>${btn('Open dossier',`data-governance-docs="${k}|${source.id}"`,'button tiny secondary')}</td></tr>`}).join('');return `<div class="card governance-register"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED SETUP DOSSIERS</span><h2>${kind==='equipment'?'Equipment EHS, commissioning & calibration procedures':'Process / test EHS, commissioning & work-instruction governance'}</h2><div class="subtle">The work instruction says how to execute. The EHS assessment controls hazards. Commissioning/release evidence proves the setup is approved for controlled use.</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>${kind==='equipment'?'Equipment':'Standard'}</th><th>EHS</th><th>Commissioning</th>${kind==='equipment'?'<th>In-house calibration procedure</th>':''}<th>Readiness</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></div>`}
const _renderProcessLibrary1055=renderProcessLibrary;
renderProcessLibrary=function(){return _renderProcessLibrary1055()+governanceRegister('standards')};
const _renderEquipmentMaster1055=renderEquipmentMaster;
renderEquipmentMaster=function(){return _renderEquipmentMaster1055()+`<div style="height:14px"></div>`+governanceRegister('equipment')};

const _releaseLibraryProcess1055=releaseLibraryProcess;
releaseLibraryProcess=async function(id){const p=App.state.processes.find(x=>x.id===id);if(!p)return;P.ensureEnterpriseModel(App.state);const coreOk=!!p.workInstruction?.steps?.length&&!!p.equipmentCapability&&!!p.competency&&Number.isFinite(Number(p.setupTime))&&Number.isFinite(Number(p.cycleTime)),gov=P.processGovernanceAssessment(p),exception=P.activeAdminException?.(App.state,'Process',id,'Process governance');if(!coreOk){toast('Cannot release: work instruction, planning time, equipment capability and certified skill are mandatory.',true);return}if(!gov.ready&&!exception){governanceDocsModal('process',id);toast(`Release dossier incomplete: ${gov.issues.join(', ')}.`,true);return}p.status='Released';p.workInstruction.status='Released';p.approvals=p.approvals||[];p.approvals.push({role:roleLabel(currentRole()),person:App.state.identity.name,date:P.todayISO(),exceptionId:exception?.id||null});P.audit(App.state,exception?'Process released under administrator exception':'Process released','Process',id,'Under review','Released',exception?`Exception ${exception.id}; unresolved governance remains visible`:'Controlled definition, work instruction, EHS and commissioning evidence complete');await persist();render();toast(exception?'Process released under controlled administrator exception.':'Process released and available for future routes.')};

function adminExceptionModal(scopeType,scopeId,condition='Lifecycle gate',after=null){if(currentRole()!=='administrator'){toast('Only Administrator may create a controlled exception.',true);return}const label=scopeType==='Build'?`${scopeId} · ${requestById(scopeId)?.title||''}`:`${scopeId} · ${governanceObject(scopeType==='Equipment'?'equipment':'process',scopeId)?.name||''}`;openModal(`Administrator exception · ${scopeType}`,`<div class="callout bad"><h3>Exception — not completion</h3><p>This permits controlled progression despite unresolved evidence. LabOS will retain the original deficiencies, exception ID, rationale, containment and approver in the audit record. Missing evidence does not turn green.</p></div><div class="score-row"><span>Scope</span><strong>${esc(label)}</strong></div><div class="score-row"><span>Condition being overridden</span><strong>${esc(condition||'Controlled blocker')}</strong></div><div class="form-grid" style="margin-top:12px"><div class="field full"><label>Reason / business justification <b>required</b></label><textarea id="exReason" placeholder="Why must work proceed before normal closure?"></textarea></div><div class="field full"><label>Risk / impact assessment <b>required</b></label><textarea id="exRisk" placeholder="What could go wrong because the normal gate is incomplete?"></textarea></div><div class="field full"><label>Containment / compensating controls <b>required</b></label><textarea id="exContain" placeholder="How is risk controlled while the exception is active?"></textarea></div><div class="field full"><label>Evidence / authorisation reference <b>required</b></label><input id="exEvidence" placeholder="Deviation / approval / meeting / document reference"></div><div class="field"><label>Expiry (optional)</label><input id="exExpiry" type="date"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Authorise controlled exception','data-save-admin-exception','button admin-exception')}`,true);setTimeout(()=>{$('[data-save-admin-exception]').onclick=async()=>{const reason=$('#exReason').value.trim(),risk=$('#exRisk').value.trim(),containment=$('#exContain').value.trim(),evidence=$('#exEvidence').value.trim();if(!reason||!risk||!containment||!evidence){toast('Reason, risk, containment and evidence are all required.',true);return}const rec={id:P.uid('EXC'),scopeType,scopeId,condition,status:'Active',reason,risk,containment,evidence,createdBy:App.state.identity.name,createdAt:P.now(),expiresAt:$('#exExpiry').value||null};App.state.adminExceptions=App.state.adminExceptions||[];App.state.adminExceptions.push(rec);P.audit(App.state,'Administrator exception authorised',scopeType,scopeId,condition,`Exception ${rec.id}`,`${reason} · Risk: ${risk} · Containment: ${containment} · Evidence: ${evidence}`);await persist();closeModal();render();toast(`Controlled exception ${rec.id} is active. The selected blocking condition is overridden; the underlying evidence deficiency remains visible and auditable.`);if(typeof after==='function')after(rec)}},0)}

const _advanceGateModal1055=advanceGateModal;
advanceGateModal=function(id){const r=requestById(id);if(!r)return;const check=new P.LifecycleService(App.state).check(id);if(!check.next){toast(check.blockers?.[0]||'No later gate is available.',true);return}if(!check.ok){if(currentRole()==='administrator'){openModal(`Gate blocked · ${r.currentGate}`,`<div class="callout bad"><h3>${check.blockers.length} blocker${check.blockers.length===1?'':'s'}</h3><ul>${check.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><p>The normal route is to resolve the underlying evidence. An Administrator may instead create a controlled exception; the deficiencies stay visible and auditable.</p>`,`${btn('Cancel','data-modal-close','button')}${btn('Authorise exception & continue…','data-gate-admin-exception','button admin-exception')}`);setTimeout(()=>{$('[data-gate-admin-exception]').onclick=()=>{closeModal();adminExceptionModal('Build',id,'Lifecycle gate',()=>advanceGateModal(id))}},0);return}toast(check.blockers.join(' '),true);return}const exception=check.exception;openModal(`Gate review · ${r.currentGate} → ${check.next}`,`${exception?`<div class="callout warn"><h3>Administrator exception active · ${esc(exception.id)}</h3><p>${esc(exception.reason)}. Unresolved conditions remain recorded: ${esc((check.overriddenBlockers||[]).join(' · ')||'none at this gate')}.</p></div>`:''}<div class="callout"><h3>Objective gate review</h3><p>${exception?'Progression is authorised by a controlled exception. Record what evidence was still reviewed.':'Gate progression remains evidence-based. Record the review conclusion before advancing.'}</p></div><div style="height:12px"></div><div class="field"><label>Evidence / review conclusion <small>required</small></label><textarea id="gateEvidence"></textarea></div><div class="field" style="margin-top:12px"><label>Reason / decision note</label><input id="gateReason"></div>`,`${btn('Cancel','data-modal-close','button')}${btn(`Advance to ${check.next}`,`data-confirm-gate-v1056="${id}"`,'button next-action')}`);setTimeout(()=>{$('[data-confirm-gate-v1056]').onclick=async()=>{try{new P.LifecycleService(App.state).advance(id,{evidence:$('#gateEvidence').value.trim(),reason:$('#gateReason').value.trim()});await persist();closeModal();render();toast(`Gate advanced to ${r.currentGate}${exception?' under controlled exception':''}.`)}catch(e){toast(e.message,true)}}},0)};

function processSkipModal(requestId,stepId){const r=requestById(requestId),route=App.state.routes.find(x=>x.requestId===requestId),step=route?.steps?.find(x=>x.id===stepId);if(!r||!step)return;App.state.processSkipApprovals=App.state.processSkipApprovals||[];let rec=App.state.processSkipApprovals.find(x=>x.requestId===requestId&&x.stepId===stepId&&x.status==='Pending');if(step.skipStatus==='Approved'){const done=App.state.processSkipApprovals.find(x=>x.id===step.skipApprovalId);openModal(`Skipped · ${step.name}`,`<div class="callout warn"><h3>Approved process-step skip</h3><p>This operation was deliberately not executed. It is treated as lifecycle-complete only because an authorised approval is retained.</p></div><div class="score-row"><span>Reason</span><strong>${esc(done?.reason||'—')}</strong></div><div class="score-row"><span>Containment / impact</span><strong>${esc(done?.impact||'—')}</strong></div><div class="score-row"><span>Approved by</span><strong>${esc(done?.approvedBy||'—')} · ${P.formatDateTime(done?.approvedAt)}</strong></div>`,btn('Close','data-modal-close','button'));return}const approverRoles=[['process_engineer','Process Engineer'],['quality','Quality Engineer'],['lab_manager','Lab Manager'],['approver','Approver / Reviewer']];if(rec){const authorised=currentRole()==='administrator'||currentRole()===rec.approverRole;openModal(`Skip approval · ${step.name}`,`<div class="callout warn"><h3>Skip requested</h3><p><b>Reason:</b> ${esc(rec.reason)}</p><p><b>Impact / containment:</b> ${esc(rec.impact)}</p><p><b>Evidence:</b> ${esc(rec.evidence)}</p></div>${authorised?`<div class="field"><label>Approval / rejection rationale <b>required</b></label><textarea id="skipDecisionNote"></textarea></div>`:`<div class="callout"><p>Waiting for ${esc(roleLabel(rec.approverRole))}. Switch role to review this request.</p></div>`}`,`${btn('Close','data-modal-close','button')}${authorised?`${btn('Reject skip','data-skip-decision="Rejected"','button blocker-action')}${btn('Approve skip','data-skip-decision="Approved"','button next-action')}`:btn(`Switch to ${roleLabel(rec.approverRole)}`,`data-switch-role="${rec.approverRole}"`,'button secondary')}`);setTimeout(()=>{$$('[data-skip-decision]').forEach(b=>b.onclick=async()=>{const note=$('#skipDecisionNote').value.trim();if(!note){toast('Record the approval decision rationale.',true);return}rec.status=b.dataset.skipDecision;rec.decisionRationale=note;rec.approvedBy=App.state.identity.name;rec.approvedAt=P.now();if(rec.status==='Approved'){step.skipStatus='Approved';step.skipApprovalId=rec.id;step.status='Skipped';step.readiness='ready';P.invalidateBuildReport(App.state,r,`Route step skipped by approval · ${step.name}`)}P.audit(App.state,rec.status==='Approved'?'Process step skip approved':'Process step skip rejected','Route step',step.id,'Pending',rec.status,`${requestId} · ${note}`);await persist();closeModal();render();toast(rec.status==='Approved'?'Process step marked Skipped with approval.':'Skip request rejected.',rec.status!=='Approved')})},0);return}openModal(`Request process-step skip · ${step.name}`,`<div class="callout warn"><h3>Skipping is a controlled exception to execution</h3><p>The step is not deleted. It remains visible as <b>Skipped</b> together with the approval and rationale in history and the Build Report.</p></div><div class="form-grid"><div class="field full"><label>Why can this step be skipped? <b>required</b></label><textarea id="skipReason"></textarea></div><div class="field full"><label>Impact / containment <b>required</b></label><textarea id="skipImpact"></textarea></div><div class="field full"><label>Evidence / reference <b>required</b></label><input id="skipEvidence"></div><div class="field"><label>Approver</label><select id="skipApprover">${approverRoles.map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Submit skip for approval','data-submit-skip','button next-action')}`);setTimeout(()=>{$('[data-submit-skip]').onclick=async()=>{const reason=$('#skipReason').value.trim(),impact=$('#skipImpact').value.trim(),evidence=$('#skipEvidence').value.trim();if(!reason||!impact||!evidence){toast('Reason, impact/containment and evidence are required.',true);return}rec={id:P.uid('SKIP'),requestId,stepId,stepName:step.name,status:'Pending',reason,impact,evidence,approverRole:$('#skipApprover').value,requestedBy:App.state.identity.name,requestedAt:P.now()};App.state.processSkipApprovals.push(rec);P.audit(App.state,'Process step skip requested','Route step',stepId,'Normal execution','Pending skip approval',`${requestId} · ${reason}`);await persist();closeModal();render();toast(`Skip request sent to ${roleLabel(rec.approverRole)}.`)}},0)}
const _workspaceExecution1055=workspaceExecution;
workspaceExecution=function(r){const html=_workspaceExecution1055(r),step=selectedExecutionStep(r);if(!step)return html;const rec=(App.state.processSkipApprovals||[]).find(x=>x.requestId===r.id&&x.stepId===step.id&&x.status==='Pending'),approved=step.skipStatus==='Approved';const panel=`<div class="card process-skip-control ${approved?'skip-approved':''}"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED STEP EXCEPTION</span><h3>${approved?'This operation was skipped by approval':rec?'Skip approval pending':'Need to omit this operation?'}</h3><div class="subtle">The operation remains in the route and audit trail; skipping never silently deletes required work.</div></div>${approved?'<span class="status warn">● Skipped</span>':btn(rec?'Review skip request':'Request skip',`data-skip-step="${r.id}|${step.id}"`,rec?'button small next-action':'button small secondary')}</div></div>`;return html+panel};
const _processCard1055=processCard;
processCard=function(s,i){let html=_processCard1055(s,i);if(s.skipStatus==='Approved')html=html.replace(/workflow-(complete|blocked|current)/,'workflow-skipped').replace(/<div class="route-workflow-icon [^"]+">[^<]*<\/div>/,'<div class="route-workflow-icon skipped">↷</div>').replace(/<span>[^<]*(Done|Blocked|Ongoing \/ planned)[^<]*<\/span>/,'<span>Skipped · approved</span>');return html};

function editSampleRegisterModalV1056(requestId){const r=requestById(requestId),profile=P.ensureAssuranceProfile(r),samples=samplesForRequest(requestId);openModal('Sample identity register',`<div class="callout"><h3>Sample number is generated once</h3><p>The build sample number and permanent Lab Sample ID are automatic. You only enter a separate formal product serial when the assurance profile requires it. LabOS will not ask you to type the same identifier twice.</p></div><div class="sample-edit-list" style="margin-top:12px">${samples.map(sm=>{const formal=sm.serialNumber===sm.sampleId||sm.serialNumber===sm.serial?'':sm.serialNumber||'';return `<div class="sample-edit-row"><div><b>Sample ${esc(sm.sampleNumber||'—')}</b><small>${esc(sm.sampleId||sm.serial)} · permanent Lab ID</small></div><div class="field"><label>Formal serial ${profile.requires.serialisation?'':'(optional)'}</label><input data-v1056-sample-serial="${esc(sm.serial)}" value="${esc(formal)}" placeholder="${profile.requires.serialisation?'Enter product serial':'Only if a separate product serial exists'}"></div></div>`}).join('')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save identity register','data-save-sample-register-v1056','button next-action')}`,true);setTimeout(()=>{$('[data-save-sample-register-v1056]').onclick=async()=>{const set=new Set();for(const sm of samples){const v=$(`[data-v1056-sample-serial="${sm.serial}"]`).value.trim();if(profile.requires.serialisation&&!v){toast(`Formal serial is required for Sample ${sm.sampleNumber}.`,true);return}if(v){if(set.has(v)){toast(`Duplicate formal serial: ${v}`,true);return}set.add(v)}}const before=JSON.stringify(samples.map(x=>({id:x.serial,serialNumber:x.serialNumber})));samples.forEach(sm=>sm.serialNumber=$(`[data-v1056-sample-serial="${sm.serial}"]`).value.trim());const after=JSON.stringify(samples.map(x=>({id:x.serial,serialNumber:x.serialNumber})));if(before!==after){P.invalidateBuildReport(App.state,r,'Formal sample serial identity changed');P.audit(App.state,'Sample identity register updated','Request',requestId,before,after,'Automatic sample numbers and Lab IDs retained')};await persist();closeModal();render();toast('Sample identity register updated.')}},0)}
editSampleRegisterModal=editSampleRegisterModalV1056;

function controlPlanProductGroups(){const groups=new Map(),cps=(App.state.controlPlans||[]).filter(c=>c.status!=='Superseded');for(const cp of cps){const linked=(App.state.requests||[]).filter(r=>r.controlPlanId===cp.id||(cp.requestIds||[]).includes(r.id)),ids=[...new Set(linked.map(r=>r.productId).filter(Boolean))],key=ids.length===1?ids[0]:ids.length>1?'MULTI':'UNLINKED',product=ids.length===1?(App.state.products||[]).find(p=>p.id===ids[0]):null,label=product?`${product.family} · ${product.partNumber} Rev ${product.revision}`:ids.length>1?'Shared / multiple products':'Unlinked / library';if(!groups.has(key))groups.set(key,{key,label,productId:product?.id||null,cps:[]});groups.get(key).cps.push({cp,linked})}return [...groups.values()].sort((a,b)=>a.label.localeCompare(b.label))}
function qualityControlPlanCard(cp,linked){const chars=cp.characteristics||[],special=chars.filter(c=>c.classification),incomplete=special.filter(c=>!P.controlCharacteristicReady(c)),ready=!incomplete.length&&chars.length>0,approvalState=controlPlanApprovalState(cp);return `<div class="card quality-cp-card"><div class="section-title-row"><div><span class="eyebrow">${esc(cp.id)} · REV ${esc(cp.revision)}</span><h3>${esc(cp.name)}</h3><div class="subtle">${esc(cp.phase||'Prototype')} · owner ${esc(cp.owner||'—')} · ${linked.length} linked build${linked.length===1?'':'s'}</div></div>${status(cp.status)}</div><div class="quality-cp-kpis"><div><strong>${chars.length}</strong><span>Controls</span></div><div><strong>${special.length}</strong><span>SC / safety</span></div><div class="${incomplete.length?'bad-text':''}"><strong>${incomplete.length}</strong><span>Incomplete</span></div></div>${incomplete.length?`<div class="callout bad"><strong>Approval blocker:</strong> ${esc(incomplete.map(x=>x.characteristic).join(', '))} still need objective specification / method / reaction / evidence.</div>`:cp.status!=='Approved'?'<div class="callout warn"><strong>Definition complete.</strong> Independent review / approval can proceed.</div>':''}<div class="route-toolbar">${can('controlplan:edit')?btn(cp.status==='Approved'?'Revise Control Plan':'Edit Control Plan',`data-edit-control-plan="${cp.id}"`,'button small secondary'):''}${cp.status!=='Approved'&&ready?(approvalState.stage==='submit-review'?(can('controlplan:edit')||currentRole()==='administrator'?btn('Submit for independent review',`data-request-cp-review="${cp.id}"`,'button small next-action'):''):approvalState.canApprove?btn('Approve formally',`data-approve-cp="${cp.id}"`,'button small next-action'):approvalState.switchRole?btn(`Switch to ${esc(approvalState.switchName||roleLabel(approvalState.switchRole))}`,`data-switch-role="${approvalState.switchRole}"`,'button small next-action'):''):''}${linked[0]?btn('Open linked build',`data-open-request="${linked[0].id}" data-tab="controls"`,'button small secondary'):''}</div></div>`}
renderQualityControlPlans=function(){const groups=controlPlanProductGroups();return `<div class="quality-subhead"><div><span class="eyebrow">CONTROL PLAN GOVERNANCE</span><h2>Control Plans by product</h2><p>A Control Plan belongs to a defined product/configuration context. Grouping by product prevents unrelated controls from being treated as one approval population.</p></div></div><div class="section-stack">${groups.map((g,i)=>`<details class="card cp-product-group" ${i<3?'open':''}><summary><span><strong>${esc(g.label)}</strong><small>${g.cps.length} Control Plan${g.cps.length===1?'':'s'}</small></span><span class="pill">${g.cps.filter(x=>x.cp.status!=='Approved').length} pending</span></summary><div class="section-stack">${g.cps.map(x=>qualityControlPlanCard(x.cp,x.linked)).join('')}</div></details>`).join('')||'<div class="empty">No Control Plans.</div>'}</div>`};

function gageRRCalculate(rows,lsl=null,usl=null){const clean=rows.map(x=>({...x,value:Number(x.value)})).filter(x=>x.part&&x.operator&&Number.isFinite(x.value)),parts=[...new Set(clean.map(x=>x.part))],ops=[...new Set(clean.map(x=>x.operator))];if(parts.length<2||ops.length<2)return {valid:false,reason:'Use at least 2 parts and 2 operators.'};const cellCounts=[];for(const p of parts)for(const o of ops)cellCounts.push(clean.filter(x=>x.part===p&&x.operator===o).length);const trials=cellCounts[0];if(trials<2||cellCounts.some(n=>n!==trials))return {valid:false,reason:'Crossed Gage R&R requires a balanced design with the same ≥2 repeated trials for every part/operator cell.'};const mean=a=>a.reduce((n,x)=>n+x,0)/a.length,grand=mean(clean.map(x=>x.value)),partMean=new Map(parts.map(p=>[p,mean(clean.filter(x=>x.part===p).map(x=>x.value))])),opMean=new Map(ops.map(o=>[o,mean(clean.filter(x=>x.operator===o).map(x=>x.value))])),cellMean=new Map();for(const p of parts)for(const o of ops)cellMean.set(`${p}|${o}`,mean(clean.filter(x=>x.part===p&&x.operator===o).map(x=>x.value)));const np=parts.length,no=ops.length,r=trials,ssPart=no*r*parts.reduce((n,p)=>n+(partMean.get(p)-grand)**2,0),ssOp=np*r*ops.reduce((n,o)=>n+(opMean.get(o)-grand)**2,0),ssInt=r*parts.reduce((n,p)=>n+ops.reduce((q,o)=>q+(cellMean.get(`${p}|${o}`)-partMean.get(p)-opMean.get(o)+grand)**2,0),0),ssRepeat=clean.reduce((n,x)=>n+(x.value-cellMean.get(`${x.part}|${x.operator}`))**2,0),dfPart=np-1,dfOp=no-1,dfInt=(np-1)*(no-1),dfRepeat=np*no*(r-1),msPart=ssPart/dfPart,msOp=ssOp/dfOp,msInt=ssInt/dfInt,msRepeat=ssRepeat/dfRepeat,varRepeat=Math.max(msRepeat,0),varInteraction=Math.max((msInt-msRepeat)/r,0),varOperator=Math.max((msOp-msInt)/(np*r),0),varRepro=varOperator+varInteraction,varGRR=varRepeat+varRepro,varPart=Math.max((msPart-msInt)/(no*r),0),varTotal=varGRR+varPart,sd=x=>Math.sqrt(Math.max(x,0)),studyPct=varTotal>0?100*sd(varGRR)/sd(varTotal):0,tol=(Number.isFinite(Number(lsl))&&Number.isFinite(Number(usl))&&Number(usl)>Number(lsl))?Number(usl)-Number(lsl):null,tolerancePct=tol?100*(6*sd(varGRR))/tol:null,ndc=varGRR>0?Math.floor(1.41*sd(varPart)/sd(varGRR)):99;return {valid:true,n:clean.length,parts:np,operators:no,trials:r,grand,varRepeat,varOperator,varInteraction,varRepro,varGRR,varPart,varTotal,repeatability6s:6*sd(varRepeat),reproducibility6s:6*sd(varRepro),grr6s:6*sd(varGRR),studyPct,tolerancePct,ndc:Math.max(1,ndc),anova:{msPart,msOp,msInt,msRepeat}}}
function gageRRStudyStatus(s){if(s.status==='Approved')return '<span class="status good">✓ Approved</span>';if(s.status==='Review requested')return '<span class="status warn">● Review requested</span>';return '<span class="status neutral">— Draft</span>'}
function renderQualityMsa(){P.ensureEnterpriseModel(App.state);const rows=(App.state.gageRRStudies||[]).slice().sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||'')));return `<div class="quality-subhead"><div><span class="eyebrow">MEASUREMENT SYSTEM ANALYSIS</span><h2>Gage R&R studies</h2><p>Capability evidence is only decision-ready when the measurement system has an approved, matching MSA study. Studies are scoped by product/configuration, characteristic, method, process and gage/equipment.</p></div>${btn('+ New Gage R&R','data-new-gage-rr','button next-action')}</div><div class="section-stack">${rows.map(s=>{const r=s.result||{},prod=(App.state.products||[]).find(p=>p.id===s.productId);return `<div class="card msa-study-card"><div class="section-title-row"><div><span class="eyebrow">${esc(s.id)}</span><h3>${esc(s.title||s.characteristic||'Gage R&R')}</h3><div class="subtle">${esc(prod?.family||s.productId||'Unscoped')} · ${esc(s.configuration||'—')} · ${esc(s.characteristic||'—')} · ${esc((App.state.equipment||[]).find(e=>e.id===s.equipmentId)?.name||s.equipmentId||'—')}</div></div>${gageRRStudyStatus(s)}</div>${r.valid?`<div class="quality-cp-kpis"><div><strong>${r.studyPct.toFixed(1)}%</strong><span>GR&R · study variation</span></div><div><strong>${r.tolerancePct==null?'—':r.tolerancePct.toFixed(1)+'%'}</strong><span>GR&R · tolerance</span></div><div><strong>${r.ndc}</strong><span>ndc</span></div></div><div class="grid cols-3"><div class="score-row"><span>Repeatability 6σ</span><strong>${r.repeatability6s.toFixed(4)}</strong></div><div class="score-row"><span>Reproducibility 6σ</span><strong>${r.reproducibility6s.toFixed(4)}</strong></div><div class="score-row"><span>Design</span><strong>${r.parts} parts × ${r.operators} operators × ${r.trials} trials</strong></div></div>`:`<div class="callout bad"><strong>Study design invalid:</strong> ${esc(r.reason||'Recalculate study.')}</div>`}<div class="route-toolbar" style="margin-top:10px">${s.status==='Draft'?btn('Submit for review',`data-gage-review="${s.id}"`,'button small next-action'):''}${s.status==='Review requested'?btn('Approve MSA',`data-gage-approve="${s.id}"`,'button small next-action'):''}</div></div>`}).join('')||'<div class="card"><div class="empty">No Gage R&R study has been recorded yet.</div></div>'}</div>`}
function gageRRModal(){const products=App.state.products||[],equipment=App.state.equipment||[],processes=App.state.processes||[];openModal('New Gage R&R study',`<div class="callout"><h3>Crossed, balanced Gage R&R</h3><p>Paste one row per observation. Required columns: part, operator, trial, value. LabOS rejects an unbalanced design instead of producing a misleading GR&R.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Product</label><select id="grrProduct">${products.map(p=>`<option value="${p.id}">${esc(p.family)} · ${esc(p.partNumber)}</option>`).join('')}</select></div><div class="field"><label>Configuration</label><input id="grrConfig" placeholder="Exact configuration / revision"></div><div class="field"><label>Characteristic</label><input id="grrChar" placeholder="e.g. Calibration offset"></div><div class="field"><label>Measurement method</label><input id="grrMethod" placeholder="Controlled method / gauge method"></div><div class="field"><label>Process</label><select id="grrProcess"><option value="">Not process-specific</option>${processes.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.id)}</option>`).join('')}</select></div><div class="field"><label>Gage / equipment</label><select id="grrEquipment"><option value="">Select gage</option>${equipment.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select></div><div class="field"><label>LSL (optional)</label><input id="grrLsl" type="number" step="any"></div><div class="field"><label>USL (optional)</label><input id="grrUsl" type="number" step="any"></div><div class="field full"><label>Observations · part,operator,trial,value</label><textarea id="grrRows" rows="12" placeholder="P01,Operator A,1,0.012\nP01,Operator A,2,0.011\nP01,Operator B,1,0.013\n..."></textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Create study','data-save-gage-rr','button next-action')}`,true);setTimeout(()=>{$('[data-save-gage-rr]').onclick=async()=>{const lines=$('#grrRows').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),rows=lines.map(line=>{const p=line.split(/[,;\t]/).map(x=>x.trim());return {part:p[0],operator:p[1],trial:p[2],value:p[3]}}),lsl=$('#grrLsl').value===''?null:Number($('#grrLsl').value),usl=$('#grrUsl').value===''?null:Number($('#grrUsl').value),result=gageRRCalculate(rows,lsl,usl);if(!result.valid){toast(result.reason,true);return}const rec={id:P.uid('GRR'),title:`${$('#grrChar').value.trim()} · Gage R&R`,productId:$('#grrProduct').value,configuration:$('#grrConfig').value.trim(),characteristic:$('#grrChar').value.trim(),method:$('#grrMethod').value.trim(),processId:$('#grrProcess').value,equipmentId:$('#grrEquipment').value,lsl,usl,rows,result,status:'Draft',createdBy:App.state.identity.name,createdAt:P.now(),updatedAt:P.now()};if(!rec.configuration||!rec.characteristic||!rec.method||!rec.equipmentId){toast('Configuration, characteristic, measurement method and gage/equipment are required.',true);return}App.state.gageRRStudies.push(rec);P.audit(App.state,'Gage R&R study created','MSA',rec.id,'—','Draft',`${rec.characteristic} · ${result.parts} parts × ${result.operators} operators × ${result.trials} trials`);await persist();closeModal();App.filters.qualityTab='msa';render();toast('Gage R&R study created as Draft.')}},0)}
function requestGageReview(id){const s=(App.state.gageRRStudies||[]).find(x=>x.id===id);if(!s)return;s.status='Review requested';s.reviewRequestedBy=App.state.identity.name;s.reviewRequestedAt=P.now();P.audit(App.state,'Gage R&R submitted for review','MSA',id,'Draft','Review requested',App.state.identity.name);persist().then(()=>render())}
function approveGageRR(id){const s=(App.state.gageRRStudies||[]).find(x=>x.id===id);if(!s)return;if(s.status!=='Review requested'){toast('Submit the study for review first.',true);return}const self=App.state.settings?.separationOfDuties&&s.createdBy===App.state.identity.name&&currentRole()!=='administrator';if(self){toast('Separation of duties prevents the study author from approving the same MSA study.',true);return}if(!['administrator','quality','metrology','approver','lab_manager'].includes(currentRole())){toast('Switch to Quality, Metrology, Lab Manager or Approver / Reviewer.',true);return}openModal(`Approve Gage R&R · ${s.id}`,`<div class="callout"><h3>Independent MSA review</h3><p>Confirm study design, scope and measurement-system result. Approval makes this study available to matching capability populations.</p></div><div class="field"><label>Review conclusion / evidence <b>required</b></label><textarea id="grrApproveNote"></textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Approve MSA','data-confirm-grr-approve','button next-action')}`);setTimeout(()=>{$('[data-confirm-grr-approve]').onclick=async()=>{const note=$('#grrApproveNote').value.trim();if(!note){toast('Record the review conclusion.',true);return}s.status='Approved';s.approvedBy=App.state.identity.name;s.approvedAt=P.now();s.approvalRationale=note;P.audit(App.state,'Gage R&R approved','MSA',id,'Review requested','Approved',note);await persist();closeModal();render();toast('MSA study approved. Matching capability populations can now be decision-ready.')}},0)}
