/* REV 1.0.59 — AIAG-style MSA decision guidance, 5S KPI trends, closed-loop audit resolution, robust sign-off packages and audit-PDF formatting */
const GRR_POLICY_V1059={studyAccept:10,studyConditional:30,toleranceAccept:10,toleranceConditional:30,ndcMin:5,typicalParts:10,typicalOperators:2,typicalTrials:2};
function grrRecommendationV1059(s){
 const r=s?.result||{},uploaded=!!r.uploaded,checks=[];let hardReject=false,conditional=false;
 if(!r.valid){checks.push({label:'Study validity',state:'bad',value:'Invalid / incomplete'});hardReject=true}
 const parts=Number(r.parts),ops=Number(r.operators),trials=Number(r.trials);
 if(!uploaded){
  const designOk=parts>=GRR_POLICY_V1059.typicalParts&&ops>=GRR_POLICY_V1059.typicalOperators&&trials>=GRR_POLICY_V1059.typicalTrials;
  checks.push({label:'Typical study design',state:designOk?'good':'warn',value:`${parts||0} parts × ${ops||0} operators × ${trials||0} trials`});
  if(!designOk)conditional=true;
 }else{checks.push({label:'Study design',state:'warn',value:'Verify in uploaded controlled study'});conditional=true;}
 const sv=Number(r.studyPct);if(Number.isFinite(sv)){
  const st=sv<GRR_POLICY_V1059.studyAccept?'good':sv<=GRR_POLICY_V1059.studyConditional?'warn':'bad';
  checks.push({label:'Total Gage R&R · %Study Var',state:st,value:`${sv.toFixed(1)}%`});if(st==='bad')hardReject=true;else if(st==='warn')conditional=true;
 }else{checks.push({label:'Total Gage R&R · %Study Var',state:'bad',value:'Not recorded'});hardReject=true}
 const tp=Number(r.tolerancePct);if(Number.isFinite(tp)){
  const st=tp<GRR_POLICY_V1059.toleranceAccept?'good':tp<=GRR_POLICY_V1059.toleranceConditional?'warn':'bad';
  checks.push({label:'Total Gage R&R · %Tolerance',state:st,value:`${tp.toFixed(1)}%`});if(st==='bad')hardReject=true;else if(st==='warn')conditional=true;
 }else checks.push({label:'%Tolerance',state:'neutral',value:'Not evaluated · no valid tolerance supplied'});
 const ndc=Number(r.ndc);if(Number.isFinite(ndc)){
  const st=ndc>=GRR_POLICY_V1059.ndcMin?'good':'bad';checks.push({label:'Number of distinct categories (ndc)',state:st,value:String(ndc)});if(st==='bad')hardReject=true;
 }else{checks.push({label:'Number of distinct categories (ndc)',state:'bad',value:'Not recorded'});hardReject=true}
 let recommend='APPROVE',level='good',headline='System recommendation: APPROVE for the stated measurement use',reason='The recorded quantitative indicators meet the default AIAG-style automotive acceptance guidance.';
 if(hardReject){recommend='REJECT';level='bad';headline='System recommendation: REJECT for the stated measurement use';reason='One or more measurement-system indicators are outside the default automotive acceptance guidance or are missing.'}
 else if(conditional){recommend='REJECT';level='warn';headline='System recommendation: REJECT unless the application justifies conditional acceptance';reason='At least one result is marginal or the study design is below the typical default. A controlled user approval is still possible with explicit risk/application rationale.'}
 return {recommend,level,headline,reason,conditional,hardReject,checks,policy:'AIAG-style default guidance for IATF 16949 workflows; customer-specific requirements and the intended measurement application take precedence.'};
}
function grrRecommendationHtmlV1059(s,{compact=false}={}){const q=grrRecommendationV1059(s),rows=q.checks.map(x=>`<div class="grr-rule-row ${x.state}"><span>${esc(x.label)}</span><strong>${esc(x.value)}</strong></div>`).join('');return `<div class="grr-recommendation ${q.level} ${compact?'compact':''}"><div class="grr-recommendation-head"><span class="grr-decision-icon">${q.recommend==='APPROVE'?'✓':'✕'}</span><div><strong>${esc(q.headline)}</strong><small>${esc(q.reason)}</small></div></div>${compact?'':`<div class="grr-rule-grid">${rows}</div><small class="grr-policy-note">${esc(q.policy)} Default guide: &lt;10% acceptable; 10–30% application-dependent; &gt;30% unacceptable; ndc ≥5. Typical study design is 10 parts with 2–3 operators and 2–3 repeated trials.</small>`}</div>`}
function grrDecisionReadyV1059(s){if(!s||s.status!=='Approved')return false;if(s.userDecision)return s.userDecision==='Approve';const c=String(s.conclusion||'').toLowerCase();return c==='acceptable'}
matchingMsa=function(a){return (App.state.gageRRStudies||[]).find(s=>grrDecisionReadyV1059(s)&&s.productId===a.ctx.productId&&s.configuration===a.ctx.configuration&&(!s.processId||s.processId===a.ctx.processId)&&s.equipmentId===a.ctx.equipmentId&&String(s.characteristic).trim().toLowerCase()===String(a.characteristic).trim().toLowerCase()&&String(s.method).trim().toLowerCase()===String(a.method).trim().toLowerCase())||null};
gageRRStudyStatus=function(s){if(s.status==='Approved')return '<span class="status good">✓ User approved</span>';if(s.status==='Rejected')return '<span class="status bad">✕ User rejected</span>';if(s.status==='Review requested')return '<span class="status warn">● Decision required</span>';return '<span class="status neutral">— Draft</span>'};

renderQualityMsa=function(){
 P.ensureEnterpriseModel(App.state);const rows=(App.state.gageRRStudies||[]).slice().sort((a,b)=>String(msaStudyDateV1057(b)||b.updatedAt||'').localeCompare(String(msaStudyDateV1057(a)||a.updatedAt||''))),approved=rows.filter(x=>x.status==='Approved'),rejected=rows.filter(x=>x.status==='Rejected'),pending=rows.filter(x=>['Draft','Review requested'].includes(x.status));
 const guide=`<div class="card msa-rule-guide"><span class="eyebrow">AUTOMOTIVE MSA DECISION GUIDE</span><h2>LabOS recommends; the authorised reviewer decides</h2><p>For variable crossed Gage R&R, LabOS uses conservative AIAG-style defaults commonly used in IATF 16949 environments. Customer-specific requirements or the intended measurement risk can require a different decision.</p><div class="grr-threshold-strip"><div class="good"><strong>&lt;10%</strong><span>Generally acceptable</span></div><div class="warn"><strong>10–30%</strong><span>Application-dependent</span></div><div class="bad"><strong>&gt;30%</strong><span>Generally unacceptable</span></div><div><strong>ndc ≥5</strong><span>Expected discrimination</span></div></div><small>Typical study setup: 10 parts, 2–3 operators, 2–3 repeated trials, crossed and balanced. The final Approve/Reject decision is retained separately from the system recommendation.</small></div>`;
 const cards=rows.map(s=>{const r=s.result||{},proc=(App.state.processes||[]).find(x=>x.id===s.processId),test=(App.state.standardTests||[]).find(x=>x.id===s.standardTestId),eq=(App.state.equipment||[]).find(x=>x.id===s.equipmentId),source=s.sourceType||'LabOS calculated',q=grrRecommendationV1059(s),decision=s.userDecision?`<div class="grr-user-decision ${s.userDecision==='Approve'?'good':'bad'}"><strong>User decision: ${esc(s.userDecision.toUpperCase())}</strong><span>${esc(s.decisionRationale||s.approvalRationale||'Decision rationale retained')}</span>${s.decisionOverride?'<small>Controlled override of the LabOS recommendation</small>':''}</div>`:'';return `<div class="card msa-study-card"><div class="section-title-row"><div><span class="eyebrow">${esc(s.id)} · ${esc(source)}</span><h3>${esc(s.title||s.characteristic||'MSA / Gage R&R')}</h3><div class="subtle">Study date ${P.formatDate(msaStudyDateV1057(s))} · ${esc(s.characteristic||'—')} · ${esc(s.method||'—')}</div></div>${gageRRStudyStatus(s)}</div><div class="msa-link-grid">${proc?`<button class="msa-object-link" data-process="${esc(proc.id)}"><span>Process</span><strong>${esc(proc.name)}</strong><small>${esc(proc.id)} · Rev ${esc(proc.revision)}</small></button>`:''}${test?`<button class="msa-object-link" data-v1057-standard-test="${esc(test.id)}"><span>Standard test</span><strong>${esc(test.name)}</strong><small>${esc(test.id)} · Rev ${esc(test.revision)}</small></button>`:''}${eq?`<button class="msa-object-link" data-v1057-equipment="${esc(eq.id)}"><span>Gage / equipment</span><strong>${esc(eq.name)}</strong><small>${esc(eq.id)}</small></button>`:''}</div>${r.valid?`<div class="quality-cp-kpis"><div><strong>${r.studyPct==null?'—':Number(r.studyPct).toFixed(1)+'%'}</strong><span>GR&R · study variation</span></div><div><strong>${r.tolerancePct==null?'—':Number(r.tolerancePct).toFixed(1)+'%'}</strong><span>GR&R · tolerance</span></div><div><strong>${r.ndc??'—'}</strong><span>ndc</span></div></div>`:`<div class="callout bad"><strong>Study result incomplete</strong><p>${esc(r.reason||'Required analysis values are not available.')}</p></div>`}${grrRecommendationHtmlV1059(s)}${decision}${r.uploaded?`<div class="score-row"><span>Uploaded evidence</span><strong>${evidenceDocumentLink(s,'Open MSA document')}</strong></div>`:''}<div class="route-toolbar" style="margin-top:10px">${s.status==='Draft'?btn('Submit for decision',`data-gage-review="${s.id}"`,'button small next-action'):''}${s.status==='Review requested'?btn('Make Approve / Reject decision',`data-gage-approve="${s.id}"`,'button small next-action'):''}${btn('Run follow-up Gage R&R',`data-v1057-run-grr="study|${s.id}"`,'button small secondary')}</div></div>`}).join('');
 return `<div class="quality-subhead"><div><span class="eyebrow">MEASUREMENT SYSTEM ANALYSIS</span><h2>MSA / Gage R&R evidence</h2><p>Measurement-system evidence stays linked to the exact process/test, gage, characteristic and application. System guidance never silently becomes the human approval.</p></div><div class="route-toolbar">${btn('+ Run Gage R&R','data-new-gage-rr','button next-action')}${btn('Upload MSA / Gage R&R','data-v1057-upload-msa','button secondary')}</div></div><div class="grid cols-3"><div class="mini-kpi"><span>User approved</span><strong>${approved.length}</strong></div><div class="mini-kpi"><span>Awaiting decision</span><strong>${pending.length}</strong></div><div class="mini-kpi"><span>User rejected</span><strong>${rejected.length}</strong></div></div><div style="height:12px"></div>${guide}<div class="section-stack">${cards||'<div class="card"><div class="empty">No MSA / Gage R&R evidence has been recorded yet.</div></div>'}</div>`;
};

gageRRModal=function(seed={}){
 seed=gageRRSeedV1057(seed);const products=App.state.products||[],equipment=App.state.equipment||[],processes=App.state.processes||[],tests=App.state.standardTests||[];
 openModal('Run guided Gage R&R',`<div class="callout"><h3>Crossed, balanced variable Gage R&R</h3><p>Use representative parts that span the actual process range and randomise the measurement sequence where practical. LabOS calculates the study, applies default automotive guidance and sends the result to an authorised human decision.</p></div><div class="grr-design-guide"><strong>Typical automotive study design</strong><span>10 parts · 2–3 operators · 2–3 repeated trials · every part/operator combination present</span><small>IATF 16949 requires measurement-system analysis for applicable measurement systems but does not impose one universal sample count or acceptance threshold; customer-specific requirements take precedence.</small></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Study date</label><input id="grrStudyDate" type="date" value="${esc(seed.studyDate||P.todayISO())}"></div><div class="field"><label>Product</label><select id="grrProduct"><option value="">Generic / not product-specific</option>${products.map(p=>`<option value="${p.id}" ${seed.productId===p.id?'selected':''}>${esc(p.family)} · ${esc(p.partNumber)}</option>`).join('')}</select></div><div class="field"><label>Configuration / revision</label><input id="grrConfig" value="${esc(seed.configuration||'')}" placeholder="Applicable configuration"></div><div class="field"><label>Characteristic</label><input id="grrChar" value="${esc(seed.characteristic||'')}" placeholder="e.g. Calibration offset"></div><div class="field"><label>Measurement method</label><input id="grrMethod" value="${esc(seed.method||'')}" placeholder="Controlled method / gage method"></div><div class="field"><label>Process link</label><select id="grrProcess"><option value="">Not process-specific</option>${processes.map(p=>`<option value="${p.id}" ${seed.processId===p.id?'selected':''}>${esc(p.name)} · ${esc(p.id)}</option>`).join('')}</select></div><div class="field"><label>Standard Test link</label><select id="grrTest"><option value="">Not test-specific</option>${tests.map(t=>`<option value="${t.id}" ${seed.standardTestId===t.id?'selected':''}>${esc(t.name)} · ${esc(t.id)}</option>`).join('')}</select></div><div class="field"><label>Gage / equipment</label><select id="grrEquipment"><option value="">Select gage</option>${equipment.map(e=>`<option value="${e.id}" ${seed.equipmentId===e.id?'selected':''}>${esc(e.name)} · ${esc(e.id)}</option>`).join('')}</select></div><div class="field"><label>LSL (optional)</label><input id="grrLsl" type="number" step="any" value="${seed.lsl??''}"></div><div class="field"><label>USL (optional)</label><input id="grrUsl" type="number" step="any" value="${seed.usl??''}"></div><div class="field full"><label>Observations · part,operator,trial,value</label><textarea id="grrRows" rows="12" placeholder="P01,Operator A,1,0.012\nP01,Operator A,2,0.011\nP01,Operator B,1,0.013\n..."></textarea><small>LabOS will calculate a smaller balanced design, but the recommendation will flag a design below the typical automotive default.</small></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Calculate & save study','data-v1059-save-grr','button next-action')}`,true);
 setTimeout(()=>{$('[data-v1059-save-grr]').onclick=async()=>{const lines=$('#grrRows').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),rows=lines.map(line=>{const q=line.split(/[,;\t]/).map(x=>x.trim());return {part:q[0],operator:q[1],trial:q[2],value:q[3]}}),lsl=$('#grrLsl').value===''?null:Number($('#grrLsl').value),usl=$('#grrUsl').value===''?null:Number($('#grrUsl').value),result=gageRRCalculate(rows,lsl,usl);if(!result.valid){toast(result.reason,true);return}const processId=$('#grrProcess').value,standardTestId=$('#grrTest').value,equipmentId=$('#grrEquipment').value,characteristic=$('#grrChar').value.trim(),method=$('#grrMethod').value.trim(),studyDate=$('#grrStudyDate').value;if(!studyDate||!characteristic||!method||!equipmentId||(!processId&&!standardTestId)){toast('Study date, characteristic, method, gage/equipment and at least one process or Standard Test link are required.',true);return}const rec={id:P.uid('GRR'),title:`${characteristic} · Gage R&R`,productId:$('#grrProduct').value,configuration:$('#grrConfig').value.trim(),characteristic,method,processId,standardTestId,equipmentId,lsl,usl,rows,result,status:'Draft',sourceType:'LabOS calculated',conclusion:result.studyPct<10?'Acceptable':result.studyPct<=30?'Conditionally acceptable':'Not acceptable',studyDate,createdBy:App.state.identity.name,createdAt:P.now(),updatedAt:P.now(),fileData:null,documentUploaded:false};const recm=grrRecommendationV1059(rec);rec.systemRecommendation=recm.recommend;rec.systemRecommendationReason=recm.reason;App.state.gageRRStudies.push(rec);P.audit(App.state,'Gage R&R study created','MSA',rec.id,'—','Draft',`${rec.characteristic} · ${result.parts} parts × ${result.operators} operators × ${result.trials} trials · system ${recm.recommend}`);await persist();closeModal();App.currentView='quality';App.filters.qualityTab='msa';render();toast(`Gage R&R saved. LabOS recommendation: ${recm.recommend}. Submit it for the authorised user decision.`)}},0)
};

approveGageRR=function(id){
 const s=(App.state.gageRRStudies||[]).find(x=>x.id===id);if(!s)return;if(s.status!=='Review requested'){toast('Submit the study for decision first.',true);return}const self=App.state.settings?.separationOfDuties&&s.createdBy===App.state.identity.name&&currentRole()!=='administrator';if(self){toast('Separation of duties prevents the study author from making the final MSA decision.',true);return}if(!['administrator','quality','metrology','approver','lab_manager'].includes(currentRole())){toast('Switch to Quality, Metrology, Lab Manager or Approver / Reviewer.',true);return}const q=grrRecommendationV1059(s);
 openModal(`MSA decision · ${s.id}`,`${grrRecommendationHtmlV1059(s)}<div class="callout"><strong>Final decision belongs to the authorised reviewer</strong><p>Review the raw study or uploaded evidence, intended use, characteristic risk and applicable customer-specific requirement. You may approve against the system recommendation, but the override rationale is retained explicitly.</p></div><div class="score-row"><span>Study date</span><strong>${P.formatDate(msaStudyDateV1057(s))}</strong></div><div class="score-row"><span>Linked use</span><strong>${esc(msaScopeLabelV1057(s))}</strong></div><div class="field"><label>Decision rationale / evidence <b>required</b></label><textarea id="grrDecisionNote" placeholder="Why is this measurement system acceptable or not acceptable for this intended use?"></textarea></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Reject for intended use','data-v1059-grr-decision="Reject"','button blocker-action')}${btn('Approve for intended use','data-v1059-grr-decision="Approve"','button next-action')}`,true);
 setTimeout(()=>{$$('[data-v1059-grr-decision]').forEach(b=>b.onclick=async()=>{const decision=b.dataset.v1059GrrDecision,note=$('#grrDecisionNote').value.trim(),override=(decision.toUpperCase()!==q.recommend);if(!note){toast('Record the decision rationale.',true);return}if(override&&note.length<20){toast('An override of the LabOS recommendation requires an explicit rationale of at least 20 characters.',true);return}s.userDecision=decision;s.status=decision==='Approve'?'Approved':'Rejected';s.conclusion=decision==='Approve'?(q.conditional||q.hardReject?'Conditionally acceptable':'Acceptable'):'Not acceptable';s.systemRecommendation=q.recommend;s.recommendationAtDecision=q.recommend;s.decisionOverride=override;s.decisionRationale=note;s.approvalRationale=note;s.approvedBy=App.state.identity.name;s.approvedAt=P.now();s.updatedAt=P.now();P.audit(App.state,`MSA ${decision.toLowerCase()} decision`,'MSA',id,'Review requested',s.status,`${override?'Override · ':''}system ${q.recommend} · ${note}`);await persist();closeModal();render();toast(`MSA decision recorded: ${decision.toUpperCase()}${override?' · controlled override retained':''}.`,decision==='Reject')})},0)
};

