function overlapV1061(a,b,c,d){return new Date(a)<new Date(d)&&new Date(c)<new Date(b)}
function bookingSlotFeasibleV1061(booking,start,ignoreIds=new Set()){const st=new Date(start),en=new Date(st.getTime()+Number(booking.durationHours||1)*3600000);if([0,6].includes(st.getDay())||st.getHours()<8||en.getHours()>17||(en.getHours()===17&&en.getMinutes()>0))return false;for(const b of App.state.bookings||[]){if(ignoreIds.has(b.id)||b.id===booking.id)continue;if((booking.equipmentId&&b.equipmentId===booking.equipmentId)||(booking.staffId&&b.staffId===booking.staffId)){if(overlapV1061(st,en,b.start,b.end))return false}}for(const c of App.state.resourceCareBookings||[]){if(c.status!=='Scheduled')continue;if((booking.equipmentId&&c.equipmentId===booking.equipmentId)||(booking.staffId&&c.staffId===booking.staffId)){if(overlapV1061(st,en,c.start,c.end))return false}}for(const ev of App.state.planningEvents||[]){if(ev.active===false)continue;const affects=ev.scope==='lab'||(ev.scope==='staff'&&ev.staffId===booking.staffId)||(ev.scope==='equipment'&&ev.equipmentId===booking.equipmentId);if(affects&&overlapV1061(st,en,ev.start,ev.end))return false}return true}
function feasibleSlotsV1061(booking,limit=24,fromDate=null,ignoreIds=new Set()){const out=[],base=fromDate?new Date(fromDate):new Date();base.setMinutes(0,0,0);if(base.getHours()<8)base.setHours(8);for(let i=0;i<24*100&&out.length<limit;i++){const d=new Date(base.getTime()+i*3600000);if(d.getHours()<8||d.getHours()>16)continue;if(bookingSlotFeasibleV1061(booking,d,ignoreIds))out.push(d.toISOString())}return out}
function showFeasibleSlotsV1061(booking){let panel=$('#dragFeasibleSlotsV1061');if(panel)panel.remove();const reqBookings=(App.state.bookings||[]).filter(b=>b.requestId===booking.requestId).sort((a,b)=>new Date(a.start)-new Date(b.start)),idx=reqBookings.findIndex(b=>b.id===booking.id),prev=idx>0?reqBookings[idx-1]:null,ignore=new Set(reqBookings.slice(idx).map(b=>b.id)),slots=feasibleSlotsV1061(booking,24,prev?.end||new Date(),ignore);const root=$('.planning-visual-main')||$('#page');root.insertAdjacentHTML('afterbegin',`<div id="dragFeasibleSlotsV1061" class="drag-feasible-panel"><div><strong>Feasible slots · ${esc(booking.stepName||'selected step')}</strong><small>Only times currently feasible for ${esc(App.state.equipment.find(e=>e.id===booking.equipmentId)?.name||'assigned equipment')} + ${esc(App.state.staff.find(s=>s.id===booking.staffId)?.name||'assigned person')}. Drop onto a slot; dependent work will then be replanned.</small></div><div class="drag-slot-grid">${slots.map(s=>`<div class="drag-slot" data-v1061-drop-slot="${esc(s)}">${P.formatDateTime(s)}</div>`).join('')||'<div class="callout bad">No feasible slot found in the next planning horizon.</div>'}</div></div>`)}
function hideFeasibleSlotsV1061(){setTimeout(()=>$('#dragFeasibleSlotsV1061')?.remove(),120)}
async function moveBookingAndReplanV1061(id,start){const b=(App.state.bookings||[]).find(x=>x.id===id);if(!b)return;const req=(App.state.bookings||[]).filter(x=>x.requestId===b.requestId).sort((a,c)=>new Date(a.start)-new Date(c.start)),idx=req.findIndex(x=>x.id===id);if(idx<0)return;const moving=req.slice(idx),ignore=new Set(moving.map(x=>x.id)),before=P.deepClone(req),newTimes=[];let cursor=new Date(start);for(let i=0;i<moving.length;i++){const x=moving[i],slots=feasibleSlotsV1061(x,1,cursor,ignore);if(!slots.length){toast(`Cannot replan ${x.stepName||x.id}: no feasible downstream slot found.`,true);return}const st=new Date(slots[0]),en=new Date(st.getTime()+Number(x.durationHours||1)*3600000);newTimes.push([x,st.toISOString(),en.toISOString()]);cursor=new Date(en.getTime()+30*60000)}for(const [x,st,en] of newTimes){x.start=st;x.end=en;const route=(App.state.routes||[]).find(r=>r.requestId===x.requestId),step=route?.steps?.find(s=>s.id===x.stepId);if(step){step.planned=st;step.equipmentId=x.equipmentId;step.owner=App.state.staff.find(s=>s.id===x.staffId)?.name||step.owner}}const r=requestById(b.requestId),last=newTimes[newTimes.length-1];if(r&&last){r.forecastDate=last[2].slice(0,10);r.pendingReplanContext={reasonCategory:'Manual planning adjustment',reason:`${b.stepName||b.id} moved by drag-and-drop; dependent work automatically replanned to earliest feasible slots.`,createdAt:P.now()}}P.audit(App.state,'Planning step moved and downstream work replanned','Request',b.requestId,before.map(x=>`${x.stepName}:${x.start}`).join(' | '),newTimes.map(([x,s])=>`${x.stepName}:${s}`).join(' | '),'Drag-and-drop constrained replan');await persist();render();toast(`${b.stepName||'Step'} moved; ${Math.max(0,moving.length-1)} dependent task${moving.length===2?'':'s'} replanned.`)}
