function installV1061Listeners(){if(App._v1061Listeners)return;App._v1061Listeners=true;document.addEventListener('dragover',e=>{const slot=e.target.closest?.('[data-v1061-drop-slot]');if(slot){e.preventDefault();slot.classList.add('drag-over')}});document.addEventListener('dragleave',e=>e.target.closest?.('[data-v1061-drop-slot]')?.classList.remove('drag-over'));document.addEventListener('drop',e=>{const slot=e.target.closest?.('[data-v1061-drop-slot]');if(slot&&App.dragBookingV1061){e.preventDefault();const id=App.dragBookingV1061;App.dragBookingV1061=null;moveBookingAndReplanV1061(id,slot.dataset.v1061DropSlot)}});document.addEventListener('click',e=>{const t=e.target.closest?.('[data-v1061-complete-request],[data-admin-build-action],[data-v1061-abort-archive],[data-v1061-archive-manager],[data-v1061-assurance-report],[data-v1061-care-type],[data-v1061-horizon],[data-v1061-scope-equipment],[data-v1061-std-jump],[data-v1061-open-ehs],[data-v1061-save-notify]');if(!t)return;if(t.dataset.v1061CompleteRequest){completeRequesterInputV1061(t.dataset.v1061CompleteRequest);return}if(t.dataset.adminBuildAction){adminBuildActionModalV1061(t.dataset.adminBuildAction);return}if(t.dataset.v1061AbortArchive){abortArchiveBuildV1061(t.dataset.v1061AbortArchive);return}if(t.hasAttribute('data-v1061-archive-manager')){archiveManagerV1061();return}if(t.hasAttribute('data-v1061-assurance-report')){assuranceReportModalV1061();return}if(t.dataset.v1061CareType){App.filters.careTypeV1061=t.dataset.v1061CareType;render();return}if(t.dataset.v1061Horizon){App.filters.careHorizonV1061=t.dataset.v1061Horizon;render();return}if(t.dataset.v1061ScopeEquipment){App.filters.careScopeV1061=t.dataset.v1061ScopeEquipment;render();return}if(t.dataset.v1061StdJump){document.querySelector(`#std-${CSS.escape(t.dataset.v1061StdJump)}`)?.scrollIntoView({behavior:'smooth',block:'start'});return}if(t.dataset.v1061OpenEhs){const [kind,id]=t.dataset.v1061OpenEhs.split('|');governanceDocsModal(kind==='Equipment'?'equipment':kind==='Process'?'process':'test',id);return}if(t.hasAttribute('data-v1061-save-notify')){const cfg=App.state.settings.resourceAssuranceNotifications;cfg.enabled=$('#v1061NotifyEnabled').checked;cfg.amount=Math.max(1,Number($('#v1061NotifyAmount').value||6));cfg.unit=$('#v1061NotifyUnit').value;persist().then(()=>{render();toast('Resource assurance notification rule saved.')});return}},true)}
