  const assigned=(App.state.equipment||[]).find(e=>e.id===booking.equipmentId);
  if(assigned&&!eqs.some(e=>e.id===assigned.id)&&(!req.capability||(P.equipmentPlanningCapability?P.equipmentPlanningCapability(assigned):assigned.capability)===req.capability))eqs.unshift(assigned);
  return eqs;
