function halfDayLabelV1066(input){
  const d=new Date(input); if(Number.isNaN(d.getTime()))return '—';
  const part=d.getHours()<13?'Morning':'Afternoon';
  return `${d.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'})} · ${part}`;
}
function halfDayShortV1066(input){const d=new Date(input);return d.getHours()<13?'AM':'PM'}
function halfDayStartV1066(date,part='AM'){const d=new Date(date);d.setHours(part==='PM'?13:8,0,0,0);return d}
