acceptPlanProposal=async function(){const pp=App.pendingPlanProposal;if(!pp)return;const note=$('#planProposalNote')?.value.trim();if(!note){toast('A planning decision rationale is required.',true);return}const currentIdentity=P.deepClone(App.state.identity),next=P.deepClone(pp.proposedState);next.identity=currentIdentity;for(const m of pp.commitMoves||[]){const r=(next.requests||[]).find(x=>x.id===m.id);if(!r||!r.forecastDate)continue;try{P.recordCommitment(next,r,r.forecastDate,{reasonCategory:m.category||'Capacity / congestion',reason:`${note} ${m.reason||''}`.trim(),eventId:m.eventId||null});r.pendingReplanContext=null}catch(e){toast(`${m.id}: ${e.message}`,true);return}}P.audit(next,pp.mode==='portfolio'?'Portfolio plan and commitment decision accepted':'Plan and commitment decision accepted','Planning',pp.mode==='portfolio'?'PORTFOLIO':pp.requestIds[0],'Proposed','Applied',`${note} · ${(pp.commitMoves||[]).length} committed-date movement(s) recorded in the same decision.`);App.state=next;App.identity=new P.DemoIdentityProvider(App.state);populateRoles();App.state.settings=App.state.settings||{};App.state.settings.planningNeedsReview=false;App.pendingPlanProposal=null;await persist();closeModal();render();toast('Reviewed plan applied. Any shown committed-date movements were recorded in the same decision; no second approval is required.')};

