function careActionRolesV130(type){const t=String(type||'');if(/Calibration/i.test(t))return ['metrology','lab_manager','administrator'];if(/Maintenance/i.test(t))return ['lab_manager','metrology','administrator'];if(/Training/i.test(t))return ['lab_manager','administrator'];return ['lab_manager','administrator']}
