roleWorkHubV1071=function(){
  const mine=[...openActions()].sort((a,b)=>(a.severity==='bad'?0:a.severity==='warn'?1:2)-(b.severity==='bad'?0:b.severity==='warn'?1:2)||String(a.due||'').localeCompare(String(b.due||''))),me=String(App.state.identity?.name||'').trim(),proposals=new P.ImprovementService().forIdentity(App.state),readiness=myWorkReadinessRowsV1072();
  const mandatory=mine.slice(0,10).map(a=>{const m=myWorkActionTextV1072(a);return `<article class="my-work-card-v1072 ${a.severity==='bad'?'bad':a.severity==='warn'?'warn':'neutral'}"><div class="my-work-card-top-v1072"><span>${a.severity==='bad'?'✕':a.severity==='warn'?'●':'•'}</span><strong>${esc(m.project)}</strong></div><div class="my-work-action-v1072"><b>Action</b><span>${esc(m.action)}</span></div><div class="my-work-owner-v1072"><b>Owner</b><span>${esc(m.owner)}</span>${a.due?`<small>Due ${P.formatDate(a.due)}</small>`:''}</div>${btn('Open',a.id?`data-resolve-action="${esc(a.id)}"`:`data-nav="${esc(a.resolve||'dashboard')}"`,'button tiny primary')}</article>`}).join('');
  const readinessHtml=readiness.slice(0,6).map(x=>`<article class="my-work-card-v1072 readiness"><div class="my-work-card-top-v1072"><span>◷</span><strong>${esc(x.type)} · ${esc(x.target)}</strong></div><div class="my-work-action-v1072"><b>Action</b><span>${esc(/Training/i.test(x.type)?'Ensure the team member completes the planned training before dependent work.':`Complete the planned ${String(x.type||'readiness').toLowerCase()} and return the resource to service.`)}</span></div><div class="my-work-owner-v1072"><b>Owner</b><span>${esc(x.owner)}</span><small>${halfDayLabelV1066(x.start)}</small></div>${btn('Open','data-nav="equipment-master"','button tiny secondary')}</article>`).join('');
  const improve=proposals.slice(0,4).map(x=>`<article class="my-work-card-v1072 improvement"><div class="my-work-card-top-v1072"><span>↗</span><strong>${esc(x.title)}</strong></div><div class="my-work-action-v1072"><b>Action</b><span>${esc(x.impact||x.proposal||'Review and decide whether to implement this improvement.')}</span></div><div class="my-work-owner-v1072"><b>Owner</b><span>${esc(x.owner||me||'Unassigned')}</span></div>${btn('Review',`data-improvement="${esc(x.id)}"`,'button tiny secondary')}</article>`).join('');
  const total=mine.length+readiness.length;
  return `<section id="myWorkHubV1071" class="card my-work-hub-v1071"><div class="section-title-row"><div><span class="eyebrow">MY WORK</span><h2>Actions that require a decision or completion</h2><p class="subtle">This is different from Upcoming Delivery: <b>My Work tells you what must be done, for which build/resource and by whom</b>. Upcoming Delivery only shows when builds are due.</p></div><span class="pill">${total} mandatory</span></div><div class="my-work-cards-v1072">${mandatory||readinessHtml?mandatory+readinessHtml:'<div class="empty compact">✓ No mandatory action is currently assigned to you.</div>'}</div>${improve?`<details class="fold compact"><summary>Improvement opportunities assigned to you (${proposals.length})</summary><div class="my-work-cards-v1072">${improve}</div></details>`:''}</section>`;
};

function capacityCardV1072(){
  const mode=App.filters.capacityModeV1072||'weeks',period=App.filters.capacityPeriodV1072||'current',buckets=opsPeriodBuckets(mode),bucket=buckets[period==='past'?0:period==='next'?2:1],rows=operationalRows(),build=rows.filter(x=>x.request&&inWindow(x.start,bucket.start,bucket.end)),care=rows.filter(x=>x.source==='readiness'&&inWindow(x.start,bucket.start,bucket.end)),cap=opsCapacityForPeriod(bucket),peopleLoad=sumHours(build.filter(x=>x.person&&x.person!=='Unassigned')),eqLoad=sumHours(build.filter(x=>x.equipment&&x.equipment!=='Unassigned'&&x.equipment!=='—')),pp=opsPct(peopleLoad,cap.peopleHours),ep=opsPct(eqLoad,cap.equipmentHours),pctClass=v=>v>100?'bad':v>85?'warn':'good';
  const pMap=new Map(),eMap=new Map();for(const x of build){if(x.person&&x.person!=='Unassigned')pMap.set(x.person,(pMap.get(x.person)||0)+x.duration);if(x.equipment&&x.equipment!=='Unassigned'&&x.equipment!=='—')eMap.set(x.equipment,(eMap.get(x.equipment)||0)+x.duration)}
  const bottlenecks=[...pMap].map(([name,h])=>({name,h,type:'Person',u:100*h/Math.max(1,Number(App.state.settings?.capacity?.productiveStaffHoursPerWeek||32)*(mode==='months'?4.3:1))})).concat([...eMap].map(([name,h])=>({name,h,type:'Equipment',u:100*h/Math.max(1,Number(App.state.settings?.capacity?.equipmentHoursPerWeek||60)*(mode==='months'?4.3:1))}))).sort((a,b)=>b.u-a.u).slice(0,5);
  const bar=(label,pct,h,c)=>`<div class="dash-load"><div><strong>${label}</strong><span>${Math.round(pct)}%</span></div><div class="dash-load-track"><i style="width:${Math.min(100,pct)}%" class="${pctClass(pct)}"></i></div><small>${h.toFixed(1)} / ${c.toFixed(1)} h</small></div>`;
  return `<div class="card dash-cap-card v1072-capacity"><div class="section-title-row"><div><span class="eyebrow">CAPACITY</span><h2>Immediate workload & bottlenecks</h2><div class="subtle">${esc(bucket.label)} · ${esc(bucket.dateLabel)} · ${v1072WeekendsEnabled()?'weekends included':'weekdays only'}</div></div><div class="capacity-period-controls-v1072"><select id="capacityModeV1072"><option value="weeks" ${mode==='weeks'?'selected':''}>Week</option><option value="months" ${mode==='months'?'selected':''}>Month</option></select><select id="capacityPeriodV1072"><option value="past" ${period==='past'?'selected':''}>Last</option><option value="current" ${period==='current'?'selected':''}>Current</option><option value="next" ${period==='next'?'selected':''}>Next</option></select></div></div><div class="capacity-summary-grid-v1072">${bar('People',pp,peopleLoad,cap.peopleHours)}${bar('Equipment',ep,eqLoad,cap.equipmentHours)}<div class="capacity-readiness-v1072"><strong>Readiness load</strong><span>${sumHours(care).toFixed(1)} h</span><small>calibration · maintenance · training</small></div></div><div class="capacity-bottlenecks-v1072"><strong>Key bottlenecks</strong>${bottlenecks.map(x=>`<span class="${pctClass(x.u)}"><b>${esc(x.name)}</b><small>${esc(x.type)} · ${x.h.toFixed(1)} h · ${Math.round(x.u)}%</small></span>`).join('')||'<span><b>No bottleneck</b><small>No assigned workload in this period.</small></span>'}</div></div>`;
}
function installMyWorkLayoutV1072(){
  if(App.currentView!=='dashboard')return;
  const hub=document.getElementById('myWorkHubV1071'),daily=document.querySelector('.daily-ops-card');if(hub&&daily&&hub.nextElementSibling!==daily)hub.after(daily);
  document.querySelector('[data-dashboard-kpi]')?.remove();
  daily?.querySelector('[data-nav="action-centre"]')?.remove();
  document.querySelector('.dash-action-card')?.remove();
  const cap=document.querySelector('.dash-cap-card');if(cap)cap.outerHTML=capacityCardV1072();
  if(currentRole()==='lab_manager'){const potential=[...document.querySelectorAll('.card')].find(c=>/POTENTIAL PROJECTS/i.test(c.textContent||''));potential?.remove()}
  const up=[...document.querySelectorAll('.card')].find(c=>/UPCOMING DELIVERY/i.test(c.textContent||''));if(up){const h=up.querySelector('.section-title-row .subtle');if(!h){const title=up.querySelector('.section-title-row>div');title?.insertAdjacentHTML('beforeend','<div class="subtle">Due-date awareness only. Actions needed to achieve these dates are shown in My Work above.</div>')}}
}
function installCapacityListenersV1072(){if(App._v1072Capacity)return;App._v1072Capacity=true;document.addEventListener('change',e=>{if(e.target.id==='capacityModeV1072'){App.filters.capacityModeV1072=e.target.value;render()}if(e.target.id==='capacityPeriodV1072'){App.filters.capacityPeriodV1072=e.target.value;render()}},true)}

function installWeekendSettingV1072(){
  if(App.currentView!=='configuration')return;
  const page=$('#page');if(!page||page.querySelector('[data-v1072-weekends]'))return;
  const sys=[...page.querySelectorAll('details.card.fold')].find(x=>/System status/i.test(x.querySelector('summary')?.textContent||''));
  const block=document.createElement('details');block.className='card fold';block.open=true;block.innerHTML=`<summary>Planning calendar</summary><div class="setting-row-v1072"><div><strong>Allow prototype builds on weekends</strong><small>When enabled, AUTO-PLAN, drag/move proposals and capacity calculations may use Saturday and Sunday. Disable for a Monday–Friday lab.</small></div><label class="plan-switch"><input type="checkbox" data-v1072-weekends ${v1072WeekendsEnabled()?'checked':''}><span>${v1072WeekendsEnabled()?'Weekends enabled':'Weekdays only'}</span></label></div>`;if(sys)sys.before(block);else page.append(block)
}
function installWeekendListenerV1072(){if(App._v1072Weekend)return;App._v1072Weekend=true;document.addEventListener('change',async e=>{const t=e.target.closest?.('[data-v1072-weekends]');if(!t)return;App.state.settings=App.state.settings||{};App.state.settings.includeWeekendsForBuilds=!!t.checked;P.audit(App.state,'Planning calendar changed','Configuration','Weekend planning',!t.checked?'Weekends':'Weekdays only',t.checked?'Weekends included':'Weekdays only',`${App.state.identity.name} changed build calendar availability.`);await persist();render();toast(t.checked?'Weekend build planning enabled.':'Weekend build planning disabled.')},true)}

function labelRequiredDateMarkersV1072(){if(App.currentView!=='planning')return;document.querySelectorAll('.swim-due').forEach(x=>{x.classList.add('v1072-required-date');if(!x.querySelector('span'))x.innerHTML='<span>Required delivery</span>'});const legend=document.querySelector('.swim-legend');if(legend&&!/Red vertical line/.test(legend.textContent||''))legend.insertAdjacentHTML('beforeend','<span class="required-date-explainer-v1072"><i class="legend-due"></i>Red vertical line = required delivery date</span>')}

function installV1072MovePerf(){
  if(validatedMoveOptionsV1071._v1072)return;
  const base=validatedMoveOptionsV1071;
  validatedMoveOptionsV1071=function(booking,limit=12){const key=`${booking.id}|${limit}|${planningFingerprintV1070(App.state)}|${v1072WeekendsEnabled()}`;if(App.v1072MoveCache?.key===key)return App.v1072MoveCache.options;const t0=performance.now(),options=base(booking,limit);App.v1072MoveCache={key,options};App.v1072LastMoveMs=Math.round(performance.now()-t0);return options};validatedMoveOptionsV1071._v1072=true;
}

const _renderV1072Base=render;
render=function(){_renderV1072Base();installCapacityListenersV1072();installWeekendListenerV1072();installMyWorkLayoutV1072();installWeekendSettingV1072();labelRequiredDateMarkersV1072();installV1072MovePerf();};



/* ============================================================
   LabOS REV 1.0.73 — frictionless request/material/method flow
   and stronger autonomous planning resource resolution.
   ============================================================ */
function nextIncompleteGuidedStepV1073(r,currentId='materials'){
  const steps=buildGuidedSteps(r),idx=steps.findIndex(x=>x.id===currentId);
  return steps.slice(Math.max(0,idx+1)).find(x=>!x.done)||steps.find(x=>!x.done&&x.id!==currentId)||null;
}
function materialReceiptAllModalV1073(requestId){
  const r=requestById(requestId);if(!r)return;P.ensureMaterialRequirements(App.state,r);
  const alloc=(App.state.allocations||[]).filter(a=>a.requestId===requestId),reqs=(r.materialRequirements||[]).map(req=>{const issued=alloc.filter(a=>a.requirementId===req.id&&a.status==='Issued').reduce((n,a)=>n+Number(a.qty||0),0);return {...req,remaining:Math.max(0,Number(req.requiredQty||0)-issued)}}).filter(x=>x.remaining>0);
  if(!reqs.length){toast('All engineering-supplied BOM material is already received and issued.');return}
  const rows=reqs.map((q,i)=>`<tr data-v1073-receipt-row="${esc(q.id)}"><td><strong>${esc(q.partNumber)}</strong><small>Rev ${esc(q.revision)} · ${esc(q.description)}</small></td><td>${esc(q.remaining)} ${esc(q.unit||'pcs')}</td><td><input data-v1073-lot="${esc(q.id)}" value="ENG-${esc(q.partNumber).replace(/[^A-Za-z0-9-]/g,'')}-${P.todayISO().replaceAll('-','')}" aria-label="Lot for ${esc(q.partNumber)}"></td><td><input data-v1073-qty="${esc(q.id)}" type="number" min="0" step="any" value="${esc(q.remaining)}" aria-label="Quantity for ${esc(q.partNumber)}"></td></tr>`).join('');
  openModal('Receive all engineering material',`<div class="callout"><strong>One receipt for the complete engineering handover</strong><p>All outstanding BOM lines are shown together. Adjust only a line that was partially supplied. LabOS immediately issues the received quantity to this build and turns each completed component green.</p></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Received from / owner</label><input id="v1073ReceiptOwner" value="${esc(r.materialSupply?.owner||r.requester||App.state.identity.name)}"></div><div class="field"><label>Common handover / shipment reference</label><input id="v1073ReceiptRef" value="${esc(r.materialSupply?.reference||'')}" placeholder="Shipment, handover or CoC reference"></div></div><div class="table-wrap" style="margin-top:12px"><table class="data-table"><thead><tr><th>BOM item</th><th>Outstanding</th><th>Lot / batch</th><th>Receive now</th></tr></thead><tbody>${rows}</tbody></table></div><details class="fold compact"><summary>What happens when you save?</summary><p>Each quantity is recorded against the exact part/revision requirement. Full lines become green immediately. If every line is complete, the Material step closes automatically and the next guided workflow action becomes available.</p></details>`,`${btn('Cancel','data-modal-close','button')}${btn('Receive all & continue','data-v1073-save-all-material','button next-action')}`,true);
  setTimeout(()=>{const save=$('[data-v1073-save-all-material]');if(!save)return;save.onclick=async()=>{const owner=$('#v1073ReceiptOwner')?.value.trim()||r.requester||App.state.identity.name,ref=$('#v1073ReceiptRef')?.value.trim()||`Engineering handover ${P.todayISO()}`;let receivedLines=0;for(const req of reqs){const qty=Number(document.querySelector(`[data-v1073-qty="${CSS.escape(req.id)}"]`)?.value||0),lot=document.querySelector(`[data-v1073-lot="${CSS.escape(req.id)}"]`)?.value.trim();if(!(qty>0))continue;if(!lot){toast(`Enter a lot/batch for ${req.partNumber}.`,true);return}const issued=Math.min(qty,req.remaining),excess=Math.max(0,qty-issued),m={id:P.uid('MAT'),partNumber:req.partNumber,description:req.description,revision:req.revision,supplier:'Engineering supplied',lot,quantity:excess,status:excess>0?'Available':'Consumed / issued',certificate:ref,specialHandling:r.specialHandling||'Standard',expiry:null,received:P.todayISO()};App.state.materials.push(m);if(issued>0)App.state.allocations.push({id:P.uid('ALLOC'),requestId,requirementId:req.id,materialId:m.id,lot,qty:issued,status:'Issued'});receivedLines++;}
    if(!receivedLines){toast('Enter a positive quantity for at least one BOM line.',true);return}r.materialSupply={owner,expectedDate:P.todayISO(),receivedAt:P.todayISO(),reference:ref};syncMaterialOutputLimit(r);P.audit(App.state,'Engineering material batch receipt','Request',requestId,'Outstanding engineering BOM material',`${receivedLines} BOM line(s) received`,`${owner} · ${ref}`);await persist();closeModal();render();const a=P.materialPlanningAssessment(App.state,r);if(a.buildReady){const next=nextIncompleteGuidedStepV1073(r,'materials');toast(next?`All material is ready. Next: ${next.title}.`:'All material is ready.');}else toast('Receipt saved. Remaining material stays highlighted until complete.',true);};},0)
}

const _workspaceMaterialsV1073Base=workspaceMaterials;
workspaceMaterials=function(r){
  P.ensurePlanningModel(App.state);const assessment=P.materialPlanningAssessment(App.state,r),reqs=r.materialRequirements||[],alloc=(App.state.allocations||[]).filter(a=>a.requestId===r.id),source=P.normaliseMaterialSource(r.materialOwnership),canAct=can('materials:allocate')||can('materials:receive')||currentRole()==='administrator',lim=assessment.outputLimit||P.materialOutputLimit(App.state,r);
  const rows=reqs.map(req=>{const linked=alloc.filter(a=>a.requirementId===req.id),issued=linked.filter(a=>a.status==='Issued').reduce((n,a)=>n+Number(a.qty||0),0),reserved=linked.filter(a=>a.status==='Reserved').reduce((n,a)=>n+Number(a.qty||0),0),available=(App.state.materials||[]).filter(m=>m.status==='Available'&&m.partNumber===req.partNumber&&m.revision===req.revision).reduce((n,m)=>n+Number(m.quantity||0),0),incomingRows=(r.materialReplenishments||[]).filter(x=>x.requirementId===req.id&&!['Cancelled','Received'].includes(x.status)&&x.expectedDate&&Number(x.qty||0)>0),incoming=incomingRows.reduce((n,x)=>n+Number(x.qty||0),0),incomingDate=incomingRows.length?incomingRows.map(x=>x.expectedDate).sort().at(-1):null,ready=issued>=Number(req.requiredQty||0);return {req,linked,issued,reserved,available,incoming,incomingDate,ready}});
  const next=assessment.buildReady?nextIncompleteGuidedStepV1073(r,'materials'):null;
  let primary='';let secondary='';
  if(source==='Engineering supplied'){
    if(!assessment.buildReady&&canAct)primary=btn('Receive all engineering material',`data-v1073-receive-all="${r.id}"`,'button small next-action');
    if(!assessment.buildReady&&canAct)secondary=btn('Receive one BOM line',`data-allocate-material="${r.id}"`,'button small secondary');
    if(!assessment.planningReady&&(currentRole()==='engineering_requester'||can('triage')||currentRole()==='administrator'))secondary+=btn('Define supply promise',`data-material-supply="${r.id}"`,'button small secondary');
  }else{
    const hasIncoming=(r.materialReplenishments||[]).some(x=>x&&!['Cancelled','Received'].includes(x.status)&&Number(x.qty||0)>0);
    if(!assessment.planningReady&&canAct)primary=btn('Resolve material availability',`data-v1082-material-resolver="${r.id}"`,'button small next-action');
    else if(!assessment.buildReady&&alloc.some(a=>a.status==='Reserved')&&canAct)primary=btn('Issue all reserved material',`data-issue-reserved="${r.id}"`,'button small next-action');
    if(hasIncoming&&canAct)secondary+=btn('Receive planned supply',`data-v1082-receive-supply="${r.id}"`,'button small secondary');
    if(assessment.planningReady&&!assessment.buildReady&&canAct)secondary+=btn('Review material plan',`data-v1082-material-resolver="${r.id}"`,'button small secondary');
  }
  if(assessment.buildReady&&next)primary=btn(`Next · ${next.title} →`,`data-workspace-tab="${esc(next.id)}"`,'button small next-action');
  const limiter=lim?.limited&&lim.maxBuildQty<lim.requestedQty?`<div class="callout warn material-output-limit"><strong>Output currently limited to ${esc(lim.maxBuildQty)} / ${esc(lim.requestedQty)} units</strong><p>The received/issued BOM quantity cannot yet support the full requested build.</p></div>`:'';
  const stateClass=assessment.buildReady?'good':assessment.planningReady?'warn':'warn';
  return `<div class="section-stack"><div class="card material-command-v1073"><div class="section-title-row"><div><span class="eyebrow">MATERIAL SOURCE & READINESS</span><h2>${assessment.buildReady?'✓ All required material is ready':esc(source)}</h2><div class="subtle">Engineering receipt or lab-stock issue is checked against exact part, revision and quantity.</div></div><div class="route-toolbar">${secondary}${primary}</div></div><div class="callout ${stateClass}"><h3>${assessment.buildReady?'Material step complete':assessment.planningReady?'Supply timing known — physical material still required':'Material action required'}</h3><p>${esc(assessment.summary)}${assessment.earliestDate?` · ${assessment.buildReady?'Received':'Earliest material date'}: <strong>${P.formatDate(assessment.earliestDate)}</strong>`:''}</p>${source==='Engineering supplied'?`<p style="margin-top:6px"><strong>Owner:</strong> ${esc(r.materialSupply?.owner||r.requester||'Not defined')} · <strong>Reference:</strong> ${esc(r.materialSupply?.reference||'—')}</p>`:''}</div>${limiter}</div><div class="card"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED BOM</span><h2>Exact material requirements</h2><div class="subtle">Each completed BOM line turns green immediately. The workflow advances only when every required line is complete.</div></div>${status(assessment.buildReady?'Build material ready':lim?.limited&&lim.maxBuildQty>0?`Output limited · ${lim.maxBuildQty}/${lim.requestedQty}`:assessment.planningReady?'Awaiting physical receipt / issue':'Material action required')}</div><div class="material-requirements">${rows.map(x=>`<div class="material-req ${x.ready?'ready v1073-material-complete':'missing'}"><div><span class="eyebrow">${esc(x.req.partNumber)} · REV ${esc(x.req.revision)}</span><strong>${esc(x.req.description)}</strong><span>Required ${esc(x.req.requiredQty)} ${esc(x.req.unit||'pcs')} · ${source==='Lab supplied'?`Reserved ${esc(x.reserved)} · Available ${esc(x.available)} · Incoming ${esc(x.incoming)}${x.incomingDate?` by ${P.formatDate(x.incomingDate)}`:''} · `:''}Received/issued ${esc(x.issued)}</span>${x.linked.length?`<span>Lot(s): ${x.linked.map(a=>`${esc(a.lot)} (${esc(a.status)})`).join(', ')}</span>`:x.incoming?`<span>Incoming supply planned; physical lot/receipt still pending.</span>`:'<span>No receipt/lot linked yet</span>'}</div>${status(x.ready?'Complete':'Outstanding')}</div>`).join('')}</div></div>${assessment.buildReady&&next?`<div class="card material-next-v1073"><span class="eyebrow">NEXT GUIDED ACTION</span><div><h2>${esc(next.title)}</h2><p>${esc(next.next||'Continue with the next controlled build step.')}</p></div>${btn(`Continue →`,`data-workspace-tab="${esc(next.id)}"`,'button next-action')}</div>`:''}</div>`;
};

