// A 5S action must resolve inside the 5S control itself, never through a generic build section.
resolve5SActionModal=function(actionId){
  const a=(App.state.actions||[]).find(x=>x.id===actionId),z=(App.state.fiveSZones||[]).find(x=>x.id===a?.fiveSAction?.zoneId),src=(App.state.fiveSAudits||[]).find(x=>x.id===a?.fiveSAction?.auditId);if(!a||!z)return;
  const pillar=a.fiveSAction.pillar,score=Number(src?.scores?.[pillar]||0),obs=src?.evidence||a.why||'';
  openModal(`Resolve 5S · ${z.name} · ${a.fiveSAction.pillarLabel}`,`<div class="resolution-focus"><span class="eyebrow">EXACT 5S GAP</span><h2>${esc(a.fiveSAction.pillarLabel)} · ${score||'—'}/5</h2><p>${esc(obs)}</p><div class="score-row"><span>Zone</span><strong>${esc(z.name)} · ${esc(z.area)}</strong></div><div class="score-row"><span>Accountable owner</span><strong>${esc(z.owner)}</strong></div></div><div class="resolution-steps compact"><div class="resolution-step complete"><span class="resolution-index">✓</span><div><strong>Gap identified</strong><small>The original 5S check remains in history.</small></div></div><div class="resolution-step current"><span class="resolution-index">2</span><div><strong>Correct the physical condition</strong><small>Restore the actual workplace standard for this criterion.</small></div></div><div class="resolution-step pending"><span class="resolution-index">3</span><div><strong>Recheck this criterion</strong><small>A score of 4 or 5 closes this action; 1–3 keeps it open.</small></div></div></div><div class="form-grid"><div class="field full"><label>Correction performed <b>required</b></label><textarea id="v1075FiveSCorrection" placeholder="What was physically corrected in this zone?"></textarea></div><div class="field"><label>Recheck score</label><select id="v1075FiveSScore">${[5,4,3,2,1].map(n=>`<option value="${n}" ${n===4?'selected':''}>${n} · ${n>=4?'Meets standard':n===3?'Improvement still required':'Gap remains'}</option>`).join('')}</select></div><div class="field"><label>Verification evidence <b>required</b></label><input id="v1075FiveSEvidence" placeholder="Observation / photo / record reference"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Record correction & recheck','data-v1075-close-5s','button next-action')}`,true);
  setTimeout(()=>{const b=$('[data-v1075-close-5s]');if(!b)return;b.onclick=async()=>{const restoreScrollY=window.scrollY,correction=$('#v1075FiveSCorrection')?.value.trim()||'',evidence=$('#v1075FiveSEvidence')?.value.trim()||'',newScore=Number($('#v1075FiveSScore')?.value||0);if(!correction||!evidence){toast('Correction and verification evidence are required.',true);return}const scores={...(src?.scores||{})};scores[pillar]=newScore;const values=Object.values(scores).map(Number).filter(Number.isFinite),audit={id:P.uid('5S-AUDIT'),zoneId:z.id,date:P.now(),auditor:App.state.identity.name,scores,evidence:`Correction: ${correction}. Verification: ${evidence}`,average:values.length?values.reduce((n,x)=>n+x,0)/values.length:newScore,resolutionOfActionId:a.id};App.state.fiveSAudits.push(audit);if(newScore>=4){a.status='Resolved';a.resolvedAt=P.now();a.resolutionEvidence=audit.evidence;P.audit(App.state,'5S action corrected, rechecked and closed','Action',a.id,`${score}/5`,`${newScore}/5`,audit.evidence);}else{a.status='Open';a.severity=newScore<=2?'bad':'warn';a.why=`Recheck remains below standard at ${newScore}/5. ${audit.evidence}`;P.audit(App.state,'5S action rechecked; gap remains','Action',a.id,`${score}/5`,`${newScore}/5`,audit.evidence);}await persist();closeModal();render();requestAnimationFrame(()=>window.scrollTo({top:restoreScrollY,left:0,behavior:'instant'}));toast(newScore>=4?'5S action closed after successful recheck.':'5S action remains open because the recheck is below 4/5.',newScore<4);};},0);
};
const _resolveActionModalV1075Base=resolveActionModal;
