  P.ensureResourceCareOwnershipV1109?.(state);state.resourceCareBookings=(state.resourceCareBookings||[]).filter(b=>!b.autoGenerated||b.portfolioOwned===true||!ids.has(b.sourceRequestId)||b.locked);
  const priority={Critical:0,High:1,Normal:2,Low:3};
