  App.manualPlanningDraftV1080={requestId,state,originalState:P.deepClone(App.state),sourceFingerprint:planningFingerprintV1070(App.state),seeded,seedError,decisions:[]};App.manualPlanningOptionsV1080={};return App.manualPlanningDraftV1080;
