  const supplyForm=trueShort.length&&!assessment.planningReady?`<div class="material-supply-plan-v1082"><span class="eyebrow">INCOMING LAB SUPPLY</span><h3>Plan only the uncovered quantity</h3><p class="subtle">LabOS first reserves any exact stock already on hand, then creates incoming supply only for the remaining shortage. This makes timing plannable without pretending material has physically arrived.</p><div class="form-grid"><div class="field"><label>Supply / procurement owner</label><input id="v1082MatOwner" value="${esc(assessment.owner||App.state.identity.name)}"></div><div class="field"><label>Expected lab arrival</label><input id="v1082MatDate" type="date" min="${P.todayISO()}" value=""></div><div class="field full"><label>PO / order / supply reference</label><input id="v1082MatRef" placeholder="Required controlled reference"></div></div><div class="material-shortage-list-v1082">${trueShort.map(x=>`<span><b>${esc(x.req.partNumber)} Rev ${esc(x.req.revision)}</b><small>True shortage after current stock: ${esc(x.procureGap)} ${esc(x.req.unit||'pcs')}</small></span>`).join('')}</div></div>`:'';
  const incomingPanel=incoming.length?`<details class="fold compact" open><summary>Incoming supply already planned · ${incoming.length}</summary><div class="material-shortage-list-v1082">${incoming.map(x=>{const q=(r.materialRequirements||[]).find(y=>y.id===x.requirementId);return `<span><b>${esc(q?.partNumber||x.requirementId)} · ${esc(x.qty)} ${esc(q?.unit||'pcs')}</b><small>${P.formatDate(x.expectedDate)} · ${esc(x.owner||'—')} · ${esc(x.reference||'—')}</small></span>`}).join('')}</div></details>`:'';
