  const physicalReceipt=canAct?`<div class="material-physical-receipt-v1085"><div><span class="eyebrow">MATERIAL IS PHYSICALLY IN THE LAB</span><strong>Receive it into lab stock now</strong><small>Record the actual lot/batch and quantity. LabOS adds it to inventory and reserves the exact BOM automatically.</small></div>${btn('Receive physical lab stock →',`data-v1083-receive-direct="${esc(r.id)}"`,'button primary')}</div>`:'';
