  P.ensureRequestingTeamModel?.(App.state);const team=id?(App.state.requestingTeams||[]).find(x=>x.id===id):null,engineeringUsers=(App.state.users||[]).filter(u=>['engineering_requester','engineering_lead'].includes(u.role)),selected=new Set(team?.memberUserIds||engineeringUsers.filter(u=>u.teamId===team?.id).map(u=>u.id)),site=team?.defaultSite||App.state.settings?.auditProfile?.site||'';
