function controlPlanDecisionModalV1091(requestId){
  const r=requestById(requestId);if(!r)return;const cps=P.reusableControlPlansForRequest?.(App.state,r)||[],current=r.controlPlanId||'__later__';
  openModal('Control Plan strategy',`<div class="callout"><strong>Make the decision explicit</strong><p>Link an approved compatible baseline now, or deliberately defer Control Plan definition/selection to the Controls step.</p></div><div class="field" style="margin-top:12px"><label>Control Plan strategy</label><select id="cpStrategyV1091">${cps.map(cp=>`<option value="${esc(cp.id)}" ${current===cp.id?'selected':''}>${esc(cp.name)} · Rev ${esc(cp.revision)} · Approved</option>`).join('')}<option value="__later__" ${!r.controlPlanId?'selected':''}>Define / select later in Controls workflow</option></select></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save decision','data-v1091-save-cp-strategy','button primary')}`);
  setTimeout(()=>{$('[data-v1091-save-cp-strategy]').onclick=async()=>{const before=r.controlPlanId||'Defined later',v=$('#cpStrategyV1091').value;if(r.controlPlanId){const old=App.state.controlPlans.find(x=>x.id===r.controlPlanId);if(old)old.requestIds=(old.requestIds||[]).filter(id=>id!==r.id)}if(v==='__later__'){r.controlPlanId=null;r.controlPlanDeferred=true;P.ensureReusePackage(r).controlPlan={mode:'deferred',source:'Define later in Controls workflow'}}else{const cp=cps.find(x=>x.id===v);if(!cp){toast('Compatible approved Control Plan no longer available.',true);return}r.controlPlanId=cp.id;r.controlPlanDeferred=false;cp.requestIds=Array.isArray(cp.requestIds)?cp.requestIds:[];if(!cp.requestIds.includes(r.id))cp.requestIds.push(r.id);P.ensureReusePackage(r).controlPlan={mode:'reused',baselineId:cp.id,revision:cp.revision,source:cp.name}}P.audit(App.state,'Control Plan strategy changed','Request',r.id,before,v==='__later__'?'Defined later':v,'Explicit request setup decision');await persist();closeModal();render();toast('Control Plan strategy updated.')}},0)
}

function v1091RequestChecks(r){return P.requestSetupAssessment?.(App.state,r)?.checks||[]}
function v1091WorkspaceConfig(r){
  const p=App.state.products.find(x=>x.id===r.productId),profile=P.ensureAssuranceProfile(r);P.applyReusePackage(App.state,r,{actor:App.state.identity.name});const pack=P.ensureReusePackage(r),cp=App.state.controlPlans.find(x=>x.id===r.controlPlanId),history=r.changeHistory||[];
  const routeState=pack.route?.mode==='reused'?'<span class="v1091-state good">✓ Reused released baseline</span>':'<span class="v1091-state warn">● Review / define in workflow</span>',cpState=cp?`<span class="v1091-state good">✓ ${esc(cp.name)} · Rev ${esc(cp.revision)}</span>`:(r.controlPlanDeferred===true||(r.status!=='DRAFT REQUEST'&&r.controlPlanDeferred==null))?'<span class="v1091-state warn">● Define / select in Controls workflow</span>':'<span class="v1091-state bad">✕ Control Plan decision missing</span>';
  return `<div class="section-stack"><div class="card"><div class="section-title-row"><div><span class="eyebrow">REUSE & CONTROL STRATEGY</span><h2>Approved baseline links</h2><div class="subtle">The request records the intended baseline up front. Later changes are controlled deltas, not duplicate document setup.</div></div>${canEditRequest(r)?btn('Change Control Plan strategy',`data-v1091-cp-decision="${esc(r.id)}"`,'button small secondary'):''}</div><div class="v1091-baseline-grid"><div><strong>Process route / work instructions</strong>${routeState}</div><div><strong>Control Plan</strong>${cpState}</div></div></div><div class="card"><div class="section-title-row"><div><h2>Product & build definition</h2><div class="subtle">Only build-defining request data is shown here; timing/progress remain in the sticky workflow header.</div></div>${canEditRequest(r)?btn('Edit request',`data-edit-request="${r.id}"`,'button small primary'):''}</div><div class="form-grid">${[['Product/device family',r.productFamily],['Part number',p?.partNumber],['Product revision',r.productRevision],['Hardware revision',r.hardwareRevision],['Software revision',r.softwareRevision],['Build maturity',r.maturity],['BOM/configuration ref',r.bomRef],['Configuration',r.configuration],['Requesting / engineering team',r.engineeringTeam],['Assurance',`${profile.code} · ${profile.label}`]].map(([l,v])=>`<div class="field"><label>${esc(l)}</label><div class="callout"><strong>${esc(v||'—')}</strong></div></div>`).join('')}</div></div>${history.length?`<div class="card v1091-change-impact"><h2>Controlled changes after submission</h2><p class="subtle">This section appears only after controlled request data changes. It shows exactly what changed and which downstream feasibility, planning or control evidence must be revalidated.</p>${history.map(changeHistoryHtml).join('')}</div>`:''}</div>`
}
workspaceConfig=v1091WorkspaceConfig;

function v1091StepPurpose(id){return ({configuration:'Confirm what Engineering needs, the exact product/configuration, ownership, assurance level and Control Plan strategy before handing the request to the lab.',materials:'Establish the exact material source and availability basis needed to plan the build without assuming stock or arrival.',processrisk:'Confirm the released route and methods that can be reused, and identify only genuine method/risk deltas that need controlled development.',controls:'Confirm the Control Plan and any build-specific or product-safety controls without recreating approved baseline information.',schedule:'Create and review the best-feasible resource plan using capable equipment, qualified people, readiness windows and portfolio constraints before committing timing.',readiness:'Prove that material, equipment, calibration/maintenance, competence and required independent decisions will be ready at the planned time.',execution:'Execute the controlled route and capture the required evidence consistently for the selected samples.',verify:'Capture and evaluate the requested test/characterisation results and disposition any exception before release.',approvals:'Complete the formal release decision only after the technical evidence and quality conditions are complete.',closeout:'Deliver the released build, retain the controlled record and capture learning for future reuse.'})[id]||'Complete the controlled work for this workflow stage.'}
function v1091Substeps(r,step){if(step?.id==='configuration')return v1091RequestChecks(r).map(x=>({label:x.label,done:x.done,detail:x.done?'Complete':'Missing request data'}));return workflowSubstepsV1066(r,step).map(x=>({...x,detail:x.done?'Complete':'Pending'}))}
function v1091StepScaffold(r,step,body){const subs=v1091Substeps(r,step),first=subs.findIndex(x=>!x.done);return `<div class="workspace-step-layout-v1091"><section class="card workspace-purpose-v1091"><span class="eyebrow">STEP ${step?.index||'—'} · PURPOSE</span><h2>Purpose of this section</h2><p>${esc(v1091StepPurpose(step?.id))}</p></section><section class="card workspace-substeps-v1091"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED SUBSTEPS</span><h2>What must be completed in this step</h2></div></div><div class="workspace-substep-list-v1091">${subs.map((x,i)=>{const cls=x.done?'good':i===first?(step?.hasBlocker?'bad':'warn'):'future',icon=x.done?'✓':i===first?(step?.hasBlocker?'✕':'●'):'○';return `<div class="workspace-substep-row-v1091 ${cls}"><span>${icon}</span><div><strong>${esc(x.label)}</strong><small>${esc(x.detail||'')}</small></div></div>`}).join('')||'<div class="workspace-substep-row-v1091 good"><span>✓</span><div><strong>No additional substeps</strong><small>This stage has no lower-level checklist.</small></div></div>'}</div></section><div class="workspace-step-content-v1091">${body}</div></div>`}
const _workspaceTabContentV1091Base=workspaceTabContent;
workspaceTabContent=function(r,tab){let body;switch(tab){case'configuration':body=workspaceConfig(r);break;case'controls':body=workspaceControlPlan(r);break;case'approvals':{const p=approvalPackageSummaryV1058(r,'release');body=`<div class="card"><span class="eyebrow">RELEASE EVIDENCE</span><h2>Release decision basis</h2><p class="subtle">Sign-off itself is performed only from the sticky SIGN-OFF control above. This page therefore shows the decision basis, not duplicate approval buttons.</p><div class="v1091-baseline-grid"><div><strong>Release signers</strong><span class="v1091-state ${p.pending.length?'warn':'good'}">${p.pending.length?'● '+p.done+'/'+p.total+' complete':'✓ Required signers complete'}</span></div><div><strong>Open release holds</strong><span class="v1091-state ${(App.state.deviations||[]).some(d=>d.requestId===r.id&&d.releaseHold&&d.status!=='CLOSED')?'bad':'good'}">${(App.state.deviations||[]).some(d=>d.requestId===r.id&&d.releaseHold&&d.status!=='CLOSED')?'✕ Resolve before release':'✓ None'}</span></div></div></div>`;break}default:body=_workspaceTabContentV1091Base(r,tab)}const steps=buildGuidedSteps(r),step=steps.find(x=>x.id===tab)||selectedGuidedStep(steps);return ['configuration','materials','processrisk','controls','schedule','readiness','execution','verify','approvals','closeout'].includes(tab)?v1091StepScaffold(r,step,body):body};

const _buildGuidedStepsV1091Base=buildGuidedSteps;
