  setTimeout(()=>{document.querySelectorAll('[data-v1094-member]').forEach(c=>c.onchange=()=>c.closest('.project-principal-v1094')?.classList.toggle('selected',c.checked));const save=$('[data-v1094-save-team]');if(save)save.onclick=async()=>{const name=$('#v1089TeamName')?.value.trim(),businessUnit=$('#v1089TeamBusiness')?.value.trim(),defaultSite=$('#v1089TeamSite')?.value.trim(),identityProvider=$('#v1094IdentityProvider')?.value||'local-demo',externalGroupKey=$('#v1094ExternalGroupKey')?.value.trim()||'',projectLeadUserId=$('#v1094ProjectLead')?.value||null,roleGovernanceEnabled=!!$('#v1094Governance')?.checked,active=!!$('#v1089TeamActive')?.checked;if(!name){toast('Project Team name is required.',true);return}const duplicate=(App.state.requestingTeams||[]).find(x=>x.id!==team?.id&&String(x.name).trim().toLowerCase()===name.toLowerCase());if(duplicate){toast('A Project Team with this name already exists.',true);return}const memberIds=[...document.querySelectorAll('[data-v1094-member]:checked')].map(x=>x.dataset.v1094Member),bindings=memberIds.map(uid=>{const u=(App.state.users||[]).find(x=>x.id===uid),roles=[...document.querySelectorAll(`[data-v1094-role^="${CSS.escape(uid)}|"]:checked`)].map(x=>x.dataset.v1094Role.split('|')[1]),approvals=[...document.querySelectorAll(`[data-v1094-right^="${CSS.escape(uid)}|"]:checked`)].map(x=>x.dataset.v1094Right.split('|')[1]);return {id:v1094RoleBindingFor(team,u)?.id||P.uid('TRB'),principalId:uid,principalName:u?.name||uid,identityProvider,externalPrincipalId:document.querySelector(`[data-v1094-principal-key="${CSS.escape(uid)}"]`)?.value.trim()||'',roleIds:[...new Set(roles.length?roles:[u?.role].filter(Boolean))],approvalRights:[...new Set(approvals)]}}),target=team||{id:P.uid('TEAM')},before=P.deepClone(target),lead=(App.state.users||[]).find(u=>u.id===projectLeadUserId);Object.assign(target,{name,businessUnit,defaultSite,identityProvider,externalGroupKey,projectLeadUserId,teamLead:lead?.name||'',roleGovernanceEnabled,active,memberUserIds:memberIds,roleBindings:bindings});if(!team)App.state.requestingTeams.push(target);for(const u of App.state.users||[]){if(!['engineering_requester','engineering_lead'].includes(u.role))continue;if(memberIds.includes(u.id)){u.teamId=target.id;u.team=target.name}else if(u.teamId===target.id){u.teamId='';u.team=''}}for(const r of App.state.requests||[]){if((r.projectTeamId||r.engineeringTeamId)===target.id){r.projectTeamId=target.id;r.engineeringTeamId=target.id;r.engineeringTeam=target.name;P.ensureApprovalRecords?.(App.state,r)}}P.ensureRequestingTeamModel(App.state);const inv=P.validateInvariants(App.state);if(inv.length){toast(`Project Team configuration is invalid: ${inv[0]}`,true);if(team)Object.assign(team,before);return}P.audit(App.state,team?'Project Team authority updated':'Project Team created','Project Team',target.id,team?JSON.stringify(before):'—',JSON.stringify(target),`${target.name} · ${roleGovernanceEnabled?'team authority enforced':'global-role fallback'} · ${bindings.length} principal(s)`);await persist();closeModal();render();toast(`${target.name} ${team?'updated':'created'}.`)}} ,0)
