function installV1094(){if(App._v1094Installed)return;App._v1094Installed=true;document.addEventListener('click',e=>{const t=e.target.closest?.('[data-v1094-health-filter],[data-v1094-review-tier],[data-v1094-escalation],[data-v1094-escalation-from-tier],[data-v1094-run-escalation],[data-v1094-review-escalation]');if(!t)return;if(t.dataset.v1094HealthFilter){e.preventDefault();v1094ApplyHealthFilter(t.dataset.v1094HealthFilter);return}if(t.dataset.v1094ReviewTier){e.preventDefault();v1094ReviewTier(t.dataset.v1094ReviewTier);return}if(t.hasAttribute('data-v1094-escalation')||t.hasAttribute('data-v1094-escalation-from-tier')){e.preventDefault();const d=App.pendingTieredPlannerV1094?.targetRequestId||App.filters.planBuild||null;v1094EscalationChooser(d);return}if(t.hasAttribute('data-v1094-run-escalation')){e.preventDefault();v1094RunEscalation();return}if(t.hasAttribute('data-v1094-review-escalation')){e.preventDefault();v1094ReviewEscalation();return}},true)}
