function v1096TierCard(row,baseline,recommendedTier,targetRequestId){const c=row.candidate,ok=!!c?.ok,eligible=!!row.eligible,recommended=row.tier===recommendedTier,metrics=c?.metrics,target=targetRequestId&&c?.state?(c.state.requests||[]).find(r=>r.id===targetRequestId):null,worsened=c?.worsened||[],blocked=c?.blockers||[],className=`planner-tier-v1094 ${row.tier} ${recommended?'recommended':''} ${eligible?'eligible':'disabled'}`;const body=ok?`<div class="planner-tier-metrics-v1094">${v1094MetricDelta('Total days late',baseline.totalLateDays,metrics.totalLateDays,' d')}${v1094MetricDelta('Max project delay',baseline.maxLateDays,metrics.maxLateDays,' d')}${v1094MetricDelta('Unplanned',baseline.unplanned,metrics.unplanned)}${v1094MetricDelta('Commitment worsening',baseline.commitmentWorseningDays,metrics.commitmentWorseningDays,' d')}</div><div class="planner-solver-summary-v1096"><span>Solver strategy <b>${esc(c.orderMode||'protected')}</b></span><span>${c.plannedCount||0}/${c.selectedCount||0} selected builds solved</span>${blocked.length?`<span class="warn-text">${blocked.length} blocker${blocked.length===1?'':'s'} isolated</span>`:'<span class="good-text">Complete candidate</span>'}</div>${target?`<div class="planner-target-outcome-v1094"><span>Target forecast</span><strong>${P.formatDate(target.forecastDate)}</strong></div>`:''}${worsened.length?`<details class="planner-impact-v1094"><summary>${worsened.length} project${worsened.length===1?'':'s'} become later</summary>${worsened.slice(0,8).map(x=>`<div><strong>${esc(x.requestId)}</strong><span>${P.formatDate(x.from)} → ${P.formatDate(x.to)} · +${x.shift} d</span></div>`).join('')}</details>`:'<div class="planner-no-worsening-v1094">✓ No other project becomes later.</div>'}`:`<div class="callout compact"><strong>Not reviewable in this tier</strong><p>${esc(v1094FriendlyPlannerFailure(c,row.tier))}</p></div>`;let action;if(eligible)action=btn(recommended?'Review recommended plan →':'Review this tier →',`data-v1094-review-tier="${row.tier}"`,'button small '+(recommended?'primary':'secondary'));else if(blocked.length)action=btn('Resolve blocker →',`data-v1096-resolve="${esc(blocked[0].requestId)}"`,'button small secondary');else action=`<button class="button small" type="button" disabled>${row.tier==='red'&&ok?'Not justified by whole-lab objective':'No beneficial change'}</button>`;return `<section class="${className}"><div class="planner-tier-head-v1094"><span class="planner-tier-number-v1094">${row.tier==='green'?'1':row.tier==='yellow'?'2':'3'}</span><div><span class="eyebrow">${recommended?'RECOMMENDED · ':''}${esc(row.tier.toUpperCase())}</span><h3>${esc(row.label)}</h3><p>${esc(row.description)}</p></div>${action}</div>${body}${row.reason&&!eligible?`<small class="planner-tier-reason-v1094">${esc(row.reason)}</small>`:''}</section>`}
v1094TierCard=v1096TierCard;
v1094OpenTieredPlanner=function(targetRequestId=null,contextEvent=null){const label=targetRequestId?`AUTO PLAN · ${targetRequestId}`:'AUTO PLAN · PORTFOLIO';openModal(label,`<div class="planner-computing-v1094"><span class="spinner"></span><div><strong>Running one planning engine through protected, recovery and portfolio strategies…</strong><small>Blocked builds are isolated rather than aborting the complete portfolio calculation.</small></div></div>`,btn('Cancel','data-modal-close','button'),true);setTimeout(()=>{let pack;try{pack=P.buildAutoPlanTiersV1096(App.state,{targetRequestId})}catch(e){console.error(e);openModal('AUTO PLAN safety stop',`<div class="callout bad"><strong>The planning analysis could not complete safely.</strong><p>The live plan has not changed. ${esc(e.message||'Unexpected planner error')}</p></div>`,btn('Close','data-modal-close','button'),true);return}App.pendingTieredPlannerV1094={pack,targetRequestId,contextEvent};const rec=pack.recommended?.tier||null,available=pack.candidates.some(x=>x.eligible)||!!pack.recommended,guidance=v1096GuidanceMarkup(pack,targetRequestId),target=requestById(targetRequestId),noChange=!available&&!pack.blockers?.length;openModal(label,`<div class="planner-policy-v1094"><strong>${target?`Target · ${esc(target.id)} · ${esc(target.title||target.productFamily||'')}`:'Whole-lab optimization · '+pack.strategiesEvaluated+' deterministic strategies'}</strong><span>Green protects other projects. Yellow may schedule controlled recovery. Red is only reviewable when moving another project improves the quantified whole-lab objective. All modes use the same scheduling kernel and final integrity gates.</span></div>${pack.candidates.map(x=>v1096TierCard(x,pack.baseline,rec,targetRequestId)).join('')}${guidance}${noChange?`<div class="callout good"><strong>The current feasible plan already wins the tested strategies.</strong><p>AUTO PLAN found no safe change that improves the objective. This is an optimization result, not a silent failure.</p></div>`:''}${(pack.suggestions||[]).length?`<section class="planner-improvements-v1094"><span class="eyebrow">IMPROVE BEYOND THE CURRENT PROPOSAL</span><h3>Capability suggestions</h3>${pack.suggestions.map(s=>`<div><strong>${esc(s.title)}</strong><span>${esc(s.detail)}</span></div>`).join('')}</section>`:''}`,`${btn('Close','data-modal-close','button')}${targetRequestId?btn('Escalation mode…','data-v1094-escalation-from-tier','button danger'):''}`,true)},20)};
v1094RunEscalation=function(){const id=$('#v1094EscalationTarget')?.value;if(!id)return;openModal(`Escalation analysis · ${id}`,`<div class="planner-computing-v1094"><span class="spinner"></span><div><strong>Clearing all movable future capacity for ${esc(id)} first…</strong><small>The target is planned first; then ${P.PlanningEngineV1096.orderModes.length} recovery orderings rebuild the remaining portfolio.</small></div></div>`,btn('Cancel','data-modal-close','button'),true);setTimeout(()=>{const out=P.buildEscalationPlanV1096(App.state,id);if(!out.ok){App.pendingPlannerFailureV1096=out.failure||null;const d=out.failure?.diagnosis||P.planningFailureDiagnosisV1096(App.state,out.failure||{requestId:id,code:'PLANNING_BLOCKED',details:{taskName:'Escalation'}});openModal(`Escalation · ${id}`,`<div class="callout bad"><strong>Escalation found a true controlled blocker.</strong><p>${esc(d.summary||out.reason)}</p></div><div class="callout"><strong>This is not a dead end.</strong><p>Use the guided recovery below. Once that controlled capability/readiness change is made, Escalation reruns the same end-to-end engine.</p></div>`,`${btn('Close','data-modal-close','button')}${btn('Start guided recovery →',`data-v1096-resolve="${esc(id)}"`,'button primary')}`,true);return}App.pendingEscalationV1094=out;const b=P.planningPortfolioScoreV1094(App.state,App.state),a=out.candidate.metrics;openModal(`Escalation result · ${id}`,`<div class="planner-policy-v1094"><strong>${esc(id)} receives the earliest valid target-first schedule found.</strong><span>All movable future work was released for the target first. The remaining portfolio was then rebuilt across ${out.strategiesEvaluated||out.alternatives} deterministic strategies and the least-damaging valid result retained.</span></div><div class="grid cols-4">${v1094MetricDelta('Target forecast',out.targetBefore||'—',out.targetAfter||'—')}${v1094MetricDelta('Total days late',b.totalLateDays,a.totalLateDays,' d')}${v1094MetricDelta('Max project delay',b.maxLateDays,a.maxLateDays,' d')}${v1094MetricDelta('Projects worsened',0,out.worsened.length)}</div>${out.worsened.length?`<section class="planner-impact-table-v1094"><h3>Consequences for other projects</h3>${out.worsened.map(x=>`<div><strong>${esc(x.requestId)} · ${esc(x.title||'')}</strong><span>${P.formatDate(x.from)} → ${P.formatDate(x.to)} · +${x.shift} d</span></div>`).join('')}</section>`:'<div class="callout good"><strong>No other project becomes later.</strong></div>'}`,`${btn('Cancel','data-modal-close','button')}${btn('Review complete escalation plan →','data-v1094-review-escalation','button danger')}`,true)},20)};
