  let all=[...builds,...care,...potential,...situations,...unplanned];if(view==='build'&&requestId)all=all.filter(x=>x.kind==='situation'||x.requestId===requestId||x.sourceRequestId===requestId);return all.filter(x=>new Date(x.end)>range.start&&new Date(x.start)<range.end)
