function v1099NetworkAdmin(){P.ensureMultiLabModelV1099(App.state);const labs=App.state.labs||[],internal=P.internalLabsV1099(App.state),products=App.state.products||[];const opts=(val)=>internal.map(l=>`<option value="${esc(l.id)}" ${l.id===val?'selected':''}>${esc(l.code)} · ${esc(l.name)}</option>`).join('');return `<details class="card fold" open><summary>Laboratory network & product routing</summary><div class="section-title-row"><div><span class="eyebrow">SCALABLE SITE MASTER</span><h2>Laboratories, facilities & default workstream routing</h2><div class="subtle">Stable site IDs are deliberately provider-neutral so master data can later be hydrated from SSO/API/ERP without changing controlled build records.</div></div><div>${btn('+ Internal lab','data-v1099-add-lab="internal"','button small primary')}${btn('+ External facility','data-v1099-add-lab="external"','button small secondary')}</div></div><div class="table-wrap"><table><thead><tr><th>Site</th><th>Type</th><th>Location</th><th>Timezone</th><th>Transfer lead</th><th></th></tr></thead><tbody>${labs.map(l=>`<tr><td><strong>${esc(l.code)}</strong><br><small>${esc(l.name)}</small></td><td>${esc(l.type)}</td><td>${esc(l.location||'—')}</td><td>${esc(l.timezone||'—')}</td><td>${Number(l.transferLeadDays||0)} d</td><td>${btn('Edit',`data-v1099-edit-lab="${esc(l.id)}"`,'button tiny')}</td></tr>`).join('')}</tbody></table></div><div style="height:14px"></div><h3>Product default sites</h3><div class="subtle">New work is routed automatically. Changing a default never moves an existing controlled build.</div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Prototype</th><th>Validation / Testing</th><th>Failure Analysis</th></tr></thead><tbody>${products.map(p=>`<tr><td><strong>${esc(p.family)}</strong><br><small>${esc(p.partNumber||p.id)}</small></td><td><select data-v1099-product-site="prototype" data-product-id="${esc(p.id)}">${opts(p.defaultSiteByWorkstream?.prototype)}</select></td><td><select data-v1099-product-site="validation" data-product-id="${esc(p.id)}">${opts(p.defaultSiteByWorkstream?.validation)}</select></td><td><select data-v1099-product-site="failureAnalysis" data-product-id="${esc(p.id)}">${opts(p.defaultSiteByWorkstream?.failureAnalysis)}</select></td></tr>`).join('')}</tbody></table></div></details>`}
const _renderAdminV1099Base=renderAdmin;
renderAdmin=function(){return v1099NetworkAdmin()+_renderAdminV1099Base()};

function v1099RefreshSiteSelector(){const sel=$('#labSelect');if(!sel||!App.state)return;P.ensureMultiLabModelV1099(App.state);const labs=P.internalLabsV1099(App.state),value=v1099ActiveLabId();sel.innerHTML=labs.map(l=>`<option value="${esc(l.id)}">${esc(l.code)} · ${esc(l.name)}</option>`).join('');sel.value=value;const lab= P.labByIdV1099(App.state,value);sel.title=lab?`${lab.name} · ${lab.location||''}`:'Active laboratory'}
function v1099ComparisonMarkup(pack){const req=requestById(pack.requestId),home=pack.homeSiteId;return `<div class="guided-network-v1099"><div class="resolution-steps compact"><div class="resolution-step complete"><span class="resolution-index">✓</span><div><strong>1 · Home-lab plan evaluated</strong><small>${esc(v1099LabName(home))}</small></div></div><div class="resolution-step complete"><span class="resolution-index">✓</span><div><strong>2 · Sister labs solved independently</strong><small>Same canonical planner · site-owned capacity only</small></div></div><div class="resolution-step current"><span class="resolution-index">3</span><div><strong>Review timing and external benchmark</strong><small>Select a valid sister-lab plan only when it improves the decision.</small></div></div><div class="resolution-step pending"><span class="resolution-index">4</span><div><strong>Accept controlled execution transfer</strong><small>Home site and audit history remain intact.</small></div></div></div><div class="network-comparison-grid-v1099">${pack.rows.map(x=>`<div class="card ${x.siteId===home?'selected':''}"><span class="eyebrow">${x.siteId===home?'HOME LAB':'SISTER LAB'}</span><h3>${esc(x.lab.name)}</h3>${x.ok?`<p><strong>${P.formatDate(x.forecast)}</strong> · ${x.onTime?'<span class="good">on time</span>':`<span class="bad">${x.daysLate} d late</span>`}</p><small>${x.plannedHours} planned h · ${x.elapsedMs} ms solver</small>${x.siteId!==home?btn('Review transfer →',`data-v1099-transfer-site="${esc(x.siteId)}" data-request-id="${esc(pack.requestId)}"`,'button small primary'):''}`:`<div class="callout bad"><strong>No complete valid plan</strong><p>${esc(x.failure?.diagnosis?.summary||x.failure?.error||'Blocked')}</p></div>`}</div>`).join('')}</div>${pack.externalBenchmark?`<div class="callout warn"><strong>External benchmark · ${esc(pack.externalBenchmark.lab.name)}</strong><p>Indicative forecast ${P.formatDate(pack.externalBenchmark.forecast)} · estimated cost <strong>€${Math.round(pack.externalBenchmark.estimatedCost).toLocaleString()}</strong>. ${pack.externalBenchmark.costBasisV123?.quotedTestCount?`${pack.externalBenchmark.costBasisV123.quotedTestCount} test-specific external price(s) contribute ${P.currency(pack.externalBenchmark.costBasisV123.quotedTestCost||0)}${pack.externalBenchmark.costBasisV123.evidenceCount?` · ${pack.externalBenchmark.costBasisV123.evidenceCount} with attached proof`:''}${pack.externalBenchmark.costBasisV123.expiredCount?` · ${pack.externalBenchmark.costBasisV123.expiredCount} expired commercial record(s) require refresh`:''}. Remaining work uses the generic facility benchmark.`:'No test-specific external prices apply, so the generic facility benchmark is used.'} This is a benchmark, not an automatically selected planning option.</p></div>`:''}${pack.recommended?`<div class="callout good"><strong>Recommended internal execution · ${esc(pack.recommended.lab.name)}</strong><p>${pack.recommended.onTime?'Meets the requested date.':'Best valid internal timing found.'} The recommendation remains a proposal until explicitly accepted.</p></div>`:''}</div>`}
function v1099OpenComparison(requestId){openModal(`Lab network recovery · ${requestId}`,`<div class="planner-computing-v1094"><span class="spinner"></span><div><strong>Solving the build independently at each internal laboratory…</strong><small>People, equipment, materials, closures, calibration and qualification remain site-isolated.</small></div></div>`,btn('Cancel','data-modal-close','button'),true);setTimeout(()=>{let pack;try{pack=P.MultiLabPlanningV1099.compareSites(App.state,requestId)}catch(e){openModal('Lab network recovery',`<div class="callout bad"><strong>Comparison stopped safely.</strong><p>${esc(e.message||e)}</p></div>`,btn('Close','data-modal-close','button'),true);return}App.pendingNetworkComparisonV1099=pack;openModal(`Lab network recovery · ${requestId}`,v1099ComparisonMarkup(pack),btn('Close','data-modal-close','button'),true)},20)}
function v1099ReviewTransfer(requestId,siteId){const pack=App.pendingNetworkComparisonV1099||P.MultiLabPlanningV1099.compareSites(App.state,requestId),row=pack.rows.find(x=>x.siteId===siteId&&x.ok);if(!row)return toast('That sister-lab plan is no longer valid.',true);openModal(`Transfer execution · ${requestId}`,`<div class="callout warn"><strong>Controlled execution-site change</strong><p>Home site remains ${esc(v1099LabName(pack.homeSiteId))}. Execution would move to <strong>${esc(row.lab.name)}</strong> with forecast <strong>${P.formatDate(row.forecast)}</strong>.</p></div><label>Decision rationale<textarea id="v1099TransferRationale" rows="3">Home laboratory cannot meet the required timing; sister lab provides a complete valid internal plan and avoids external outsourcing.</textarea></label>`,`${btn('Cancel','data-modal-close','button')}${btn('Accept transfer & replan',`data-v1099-accept-transfer="${esc(siteId)}" data-request-id="${esc(requestId)}"`,'button next-action')}`,true)}
async function v1099AcceptTransfer(requestId,siteId){const rationale=String($('#v1099TransferRationale')?.value||'').trim();if(rationale.length<8)return toast('Add a clear transfer rationale.',true);const result=P.MultiLabPlanningV1099.transferToSite(App.state,requestId,siteId,rationale);if(!result.ok)return toast(result.error||'Transfer could not be completed safely.',true);App.state=result.next;P.ensureMultiLabModelV1099(App.state);await persist();closeModal();render();toast(`${requestId} execution moved to ${v1099LabName(siteId)}. Home-site traceability retained.`)}
function v1099LabModal(id=null,type='internal'){const l=id?P.labByIdV1099(App.state,id):{id:'',code:'',name:'',location:'',timezone:'Europe/Amsterdam',type,active:true,transferLeadDays:type==='external'?5:1,externalLeadDays:12,externalHourlyRate:285,externalSetupFee:1750};openModal(id?'Edit laboratory':'Add laboratory',`<div class="grid cols-2"><label>Stable site ID<input id="v1099LabId" value="${esc(l.id)}" ${id?'disabled':''} placeholder="LAB-XX"></label><label>Site code<input id="v1099LabCode" value="${esc(l.code||'')}"></label><label>Name<input id="v1099LabName" value="${esc(l.name||'')}"></label><label>Type<select id="v1099LabType"><option value="internal" ${l.type==='internal'?'selected':''}>Internal laboratory</option><option value="external" ${l.type==='external'?'selected':''}>External facility</option></select></label><label>Location<input id="v1099LabLocation" value="${esc(l.location||'')}"></label><label>Timezone<input id="v1099LabTimezone" value="${esc(l.timezone||'')}"></label><label>Transfer lead days<input id="v1099LabLead" type="number" min="0" value="${Number(l.transferLeadDays||0)}"></label><label>External hourly rate (€)<input id="v1099LabRate" type="number" min="0" value="${Number(l.externalHourlyRate||0)}"></label><label>External setup fee (€)<input id="v1099LabSetup" type="number" min="0" value="${Number(l.externalSetupFee||0)}"></label><label>External nominal lead days<input id="v1099LabExternalLead" type="number" min="0" value="${Number(l.externalLeadDays||0)}"></label></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save site','data-v1099-save-lab','button primary')}`,true)}
async function v1099SaveLab(){const id=String($('#v1099LabId')?.value||'').trim().toUpperCase(),name=String($('#v1099LabName')?.value||'').trim();if(!id||!name)return toast('Stable site ID and name are required.',true);let l=P.labByIdV1099(App.state,id);if(!l){l={id};App.state.labs.push(l)}Object.assign(l,{code:String($('#v1099LabCode')?.value||id).trim(),name,type:$('#v1099LabType')?.value||'internal',location:String($('#v1099LabLocation')?.value||'').trim(),timezone:String($('#v1099LabTimezone')?.value||'').trim(),active:true,transferLeadDays:Number($('#v1099LabLead')?.value||0),externalHourlyRate:Number($('#v1099LabRate')?.value||0),externalSetupFee:Number($('#v1099LabSetup')?.value||0),externalLeadDays:Number($('#v1099LabExternalLead')?.value||0)});await persist();closeModal();render();toast('Laboratory network master updated.')}
const _submitRequestV1099Base=submitRequest;
submitRequest=async function(id){const r=requestById(id);if(r)P.assignRequestDefaultSiteV1099(App.state,r,{force:!r.homeSiteId});return _submitRequestV1099Base(id)};

function installV1099(){if(App._v1099Installed)return;App._v1099Installed=true;document.addEventListener('change',async e=>{const t=e.target;if(t?.id==='labSelect'){if(P.MultiLabPlanningV1099.setActiveLab(App.state,t.value)){new P.ImprovementService().dailyReview(App.state,{force:false,siteId:t.value});await persist();render();toast(`Active lab · ${v1099LabName(t.value)}`)}return}if(t?.matches?.('[data-v1099-product-site]')){const p=(App.state.products||[]).find(x=>x.id===t.dataset.productId);if(p){p.defaultSiteByWorkstream=p.defaultSiteByWorkstream||{};p.defaultSiteByWorkstream[t.dataset.v1099ProductSite]=t.value;P.audit(App.state,'Product default site changed','Product',p.id,t.dataset.v1099ProductSite,t.value,'Applies to new demand only; existing controlled builds unchanged');await persist();toast(`${p.family} ${t.dataset.v1099ProductSite} default updated.`)}return}},true);document.addEventListener('click',async e=>{const t=e.target.closest?.('[data-v1099-compare-site],[data-v1099-transfer-site],[data-v1099-accept-transfer],[data-v1099-add-lab],[data-v1099-edit-lab],[data-v1099-save-lab]');if(!t)return;if(t.dataset.v1099CompareSite){e.preventDefault();v1099OpenComparison(t.dataset.v1099CompareSite)}else if(t.dataset.v1099TransferSite){e.preventDefault();v1099ReviewTransfer(t.dataset.requestId,t.dataset.v1099TransferSite)}else if(t.dataset.v1099AcceptTransfer){e.preventDefault();await v1099AcceptTransfer(t.dataset.requestId,t.dataset.v1099AcceptTransfer)}else if(t.dataset.v1099AddLab){e.preventDefault();v1099LabModal(null,t.dataset.v1099AddLab)}else if(t.dataset.v1099EditLab){e.preventDefault();v1099LabModal(t.dataset.v1099EditLab)}else if(t.hasAttribute('data-v1099-save-lab')){e.preventDefault();await v1099SaveLab()}},true)}
const _renderV1099Base=render;
render=function(){_renderV1099Base();installV1099();v1099RefreshSiteSelector();const main=$('#main');if(main)main.dataset.activeLab=v1099ActiveLabId()};

/* ============================================================
   LabOS REV 1.0.102 — day-resolution planning, direct timeline
   panning, complete-plan network recovery and elective sister-lab
   routing with KPI classification.
   ============================================================ */

// Day resolution in the user experience. Exact working-hour timestamps remain
// internal so resource collisions and dependencies are still validated safely.
halfDayLabelV1066=function(input){
  const d=new Date(input);if(Number.isNaN(d.getTime()))return '—';
  return d.toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'});
};
halfDayShortV1066=function(){return ''};
halfDayCoordV1066=function(input,start,days,isEnd=false){
  const d=new Date(input),day0=new Date(start);day0.setHours(0,0,0,0);const dd=new Date(d);dd.setHours(0,0,0,0);
  let delta=Math.floor((dd-day0)/86400000)+(isEnd?1:0);return Math.max(0,Math.min(days,delta));
};
moveOptionKeyV1071=function(x){return `${String(x.start||'').slice(0,10)}|${x.equipmentId||''}`};

v1096TimelineAxis=function(start,end){
  const days=(+end-+start)/86400000,
    month=v1096GroupedSegments(start,end,d=>`${d.getFullYear()}-${d.getMonth()}`,d=>d.toLocaleDateString(undefined,{month:'short',year:'numeric'}).toUpperCase(),'timeline-month-cell-v1096'),
    week=v1096GroupedSegments(start,end,d=>{const p=isoWeekPartsV1094(d);return `${p.year}-${p.week}`},d=>{const p=isoWeekPartsV1094(d);return `CW ${String(p.week).padStart(2,'0')} · ${p.year}`},'timeline-week-cell-v1096');
  let bottom='';
  if(days<=42){let d=v1096DayStart(start);while(+d<+end){const n=v1096DayEnd(d),a=new Date(Math.max(+d,+start)),b=new Date(Math.min(+n,+end)),weekend=!v1072WeekendsEnabled()&&[0,6].includes(d.getDay());bottom+=`<div class="timeline-day-cell-v1096 ${weekend?'weekend':''}" style="${v1096SegStyle(a,b,start,end)}"><strong>${esc(d.toLocaleDateString(undefined,{weekday:'short'}).toUpperCase())}</strong><em>${d.getDate()}</em></div>`;d=n}}
  else bottom=v1096GroupedSegments(start,end,d=>{const p=isoWeekPartsV1094(d);return `${p.year}-${p.week}`},d=>{const n=planAddDays(d,6);return `${d.getDate()} ${d.toLocaleDateString(undefined,{month:'short'}).toUpperCase()} – ${n.getDate()} ${n.toLocaleDateString(undefined,{month:'short'}).toUpperCase()}`},'timeline-period-cell-v1096');
  return `<div class="timeline-axis-v1096 ${days<=28?'detail':days<=98?'medium':'wide'}"><div class="timeline-month-row-v1096">${month}</div><div class="timeline-week-row-v1096">${week}</div><div class="timeline-day-row-v1096">${bottom}</div></div>`;
};
v1096TimelineToolbar=function(range){
  const label=`${Math.max(1,Math.round(range.days))} day${Math.round(range.days)===1?'':'s'} · ${P.formatDate(range.start)} – ${P.formatDate(new Date(+range.end-1))}`;
  return `<div class="timeline-toolbar-v1096" data-timeline-key="${esc(range.key)}"><button type="button" data-v1096-timeline-zoom="in" title="Zoom in: show a shorter period">−</button><button type="button" data-v1096-timeline-zoom="fit" class="${range.mode==='fit'?'active':''}" title="Fit the entire selected plan to the available width">Fit</button><button type="button" data-v1096-timeline-zoom="out" title="Zoom out: show a longer period">+</button><span class="timeline-range-label-v1096">${esc(label)}</span><span class="timeline-pan-hint-v1102">Swipe or drag chart ↔</span></div>`;
};

// The active move UI now talks in days, not half-days. Underlying proposals keep
// exact timestamps so the existing full constraint validation is preserved.
const _planningMovePanelV1071BaseV1102=planningMovePanelV1071;
planningMovePanelV1071=function(booking){_planningMovePanelV1071BaseV1102(booking);const b=document.getElementById('dragFeasibleSlotsV1061');if(b){b.innerHTML=b.innerHTML.replace(/highlighted half-day/gi,'highlighted day').replace(/half-day option/gi,'day option').replace(/half-day/gi,'day')}};
planningMovePanelV1070=planningMovePanelV1071;planningMovePanelV1065=planningMovePanelV1071;planningMovePanelV1066=planningMovePanelV1071;showFeasibleSlotsV1064=planningMovePanelV1071;showFeasibleSlotsV1061=planningMovePanelV1071;

function v1102PlanStatusText(r){
  const h=P.networkRecoveryStatusV1102(App.state,r);
  if(h.unplanned)return 'No current canonical plan';
  if(h.incomplete)return `Current plan incomplete · ${h.scheduledCount}/${h.expectedCount} canonical tasks scheduled`;
  if(h.late)return `Current plan finish ${P.formatDate(h.forecastDate)} · ${h.lateDays} day${h.lateDays===1?'':'s'} late`;
  return `Current plan finish ${P.formatDate(h.forecastDate)} · on time`;
}
v1099NetworkKpis=function(){
  const m=P.networkMetricsV1099(App.state);
  return `<div class="grid cols-3 network-kpis-v1099">${metric('Sister-lab builds',m.sisterLabBuilds,'All accepted whole-build execution-site transfers')}${metric('Sister-lab operations',m.sisterLabOperations||0,'Individual planned steps routed internally')}${metric('Recovery moves',m.recoveryTransfers||0,'Transfers triggered by an unplanned, incomplete or late home/current plan')}${metric('Elective routing',m.electiveTransfers||0,'On-time projects deliberately routed to a sister lab')}${metric('Internal hours retained',`${Math.round(m.internallyRetainedHours)} h`,'Work retained in the internal lab network')}${metric('Outsourcing avoided',`€${Math.round(m.outsourcingAvoided).toLocaleString()}`,'Estimated external benchmark spend avoided')}${metric('External spend',`€${Math.round(m.externalSpend).toLocaleString()}`,'Accepted external work')}</div>`;
};
v1099NetworkRecoveryPanel=function(){
  const site=v1099ActiveLabId(),lab=P.labByIdV1099(App.state,site),terminal=new Set(['CLOSED','DELIVERED','RELEASED','ARCHIVED']),
    open=(App.state.requests||[]).filter(r=>P.requestExecutionSiteIdV1099(App.state,r)===site&&!terminal.has(String(r.status||'').toUpperCase())),
    opps=open.filter(r=>P.networkRecoveryStatusV1102(App.state,r).requiresRecovery),
    networkOpen=(App.state.requests||[]).filter(r=>!terminal.has(String(r.status||'').toUpperCase())).sort((a,b)=>String(a.id).localeCompare(String(b.id))),
    routeOptions=networkOpen.map(r=>{const sid=P.requestExecutionSiteIdV1099(App.state,r),sl=P.labByIdV1099(App.state,sid);return `<option value="${esc(r.id)}">${esc(r.id)} · ${esc(r.productFamily||r.title||'Build')} · ${esc(sl?.code||sid)}</option>`}).join('');
  return `<section class="card lab-network-v1099"><div class="section-title-row"><div><span class="eyebrow">LAB NETWORK RECOVERY</span><h2>${esc(lab?.name||site)} · recovery candidates</h2><div class="subtle">Only active builds with no plan, an incomplete canonical plan, or a complete plan that finishes after the requested delivery cutoff appear here.</div></div><span class="pill">${opps.length} recovery opportunit${opps.length===1?'y':'ies'}</span></div>${v1099NetworkKpis()}<div class="network-opportunities-v1099">${opps.length?opps.slice(0,12).map(r=>`<div class="planning-build-row"><span><strong>${esc(r.id)} · ${esc(r.productFamily||r.title||'Build')}</strong><small>Required ${P.formatDate(r.requiredDate)} · ${esc(v1102PlanStatusText(r))}</small></span><span>${btn('Compare sister labs →',`data-v1099-compare-site="${esc(r.id)}"`,'button small primary')}</span></div>`).join(''):'<div class="callout good"><strong>No current network recovery is required.</strong><p>Every active build in this lab currently has a complete on-time canonical plan.</p></div>'}</div><div class="network-elective-routing-v1102"><div><span class="eyebrow">OPTIONAL NETWORK ROUTING</span><strong>Any active project can be considered for a sister lab</strong><small>This is available even when the current plan is on time. Accepted elective moves are tracked separately in KPI.</small></div><div class="network-route-controls-v1102"><select id="v1102NetworkProjectSelect" aria-label="Project to compare across sister labs">${routeOptions||'<option value="">No active projects</option>'}</select>${btn('Compare labs',`data-v1102-compare-selected="1"`,'button small secondary')}</div></div></section>`;
};

v1099ComparisonMarkup=function(pack){
  const req=requestById(pack.requestId),home=pack.homeSiteId,current=pack.currentSiteId,cp=pack.currentPlan,
    currentLab=v1099LabName(current),currentSummary=!cp||cp.unplanned?'No current canonical plan.':cp.incomplete?`Current plan is incomplete (${cp.scheduledCount}/${cp.expectedCount} canonical tasks scheduled), so no reliable current finish is shown.`:`Current accepted plan finishes ${P.formatDate(cp.forecast)} · ${cp.late?`${cp.lateDays} day${cp.lateDays===1?'':'s'} late`:'on time'}.`,
    currentClass=cp?.complete&&!cp?.late?'good':cp?.late?'bad':'warn';
  return `<div class="guided-network-v1099"><div class="callout ${currentClass}"><strong>Current execution plan · ${esc(currentLab)}</strong><p>${esc(currentSummary)}</p></div><div class="callout info"><strong>Why a comparison date can differ</strong><p>The cards below are <b>fresh replans from now</b>. LabOS removes this project's remaining future bookings and solves it again against today's capacity. A current reserved plan can therefore finish earlier than “Replan now at home”. These are intentionally different values.</p></div><div class="resolution-steps compact"><div class="resolution-step complete"><span class="resolution-index">✓</span><div><strong>1 · Current plan status evaluated</strong><small>${esc(P.networkRecoveryStatusV1102(App.state,req).reason)}</small></div></div><div class="resolution-step complete"><span class="resolution-index">✓</span><div><strong>2 · Every internal lab replanned independently from now</strong><small>Same canonical planner · site-owned capacity only</small></div></div><div class="resolution-step current"><span class="resolution-index">3</span><div><strong>Review timing and routing purpose</strong><small>Recovery and elective network routing are both allowed and tracked separately.</small></div></div><div class="resolution-step pending"><span class="resolution-index">4</span><div><strong>Accept controlled execution transfer</strong><small>Home site, execution site and audit history remain traceable.</small></div></div></div><div class="network-comparison-grid-v1099">${pack.rows.map(x=>{const label=x.siteId===current?'CURRENT EXECUTION · REPLAN NOW':x.siteId===home?'HOME LAB · REPLAN NOW':'SISTER LAB · REPLAN NOW';return `<div class="card ${x.siteId===current?'selected':''}"><span class="eyebrow">${esc(label)}</span><h3>${esc(x.lab.name)}</h3>${x.ok?`<p><strong>${P.formatDate(x.forecast)}</strong> · ${x.onTime?'<span class="good">on time</span>':`<span class="bad">${x.daysLate} d late</span>`}</p><small>${x.plannedHours} planned h</small>${x.siteId!==current?btn('Review transfer →',`data-v1099-transfer-site="${esc(x.siteId)}" data-request-id="${esc(pack.requestId)}"`,'button small primary'):''}`:`<div class="callout bad"><strong>No complete valid replan</strong><p>${esc(x.failure?.diagnosis?.summary||x.failure?.error||'Blocked')}</p></div>`}</div>`}).join('')}</div>${pack.externalBenchmark?`<div class="callout warn"><strong>External benchmark · ${esc(pack.externalBenchmark.lab.name)}</strong><p>Indicative forecast ${P.formatDate(pack.externalBenchmark.forecast)} · estimated cost <strong>€${Math.round(pack.externalBenchmark.estimatedCost).toLocaleString()}</strong>. ${pack.externalBenchmark.costBasisV123?.quotedTestCount?`${pack.externalBenchmark.costBasisV123.quotedTestCount} test-specific external price(s) contribute ${P.currency(pack.externalBenchmark.costBasisV123.quotedTestCost||0)}${pack.externalBenchmark.costBasisV123.evidenceCount?` · ${pack.externalBenchmark.costBasisV123.evidenceCount} with attached proof`:''}${pack.externalBenchmark.costBasisV123.expiredCount?` · ${pack.externalBenchmark.costBasisV123.expiredCount} expired commercial record(s) require refresh`:''}. Remaining work uses the generic facility benchmark.`:'No test-specific external prices apply, so the generic facility benchmark is used.'} Benchmark only; it is not automatically selected.</p></div>`:''}</div>`;
};
v1099OpenComparison=function(requestId){
  openModal(`Lab network comparison · ${requestId}`,`<div class="planner-computing-v1094"><span class="spinner"></span><div><strong>Replanning the build independently at each internal laboratory…</strong><small>The current accepted plan remains untouched. Each comparison starts from now using site-owned people, equipment, materials and readiness.</small></div></div>`,btn('Cancel','data-modal-close','button'),true);
  setTimeout(()=>{let pack;try{pack=P.MultiLabPlanningV1099.compareSites(App.state,requestId)}catch(e){openModal('Lab network comparison',`<div class="callout bad"><strong>Comparison stopped safely.</strong><p>${esc(e.message||e)}</p></div>`,btn('Close','data-modal-close','button'),true);return}App.pendingNetworkComparisonV1099=pack;openModal(`Lab network comparison · ${requestId}`,v1099ComparisonMarkup(pack),btn('Close','data-modal-close','button'),true)},20);
};
v1099ReviewTransfer=function(requestId,siteId){
  const pack=App.pendingNetworkComparisonV1099||P.MultiLabPlanningV1099.compareSites(App.state,requestId),row=pack.rows.find(x=>x.siteId===siteId&&x.ok);if(!row)return toast('That sister-lab plan is no longer valid.',true);
  const recovery=P.networkRecoveryStatusV1102(App.state,requestId),mode=recovery.requiresRecovery?'RECOVERY':'ELECTIVE ROUTING',why=recovery.requiresRecovery?'Current execution cannot provide a complete on-time canonical plan; the selected internal lab provides a controlled recovery option.':'Current execution has an acceptable complete plan; this is a deliberate sister-lab routing decision for network balancing, capability or another documented business reason.';
  openModal(`Transfer execution · ${requestId}`,`<div class="callout ${recovery.requiresRecovery?'warn':'info'}"><strong>${mode} · controlled execution-site change</strong><p>Home site remains ${esc(v1099LabName(pack.homeSiteId))}. Execution would move to <strong>${esc(row.lab.name)}</strong> with fresh replan finish <strong>${P.formatDate(row.forecast)}</strong>. KPI classification: <strong>${mode}</strong>.</p></div><label>Decision rationale<textarea id="v1099TransferRationale" rows="3">${esc(why)}</textarea></label>`,`${btn('Cancel','data-modal-close','button')}${btn('Accept transfer & replan',`data-v1099-accept-transfer="${esc(siteId)}" data-request-id="${esc(requestId)}"`,'button next-action')}`,true);
};

const _workspaceScheduleV1102Base=workspaceSchedule;
workspaceSchedule=function(r){
  const html=_workspaceScheduleV1102Base(r),terminal=['CLOSED','DELIVERED','RELEASED','ARCHIVED'].includes(String(r?.status||'').toUpperCase());if(!r||terminal)return html;
  const sid=P.requestExecutionSiteIdV1099(App.state,r),lab=P.labByIdV1099(App.state,sid),recovery=P.networkRecoveryStatusV1102(App.state,r);
  return html+`<section class="card workspace-network-routing-v1102"><div class="section-title-row"><div><span class="eyebrow">LAB NETWORK EXECUTION</span><h3>${recovery.requiresRecovery?'Recovery option available':'Optional sister-lab routing'}</h3><p class="subtle">Current execution: ${esc(lab?.name||sid)} · ${esc(recovery.reason)}. Any active project can be compared with sister labs; elective transfers are KPI-tracked separately.</p></div>${btn('Compare sister labs →',`data-v1099-compare-site="${esc(r.id)}"`,'button small secondary')}</div></section>`;
};

function v1102InstallTimelinePan(){
  if(App._v1102TimelinePanInstalled)return;App._v1102TimelinePanInstalled=true;let drag=null;
  const blocked=t=>!!t?.closest?.('button,input,select,textarea,a,label,summary,.swim-bar,[data-planning-booking-v1061],.planning-slot-overlay-v1071,.drag-slot');
  document.addEventListener('pointerdown',e=>{const sc=e.target.closest?.('.timeline-scroll-v1096');if(!sc||blocked(e.target)||e.button>0)return;const root=sc.closest('[data-v1096-timeline]');if(!root)return;const start=+new Date(root.dataset.rangeStart),end=+new Date(root.dataset.rangeEnd);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,start,end,days:(end-start)/86400000,width:Math.max(120,sc.clientWidth),root,sc,moved:false};try{sc.setPointerCapture?.(e.pointerId)}catch(_){}} ,true);
  document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.abs(dx)>8&&Math.abs(dx)>Math.abs(dy)){drag.moved=true;drag.sc.classList.add('timeline-panning-v1102')}if(drag.moved)e.preventDefault()}, {capture:true,passive:false});
  const finish=e=>{if(!drag||e.pointerId!==drag.id)return;const d=drag;drag=null;d.sc.classList.remove('timeline-panning-v1102');const dx=e.clientX-d.x;if(!d.moved||Math.abs(dx)<18)return;const key=d.root.dataset.v1096Timeline;App.timelineViewportV1096=App.timelineViewportV1096||{};const shiftDays=-(dx/d.width)*d.days;App.timelineViewportV1096[key]={mode:'span',spanDays:Math.max(2,d.days),centerMs:(d.start+d.end)/2+shiftDays*86400000};render()};
  document.addEventListener('pointerup',finish,true);document.addEventListener('pointercancel',e=>{if(drag&&e.pointerId===drag.id){drag.sc.classList.remove('timeline-panning-v1102');drag=null}},true);
}
function v1102InstallNetworkRouting(){
  if(App._v1102NetworkRoutingInstalled)return;App._v1102NetworkRoutingInstalled=true;document.addEventListener('click',e=>{const t=e.target.closest?.('[data-v1102-compare-selected]');if(!t)return;e.preventDefault();const id=$('#v1102NetworkProjectSelect')?.value;if(id)v1099OpenComparison(id);else toast('Select an active project first.',true)},true);
}
function installV1102(){v1102InstallTimelinePan();v1102InstallNetworkRouting()}
const _renderV1102Base=render;
render=function(){_renderV1102Base();installV1102()};
window.__LABOS_V1102_TEST__={planStatus:r=>P.networkRecoveryStatusV1102(App.state,r),timelineAxis:v1096TimelineAxis,timelineToolbar:v1096TimelineToolbar};


/* REV 1.0.109 Scenario Lab Stage 2 UI */
function v1103Site(){return App.state.settings?.activeLabId||App.state.settings?.primaryLabId||'LAB-NL'}
function v1103Tomorrow(n=1){const d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function v1103Money(v){return `€${Math.round(Number(v||0)).toLocaleString()}`}
function v1103Pct(v){return `${Math.round(Number(v||0)*100)}%`}
function v1103ResourceOptions(type){const sid=v1103Site();if(type==='equipment_outage')return (App.state.equipment||[]).filter(x=>x.siteId===sid).map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.capability||'equipment')}</option>`).join('');if(type==='staff_absence')return (App.state.staff||[]).filter(x=>x.siteId===sid).map(x=>`<option value="${esc(x.id)}">${esc(x.name)} · ${esc(x.role||'staff')}</option>`).join('');return '<option value="">Not applicable</option>'}
function v1103Mechanisms(o){const x=[];if(o.diff?.equipmentReassignments)x.push(`${o.diff.equipmentReassignments} equipment reassignment${o.diff.equipmentReassignments===1?'':'s'}`);if(o.diff?.staffReassignments)x.push(`${o.diff.staffReassignments} person reassignment${o.diff.staffReassignments===1?'':'s'}`);if(o.diff?.weekendHoursDelta)x.push(`${o.diff.weekendHoursDelta.toFixed(1)} weekend h`);if(o.kind==='sister')x.push(`complete route to ${o.meta?.labName||o.siteId}`);if(o.kind==='external')x.push('external capacity');if(o.kind==='commitment')x.push('formal commitment movement');if(o.kind==='split-review')x.push('selected-process sister-lab review');return x.join(' · ')||'Current controlled resources and sequence'}
function v1103OptionCard(o,recommended){const t=o.target||{},m=o.metrics||{},cls=t.onTime?'good':t.late?'bad':'warn',review=o.applyMode==='review',rank=review?(o.rank||'REVIEW'):(o.rank?`#${o.rank}`:'OPTION'),gain=o.improvementVsBaseline?.summary||'Verified improvement over baseline';return `<article class="scenario-option-v1103 ${recommended?'recommended':''}"><div class="scenario-option-head-v1103"><div><span class="scenario-rank-v1103">${esc(String(rank))}</span><span class="eyebrow">${recommended?'RECOMMENDED · ':''}${esc(String(o.kind||'OPTION').toUpperCase())}</span><h3>${esc(o.label)}</h3></div><span class="pill ${cls}">${t.onTime?'Target on time':t.unresolved?'Unresolved':`${t.lateDays||0} d late`}</span></div><div class="scenario-improvement-v1106"><strong>BETTER THAN BASELINE</strong><span>${esc(gain)}</span></div><p>${esc(o.description||'')}</p><div class="scenario-option-kpis-v1103"><span><small>Target finish</small><strong>${t.forecast?P.formatDate(t.forecast):'—'}</strong></span><span><small>Network on-time</small><strong>${v1103Pct(m.onTimeRate)}</strong></span><span><small>Total late days</small><strong>${Number(m.totalLateDays||0)}</strong></span><span><small>Other projects worsened</small><strong>${Number(o.diff?.worsenedCount||0)}</strong></span><span><small>Bookings moved</small><strong>${Number(o.diff?.movedBookings||0)}</strong></span><span><small>Incremental cost</small><strong>${v1103Money(o.estimatedCost)}</strong></span></div><div class="scenario-mechanisms-v1103">${esc(v1103Mechanisms(o))}</div><small class="scenario-rank-reason-v1103">${esc(o.rankReason||'')}</small><div class="route-toolbar">${btn('Review impact',`data-v1103-review="${esc(o.id)}"`,'button small secondary')}${review?btn('Create split-route proposal',`data-v1103-split="${esc(o.id)}"`,'button small primary'):btn('Apply to LIVE →',`data-v1103-apply="${esc(o.id)}"`,'button small primary')}</div></article>`}
function v1103TargetLabel(t){if(!t)return '—';if(t.unresolved)return 'Unresolved';if(t.onTime)return 'On time';return `${Number(t.lateDays||0)} d late`}
function v1103ComparisonTable(pack){const live=pack?.liveComparisonBaseline||pack?.comparisonBaseline||{target:pack?.targetLive,metrics:pack?.baseline,diff:{},estimatedCost:0,residualConflicts:0},scenario=pack?.scenarioBaseline||null,rows=[{baseline:true,label:'Current LIVE baseline',rank:'LIVE',target:live.target||{},metrics:live.metrics||{},diff:live.diff||{},estimatedCost:0,residualConflicts:0,improvementVsBaseline:{summary:'Untouched accepted plan — optimization reference'}},...(scenario?[{scenarioAsIs:true,label:'Scenario as-is',rank:'IMPACT',target:scenario.target||{},metrics:scenario.metrics||{},diff:scenario.diff||{},estimatedCost:0,residualConflicts:Number(scenario.residualConflicts||0),improvementVsBaseline:{summary:'Impact after applying the disruption, before recovery'}}]:[]),...(pack?.options||[])];return `<div class="scenario-comparison-v1106"><div class="section-title-row"><div><span class="eyebrow">LIVE BASELINE VS SCENARIO IMPACT VS VERIFIED OPTIMIZATIONS</span><h3>Decision comparison</h3><div class="subtle">The untouched LIVE plan is the optimization reference. The Scenario as-is row shows the disruption impact only. An option is shown as an optimization only when it resolves scenario conflicts and does not worsen any critical delivery KPI versus LIVE while improving at least one.</div></div><span class="pill good">${pack?.options?.length||0} verified improvement${pack?.options?.length===1?'':'s'}</span></div><div class="table-wrap scenario-comparison-scroll-v1106"><table class="data-table scenario-comparison-table-v1106"><thead><tr><th>Rank</th><th>Plan</th><th>Target finish</th><th>Target status</th><th>Network OTD</th><th>Portfolio late days</th><th>Scenario conflicts</th><th>Other projects worsened</th><th>Bookings moved</th><th>Added cost</th><th>Meaning</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.baseline?'scenario-baseline-row-v1106':r.scenarioAsIs?'scenario-impact-row-v1109':r.id===pack?.recommendedId?'scenario-recommended-row-v1106':''}"><td><strong>${esc(String(r.baseline?'LIVE':r.scenarioAsIs?'IMPACT':r.rank||'REVIEW'))}</strong></td><td><strong>${esc(r.label||'Option')}</strong>${r.baseline?'<br><small>Optimization reference</small>':r.scenarioAsIs?'<br><small>Not a proposal</small>':r.id===pack?.recommendedId?'<br><small>Recommended</small>':''}</td><td>${r.target?.forecast?P.formatDate(r.target.forecast):'—'}</td><td>${esc(v1103TargetLabel(r.target))}</td><td>${v1103Pct(r.metrics?.onTimeRate)}</td><td>${Number(r.metrics?.totalLateDays||0)}</td><td>${Number(r.residualConflicts||0)}</td><td>${Number(r.diff?.worsenedCount||0)}</td><td>${Number(r.diff?.movedBookings||0)}</td><td>${v1103Money(r.estimatedCost)}</td><td>${esc(r.improvementVsBaseline?.summary||'—')}</td></tr>`).join('')}</tbody></table></div></div>`}
function v1103Saved(){P.ensureScenarioModelV1103?.(App.state);const rows=(App.state.scenarioRuns||[]).slice(0,8);if(!rows.length)return '';return `<details class="fold compact scenario-saved-v1103"><summary>Saved scenario analyses · ${rows.length}</summary><div class="scenario-saved-list-v1103">${rows.map(x=>`<div><span><strong>${esc(x.name)}</strong><small>${P.formatDateTime(x.createdAt)} · ${esc(x.spec?.targetRequestId||'portfolio')} · ${x.options?.length||0} options</small></span>${btn('Run again',`data-v1103-rerun="${esc(x.id)}"`,'button tiny secondary')}</div>`).join('')}</div></details>`}
function v1103Markup(){P.ensureScenarioModelV1103?.(App.state);const sid=v1103Site(),lab=P.labByIdV1099?.(App.state,sid),active=(App.state.requests||[]).filter(r=>!['CLOSED','DELIVERED','RELEASED','ARCHIVED'].includes(String(r.status||'').toUpperCase())&&P.requestExecutionSiteIdV1099(App.state,r)===sid).sort((a,b)=>String(a.requiredDate||'').localeCompare(String(b.requiredDate||''))),pick=App.scenarioTargetV1103||active[0]?.id||'',pack=App.pendingScenarioV1103,reco=pack?.options?.find(o=>o.id===pack.recommendedId),undo=App.state.scenarioLastUndoV1103;const options=active.map(r=>{const h=P.networkRecoveryStatusV1102(App.state,r);return `<option value="${esc(r.id)}" ${r.id===pick?'selected':''}>${esc(r.id)} · ${esc(r.productFamily||r.title)} · ${esc(h.requiresRecovery?h.reason:'on time')}</option>`}).join(''),baseline=pack?.liveComparisonBaseline||pack?.comparisonBaseline,scenarioBaseline=pack?.scenarioBaseline,baseConflicts=Number(scenarioBaseline?.residualConflicts||0),filtered=Number(pack?.filteredOutCount||0),evaluated=Number(pack?.evaluatedOptionCount||0);let result='';if(pack){const noBetter=!pack.options?.length,noBetterText=baseConflicts?`No verified optimization beats the current LIVE plan. The simulated disruption creates ${baseConflicts} conflict${baseConflicts===1?'':'s'}; review the Scenario as-is impact or change the assumptions. Recovery trade-offs that are worse than LIVE are intentionally not proposed as optimizations.`:`The current LIVE baseline remains best. ${filtered||evaluated} evaluated alternative${(filtered||evaluated)===1?' was':'s were'} suppressed because they did not produce a Pareto improvement versus LIVE.`;result=`<div class="scenario-result-summary-v1103 scenario-result-summary-v1106"><div><span class="eyebrow">SCENARIO RESULT</span><strong>${baseConflicts?`${baseConflicts} simulated conflict${baseConflicts===1?'':'s'} to recover`:'Scenario introduces no direct conflict'}</strong><small>${pack.directImpacts?.length||0} accepted booking${pack.directImpacts?.length===1?'':'s'} directly intersect the simulated disruption · LIVE data unchanged.</small><small>${evaluated} candidate${evaluated===1?'':'s'} evaluated · ${filtered} non-improving option${filtered===1?'':'s'} hidden.</small></div><div class="scenario-baseline-compare-v1103 scenario-baseline-kpis-v1106"><span><small>LIVE target</small><strong>${baseline?.target?.forecast?P.formatDate(baseline.target.forecast):'—'}</strong></span><span><small>LIVE OTD</small><strong>${v1103Pct(baseline?.metrics?.onTimeRate)}</strong></span><span><small>Verified improvements</small><strong>${pack.options?.length||0}</strong></span><span><small>Recommended target</small><strong>${reco?.target?.forecast?P.formatDate(reco.target.forecast):'—'}</strong></span></div></div>${v1103ComparisonTable(pack)}${noBetter?`<div class="callout ${baseConflicts?'bad':'good'} scenario-no-better-v1106"><strong>${baseConflicts?'No verified optimization beats LIVE':'Keep the current LIVE baseline'}</strong><p>${esc(noBetterText)}</p></div>`:`<div class="scenario-options-v1103">${pack.options.map(o=>v1103OptionCard(o,o.id===pack.recommendedId)).join('')}</div>`}`}
return `<section id="planning-scenario-lab-v1103" class="card scenario-lab-v1103 section-jump-target"><div class="scenario-live-banner-v1103"><span>SCENARIO LAB · STAGE 2</span><strong>OPTIMIZATION & RECOVERY</strong><em>NOT LIVE until explicitly applied</em></div><div class="section-title-row"><div><span class="eyebrow">OPERATIONAL DIGITAL TWIN</span><h2>Compare only verified LIVE improvements before changing the live plan</h2><div class="subtle">The scenario is a disposable clone. Every executable recovery is solved by the same canonical planner used for live scheduling. Alternatives that do not beat the untouched current LIVE baseline are automatically discarded as optimizations.</div></div>${undo?btn('Undo last applied scenario','data-v1103-undo="1"','button small danger'):''}</div><div class="scenario-builder-v1103"><label>Target build<select id="v1103Target">${options||'<option value="">No active builds</option>'}</select></label><label>Disruption<select id="v1103Type"><option value="none">Current risk / recovery scan</option><option value="equipment_outage">Equipment outage</option><option value="staff_absence">Person absence</option><option value="lab_closure">Lab closure</option><option value="priority_change">Priority escalation</option><option value="material_delay">Material delay</option></select></label><label id="v1103ResourceWrap">Affected resource<select id="v1103Resource"><option value="">Not applicable</option></select></label><label id="v1103StartWrap"><span id="v1103StartLabel">Unavailable from</span><input id="v1103Start" type="date" value="${v1103Tomorrow(1)}"></label><label id="v1103EndWrap"><span id="v1103EndLabel">Unavailable through</span><input id="v1103End" type="date" value="${v1103Tomorrow(8)}"></label><div id="v1103Context" class="callout info scenario-context-v1104"></div><label>Decision objective<select id="v1103Objective"><option value="balanced">Balanced · delivery / disruption / cost</option><option value="delivery">Delivery first</option><option value="min-disruption">Minimum disruption</option><option value="min-cost">Minimum incremental cost</option></select></label></div><div class="route-toolbar scenario-runbar-v1103">${btn('Generate & rank better options','data-v1103-run="1"','button primary')}${pack?btn('Save analysis','data-v1103-save="1"','button secondary'):''}${pack?btn('Clear','data-v1103-clear="1"','button'):''}<span class="subtle">Active lab: ${esc(lab?.name||sid)}</span></div>${pack?result:`<div class="scenario-empty-v1103"><strong>Choose a build and disruption, then run the twin.</strong><span>LabOS tests protected resequencing, alternative resources, readiness/training, lower-priority movement, weekend capacity, sister labs, split-route review, external facilities and commitment movement — and shows only options that improve the baseline.</span></div>`}${v1103Saved()}</section>`}

function v1103UpdateResource(){const type=$('#v1103Type')?.value||'none',sel=$('#v1103Resource'),resourceWrap=$('#v1103ResourceWrap'),startWrap=$('#v1103StartWrap'),endWrap=$('#v1103EndWrap'),startLabel=$('#v1103StartLabel'),endLabel=$('#v1103EndLabel'),context=$('#v1103Context');if(!sel||!resourceWrap||!startWrap||!endWrap)return;sel.innerHTML=v1103ResourceOptions(type);const cfg={none:{resource:false,start:false,end:false,title:'Current risk / recovery scan',help:'Uses the current LIVE portfolio and current constraints exactly as they stand. No disruption dates are applied.'},equipment_outage:{resource:true,start:true,end:true,title:'Equipment outage',help:'Temporarily removes the selected equipment from capacity for the dates below, then searches for the best controlled recovery.'},staff_absence:{resource:true,start:true,end:true,title:'Person absence',help:'Temporarily removes the selected person from capacity for the dates below, then searches for the best controlled recovery.'},lab_closure:{resource:false,start:true,end:true,title:'Lab closure',help:'Temporarily closes the active lab for the dates below, then tests local recovery, sister labs and other alternatives.'},priority_change:{resource:false,start:false,end:false,title:'Priority escalation',help:'Escalates the selected build to Critical inside the scenario only. No dates are required.'},material_delay:{resource:false,start:false,end:true,title:'Material delay',help:"Moves the selected build's earliest planning date to the material-available date below."}}[type]||{};resourceWrap.hidden=!cfg.resource;startWrap.hidden=!cfg.start;endWrap.hidden=!cfg.end;sel.disabled=!cfg.resource;if(startLabel)startLabel.textContent='Unavailable from';if(endLabel)endLabel.textContent=type==='material_delay'?'Material available on':'Unavailable through';if(context)context.innerHTML=`<strong>${esc(cfg.title||'Scenario')}</strong><span>${esc(cfg.help||'')}</span>`}
function v1103Inject(){if(App.currentView==='planning'){const page=$('#page');if(!page)return;if(page.querySelector('[data-canonical-planning]'))return;if(!page.querySelector('#planning-scenario-lab-v1103')){const x=document.createElement('div');x.innerHTML=v1103Markup();const sec=x.firstElementChild,net=page.querySelector('.lab-network-v1099'),pot=page.querySelector('#planning-potential-demand-v1090');if(net)net.after(sec);else if(pot)pot.before(sec);else page.append(sec)}const navEl=page.querySelector('.section-jump-nav');if(navEl&&!navEl.querySelector('[data-v1103-jump]')){const b=document.createElement('button');b.type='button';b.dataset.v1103Jump='1';b.textContent='Scenario Lab';b.onclick=()=>$('#planning-scenario-lab-v1103')?.scrollIntoView({behavior:'smooth',block:'start'});navEl.appendChild(b)}v1103UpdateResource();page.querySelectorAll('[data-v1099-compare-site]').forEach(c=>{const p=c.parentElement;if(p&&!p.querySelector('[data-v1103-open]')){const b=document.createElement('button');b.type='button';b.className='button small secondary';b.dataset.v1103Open=c.dataset.v1099CompareSite;b.textContent='Optimize recovery';p.prepend(b)}})}if(App.currentView==='workspace'&&App.workspaceTab==='schedule'){const c=$('.workspace-network-routing-v1102');if(c&&!c.querySelector('[data-v1103-open]')){const b=document.createElement('button');b.type='button';b.className='button small primary';b.dataset.v1103Open=App.workspaceId;b.textContent='Scenario Lab →';c.querySelector('.section-title-row')?.appendChild(b)}}}
function v1103Spec(){const target=$('#v1103Target')?.value||App.scenarioTargetV1103,type=$('#v1103Type')?.value||'none',resource=$('#v1103Resource')?.value||'',start=$('#v1103Start')?.value||'',end=$('#v1103End')?.value||'',objective=$('#v1103Objective')?.value||'balanced';if(!target)throw new Error('Select an active build.');let assumption={type,requestId:target};if(['equipment_outage','staff_absence'].includes(type)){if(!resource)throw new Error('Select the affected resource.');if(!start||!end)throw new Error('Enter the disruption start and end dates.');if(end<start)throw new Error('The end date cannot be before the start date.');assumption={...assumption,objectId:resource,startDate:start,endDate:end}}else if(type==='lab_closure'){if(!start||!end)throw new Error('Enter the closure start and end dates.');if(end<start)throw new Error('The end date cannot be before the start date.');assumption={...assumption,startDate:start,endDate:end}}else if(type==='priority_change'){assumption={...assumption,priority:'Critical'}}else if(type==='material_delay'){if(!end)throw new Error('Enter the date on which material will be available.');assumption={...assumption,endDate:end}}return {name:`${target} · ${type==='none'?'recovery scan':type.replaceAll('_',' ')}`,siteId:v1103Site(),targetRequestId:target,objective,assumptions:[assumption]}}
function v1103Run(spec=null){let s;try{s=spec||v1103Spec()}catch(e){toast(e.message,true);return}openModal('Scenario Lab · solving',`<div class="planner-computing-v1094"><span class="spinner"></span><div><strong>Generating recovery alternatives…</strong><small>LIVE plan remains untouched while the canonical planner evaluates local, network and external options.</small></div></div>`,btn('Cancel','data-modal-close','button'),true);setTimeout(()=>{try{App.pendingScenarioV1103=P.ScenarioEngineV1103.generate(App.state,s);App.scenarioTargetV1103=s.targetRequestId;closeModal();render();setTimeout(()=>$('#planning-scenario-lab-v1103')?.scrollIntoView({behavior:'smooth',block:'start'}),50)}catch(e){openModal('Scenario Lab',`<div class="callout bad"><strong>Scenario stopped safely.</strong><p>${esc(e.message||e)}</p></div>`,btn('Close','data-modal-close','button'),true)}},30)}
function v1103Review(id){const o=App.pendingScenarioV1103?.options?.find(x=>x.id===id);if(!o)return;const changes=(o.diff?.changed||[]).map(x=>`<tr><td>${esc(x.requestId)}</td><td>${esc(x.stepName||'Task')}</td><td>${x.from?P.formatDate(x.from):'—'}</td><td>${x.to?P.formatDate(x.to):'—'}</td><td>${x.fromEquipment!==x.toEquipment?`${esc(x.fromEquipment||'—')} → ${esc(x.toEquipment||'—')}`:'—'}</td><td>${x.fromStaff!==x.toStaff?`${esc(x.fromStaff||'—')} → ${esc(x.toStaff||'—')}`:'—'}</td></tr>`).join(''),worse=(o.diff?.worsened||[]).map(x=>`<li><strong>${esc(x.requestId)}</strong> · ${P.formatDate(x.from)} → ${P.formatDate(x.to)} · +${x.shift} d</li>`).join('');openModal(`Scenario option · ${o.label}`,`<div class="callout ${o.target?.onTime?'good':o.target?.late?'warn':'bad'}"><strong>${esc(o.rankReason||'')}</strong><p>${esc(v1103Mechanisms(o))}</p></div><div class="grid cols-4 scenario-review-kpis-v1103"><div class="mini-kpi"><span>Target finish</span><strong>${o.target?.forecast?P.formatDate(o.target.forecast):'—'}</strong></div><div class="mini-kpi"><span>Network OTD</span><strong>${v1103Pct(o.metrics?.onTimeRate)}</strong></div><div class="mini-kpi"><span>Moved bookings</span><strong>${o.diff?.movedBookings||0}</strong></div><div class="mini-kpi"><span>Cost</span><strong>${v1103Money(o.estimatedCost)}</strong></div></div>${changes?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Build</th><th>Step</th><th>Before</th><th>After</th><th>Equipment</th><th>Person</th></tr></thead><tbody>${changes}</tbody></table></div>`:'<div class="callout info">No sampled booking-level movement.</div>'}${worse?`<div class="callout warn"><strong>Other projects become later</strong><ul>${worse}</ul></div>`:''}${o.applyMode==='review'?`<div class="callout info"><strong>Split-route opportunities</strong><ul>${(o.meta?.steps||[]).map(s=>`<li>${esc(s.stepName)} · ${s.gainDays} d earlier at ${esc(o.meta?.sisterLab||o.meta?.sisterSiteId)}</li>`).join('')}</ul><p>This creates a governed proposal only; it does not fabricate mixed-site bookings.</p></div>`:''}`,`${btn('Close','data-modal-close','button')}${o.applyMode==='review'?btn('Create split-route proposal',`data-v1103-split="${esc(o.id)}"`,'button primary'):btn('Apply to LIVE →',`data-v1103-apply="${esc(o.id)}"`,'button primary')}`,true)}
function v1103ApplyAsk(id){const o=App.pendingScenarioV1103?.options?.find(x=>x.id===id);if(!o)return;openModal(`Apply scenario · ${o.label}`,`<div class="callout warn"><strong>This changes the LIVE operational plan.</strong><p>${o.diff?.movedBookings||0} booking(s) move and ${o.diff?.worsenedCount||0} other project(s) become later. The previous state is retained for one-click undo.</p></div><label>Decision rationale<textarea id="v1103Rationale" rows="4">${esc(o.target?.onTime?'Selected recovery preserves the required timing with the best ranked balance of delivery, disruption and cost.':'Selected option is the best controlled recovery after reviewing delivery, disruption and cost.')}</textarea></label>`,`${btn('Cancel','data-modal-close','button')}${btn('Apply to LIVE plan',`data-v1103-confirm="${esc(id)}"`,'button next-action')}`,true)}
async function v1103Apply(id){const rationale=String($('#v1103Rationale')?.value||'').trim();if(rationale.length<12)return toast('Add a meaningful decision rationale.',true);const r=P.ScenarioEngineV1103.applyOption(App.state,App.pendingScenarioV1103,id,rationale);if(!r.ok)return toast(r.error,true);App.state=r.next;App.pendingScenarioV1103=null;await persist();closeModal();render();toast(`Scenario applied · ${r.application.optionLabel}`)}
function v1103SplitAsk(id){const o=App.pendingScenarioV1103?.options?.find(x=>x.id===id);if(!o)return;openModal('Create split-route proposal',`<div class="callout info"><strong>Proposal only — LIVE bookings remain unchanged.</strong><p>Selected steps appear materially earlier at ${esc(o.meta?.sisterLab||o.meta?.sisterSiteId)}. Transport, custody, handover and sequence controls must be reviewed before execution.</p></div><label>Rationale<textarea id="v1103SplitReason" rows="3">Offload only the identified bottleneck steps to the sister lab, subject to transport and handover feasibility.</textarea></label>`,`${btn('Cancel','data-modal-close','button')}${btn('Create review proposal',`data-v1103-split-confirm="${esc(id)}"`,'button primary')}`,true)}
async function v1103Split(id){const reason=String($('#v1103SplitReason')?.value||'').trim(),r=P.ScenarioEngineV1103.createSplitProposal(App.state,App.pendingScenarioV1103,id,reason);if(!r.ok)return toast(r.error,true);await persist();closeModal();render();toast('Split-route proposal created; LIVE bookings unchanged.')}
function v1103SaveAsk(){const p=App.pendingScenarioV1103;if(!p)return;openModal('Save scenario analysis',`<label>Name<input id="v1103SaveName" value="${esc(p.spec?.name||'Scenario recovery')}"></label><div class="callout info">The compact scenario definition/results are saved; candidate state is rerun against current LIVE data when needed.</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save',`data-v1103-save-confirm="1"`,'button primary')}`)}
