async function v1103Undo(){if(!confirm('Revert the last applied Scenario Lab recovery and restore its prior planning state?'))return;const r=P.ScenarioEngineV1103.undoLast(App.state);if(!r.ok)return toast(r.error,true);await persist();render();toast(`Scenario reverted · ${r.label}`)}
function v1103Open(id){App.scenarioTargetV1103=id;App.pendingScenarioV1103=null;nav('planning');setTimeout(()=>$('#planning-scenario-lab-v1103')?.scrollIntoView({behavior:'smooth',block:'start'}),70)}
function v1103Install(){if(App._v1103Installed)return;App._v1103Installed=true;document.addEventListener('change',e=>{if(e.target?.id==='v1103Type')v1103UpdateResource()},true);document.addEventListener('click',async e=>{const t=e.target.closest?.('[data-v1103-run],[data-v1103-review],[data-v1103-apply],[data-v1103-confirm],[data-v1103-split],[data-v1103-split-confirm],[data-v1103-save],[data-v1103-save-confirm],[data-v1103-clear],[data-v1103-undo],[data-v1103-rerun],[data-v1103-open]');if(!t)return;e.preventDefault();if(t.dataset.v1103Run)v1103Run();else if(t.dataset.v1103Review)v1103Review(t.dataset.v1103Review);else if(t.dataset.v1103Apply)v1103ApplyAsk(t.dataset.v1103Apply);else if(t.dataset.v1103Confirm)await v1103Apply(t.dataset.v1103Confirm);else if(t.dataset.v1103Split)v1103SplitAsk(t.dataset.v1103Split);else if(t.dataset.v1103SplitConfirm)await v1103Split(t.dataset.v1103SplitConfirm);else if(t.dataset.v1103Save)v1103SaveAsk();else if(t.dataset.v1103SaveConfirm)await v1103Save();else if(t.dataset.v1103Clear){App.pendingScenarioV1103=null;render()}else if(t.dataset.v1103Undo)await v1103Undo();else if(t.dataset.v1103Rerun){const x=(App.state.scenarioRuns||[]).find(r=>r.id===t.dataset.v1103Rerun);if(x)v1103Run(P.deepClone(x.spec))}else if(t.dataset.v1103Open)v1103Open(t.dataset.v1103Open)},true)}
