window.__LABOS_V1103_TEST__={markup:v1103Markup,spec:v1103Spec,inject:v1103Inject};


/* ============================================================
   LabOS REV 1.0.109 — AUTO PLAN decision UX (preserved).
   Only verified baseline improvements are presented as optimization
   scenarios. Feasibility recoveries that worsen a critical KPI are
   separated into a clearly-labelled recovery trade-off section.
   ============================================================ */
function v1107MetricCell(before,after,suffix=''){const b=Number(before||0),a=Number(after||0),d=a-b,cls=d<0?'good-text':d>0?'bad-text':'';return `<td><strong class="${cls}">${a}${suffix}</strong><small>${d===0?'—':`${d>0?'+':''}${d}${suffix}`}</small></td>`}
function v1107ComparisonTable(pack,targetRequestId=null){const rows=pack.optimizationCandidates||[],b=pack.baseline||{};return `<section class="planner-compare-v1107"><div class="section-title-row compact"><div><span class="eyebrow">BASELINE VS VERIFIED OPTIMIZATIONS</span><h3>Compare impact before choosing</h3><div class="subtle">An option appears here only when no critical delivery KPI is worse than the current LIVE baseline and either a delivery outcome improves or AUTO PLAN can release a re-optimizable manual delay. Explicitly protected manual slots remain fixed.</div></div><span class="pill">${rows.length} better option${rows.length===1?'':'s'}</span></div><div class="table-wrap planner-compare-wrap-v1107"><table class="data-table planner-compare-table-v1107"><thead><tr><th>Scenario</th><th>Unplanned</th><th>Total late</th><th>Max delay</th><th>Commitment worsening</th><th>Priority-weighted late</th><th>Projects moved later</th><th>Decision</th></tr></thead><tbody><tr class="baseline-v1107"><td><strong>Current LIVE baseline</strong><small>Reference plan</small></td><td><strong>${b.unplanned||0}</strong></td><td><strong>${b.totalLateDays||0} d</strong></td><td><strong>${b.maxLateDays||0} d</strong></td><td><strong>${b.commitmentWorseningDays||0} d</strong></td><td><strong>${b.weightedLateDays||0}</strong></td><td><strong>0</strong></td><td><span class="status neutral">Baseline</span></td></tr>${rows.map(r=>{const m=r.candidate.metrics||{},a=r.assessmentV1107||{},rec=pack.recommended?.tier===r.tier;return `<tr class="improvement-v1107"><td><strong>${esc(r.label)}</strong><small>${esc(r.candidate.orderMode||'solver')}</small></td>${v1107MetricCell(b.unplanned,m.unplanned)}${v1107MetricCell(b.totalLateDays,m.totalLateDays,' d')}${v1107MetricCell(b.maxLateDays,m.maxLateDays,' d')}${v1107MetricCell(b.commitmentWorseningDays,m.commitmentWorseningDays,' d')}${v1107MetricCell(b.weightedLateDays,m.weightedLateDays)}<td><strong>${r.candidate.worsened?.length||0}</strong></td><td><span class="status ${rec?'good':'info'}">${rec?'Recommended':'Better than baseline'}</span><small>${esc(a.gains?.slice(0,2).map(x=>x.text).join(' · ')||'Verified improvement')}</small></td></tr>`}).join('')||`<tr><td colspan="8"><div class="empty compact"><strong>No tested scenario beats the current baseline.</strong><br>The current plan remains the optimization reference.</div></td></tr>`}</tbody></table></div></section>`}
function v1107RecoveryCard(row,baseline){const c=row.candidate,m=c.metrics||{},a=row.assessmentV1107||{},gain=a.gains?.map(x=>x.text).join(' · ')||'Feasibility improves',loss=a.losses?.map(x=>x.text).join(' · ')||'Delivery trade-off';return `<article class="planner-recovery-card-v1107"><div class="planner-recovery-head-v1107"><div><span class="eyebrow">RECOVERY TRADE-OFF · NOT AN OPTIMIZATION</span><h4>${esc(row.label)}</h4><p>${esc(row.description)}</p></div>${btn('Review recovery trade-off →',`data-v1094-review-tier="${row.tier}"`,'button small secondary')}</div><div class="planner-recovery-balance-v1107"><div class="good"><span>What improves</span><strong>${esc(gain)}</strong></div><div class="bad"><span>What gets worse</span><strong>${esc(loss)}</strong></div></div><div class="planner-tier-metrics-v1094">${v1094MetricDelta('Total days late',baseline.totalLateDays,m.totalLateDays,' d')}${v1094MetricDelta('Max project delay',baseline.maxLateDays,m.maxLateDays,' d')}${v1094MetricDelta('Unplanned',baseline.unplanned,m.unplanned)}${v1094MetricDelta('Commitment worsening',baseline.commitmentWorseningDays,m.commitmentWorseningDays,' d')}</div></article>`}
function v1107RecoverySection(pack){const rows=pack.recoveryTradeoffs||[],suppressed=pack.suppressedCandidates||[];if(!rows.length&&!suppressed.length)return '';return `<details class="planner-recovery-v1107"><summary><span><strong>Recovery trade-offs — not optimization proposals</strong><small>${rows.length?`${rows.length} non-dominated recovery option${rows.length===1?'':'s'} can solve additional work only by accepting a worse delivery KPI.`:'No recovery trade-off remains worth reviewing.'}</small></span><span class="pill warn">${rows.length}</span></summary><div class="callout warn compact"><strong>Why these are separate</strong><p>Feasible does not automatically mean better. These options are never marked Recommended because at least one critical delivery KPI is worse than the current baseline. Use them only when resolving an unplanned/blocking situation justifies the stated cost.</p></div>${rows.map(r=>v1107RecoveryCard(r,pack.baseline)).join('')}${suppressed.length?`<div class="subtle planner-suppressed-v1107">${suppressed.length} inferior recovery strateg${suppressed.length===1?'y was':'ies were'} hidden because another recovery option is equal or better on every compared KPI.</div>`:''}</details>`}
function v1107OptimizationCard(row,pack,targetRequestId){const a=row.assessmentV1107||{},summary=a.gains?.map(x=>x.text).join(' · ')||'Verified improvement',manual=a.manualReconsideredV126||[],manualHtml=manual.length?`<div class="callout info soft-manual-refinement-v126"><strong>A prior manual delay can be reconsidered</strong><p>A reason remains in the audit trail; this proposal changes only the live schedule. Review before accepting.</p><div class="table-wrap"><table class="data-table compact"><thead><tr><th>Build / task</th><th>Current → proposed</th><th>Earlier</th><th>Original manual reason</th></tr></thead><tbody>${manual.slice(0,8).map(x=>`<tr><td><strong>${esc(x.requestId)}</strong><small>${esc(x.stepName||x.stepId)}</small></td><td>${P.formatDate(x.from)} → ${P.formatDate(x.to)}</td><td>${Number(x.daysEarlier||0).toFixed(1)} d</td><td><strong>${esc(x.reasonCategory||'Other')}</strong><small>${esc(x.reason||'—')}</small></td></tr>`).join('')}</tbody></table></div></div>`:'';return `<div class="planner-verified-v1107"><div class="planner-verified-banner-v1107">✓ VERIFIED BETTER THAN LIVE BASELINE · ${esc(summary)}</div>${manualHtml}${v1096TierCard(row,pack.baseline,pack.recommended?.tier||null,targetRequestId)}</div>`}
v1094ReviewTier=function(tier){const pending=App.pendingTieredPlannerV1094;if(!pending)return;let row=pending.pack.candidates.find(x=>x.tier===tier&&(x.eligible||x.recoveryReviewable));if(!row&&pending.pack.recommended?.tier===tier)row=pending.pack.recommended;if(!row?.candidate?.ok){toast('That scenario is not reviewable.',true);return}const c=row.candidate,ids=(c.state.requests||[]).filter(r=>!['DELIVERED','CLOSED','RELEASED','ARCHIVED'].includes(r.status)).map(r=>r.id),recovery=!!row.recoveryReviewable;showPlanProposal({mode:pending.targetRequestId?'single':'portfolio',proposedState:c.state,requestIds:ids,results:c.results,contextEvent:pending.contextEvent,focusRequestId:pending.targetRequestId||null});const note=$('#planProposalNote');if(note){const gains=row.assessmentV1107?.gains?.map(x=>x.text).join('; ')||'Verified improvement';note.value=recovery?`RECOVERY TRADE-OFF — not an optimization. ${gains}, but ${row.assessmentV1107?.losses?.map(x=>x.text).join('; ')||'a critical delivery KPI worsens'}. Explicit acceptance required.`:`${row.label}. ${gains}. Verified against the LIVE baseline; no critical delivery KPI becomes worse.`};if(recovery){const host=$('.proposal-summary')||$('.modal-body');host?.insertAdjacentHTML?.('afterbegin','<div class="callout warn"><strong>Recovery trade-off — not an optimization</strong><p>This plan is reviewable because it resolves feasibility, but at least one critical delivery KPI becomes worse than the current LIVE baseline. Accept only if that business trade-off is intentional.</p></div>')}};
v1094OpenTieredPlanner=function(targetRequestId=null,contextEvent=null){const label=targetRequestId?`AUTO PLAN · ${targetRequestId}`:'AUTO PLAN · PORTFOLIO';openModal(label,`<div class="planner-computing-v1094"><span class="spinner"></span><div><strong>Testing protected, recovery and portfolio strategies against the current baseline…</strong><small>Feasibility alone is not counted as optimization.</small></div></div>`,btn('Cancel','data-modal-close','button'),true);setTimeout(()=>{let pack;try{pack=(P.buildAutoPlanTiersV1107||P.buildAutoPlanTiersV1096)(App.state,{targetRequestId})}catch(e){console.error(e);openModal('AUTO PLAN safety stop',`<div class="callout bad"><strong>The planning analysis could not complete safely.</strong><p>The live plan has not changed. ${esc(e.message||'Unexpected planner error')}</p></div>`,btn('Close','data-modal-close','button'),true);return}App.pendingTieredPlannerV1094={pack,targetRequestId,contextEvent};const target=requestById(targetRequestId),improvements=pack.optimizationCandidates||[],guidance=v1096GuidanceMarkup(pack,targetRequestId),comparison=v1107ComparisonTable(pack,targetRequestId),recovery=v1107RecoverySection(pack);openModal(label,`<div class="planner-policy-v1094"><strong>${target?`Target · ${esc(target.id)} · ${esc(target.title||target.productFamily||'')}`:'Whole-lab optimization · '+pack.strategiesEvaluated+' deterministic strategies'}</strong><span><b>Optimization rule:</b> AUTO PLAN never worsens a critical delivery KPI. It may improve delivery outcomes or propose releasing a <b>re-optimizable manual delay</b>. Manual reasons remain traceable; only slots explicitly marked <b>Protect from AUTO PLAN</b> are hard constraints. Worse-but-feasible plans are separated as recovery trade-offs.</span></div>${comparison}${improvements.length?`<section class="planner-better-list-v1107"><span class="eyebrow">VERIFIED OPTIMIZATION OPTIONS</span>${improvements.map(x=>v1107OptimizationCard(x,pack,targetRequestId)).join('')}</section>`:`<div class="callout good"><strong>Keep the current baseline.</strong><p>None of the tested strategies improves a critical delivery outcome or releases a re-optimizable manual delay without worsening another critical KPI. AUTO PLAN will therefore not recommend a change.</p></div>`}${recovery}${guidance}${(pack.suggestions||[]).length?`<section class="planner-improvements-v1094"><span class="eyebrow">CAPABILITY IMPROVEMENTS</span><h3>Ways to create a genuinely better plan</h3>${pack.suggestions.map(s=>`<div><strong>${esc(s.title)}</strong><span>${esc(s.detail)}</span></div>`).join('')}</section>`:''}`,`${btn('Close','data-modal-close','button')}${targetRequestId?btn('Escalation mode…','data-v1094-escalation-from-tier','button danger'):''}`,true)},20)};


/* ============================================================
   LabOS REV 1.0.118 — route-review loop closure + direct manual
   replan UX + per-build required-delivery marker restoration.
   ============================================================ */

// Any governed route/test definition change must reopen the explicit route/method
// review. Controls are also reopened because route changes can change which
// characteristics/controls apply to the physical build.
const _invalidatePlanningDefinitionV1111Base=invalidatePlanningDefinitionV1095;
invalidatePlanningDefinitionV1095=function(r,reason,opts={}){
  const out=_invalidatePlanningDefinitionV1111Base(r,reason,opts);
  if(r?.workflowReviewV1077&&/route|process|method|test/i.test(String(reason||''))){
    r.workflowReviewV1077.processReviewed=false;
    r.workflowReviewV1077.processReviewedAt=null;
    r.workflowReviewV1077.processReviewedBy=null;
    r.workflowReviewV1077.controlsReviewed=false;
    r.workflowReviewV1077.controlsReviewedAt=null;
    r.workflowReviewV1077.controlsReviewedBy=null;
  }
  return out;
};

// Use exact governed process revisions for the guided "what do I fix next?"
// path as well, so the cockpit and ReadinessService cannot disagree.
v1075ProcessNextResolution=function(r){
  const route=(App.state.routes||[]).find(x=>x.requestId===r.id),profile=P.ensureAssuranceProfile(r),devs=(App.state.processDevelopments||[]).filter(d=>d.requestId===r.id);
  if(!route?.steps?.length)return {label:'Choose starting route',attrs:`data-route-source="${esc(r.id)}"`,detail:'Select the released product route, a proven previous route, or start from scratch.'};
  if(route.confirmed!==true)return {label:'Confirm this route',attrs:`data-confirm-route="${esc(r.id)}"`,detail:'Review the shown operations and confirm that this is the intended build route.'};
  for(const st of route.steps||[]){
    const live=(App.state.processes||[]).find(p=>p.id===st.processId),proc=P.processRevisionDefinition?P.processRevisionDefinition(App.state,st):live,dev=devs.find(d=>d.libraryCandidate===st.processId||String(d.name||'').includes(st.name));
    const methodOk=(st.type==='standard'&&proc?.status==='Released')||dev?.status==='RELEASED';
    if(!methodOk){
      const revisionNote=st.type==='standard'&&live&&!proc?` Routed Rev ${st.processRevision||'—'} is not available in controlled history.`:'';
      return {label:`Resolve method · ${st.name}`,attrs:`data-edit-route-step="${esc(st.id)}"`,detail:`${st.name} does not yet have a planning-ready released method.${revisionNote} Open this operation and select/release the correct method, or remove it if it is not required for this build.`};
    }
    if(st.type==='standard'&&proc){
      if(!Number.isFinite(Number(proc.setupTime))||!Number.isFinite(Number(proc.cycleTime)))return {label:`Complete planning data · ${st.name}`,attrs:`data-edit-route-step="${esc(st.id)}"`,detail:`${st.name} is missing setup/cycle time required by AUTO-PLAN.`};
      if(!P.planningCapabilityForProcess(App.state,r,proc)&&st?.equipmentRequired!==false&&!/material receipt|cleaning|surface preparation|assembly|packaging|manual bench/i.test(st.name||''))return {label:`Define equipment · ${st.name}`,attrs:`data-edit-route-step="${esc(st.id)}"`,detail:`${st.name} has no usable equipment capability for planning.`};
      if(!P.planningSkillForProcess(proc))return {label:`Define competency · ${st.name}`,attrs:`data-edit-route-step="${esc(st.id)}"`,detail:`${st.name} has no required competency defined for planning.`};
    }
  }
  for(const tr of r.testRequirements||[]){
    if(tr.standardTestId){const test=(App.state.standardTests||[]).find(x=>x.id===tr.standardTestId);if(!test||((profile.requires.testRelease)&&test.status!=='Released')||!P.planningCapabilityForTest(test)||!test.competency||!Number.isFinite(Number(test.setupTime))||!Number.isFinite(Number(test.cycleTime)))return {label:`Resolve test method · ${tr.name}`,attrs:`data-select-end-tests="${esc(r.id)}"`,detail:`${tr.name} is not yet planning-ready. Select or complete the correct test definition.`};}
    else if(!Number(tr.developmentEstimateHours)||!Number(tr.executionEstimateHours)||!tr.competency)return {label:`Define test · ${tr.name}`,attrs:`data-test-estimate="${esc(r.id)}|${esc(tr.id)}"`,detail:`${tr.name} needs planning duration, equipment and competency before scheduling.`};
  }
  return null;
};

// One confirmation now performs both route confirmation and the explicit
// route/method review when the remaining technical definition is ready. This
// removes the old two-confirmation loop after deleting an unnecessary method
// such as Thermal Soak.
confirmRoute=async function(id){
  const route=(App.state.routes||[]).find(x=>x.requestId===id),r=requestById(id);
  if(!route){toast('No route found.',true);return}
  if(!can('route:edit')&&currentRole()!=='administrator'){toast('Process Engineer role is required to confirm the route.',true);return}
  const previousReview=r?.workflowReviewV1077?P.deepClone(r.workflowReviewV1077):null;
  route.proposed=false;route.confirmed=true;route.assessedAt=P.now();
  route.steps.forEach(s=>{if(s.status==='Proposed')s.status='Planned'});
  if(['SUBMITTED','FEASIBILITY'].includes(r.status))r.status=r.currentGate='PROCESS DEFINITION';
  P.audit(App.state,'Process route assessed and confirmed','Request',id,'Proposed route','Confirmed route',`Route ${route.revision}; standard/new/modified decisions retained`);
  const assessment=P.processPlanningAssessment(App.state,r);
  if(assessment.ready){
    const review=v1077WorkflowReview(r);
    review.processReviewed=true;review.processReviewedAt=P.now();review.processReviewedBy=App.state.identity.name;
    if(P.GATES.indexOf(r.currentGate)<P.GATES.indexOf('PROCESS DEFINITION'))r.status=r.currentGate='PROCESS DEFINITION';
    P.audit(App.state,'Route & methods reviewed for build','Request',r.id,previousReview||'Not reviewed',P.deepClone(review),'Route confirmation completed the technical definition; no duplicate confirmation required.');
    await persist();
    const steps=buildGuidedSteps(r),next=steps.find(s=>!s.done);
    App.workspaceTab=next?.id||App.workspaceTab;
    render();
    toast(`Route & methods confirmed. ${next?`Next: ${next.title}.`:'Definition complete.'}`);
    return;
  }
  await persist();render();
  const next=v1075ProcessNextResolution(r),detail=next?.detail||assessment.issues?.[0]||'Resolve the remaining method definition.';
  toast(`Route confirmed. Next method action: ${detail}`,true);
};

