install5SKpiV1059=function(){if(App.currentView!=='management')return;const page=$('#page'),grid=page?.querySelector('.kpi-pillar-grid');if(!page||!grid||grid.querySelector('.kpi-pillar-five-s'))return;const p=v125PeriodBounds(),audits=(App.state.fiveSAudits||[]).filter(a=>v125InPeriod(a.date,p)),avg=audits.length?audits.reduce((n,a)=>n+Number(a.average||0),0)/audits.length:null,meets=audits.filter(a=>FIVE_S_PILLARS.every(([k])=>Number(a.scores?.[k]||0)>=4)).length,compliance=audits.length?100*meets/audits.length:null,zones=new Set(audits.map(a=>a.zoneId)),actionIds=new Set(audits.map(a=>a.id)),actions=(App.state.actions||[]).filter(a=>a.fiveSAction&&actionIds.has(a.fiveSAction.auditId)),pillar=document.createElement('section');pillar.className='kpi-pillar kpi-pillar-five-s';pillar.innerHTML=`<div class="kpi-pillar-head"><div><span class="eyebrow">5S / WORKPLACE</span><h2>What did workplace checks show in the period?</h2></div><button class="button tiny secondary" data-nav="process-library">Open →</button></div><div class="kpi-pillar-metrics"><div class="kpi-pillar-metric ${avg!=null&&avg<4?'warn':''}"><span>Average 5S</span><strong>${avg==null?'—':avg.toFixed(1)+'/5'}</strong><small>${audits.length} check${audits.length===1?'':'s'} in period</small></div><div class="kpi-pillar-metric ${compliance!=null&&compliance<100?'warn':''}"><span>Checks at standard</span><strong>${compliance==null?'—':compliance.toFixed(0)+'%'}</strong><small>${meets}/${audits.length} checks</small></div><div class="kpi-pillar-metric"><span>Zones checked</span><strong>${zones.size}</strong><small>inside selected period</small></div><div class="kpi-pillar-metric ${actions.length?'warn':''}"><span>Actions raised</span><strong>${actions.length}</strong><small>from selected-period checks</small></div></div>`;grid.appendChild(pillar)};


// Make AUTO-PLAN / portfolio replans use the same reason taxonomy. The existing
