const _processDevelopmentPanelV129Base=processDevelopmentPanel;
processDevelopmentPanel=function(dev){const html=_processDevelopmentPanelV129Base(dev),rec=P.developmentRecommendationV129(App.state,v129ProcessDevelopmentContext(dev)),actual=Number(dev.actualDevelopmentHours||0);return html+`<div class="card development-learning-v129"><div class="section-title-row"><div><span class="eyebrow">DEVELOPMENT LEARNING</span><h3>Estimate vs measured engineering effort</h3></div>${actual?status('Measured'):status('Actual pending')}</div><div class="grid cols-3"><div class="development-stat"><span>Learned recommendation</span><strong>${rec.hours.toFixed(1)} h</strong></div><div class="development-stat"><span>Current plan</span><strong>${Number(dev.planningEstimateHours||0).toFixed(1)} h</strong></div><div class="development-stat"><span>Measured actual</span><strong>${actual?actual.toFixed(1)+' h':'—'}</strong></div></div><div class="subtle" style="margin-top:8px">${esc(rec.basis)}</div><div class="route-toolbar" style="margin-top:10px">${(can('process:develop')||currentRole()==='administrator')?btn(actual?'Update actual engineering time':'Record actual engineering time',`data-v129-process-actual="${esc(dev.id)}"`,'button small secondary'):''}</div></div>`};

function v129TrendSvg(rows){const pts=rows.filter(x=>Number(x.actualHours)>0).slice(-12);if(!pts.length)return '<div class="empty compact">No measured development records yet.</div>';const W=680,H=220,L=45,R=20,T=20,B=42,max=Math.max(1,...pts.flatMap(x=>[Number(x.plannedHours||0),Number(x.actualHours||0)])),y=v=>T+(H-T-B)*(1-Number(v||0)/(max*1.1)),x=i=>L+(W-L-R)*(pts.length===1?.5:i/(pts.length-1)),plan=pts.map((p,i)=>`${x(i).toFixed(1)},${y(p.plannedHours).toFixed(1)}`).join(' '),act=pts.map((p,i)=>`${x(i).toFixed(1)},${y(p.actualHours).toFixed(1)}`).join(' ');return `<div class="development-trend-chart-v129"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Development planned versus actual engineering hours over time"><line x1="${L}" y1="${H-B}" x2="${W-R}" y2="${H-B}" class="v129-axis"/><line x1="${L}" y1="${T}" x2="${L}" y2="${H-B}" class="v129-axis"/><text x="8" y="${T+5}" class="v129-axis-label">${max.toFixed(0)} h</text><text x="18" y="${H-B+5}" class="v129-axis-label">0</text><polyline points="${plan}" class="v129-plan-line"/><polyline points="${act}" class="v129-actual-line"/>${pts.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.actualHours)}" r="4" class="v129-actual-point"><title>${esc(P.formatDate(p.completedAt))}: ${Number(p.actualHours).toFixed(1)} h actual</title></circle>`).join('')}<text x="${L}" y="${H-12}" class="v129-axis-label">${esc(P.formatDate(pts[0].completedAt))}</text><text x="${W-R}" y="${H-12}" text-anchor="end" class="v129-axis-label">${esc(P.formatDate(pts[pts.length-1].completedAt))}</text></svg><div class="v129-trend-legend"><span class="v129-legend-plan">Planned</span><span class="v129-legend-actual">Measured actual</span></div></div>`}
function v129TestDevelopmentTrendHtml(testId,{compact=false}={}){const t=(App.state.standardTests||[]).find(x=>x.id===testId);if(!t)return '';const rows=P.developmentHistoryForTestV129(App.state,testId),rec=P.developmentRecommendationV129(App.state,{kind:'test',methodId:testId,standardTestId:testId,name:t.name,familyId:t.familyId,developmentType:'Adaptation',fallbackHours:2}),measured=rows.filter(x=>Number(x.actualHours)>0),first=measured[0],last=measured[measured.length-1],change=first&&last?100*(Number(last.actualHours)-Number(first.actualHours))/Number(first.actualHours):null;return `<div class="card development-history-v129"><div class="section-title-row"><div><span class="eyebrow">DEVELOPMENT TIME HISTORY</span><h3>${esc(t.name)}</h3><div class="subtle">Measured engineering effort by completed method-development episode. Test execution time is deliberately excluded.</div></div><span class="pill">${measured.length} measured</span></div><div class="grid cols-3"><div class="development-stat"><span>Next recommendation</span><strong>${rec.hours.toFixed(1)} h</strong></div><div class="development-stat"><span>Latest actual</span><strong>${last?Number(last.actualHours).toFixed(1)+' h':'—'}</strong></div><div class="development-stat"><span>First → latest</span><strong>${change==null?'—':`${change>0?'+':''}${change.toFixed(0)}%`}</strong></div></div>${v129TrendSvg(rows)}${compact?'':`<div class="table-wrap"><table class="data-table"><thead><tr><th>Completed</th><th>Build</th><th>Type</th><th>Planned</th><th>Actual</th><th>Variance</th><th>Trials</th><th>Outcome</th></tr></thead><tbody>${rows.slice().reverse().slice(0,12).map(x=>{const p=Number(x.plannedHours||0),a=Number(x.actualHours||0),v=p?100*(a-p)/p:null;return `<tr><td>${P.formatDate(x.completedAt)}</td><td>${esc(x.requestId||'Method master')}</td><td>${esc(x.developmentType||'—')}</td><td>${p?p.toFixed(1)+' h':'—'}</td><td><strong>${a.toFixed(1)} h</strong></td><td>${v==null?'—':`${v>0?'+':''}${v.toFixed(0)}%`}</td><td>${Number(x.trialCount||0)}</td><td>${esc(x.outcome||'—')}</td></tr>`}).join('')}</tbody></table></div><div class="route-toolbar" style="margin-top:10px">${(can('process:develop')||currentRole()==='administrator')?btn('+ Record development episode',`data-v129-record-test-dev="${esc(testId)}"`,'button small secondary'):''}</div>`}<div class="callout compact"><strong>Recommendation basis</strong><p>${esc(rec.basis)}${rec.trendPct==null?'':` · historical trend ${rec.trendPct>0?'+':''}${rec.trendPct.toFixed(0)}%`}</p></div></div>`}
function recordStandardTestDevelopmentV129(testId){const t=(App.state.standardTests||[]).find(x=>x.id===testId);if(!t)return;const rec=P.developmentRecommendationV129(App.state,{kind:'test',methodId:testId,name:t.name,familyId:t.familyId,developmentType:'Adaptation',fallbackHours:2}),reqs=(App.state.requests||[]).filter(r=>!r.archived).slice().sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));openModal(`Record development · ${t.name}`,`<div class="callout good"><strong>Current learned recommendation: ${rec.hours.toFixed(1)} h</strong><p>${esc(rec.basis)}</p></div><div class="form-grid"><div class="field"><label>Related build <small>optional</small></label><select id="v129HistReq"><option value="">Method master / no build</option>${reqs.slice(0,60).map(r=>`<option value="${esc(r.id)}">${esc(r.id)} · ${esc(r.title)}</option>`).join('')}</select></div><div class="field"><label>Development type</label><select id="v129HistType">${v129DevelopmentTypeOptions('Adaptation')}</select></div><div class="field"><label>Planned hours</label><input id="v129HistPlan" type="number" min="0.25" step="0.25" value="${rec.hours}"></div><div class="field"><label>Actual engineering hours</label><input id="v129HistActual" type="number" min="0.25" step="0.25"></div><div class="field"><label>Started</label><input id="v129HistStart" type="date" value="${P.todayISO()}"></div><div class="field"><label>Completed</label><input id="v129HistComplete" type="date" value="${P.todayISO()}"></div><div class="field"><label>Trials / iterations</label><input id="v129HistTrials" type="number" min="0" step="1" value="1"></div><div class="field"><label>Outcome</label><select id="v129HistOutcome"><option>Successful</option><option>Partial</option><option>Failed</option></select></div><div class="field full"><label>Learning note / evidence</label><textarea id="v129HistNote"></textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Retain measured episode','data-v129-save-test-history','button primary')}`,true);setTimeout(()=>{$('[data-v129-save-test-history]').onclick=async()=>{const actual=Number($('#v129HistActual').value),planned=Number($('#v129HistPlan').value),start=$('#v129HistStart').value,complete=$('#v129HistComplete').value;if(!(actual>0)||!(planned>0)){toast('Planned and actual engineering hours must be positive.',true);return}if(start&&complete&&complete<start){toast('Completion cannot be before start.',true);return}const rid=$('#v129HistReq').value||null,r=rid?requestById(rid):null,row=P.recordDevelopmentHistoryV129(App.state,{kind:'test',sourceRecordId:P.uid('MANDEV'),requestId:rid,labId:r?.executionSiteId||App.activeLabId||null,productId:r?.productId||null,methodId:t.id,methodName:t.name,familyId:t.familyId,developmentType:$('#v129HistType').value,plannedHours:planned,recommendedHours:rec.hours,actualHours:actual,startedAt:start,completedAt:complete,trialCount:Number($('#v129HistTrials').value||0),outcome:$('#v129HistOutcome').value,note:$('#v129HistNote').value.trim(),actor:App.state.identity.name,source:'Manually retained Standard Test development'});P.audit(App.state,'Standard Test development episode retained','Standard Test',t.id,`${planned} h planned`,`${actual} h actual`,`${row.developmentType} · ${row.trialCount} trial(s) · ${row.requestId||'method master'}`);await persist();closeModal();showStandardTestV1057(testId);toast('Development episode retained and included in future learning.')}},0)}

