 if(changed&&!v130RoleMigrationSavePending&&App.repo?.save){v130RoleMigrationSavePending=true;setTimeout(()=>App.repo.save(App.state).catch(()=>{}).finally(()=>{v130RoleMigrationSavePending=false}),0)}
