/* ============================================================
   LabOS REV 1.0.133 — non-blocking planning situations +
   reachable build-change readiness resolution.

   Planning situations are facts/constraints, not workflow defects.
   Adding/tightening Vacation, staff absence, equipment outage or
   lab closure therefore produces the best feasible portfolio and
   surfaces any residual unplanned work as a consequence. The user
   is never forced to "resolve" unrelated builds before the capacity
   event itself can be accepted.

   Build-specific route / reused-document reviews are also surfaced
   at the definition/control step where they belong and the Build
   Readiness blocker opens the real approval package instead of a
   dead-end generic approval tab.
   ============================================================ */
function v131SituationHardConstraint(ev){
 return !!ev&&ev.active!==false&&['staff','equipment','lab'].includes(ev.scope)&&!!ev.start&&!!ev.end;
}
function v131HistoricalBooking(b){return /complete|completed|actual|done|cancel|superseded/i.test(String(b?.status||''))}
function v131MarkRequestUnplanned(state,rid,draft,message,code='SITUATION_REPLAN_INCOMPLETE'){
 const r=(state.requests||[]).find(x=>x.id===rid);if(!r)return;
 state.bookings=(state.bookings||[]).filter(b=>b.requestId!==rid||v131HistoricalBooking(b));
 P.ensureResourceCareOwnershipV1109?.(state);state.resourceCareBookings=(state.resourceCareBookings||[]).filter(c=>c.sourceRequestId!==rid||c.portfolioOwned===true||v131HistoricalBooking(c)||!c.autoGenerated);
 r.forecastDate=null;r.risk='High';r.triage={...(r.triage||{}),status:'Provisional',plannedStart:null,plannedFinish:null,forecastDate:null,slackDays:null,feasibleByRequiredDate:false,planQuality:'Unplanned after capacity change',capacityConflicts:1,riskNotes:[...new Set([...(r.triage?.riskNotes||[]),message||'The new planning constraint leaves this build without a complete feasible schedule.'])]};
 r.pendingReplanContext={eventId:draft?.id||null,reasonCategory:planningSituationReasonCategory(draft),reason:`${draft?.type||'Planning situation'}: ${draft?.reason||'capacity changed'}. ${message||'No complete feasible slot is currently available.'}`,eventAction:'planning situation accepted; build left unplanned for follow-up',createdAt:P.now(),code};
}
function v131BestPossibleSituationProposal(draft,opts={}){
 const proposed=P.deepClone(App.state);P.ensureEnterpriseModel(proposed);proposed.planningEvents=proposed.planningEvents||[];
 const i=proposed.planningEvents.findIndex(x=>x.id===draft.id);if(i>=0)proposed.planningEvents[i]=P.deepClone(draft);else proposed.planningEvents.push(P.deepClone(draft));
 proposed.settings=proposed.settings||{};proposed.settings.planningNeedsReview=true;
 P.audit(proposed,opts.existingId?'Planning situation change proposed':'Planning situation proposed','Planning Situation',draft.id,opts.existingId?'Existing situation':'—',planningSituationLabel(draft),`${draft.reason||'Capacity change'} · best-feasible automatic affected-work replan`);

 // REV 1.0.133: a capacity fact must never become hostage to unrelated portfolio defects.
 // Replan only work whose CURRENT accepted booking footprint is actually made impossible by
 // this situation. The canonical single-build planner then works around all unaffected work,
 // so successful replans remain applied even if a different affected build cannot be placed.
 const before=P.deepClone(App.state),historical=v131HistoricalBooking;
 const directlyAffected=new Set((before.bookings||[]).filter(b=>!historical(b)&&planningSituationBlocksBooking(draft,b,before)).map(b=>b.requestId).filter(Boolean));

 // A hard capacity event may also displace a scheduled calibration / maintenance / training
 // reservation. That reservation is a consequence too, not a reason to reject the event.
 // Remove the conflicting reservation and let the canonical build planner recreate readiness
 // where it is needed. The readiness action remains visible for governed rescheduling/evidence.
 const displacedCare=[];
 if(v131SituationHardConstraint(draft)){
   const overlap=(a,b,c,d)=>new Date(a)<new Date(d)&&new Date(c)<new Date(b);
   const careBlocked=c=>{if(c.status!=='Scheduled'||!overlap(c.start,c.end,draft.start,draft.end))return false;const sid=c.siteId||(proposed.equipment||[]).find(e=>e.id===c.equipmentId)?.siteId||(proposed.staff||[]).find(st=>st.id===c.staffId)?.siteId||proposed.settings?.primaryLabId;if(draft.scope==='lab')return !draft.siteId||!sid||draft.siteId===sid;if(draft.scope==='equipment')return !!draft.equipmentId&&draft.equipmentId===c.equipmentId;if(draft.scope==='staff')return !!draft.staffId&&draft.staffId===c.staffId;return false};
   for(const c of (proposed.resourceCareBookings||[]).filter(careBlocked)){
     displacedCare.push({id:c.id,itemKey:c.itemKey,type:c.type,target:c.equipmentId||c.staffId,start:c.start,end:c.end,sourceRequestId:c.sourceRequestId||null});
     if(c.sourceRequestId)directlyAffected.add(c.sourceRequestId);
   }
   if(displacedCare.length){const ids=new Set(displacedCare.map(x=>x.id));proposed.resourceCareBookings=(proposed.resourceCareBookings||[]).filter(c=>!ids.has(c.id));for(const x of displacedCare){const a=(proposed.actions||[]).find(a=>a.careItemKey===x.itemKey);if(a){a.status='Open';a.severity='warn';a.impact=`${x.type} reservation was displaced by ${planningSituationLabel(draft)}. LabOS will re-create readiness capacity automatically where a build requires it.`;a.why=`The previous reservation ${P.formatDateTime(x.start)} is no longer feasible because of the accepted planning situation.`}}}
 }

 const score={Critical:0,High:1,Normal:2,Low:3},targets=[...directlyAffected].map(id=>(proposed.requests||[]).find(r=>r.id===id)).filter(r=>r&&!['DELIVERED','CLOSED','RELEASED'].includes(r.status)).sort((a,b)=>(score[a.priority]??2)-(score[b.priority]??2)||String(a.requiredDate||'9999').localeCompare(String(b.requiredDate||'9999'))||String(a.id).localeCompare(String(b.id)));
 const results=[],failures=new Map();
 for(const r of targets){
   try{const changes=new P.PlannerService().autoPlan(proposed,r.id),fresh=(proposed.requests||[]).find(x=>x.id===r.id);results.push({requestId:r.id,ok:true,bookings:changes.length,forecast:fresh?.forecastDate||null,quality:fresh?.triage?.planQuality||'Best feasible'});}
   catch(e){const row={requestId:r.id,ok:false,error:e.message,code:e.code||'SITUATION_REPLAN_INCOMPLETE',details:{taskName:e.taskName||null,skillId:e.skillId||null,skillName:e.skillName||null,capability:e.capability||null,staffId:e.staffId||null,equipmentId:e.equipmentId||null,careType:e.careType||null}};failures.set(r.id,row);v131MarkRequestUnplanned(proposed,r.id,draft,row.error,row.code);results.push({...row,error:`${row.error} The planning situation can still be accepted; ${r.id} will be left unplanned / at risk instead of blocking the capacity event.`,consequenceOnly:true});}
 }

 // Defensive invariant: no future booking anywhere may survive inside the newly unavailable
 // capacity. If stale/locked data escaped the affected-work pass, remove that request's
 // complete future plan rather than accepting a contradictory partial schedule.
 if(v131SituationHardConstraint(draft)){
   const residual=(proposed.bookings||[]).filter(b=>!historical(b)&&planningSituationBlocksBooking(draft,b,proposed));
   for(const b of residual){if(!failures.has(b.requestId)){const row={requestId:b.requestId,ok:false,code:'SITUATION_RESIDUAL_CONFLICT',error:`${b.stepName||'Planned work'} cannot remain inside ${planningSituationLabel(draft)}.`};failures.set(b.requestId,row);v131MarkRequestUnplanned(proposed,b.requestId,draft,row.error,row.code);const prev=results.findIndex(x=>x.requestId===b.requestId);const display={...row,error:`${row.error} The planning situation can still be accepted; ${b.requestId} will be left unplanned / at risk instead of blocking the capacity event.`,consequenceOnly:true};if(prev>=0)results[prev]=display;else results.push(display)}}
 }
 const ids=[...new Set([...targets.map(r=>r.id),...results.map(x=>x.requestId).filter(Boolean)])];
 return {proposed,out:{results,ids},failures:[...failures.values()],displacedCare};
}

