function v131PendingBuildChangeApprovals(r){return (App.state.approvals||[]).filter(a=>a.requestId===r.id&&a.stage==='build-change'&&a.status==='Pending')}
function v131OpenBuildChangeResolution(requestId){const r=requestById(requestId);if(!r)return;const pending=v131PendingBuildChangeApprovals(r);if(!pending.length){render();toast('Build-specific change reviews are already complete.');return}openApprovalPackageV1058(requestId,'definition')}

