// A build-specific delta belongs to its definition/control gate. Do not show the earlier
// steps as green and then surprise the user with an unreachable approval blocker at
// Build Readiness.
const _buildGuidedStepsV131Base=buildGuidedSteps;
buildGuidedSteps=function(r){
 let steps=_buildGuidedStepsV131Base(r),pending=v131PendingBuildChangeApprovals(r);if(!pending.length)return steps;
 const routeRows=pending.filter(a=>/process route|route|work instruction/i.test(String(a.changeArea||a.type||''))),controlRows=pending.filter(a=>/control plan/i.test(String(a.changeArea||a.type||''))),otherRows=pending.filter(a=>!routeRows.includes(a)&&!controlRows.includes(a));
 const mark=(id,rows,label)=>{if(!rows.length)return;let s=steps.find(x=>x.id===id);if(!s)return;s.done=false;s.roleId=rows[0].roleId||roleIdForLabel(rows[0].role)||s.roleId;s.owner=`${rows[0].person||rows[0].role||'Required reviewer'} · ${rows[0].role||'Controlled reviewer'}`;s.next=`${label}: ${rows.map(a=>a.role).filter((x,i,a)=>a.indexOf(x)===i).join(' + ')} sign-off required`;};
 mark('processrisk',routeRows,'Complete build-specific route / work-instruction review');mark('controls',[...controlRows,...otherRows],'Complete build-specific controlled-document review');
 // Recalculate visual state after changing completion truth.
 const today=new Date();today.setHours(0,0,0,0);const hardBlocked=allOpenActions().some(a=>a.requestId===r.id&&a.severity==='bad'),late=!['CLOSED','DELIVERED'].includes(r.status)&&((P.requestDeliveryHealthV1100?.(App.state,r)?.late===true)||(!r.forecastDate&&new Date(r.requiredDate)<today));let firstOpen=true;
 for(const s of steps){if(s.done){s.state='complete';s.locked=false;s.late=false}else if(firstOpen){s.state=(hardBlocked||late)?'blocked':'current';s.late=late;s.locked=false;firstOpen=false}else{s.state='pending';s.locked=true;s.late=false}}
 return steps;
};

