/* REV 1.0.137 — Internal audit review, audit evidence printing, turtle diagram,
   clearer task help, and dense-table readability. */
function auditRuleScoreV135(rule){return rule?.status==='Ready'?100:rule?.status==='Minor'?50:rule?.status==='Major'?0:null}
function auditWorstStatusV135(rows){return rows.some(x=>x.status==='Major')?'Major':rows.some(x=>x.status==='Minor')?'Minor':rows.length?'Ready':'Manual review'}
function auditFrameworkCoverageV135(a){
 const listed=AUDIT_FRAMEWORKS[a.framework]?.areas||[],norm=s=>String(s||'').replace(/\s+/g,'').toLowerCase();
 const rows=listed.map(([clause,title])=>{const checks=(a.rules||[]).filter(r=>{const rc=norm(r.clause),cc=norm(clause);return rc===cc||rc.split('/').some(x=>x===cc)||cc.split('/').some(x=>x===rc)||rc.startsWith(cc+'.')||cc.startsWith(rc+'.')});const scores=checks.map(auditRuleScoreV135).filter(Number.isFinite),score=scores.length?Math.round(scores.reduce((n,x)=>n+x,0)/scores.length):null,status=auditWorstStatusV135(checks);return {clause,title,checks,score,status,evidence:checks.map(x=>x.evidence).filter(Boolean).join(' · ')} });
 const mapped=rows.filter(x=>x.checks.length).length;return {rows,mapped,total:rows.length,coverage:rows.length?Math.round(100*mapped/rows.length):0};
}
function auditRecommendationsV135(){
 const today=new Date(`${P.todayISO()}T00:00:00`),days=d=>{if(!d)return null;const x=new Date(`${String(d).slice(0,10)}T00:00:00`);return Number.isFinite(x.getTime())?Math.ceil((x-today)/86400000):null},out=[];
 (App.state.equipment||[]).forEach(e=>{const dc=days(e.calibrationDue),dm=days(e.maintenanceDue);if(e.calibrationRequired!==false&&dc!==null&&dc>=0&&dc<=60&&P.validCalibrationCertificate(App.state,e.id,P.todayISO()))out.push({kind:'Calibration horizon',title:`${e.name} calibration due in ${dc} d`,evidence:`${e.id} · due ${P.formatDate(e.calibrationDue)}`,action:'Review the forward calibration plan before the current certificate expires.'});if(dm!==null&&dm>=0&&dm<=60)out.push({kind:'Maintenance horizon',title:`${e.name} maintenance due in ${dm} d`,evidence:`${e.id} · due ${P.formatDate(e.maintenanceDue)}`,action:'Confirm the maintenance slot and retained service evidence.'})});
 (App.state.trainingCertificates||[]).filter(c=>c.status==='Valid').forEach(c=>{const d=days(c.expiresAt);if(d!==null&&d>=0&&d<=60){const st=(App.state.staff||[]).find(x=>x.id===c.staffId),sk=(App.state.competencies||[]).find(x=>x.id===c.skillId);out.push({kind:'Competence horizon',title:`${st?.name||c.staffId} qualification expires in ${d} d`,evidence:`${sk?.name||c.skillId} · expires ${P.formatDate(c.expiresAt)}`,action:'Plan renewal before the qualification becomes unavailable to the scheduler.'})}});
 return out.sort((a,b)=>{const an=Number((a.title.match(/in (\d+) d/)||[])[1]||999),bn=Number((b.title.match(/in (\d+) d/)||[])[1]||999);return an-bn}).slice(0,12);
}
function auditSectionOverviewV135(a){
 const groups=new Map();for(const r of a.rules||[]){const key=r.area||'Other';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)}
 return [...groups.entries()].map(([area,rules])=>{const scores=rules.map(auditRuleScoreV135).filter(Number.isFinite),score=scores.length?Math.round(scores.reduce((n,x)=>n+x,0)/scores.length):null;return {area,rules,score,status:auditWorstStatusV135(rules),clauses:[...new Set(rules.map(x=>x.clause))].join(', '),evidence:rules.map(x=>x.evidence).filter(Boolean).join(' · ')}}).sort((x,y)=>{const rank={Major:0,Minor:1,Ready:2};return (rank[x.status]??3)-(rank[y.status]??3)||x.area.localeCompare(y.area)});
}
function auditStatusPillV135(status){return status==='Major'?'<span class="audit-severity major">✕ Major</span>':status==='Minor'?'<span class="audit-severity minor">● Minor</span>':status==='Ready'?'<span class="audit-severity ready">✓ Ready</span>':'<span class="audit-severity manual">◇ Manual review</span>'}
function auditScoringExplainerV135(){return `<div class="audit-scoring-v135"><strong>How the readiness score is calculated</strong><p>This is a <b>system-assisted internal readiness score</b>, not a certification score and not a substitute for an auditor's judgement. Every automated control check is classified from current LabOS records: <b>Ready = 100%</b>, <b>Minor = 50%</b>, <b>Major = 0%</b>. The existing risk weighting is retained (Major-class control = 10 points, Minor-class control = 4, advisory = 2); a Minor finding loses half of that control's weight and a Major loses all of it. Framework sections without an automated evidence check are explicitly shown as <b>Manual review required</b> and are not silently treated as compliant.</p></div>`}
function prototypeTurtleDiagramV135(){
 const equipment=(App.state.equipment||[]).length,people=(App.state.staff||[]).length,processes=(App.state.processes||[]).filter(x=>x.status==='Released').length,tests=(App.state.standardTests||[]).filter(x=>x.status==='Released').length;
 const steps=['Define engineering need','Material source & feasibility','Route / method definition','Resource plan & timing','Control Plan / special approvals','Build readiness','Build samples & process evidence','Characterise / disposition','Release approval','Deliver / retain / learn'];
 const box=(cls,title,items)=>`<div class="turtle-box-v135 ${cls}"><span>${esc(title)}</span>${items.map(x=>`<div>• ${esc(x)}</div>`).join('')}</div>`;
 return `<div class="turtle-wrap-v135"><div class="section-title-row"><div><span class="eyebrow">PROCESS TURTLE</span><h2>Prototype build control process</h2><div class="subtle">Derived from the controlled Prototype build flow in this application. It shows the process context an internal auditor should sample; it does not replace the controlled procedures referenced by your QMS.</div></div></div><div class="turtle-grid-v135">${box('withwhat','WITH WHAT? · resources',[`${equipment} equipment assets`,`Released methods: ${processes} processes / ${tests} tests`,'Calibration / maintenance / controlled documents','LabOS planning, traceability and evidence records'])}${box('withwhom','WITH WHOM? · competence',[`${people} people in staff master`,'Engineering Requester / Lab Planner','Process Engineer / Technician','Quality / Metrology / Release authority'])}${box('inputs','INPUTS',['Approved engineering need / request','Product configuration & BOM','Material availability / lots','Customer, safety and test requirements'])}<div class="turtle-process-v135"><span>PROCESS</span><strong>Controlled Prototype Build</strong><div class="turtle-flow-v135">${steps.map((x,i)=>`<span><b>${i+1}</b>${esc(x)}</span>`).join('')}</div></div>${box('outputs','OUTPUTS',['Built / traceable samples','Process + test evidence','Approved report / release decision','Delivery record and retained lessons'])}${box('how','HOW? · controls',['Guided workflow gates','Released work instructions / standard tests','Control Plan & reaction plans where applicable','AUTO-PLAN + readiness + deviation controls'])}${box('measures','MEASURES',['On-time delivery / days late','Right-first-time / repeats','Calibration, maintenance and skill readiness','Traceability, replan causes, cost and learning'])}</div></div>`;
}
function auditFindingCardV135(rule){const affected=auditFindingAffected(rule),t=auditFindingTargets(rule);return `<div class="audit-finding-card-v135 ${String(rule.status||'').toLowerCase()}"><div class="audit-finding-card-head-v135">${auditStatusPillV135(rule.status)}<span>Clause ${esc(rule.clause)}</span></div><strong>${esc(rule.title)}</strong><p>${esc(rule.evidence)}</p>${affected.length?`<small><b>Objective records:</b> ${esc(affected.slice(0,3).join(' · '))}${affected.length>3?` · +${affected.length-3} more`:''}</small>`:''}<div class="audit-finding-action-v135"><span>${esc(rule.action)}</span>${btn(t.label||'Review →',`data-audit-resolve="${esc(rule.key)}"`,'button tiny secondary')}</div></div>`}
function renderAuditReadinessV135(){
 if(!can('audit:view')&&currentRole()!=='administrator')return pageHeader('Audit Readiness','Audit access required.')+'<div class="empty">Auditor, Quality, Lab Manager or Administrator access is required.</div>';
 const framework=App.filters.auditFramework||'iatf',a=auditAssessment(framework),scope=auditScopeRows(),profile=App.state.settings?.auditProfile||{},open=a.rules.filter(x=>x.status!=='Ready'),ready=a.rules.filter(x=>x.status==='Ready'),major=open.filter(x=>x.status==='Major'),minor=open.filter(x=>x.status==='Minor'),recs=auditRecommendationsV135(),coverage=auditFrameworkCoverageV135(a),sections=auditSectionOverviewV135(a),scoreClass=a.major?'bad':a.minor?'warn':'good';
 const sectionRows=sections.map(x=>`<tr><td><strong>${esc(x.area)}</strong><small>Clause ${esc(x.clauses)}</small></td><td>${auditStatusPillV135(x.status)}</td><td><strong>${x.score==null?'—':x.score+'%'}</strong></td><td>${esc(x.evidence||'No automated evidence')}</td></tr>`).join('');
 const normRows=coverage.rows.map(x=>`<tr><td><strong>${esc(x.clause)}</strong><small>${esc(x.title)}</small></td><td>${auditStatusPillV135(x.status)}</td><td><strong>${x.score==null?'—':x.score+'%'}</strong></td><td>${x.checks.length?x.checks.map(c=>`<div class="audit-objective-evidence-v135"><b>${esc(c.title)}</b><span>${esc(c.evidence)}</span></div>`).join(''):'<span class="subtle">No automated LabOS evidence rule is mapped to this framework section. Include it in the human audit plan.</span>'}</td></tr>`).join('');
 return pageHeader('Audit Readiness','Internal audit overview with transparent evidence, scoring and guided findings.',`${btn('Audit evidence pack','data-audit-pack','button primary')}`)+`<div class="card audit-framework-card audit-hero-v135"><div class="section-title-row"><div><span class="eyebrow">INTERNAL AUDIT REVIEW</span><h2>${esc(profile.scopeStatement||'Scope not defined')}</h2><div class="subtle">${esc(a.edition)} · ${profile.organisation?esc(profile.organisation):'Organisation required'}${profile.site?' · '+esc(profile.site):' · Site/lab required'}</div></div>${btn(profile.scopeStatement?'Edit scope':'Define scope','data-audit-profile','button small primary')}</div><div class="audit-score-grid audit-score-grid-v135"><div class="audit-score ${scoreClass}"><span>Readiness score</span><strong>${a.score}%</strong><small>automated checks</small></div><div class="audit-count ready"><strong>${coverage.mapped}/${coverage.total}</strong><span>Norm sections mapped</span></div><div class="audit-count major"><strong>${a.major}</strong><span>Major</span></div><div class="audit-count minor"><strong>${a.minor}</strong><span>Minor</span></div><div class="audit-count recommendation"><strong>${recs.length}</strong><span>Recommendations</span></div></div><div class="audit-hero-controls-v135"><label class="compact-select">Framework<select id="auditFramework"><option value="iatf" ${framework==='iatf'?'selected':''}>IATF 16949</option><option value="iso17025" ${framework==='iso17025'?'selected':''}>ISO/IEC 17025</option></select></label><span class="pill">Automated framework coverage ${coverage.coverage}%</span></div>${auditScoringExplainerV135()}</div><div class="card audit-overview-v135"><div class="section-title-row"><div><span class="eyebrow">WHAT HAS BEEN ASSESSED</span><h2>Internal audit section overview</h2><div class="subtle">Each section shows the current system-assessed result and the objective evidence used. Open findings are prioritised below.</div></div></div><div class="table-wrap"><table class="data-table audit-review-table-v135"><thead><tr><th>Audit section</th><th>Result</th><th>Section score</th><th>Objective evidence used</th></tr></thead><tbody>${sectionRows}</tbody></table></div></div><div class="card audit-norm-map-v135"><div class="section-title-row"><div><span class="eyebrow">RELEVANT NORM MAP</span><h2>${esc(AUDIT_FRAMEWORKS[framework].label)} · clause coverage</h2><div class="subtle">Manual-review rows make the boundary of automation explicit instead of giving unassessed clauses a false green result.</div></div></div><div class="table-wrap"><table class="data-table audit-review-table-v135"><thead><tr><th>Norm section</th><th>System assessment</th><th>Score</th><th>Objective evidence / review boundary</th></tr></thead><tbody>${normRows}</tbody></table></div></div><div class="grid cols-2 audit-priority-grid-v135"><div class="card"><div class="section-title-row"><div><span class="eyebrow">MAJOR FINDINGS</span><h2>${major.length?`${major.length} major nonconformity candidate${major.length===1?'':'s'}`:'No automated major findings'}</h2><div class="subtle">High-risk evidence gaps requiring formal review and disposition.</div></div></div><div class="audit-finding-stack-v135">${major.map(auditFindingCardV135).join('')||'<div class="callout good"><strong>✓ No Major result from the automated checks.</strong></div>'}</div></div><div class="card"><div class="section-title-row"><div><span class="eyebrow">MINOR FINDINGS</span><h2>${minor.length?`${minor.length} minor finding${minor.length===1?'':'s'}`:'No automated minor findings'}</h2><div class="subtle">Lower-severity gaps still requiring controlled closure.</div></div></div><div class="audit-finding-stack-v135">${minor.map(auditFindingCardV135).join('')||'<div class="callout good"><strong>✓ No Minor result from the automated checks.</strong></div>'}</div></div></div><div class="card"><div class="section-title-row"><div><span class="eyebrow">RECOMMENDATIONS / OPPORTUNITIES FOR IMPROVEMENT</span><h2>${recs.length?`${recs.length} preventive item${recs.length===1?'':'s'} to watch`:'No near-term preventive recommendation generated'}</h2><div class="subtle">Recommendations are not nonconformities. They highlight objective upcoming risks such as expiry or planned-care horizons.</div></div></div><div class="audit-recommendations-v135">${recs.map(x=>`<div class="audit-recommendation-v135"><span>${esc(x.kind)}</span><strong>${esc(x.title)}</strong><small>${esc(x.evidence)}</small><p>${esc(x.action)}</p></div>`).join('')||'<div class="empty compact">No calibration, maintenance or competence expiry within the configured 60-day watch window.</div>'}</div></div>${prototypeTurtleDiagramV135()}<details class="card fold"><summary>✓ Ready controls (${ready.length})</summary><div class="table-wrap"><table class="data-table audit-ready-table-v135"><thead><tr><th>Clause</th><th>Control</th><th>Objective evidence</th></tr></thead><tbody>${ready.map(x=>`<tr><td>${esc(x.clause)}</td><td><strong>${esc(x.title)}</strong></td><td>${esc(x.evidence)}</td></tr>`).join('')}</tbody></table></div></details><details class="card fold"><summary>Laboratory capability scope by equipment category (${scope.length})</summary><div class="table-wrap"><table class="data-table lab-scope-table"><thead><tr><th>Category</th><th>Equipment</th><th>Activity</th><th>Range</th><th>Resolution</th><th>Uncertainty / capability</th><th>Method</th><th></th></tr></thead><tbody>${scope.map(x=>`<tr><td><strong>${esc(x.category)}</strong></td><td>${x.equipmentCount}<small>${esc(x.equipmentTypes.join(', '))}</small></td><td>${esc(x.activity||'MISSING')}</td><td>${esc(x.range||'MISSING')}</td><td>${esc(x.resolution||'—')}</td><td>${esc(x.uncertainty||'—')}</td><td>${esc(x.method||'MISSING')}</td><td>${(currentRole()==='administrator'||can('equipment:manage'))?btn('Edit',`data-edit-equipment-scope="${esc(x.category)}"`,'button tiny secondary'):''}</td></tr>`).join('')}</tbody></table></div></details><details class="card fold"><summary>Exports & audit documents</summary><div class="route-toolbar">${btn('Findings CSV','data-audit-export-findings','button secondary')}${btn('Lab scope CSV','data-audit-export-scope','button secondary')}${btn('Print evidence pack','data-audit-pack','button primary')}</div></details>`;
}
renderAuditReadiness=renderAuditReadinessV135;

auditFindingsCsv=function(a){const q=v=>`"${String(v??'').replace(/"/g,'""')}"`,head=['framework','clause','area','status','score_percent','severity_class','requirement','objective_evidence','recommended_action'],rows=a.rules.map(x=>[a.label,x.clause,x.area,x.status,auditRuleScoreV135(x),x.status==='Ready'?'':x.severity,x.title,x.evidence,x.action]);return [head.map(q).join(','),...rows.map(r=>r.map(q).join(','))].join('\r\n')};

function auditEvidencePackHtmlV135(){
 const a=auditAssessment(App.filters.auditFramework||'iatf'),profile=App.state.settings.auditProfile||{},coverage=auditFrameworkCoverageV135(a),sections=auditSectionOverviewV135(a),recs=auditRecommendationsV135(),care=App.state.resourceCareBookings||[],cal=(App.state.calibrationCertificates||[]).slice().sort((x,y)=>String(y.completedAt||'').localeCompare(String(x.completedAt||''))),mnt=(App.state.maintenanceRecords||[]).filter(x=>x.type==='Maintenance').slice().sort((x,y)=>String(y.completedAt||'').localeCompare(String(x.completedAt||''))),trn=(App.state.trainingCertificates||[]).filter(x=>x.status!=='Revoked').slice().sort((x,y)=>String(y.expiresAt||'').localeCompare(String(x.expiresAt||'')));
 const docs=[['Audit scope & boundaries',`${profile.organisation||'—'} · ${profile.site||'—'}`],['System-assisted readiness',`${a.score}% · ${a.major} major · ${a.minor} minor · ${a.ready} ready`],['Framework coverage',`${coverage.mapped}/${coverage.total} selected norm sections have automated evidence checks`],['Laboratory capability / uncertainty scope',`${auditScopeRows().length} equipment category scope record(s)`],['Calibration register & certificate index',`${cal.length} certificate(s)`],['Maintenance register & evidence index',`${mnt.length} record(s)`],['Competence / training matrix & certificate index',`${trn.length} certificate(s)`],['Controlled methods / work-instruction register',`${(App.state.processes||[]).filter(x=>x.status==='Released').length} released process(es)`],['Control Plan / special-characteristic register',`${(App.state.controlPlans||[]).length} plan(s)`],['Sample genealogy / traceability records',`${(App.state.serials||[]).length} sample record(s)`],['Quality / nonconformity / corrective-action register',`${(App.state.deviations||[]).length} case(s)`],['Approved build / release dossiers',`${(App.state.requests||[]).filter(r=>P.ensureBuildReportApproval(App.state,r).status==='Approved').length} approved report(s)`],['Change & approval audit trail',`${(App.state.auditTrail||[]).length} event(s) · retention ${profile.recordsRetentionReference||'reference not set'}`],['Internal-audit programme / latest report',profile.internalAuditReference||'reference not set'],['Calibration / maintenance / training schedule',`${care.filter(x=>x.status==='Scheduled').length} scheduled item(s)`]];
 const certSection=(title,rows,fn)=>`<details open><summary>${esc(title)} (${rows.length})</summary><div class="audit-evidence-links">${rows.slice(0,40).map(fn).join('')||'<div class="empty compact">No records.</div>'}${rows.length>40?`<small>Showing first 40 of ${rows.length}; use the source register for the full list.</small>`:''}</div></details>`;
 return `<article class="report audit-evidence-report audit-pack-v135"><div class="report-head"><div class="report-title-block">${reportBrand()}<div><h1>Internal Audit Evidence Pack</h1><div>${esc(a.label)} · generated ${P.formatDateTime(P.now())}</div></div></div></div><div class="report-grid">${[['Organisation',profile.organisation],['Site / laboratory',profile.site],['Scope',profile.scopeStatement],['Owner',profile.auditOwner||'—'],['Controlled scope reference',profile.controlledReference||'—'],['Records-retention reference',profile.recordsRetentionReference||'—'],['Internal-audit reference',profile.internalAuditReference||'—'],['Boundaries / exclusions',profile.exclusions||'None stated']].map(([k,v])=>`<div class="report-field"><span>${esc(k)}</span><strong>${esc(v||'—')}</strong></div>`).join('')}</div>${auditScoringExplainerV135()}<section class="report-section"><h2>1. Internal audit review overview</h2><div class="table-wrap"><table class="data-table audit-review-table-v135"><thead><tr><th>Section</th><th>Status</th><th>Score</th><th>Objective evidence</th></tr></thead><tbody>${sections.map(x=>`<tr><td><strong>${esc(x.area)}</strong><small>${esc(x.clauses)}</small></td><td>${esc(x.status)}</td><td>${x.score==null?'—':x.score+'%'}</td><td>${esc(x.evidence||'No automated evidence')}</td></tr>`).join('')}</tbody></table></div></section><section class="report-section"><h2>2. Norm coverage & manual-review boundary</h2><div class="table-wrap"><table class="data-table audit-review-table-v135"><thead><tr><th>Clause</th><th>Subject</th><th>Status</th><th>Score</th><th>Evidence / boundary</th></tr></thead><tbody>${coverage.rows.map(x=>`<tr><td>${esc(x.clause)}</td><td>${esc(x.title)}</td><td>${esc(x.status)}</td><td>${x.score==null?'—':x.score+'%'}</td><td>${x.checks.length?esc(x.evidence):'Manual review required — no automated evidence rule mapped.'}</td></tr>`).join('')}</tbody></table></div></section><section class="report-section"><h2>3. Major & minor findings</h2>${a.rules.filter(x=>x.status!=='Ready').map(x=>`<div class="audit-pack-finding-v135 ${String(x.status).toLowerCase()}"><strong>${esc(x.status)} · ${esc(x.clause)} · ${esc(x.title)}</strong><p><b>Objective evidence:</b> ${esc(x.evidence)}</p><p><b>Required action:</b> ${esc(x.action)}</p></div>`).join('')||'<p>No automated Major or Minor findings.</p>'}</section><section class="report-section"><h2>4. Recommendations / opportunities for improvement</h2>${recs.map(x=>`<div class="audit-pack-recommendation-v135"><strong>${esc(x.kind)} · ${esc(x.title)}</strong><p>${esc(x.evidence)} · ${esc(x.action)}</p></div>`).join('')||'<p>No preventive recommendation generated in the 60-day watch window.</p>'}</section><section class="report-section"><h2>5. Process turtle · Prototype build</h2>${prototypeTurtleDiagramV135()}</section><section class="report-section"><h2>6. Evidence index</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Audit evidence set</th><th>Current record</th></tr></thead><tbody>${docs.map(([n,v])=>`<tr><td><strong>${esc(n)}</strong></td><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div></section>${certSection('Calibration certificates',cal,c=>`<div><strong>${esc(c.certificateNo||c.id)}</strong><span>${esc((App.state.equipment||[]).find(e=>e.id===c.equipmentId)?.name||c.equipmentId)}</span>${evidenceDocumentLink(c,'Open certificate')}</div>`)}${certSection('Maintenance evidence',mnt,c=>`<div><strong>${esc(c.id)}</strong><span>${esc((App.state.equipment||[]).find(e=>e.id===c.equipmentId)?.name||c.equipmentId)}</span>${evidenceDocumentLink(c,'Open evidence')}</div>`)}${certSection('Training certificates',trn,c=>`<div><strong>${esc(c.certificateNo||c.id)}</strong><span>${esc((App.state.staff||[]).find(x=>x.id===c.staffId)?.name||c.staffId)}</span>${evidenceDocumentLink(c,'Open certificate')}</div>`)}</article>`;
}
function printAuditEvidencePackV135(){
 const modal=$('#modalRoot .modal'),report=modal?.querySelector('.audit-evidence-report');if(!modal||!report){toast('Audit evidence pack is not open.',true);return}
 const details=[...report.querySelectorAll('details')],states=details.map(x=>x.open);details.forEach(x=>x.open=true);document.body.classList.add('print-audit-evidence-now');
 let cleaned=false;const cleanup=()=>{if(cleaned)return;cleaned=true;document.body.classList.remove('print-audit-evidence-now');details.forEach((x,i)=>x.open=states[i]);window.removeEventListener('afterprint',cleanup)};window.addEventListener('afterprint',cleanup,{once:true});
 requestAnimationFrame(()=>requestAnimationFrame(()=>{try{window.print()}catch(e){cleanup();toast(`Print could not start: ${e.message||e}`,true)}}));setTimeout(cleanup,8000);
}
auditEvidencePackModal=function(){const profile=App.state.settings?.auditProfile||{},scopeReady=String(profile.organisation||'').trim()&&String(profile.site||'').trim()&&String(profile.scopeStatement||'').trim();if(!scopeReady){toast('Define the organisation, site/laboratory and audit scope before generating the audit pack.',true);auditProfileModal();return}openModal('Internal audit evidence pack',auditEvidencePackHtmlV135(),`${btn('Close','data-modal-close','button')}${btn('Print / save PDF','data-v135-print-audit-pack','button primary')}`,true);setTimeout(()=>{const modal=$('#modalRoot .modal');modal?.classList.add('audit-evidence-modal');const b=$('[data-v135-print-audit-pack]');if(b)b.onclick=printAuditEvidencePackV135;modal?.querySelectorAll('.audit-evidence-links>div').forEach(row=>row.classList.add('audit-evidence-row'))},0)};

renderHelp=function(){const tasks=[
 ['Where is the guided build editor?',['Open Prototype in the left navigation, then open the required build.','The horizontal BUILD WORKFLOW strip at the top of the build is the workflow navigator. Green means complete, yellow is the current required step, grey is future work and red is a blocker.','Click a workflow tile by its title. The detailed editor for that step opens directly below the fixed build summary. Step numbers can differ by assurance profile, so use the title rather than relying on a number.']],
 ['How engineering requests a prototype',['Left navigation → Requests → Prototype → New prototype request.','Complete need, objective, date/priority, product/configuration, requested characterisation and final review.','Submit the request. Then open the created build from Prototype to continue in the BUILD WORKFLOW strip.']],
 ['How lab triages and plans a build',['Left navigation → Prototype → open the build → BUILD WORKFLOW → Resource plan & committed timing.','Before AUTO-PLAN, confirm Material source & feasibility and Route / method definition.','Choose PREVIEW AUTO-PLAN. LabOS plans around accepted closures, vacations, maintenance and other availability constraints and identifies only true missing capability/readiness.','Review the proposed schedule and commit the forecast when the timing basis is accepted.']],
 ['How to issue the correct build material',['Prototype → open the build → BUILD WORKFLOW → Material source & feasibility.','Check every BOM line for exact part number, revision and quantity. For Lab supplied material, reserve/issue a matching lot; for Engineering supplied material, record arrival and then receive the actual lot.','Once the exact BOM is received/issued, that evidence satisfies material readiness; it is not necessary to schedule a second Material Receipt task.']],
 ['How to define the process route / test methods',['Prototype → open the build → BUILD WORKFLOW → Route / method definition (the wording can be “Use or adapt engineering route & methods” or “Reuse released route / work instructions…” depending on the assurance profile).','Insert a released process/test when it fits the requirement. Use the fit assessment for capability/material/geometry.','If the requirement is outside the released envelope, start controlled modified/new method development and complete its development evidence before release.']],
 ['How to create or review a Control Plan',['Prototype → open the build → look in the top BUILD WORKFLOW strip for the tile titled “Reuse approved controls…” / “Control Plan & special approvals”. This tile only appears when the selected assurance profile requires it.','Click that tile. In the page section below, open the Control Plan card/editor for the build. Link characteristics and controls to the relevant route step.','For every special/safety characteristic, provide the specification/limits, measurement method or gauge, required evidence and reaction plan.','Use the sign-off control in the fixed build header when the workflow says independent approval is required. If the controls tile is absent, this assurance profile does not require a formal Control Plan step.']],
 ['How to perform build readiness',['Prototype → open build → BUILD WORKFLOW → Build readiness.','Open each remaining readiness item. The card states the exact resource/evidence, owner and next action.','For equipment readiness, follow the button to Resource Assurance or the exact calibration/maintenance evidence. For people readiness, follow the qualification/training action.','Do not remove accepted closures/vacations simply to clear readiness; the planner must schedule around them.']],
 ['How a technician executes a build',['Switch Demo role to Prototype Technician → Prototype → open the build → BUILD WORKFLOW → Build samples & capture process evidence.','Create/confirm the sample register. Select the current route operation, sample/batch, capable equipment and operator, then record required process evidence.','Record Control Plan measurements at the owning process step before moving on.']],
 ['How to record characterisation and deviations',['Prototype → open build → BUILD WORKFLOW → Characterise, evaluate & disposition exceptions.','Use the result matrix/manual entry/CSV as appropriate. Out-of-limit evidence opens a quality hold.','Contain, investigate and disposition the deviation. Rework returns to the controlled process/reinspection path; close only after required evidence and verification are complete.']],
 ['How to release and close a build',['Prototype → open build → BUILD WORKFLOW → Formal release approval. Use the fixed SIGN-OFF area for the required release decision.','After release, open Deliver, retain records & feed learning. Confirm delivery/receipt, records, lessons and final closeout.']],
 ['How sister-lab transfer works',['Planning → Lab Network Recovery, or use the sister-lab option from a build/task planner.','The sending lab compares feasible sister labs and sends a formal request with rationale. LIVE work does not move yet.','Switch Active lab to the receiving lab. Open My Work or Planning → Lab Network Recovery → Transfer requests & acceptance. The receiving Lab Planner/Lab Manager accepts or rejects with rationale.','Acceptance reruns the canonical planner against the receiver’s current capacity before any LIVE transfer is applied.']],
 ['How to manage calibration, maintenance and training',['Left navigation → Resource Assurance.','Use the Calibration / Maintenance / Training controls and filters to identify the exact resource. Select work and choose Review & schedule selected.','If a build planner says an equipment certificate is missing, open that exact equipment record and add/approve the required evidence. If calibration is still valid, do not schedule an unnecessary recalibration.']],
 ['How to use Audit Readiness',['Left navigation → Governance → Audit Readiness. Choose IATF 16949 or ISO/IEC 17025 at the top.','Start with Internal audit section overview: each row shows status, score and the objective evidence LabOS used. Then review the norm map; “Manual review” means LabOS deliberately has no automated evidence rule for that section.','Review Major findings first, then Minor findings, then Recommendations / opportunities for improvement. Use Resolve on a finding to go to the owning record/workflow.','The process turtle shows the Prototype build inputs, resources, people, controls, outputs and measures derived from the app’s controlled build flow.','Choose Audit evidence pack → Print / save PDF to print the complete evidence pack. Browser print can be saved as PDF.']],
 ['How to understand task replan history',['Prototype → open build → Resource plan & committed timing → Task replan history.','Each row is one task movement. From → To is the actual date movement; Reason shows the controlled category on the first line and the retained rationale below it. This is separate from customer commitment history.']],
 ['How to generate a prototype report',['Left navigation → Reports, or open a build → Deliver, retain records & feed learning.','Open the Build Report, confirm approval state and retained evidence, then choose Print / save PDF.']]
 ];return pageHeader('Help / User Manual','Exact navigation paths for the current LabOS proof of concept.')+`<div class="card help-location-v135"><span class="eyebrow">START HERE</span><h2>“Guided editor” means the open build workspace</h2><p>Open <b>Prototype → [build]</b>. The <b>BUILD WORKFLOW</b> strip across the top is the guided navigation. Click the tile named in the instruction; the editor opens below the fixed build summary. Because E0/E1/V/P assurance profiles show different required steps, use the <b>step title</b>, not a fixed step number.</p></div><div class="quick-start"><div class="quick-step"><strong>1 · Pick role</strong><span>Use Demo role at top right.</span></div><div class="quick-step"><strong>2 · Pick active lab</strong><span>Use Active lab beside the role.</span></div><div class="quick-step"><strong>3 · Open Prototype build</strong><span>Choose the specific build.</span></div><div class="quick-step"><strong>4 · Follow yellow workflow tile</strong><span>The yellow tile is the next controlled action.</span></div></div><div style="height:14px"></div>${tasks.map(([t,steps])=>`<details class="help-task"><summary>${esc(t)}</summary><div class="help-body"><ol>${steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div></details>`).join('')}`};

window.__LABOS_V135_AUDIT_TEST__={version:'1.0.137',summary:()=>{const a=auditAssessment(App.filters.auditFramework||'iatf'),c=auditFrameworkCoverageV135(a);return {score:a.score,major:a.major,minor:a.minor,ready:a.ready,frameworkCoverage:c.coverage,mapped:c.mapped,total:c.total,recommendations:auditRecommendationsV135().length}},turtle:()=>({equipment:(App.state.equipment||[]).length,staff:(App.state.staff||[]).length,releasedProcesses:(App.state.processes||[]).filter(x=>x.status==='Released').length})};


/* ============================================================
   LabOS REV 1.0.137 — planning commitment independence, direct
   Control Plan creation and review-grade demo migration.
   AUTO-PLAN is an optimiser, not a prerequisite for commitment.
   ============================================================ */
function v136EnsureRichDemoUpgrade(){
  if(App._v136RichDemoChecked)return;App._v136RichDemoChecked=true;
  if(!P.isDemoDataset?.(App.state)||!P.ensureRichDemoExamplesV136)return;
  const out=P.ensureRichDemoExamplesV136(App.state);if(out?.changed){persist().catch(e=>console.error('REV136 demo upgrade save failed',e));}
}
const _renderV136Base=render;
render=function(){v136EnsureRichDemoUpgrade();return _renderV136Base();};

function v136CurrentPlanCommitState(r){
  if(!r)return {canCommit:false,reason:'Build not found'};P.ensurePlanningModel(App.state);
  const mat=P.materialPlanningAssessment(App.state,r),proc=P.processPlanningAssessment(App.state,r),plan=P.currentPlanStatusV1102?.(App.state,r)||{complete:false,forecastDate:null};
  if(plan.complete)P.reconcileRequestForecastV1100?.(App.state,r);
  const forecast=plan.forecastDate||r.forecastDate||r.triage?.forecastDate||null,permission=can('triage')||currentRole()==='administrator',already=!!(forecast&&r.triage?.status==='Committed'&&(r.currentCommitmentDate||r.originalCommitmentDate)===forecast);
  return {canCommit:permission&&mat.planningReady&&proc.ready&&plan.complete&&!!forecast&&!already,permission,materialReady:mat.planningReady,processReady:proc.ready,planComplete:!!plan.complete,forecast,already,plan,mat,proc};
}
const _workspaceScheduleV136Base=workspaceSchedule;
workspaceSchedule=function(r){
  let html=_workspaceScheduleV136Base(r),cs=v136CurrentPlanCommitState(r),id=String(r.id).replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  html=html.replace(new RegExp(`<button[^>]*data-commit-triage="${id}"[^>]*>[\\s\\S]*?<\\/button>`,'g'),'');
  if(cs.canCommit){
    const source=/manual/i.test(String(r.triage?.planQuality||''))?'manual plan':'current plan';
    const callout=`<div class="callout good v136-commit-ready"><div class="v136-commit-ready-copy"><strong>✓ Complete ${esc(source)} established · ${P.formatDate(cs.forecast)}</strong><p>This solver-valid plan can be committed now. AUTO-PLAN is optional and is only used when you want LabOS to search for a better alternative.</p></div>${btn('COMMIT CURRENT PLAN →',`data-commit-triage="${esc(r.id)}"`,'button next-action')}</div>`;
    html=callout+html;
  }
  return html.replace('Re-run AUTO-PLAN or save a complete manual plan before committing timing.','Complete every required planning task. A complete manual plan can be committed directly; AUTO-PLAN is optional.');
};

const _commitTriageV136Base=commitTriage;
commitTriage=async function(id){
  const r=requestById(id);if(!r)return;P.ensurePlanningModel(App.state);const plan=P.currentPlanStatusV1102?.(App.state,r);
  if(!plan?.complete){toast(`Timing cannot be committed yet: ${plan?.scheduledCount||0}/${plan?.expectedCount||0} required planning tasks are validly scheduled. Complete the manual plan or use AUTO-PLAN.`,true);return;}
  P.reconcileRequestForecastV1100?.(App.state,r);r.triage=r.triage||{};r.triage.forecastDate=plan.forecastDate||r.forecastDate;r.forecastDate=r.triage.forecastDate;
  if(!r.triage.forecastDate){toast('The current plan has no valid finish date to commit.',true);return;}
  return _commitTriageV136Base(id);
};

