/* ============================================================
   LabOS REV 1.0.137 — prototype-flow liveness, integrated lab
   scope evidence, report capability visibility and request UX.
   ============================================================ */

// The controlled process library intentionally treats a few operations as
// manual/no-dedicated-equipment activities.  They still require the governed
// method and competence but must not be blocked simply because no machine is
// assigned.  This helper is also used by the guided resolver so the UI and
// canonical planning definition cannot disagree again.
function v137ProcessNeedsDedicatedEquipment(r,step,proc){
  if(proc?.equipmentRequired===false||step?.equipmentRequired===false)return false;
  const name=String(step?.name||proc?.name||'').toLowerCase();
  if(/material receipt|cleaning$|surface preparation|mechanical assembly|packaging|manual bench|ultrasonic cleaning/.test(name))return false;
  return !!P.planningCapabilityForProcess(App.state,r,proc);
}

// A single diagnostic used everywhere the user needs to know why Process
// Definition cannot advance.  It deliberately distinguishes method definition
// from later resource availability/calibration/maintenance constraints.
function v137ProcessDefinitionDiagnostic(r){
  const assessment=P.processPlanningAssessment(App.state,r),route=(App.state.routes||[]).find(x=>x.requestId===r.id),next=v1075ProcessNextResolution(r);
  if(assessment.ready)return {ready:true,assessment,route,next:null};
  let step=null,proc=null,cap=null;
  for(const st of route?.steps||[]){
    const live=(App.state.processes||[]).find(p=>p.id===st.processId);proc=P.processRevisionDefinition?P.processRevisionDefinition(App.state,st):live;
    if(!proc)continue;
    cap=P.planningCapabilityForProcess(App.state,r,proc);
    if((assessment.issues||[]).some(x=>String(x).startsWith(`${st.name}:`))){step=st;break}
  }
  return {ready:false,assessment,route,next,step,proc,cap};
}

// Make the current Process Engineering hand-off executable instead of sending
// users between roles with no visible action.  After switching role the exact
// current route/method action remains in the fixed Next Step slot.
const _guidedNextDockV137Base=guidedNextDock;
guidedNextDock=function(r,steps,step){
  if(step?.id==='processrisk'&&!step.done){
    const d=v137ProcessDefinitionDiagnostic(r),review=v1077WorkflowReview(r),route=d.route;
    if(!d.ready){
      const label=d.next?.label||'Resolve route / method definition',attrs=d.next?.attrs||`data-workspace-tab="processrisk"`;
      if(currentRole()!=='process_engineer'&&currentRole()!=='administrator')return btn(`Switch to Process Engineer · ${label} →`,`data-v137-process-handoff="${esc(r.id)}"`,'button small next-action workflow-dock-button');
      return btn(`${label} →`,attrs,'button small next-action workflow-dock-button');
    }
    if(route?.confirmed===true&&!review.processReviewed){
      if(currentRole()!=='process_engineer'&&currentRole()!=='administrator')return btn('Switch to Process Engineer & confirm route/methods →',`data-v137-process-handoff="${esc(r.id)}"`,'button small next-action workflow-dock-button');
      return btn('Confirm route & methods & continue →',`data-v1077-confirm-stage="${esc(r.id)}|processrisk"`,'button small next-action workflow-dock-button');
    }
  }
  // Never show a generic planning action while a definition prerequisite is
  // actually open. Route users to the real owner/action first.
  if(step?.id==='schedule'&&!step.done){
    const mat=P.materialPlanningAssessment(App.state,r),proc=P.processPlanningAssessment(App.state,r);
    if(!mat.planningReady)return btn('Resolve material feasibility first →',`data-workspace-tab="materials"`,'button small next-action workflow-dock-button');
    if(!proc.ready){
      const next=v1075ProcessNextResolution(r),label=next?.label||'Resolve route / method';
      if(currentRole()!=='process_engineer'&&currentRole()!=='administrator')return btn(`Switch to Process Engineer · ${label} →`,`data-v137-process-handoff="${esc(r.id)}"`,'button small next-action workflow-dock-button');
      return btn(`${label} →`,next?.attrs||`data-workspace-tab="processrisk"`,'button small next-action workflow-dock-button');
    }
  }
  return _guidedNextDockV137Base(r,steps,step);
};

function v137ProcessHandoff(requestId){
  const r=requestById(requestId);if(!r)return;
  App.identity.switchRole('process_engineer');populateRoles();App.workspaceTab='processrisk';
  persist().then(()=>{render();const d=v137ProcessDefinitionDiagnostic(r);toast(d.ready?'Process Engineer active. Confirm the reviewed route/methods in the fixed Next Step action.':`Process Engineer active. Next: ${d.next?.label||d.assessment.issues?.[0]||'resolve the highlighted method definition'}.`);setTimeout(()=>document.querySelector('.workflow-command-next,.workflow-next-slot,.route-readiness-summary')?.scrollIntoView({behavior:'smooth',block:'center'}),30)});
}
function installV137ProcessHandoff(){
  if(App._v137ProcessHandoffInstalled)return;App._v137ProcessHandoffInstalled=true;
  document.addEventListener('click',e=>{const t=e.target.closest?.('[data-v137-process-handoff]');if(!t)return;e.preventDefault();e.stopPropagation();v137ProcessHandoff(t.dataset.v137ProcessHandoff)},true);
}
const _renderV137Base=render;
render=function(){_renderV137Base();installV137ProcessHandoff()};

// Keep the exact route/method action visible in the body as well as the fixed
// header.  This prevents a technically complete set of green operation tiles
// from looking stalled merely because the build-level Process Engineer review
// has not yet been acknowledged.
const _workspaceFlowV137GuidedBase=workspaceFlow;
workspaceFlow=function(r){
  let html=_workspaceFlowV137GuidedBase(r),d=v137ProcessDefinitionDiagnostic(r),review=v1077WorkflowReview(r);
  if(d.ready&&review.processReviewed)return html;
  let title,detail,action;
  if(!d.ready){
    title=d.next?.label||'Complete route / method definition';
    detail=d.next?.detail||d.assessment?.issues?.[0]||'Resolve the remaining controlled process definition.';
    action=currentRole()==='process_engineer'||currentRole()==='administrator'?btn(`${title} →`,d.next?.attrs||`data-workspace-tab="processrisk"`,'button primary'):btn(`Switch to Process Engineer · ${title} →`,`data-v137-process-handoff="${esc(r.id)}"`,'button primary');
  }else{
    title='Confirm the completed route & methods';
    detail='All operation definitions are planning-ready. The only remaining Process Definition action is the build-level review/confirmation; no equipment or planning change is required.';
    action=currentRole()==='process_engineer'||currentRole()==='administrator'?btn('Confirm route & methods & continue →',`data-v1077-confirm-stage="${esc(r.id)}|processrisk"`,'button primary'):btn('Switch to Process Engineer & confirm →',`data-v137-process-handoff="${esc(r.id)}"`,'button primary');
  }
  const card=`<div class="card v137-guided-definition"><div class="section-title-row"><div><span class="eyebrow">GUIDED PROCESS-DEFINITION RESOLUTION</span><h2>${esc(title)}</h2><p>${esc(detail)}</p></div>${action}</div><div class="callout info compact"><strong>Role hand-off is explicit</strong><p>Process Engineering owns the route/method definition and its confirmation. Once that one action is complete, LabOS advances the build to the next applicable owner instead of sending the Planner back to an empty Process Engineer page.</p></div></div>`;
  return html.replace('<div class="section-stack">',`<div class="section-stack">${card}`);
};

// Consolidated laboratory scope.  The scope remains an asset/capability register
// but now exposes the objective evidence management needs to verify readiness:
// current calibration evidence, maintenance state and qualified-skill coverage.
function v137LabScopeSkillCoverage(e){
  const cap=P.equipmentPlanningCapability?P.equipmentPlanningCapability(e):(e.planningCapability||e.capability),skillIds=new Set(),today=P.todayISO();
  for(const p of App.state.processes||[]){if(p.status!=='Released')continue;if(P.planningCapabilityForProcess(App.state,null,p)===cap){const sk=P.planningSkillForProcess(p);if(sk)skillIds.add(sk)}}
  for(const t of App.state.standardTests||[]){if(t.status!=='Released')continue;if(P.planningCapabilityForTest(t)===cap&&t.competency)skillIds.add(t.competency)}
  return [...skillIds].map(id=>{
    const skill=(App.state.competencies||[]).find(x=>x.id===id),details=(App.state.staff||[]).filter(st=>st.available!==false).map(st=>{const q=P.projectedStaffQualificationAt?P.projectedStaffQualificationAt(App.state,st,id,`${today}T12:00:00`):{valid:(st.competencies||[]).includes(id)};return {st,q}}),qualified=details.filter(x=>x.q.valid),expiries=qualified.map(x=>x.q.certificate?.expiresAt||x.q.planned?.projectedNextDue||null).filter(Boolean).sort(),scheduled=(App.state.resourceCareBookings||[]).filter(x=>x.status==='Scheduled'&&x.type==='Training'&&x.skillId===id).length;
    return {id,name:skill?.name||id,count:qualified.length,names:qualified.map(x=>x.st.name),nextExpiry:expiries[0]||null,scheduled};
  });
}
function v137EvidenceDate(x){return x?.completedAt||x?.date||x?.timestamp||x?.issuedAt||null}
v1075EquipmentSection=function(){
  const today=P.todayISO(),rows=(App.state.equipment||[]).slice().sort((a,b)=>String(a.location||'').localeCompare(String(b.location||''))||String(a.name||'').localeCompare(String(b.name||''))).map(e=>{
    const spec=scopeSpecResolvedV1063(e),cap=P.equipmentPlanningCapability?P.equipmentPlanningCapability(e):(e.planningCapability||e.capability),certs=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===e.id).sort((a,b)=>String(v137EvidenceDate(b)||'').localeCompare(String(v137EvidenceDate(a)||''))),valid=P.validCalibrationCertificate?.(App.state,e.id,today)||null,latestCert=certs[0]||null,mnts=(App.state.maintenanceRecords||[]).filter(m=>m.equipmentId===e.id).sort((a,b)=>String(v137EvidenceDate(b)||'').localeCompare(String(v137EvidenceDate(a)||''))),latestMnt=mnts[0]||null,skills=v137LabScopeSkillCoverage(e),ready=P.equipmentReady(e,today,App.state);
    const cal=e.calibrationRequired===false?`<span class="status good">Not required</span>`:valid?`<span class="status good">Valid</span><small>${esc(valid.certificateNo||valid.id||'Certificate')} · to ${P.formatDate(valid.nextDue||e.calibrationDue)}</small>`:`<span class="status bad">Evidence / validity gap</span><small>Due ${P.formatDate(e.calibrationDue)}${latestCert?` · latest ${esc(latestCert.certificateNo||latestCert.id)}`:''}</small>`;
    const mntDue=e.maintenanceDue||e.nextMaintenance,mntLate=!!(mntDue&&mntDue<today)||/overdue|failed/i.test(String(e.maintenanceStatus||'')),mnt=`<span class="status ${mntLate?'bad':'good'}">${mntLate?'Due / overdue':'Controlled'}</span><small>${mntDue?`Next ${P.formatDate(mntDue)}`:'No due date'}${latestMnt?` · latest ${P.formatDate(v137EvidenceDate(latestMnt))}`:''}</small>`;
    const sk=skills.length?skills.map(x=>`<div class="v137-scope-skill ${x.count?'ok':'gap'}"><strong>${esc(x.name)}</strong><span>${x.count} independently qualified${x.count?` · ${esc(x.names.slice(0,3).join(', '))}${x.names.length>3?'…':''}`:''}</span><small>${x.nextExpiry?`Next qualification expiry ${P.formatDate(x.nextExpiry)}`:'No stated qualification expiry'}${x.scheduled?` · ${x.scheduled} training action${x.scheduled===1?'':'s'} scheduled`:''}</small></div>`).join(''):'<span class="subtle">No dedicated certified skill mapped</span>';
    return `<tr data-v1075-searchable><td><strong>${esc(e.id)} · ${esc(e.name)}</strong><small>${esc(e.location||'Prototype Lab')} · ${esc(e.equipmentType||'')}</small></td><td><strong>${esc(cap||e.capability||'Manual / no dedicated capability')}</strong><small>${esc(spec.range)} · resolution ${esc(spec.resolution)}</small></td><td>${ready?'<span class="status good">Ready</span>':'<span class="status bad">Not ready</span>'}<small>${esc(e.status||'')}</small></td><td>${cal}</td><td>${mnt}</td><td>${sk}</td><td><div class="route-toolbar">${btn('Readiness timing',`data-equipment-assurance="${esc(e.id)}"`,'button tiny secondary')}${btn('Calibration evidence',`data-view-cal-certificates="${esc(e.id)}"`,'button tiny secondary')}</div></td></tr>`;
  }).join('');
  return `<details id="std-equipment" class="card fold lab-master-section-v1075 v137-lab-scope" open><summary><span><b>Equipment & laboratory scope</b><small>All registered equipment with capability, calibration, maintenance and competency evidence in one controlled register</small></span></summary><div class="callout info compact v137-scope-note"><strong>Integrated laboratory-scope evidence</strong><p>This view links each asset/capability to its current calibration evidence, maintenance state and the people/competencies that can operate the associated released methods. It supports IATF/ISO-oriented internal-laboratory control without implying that every displayed field is itself a standalone certification requirement.</p></div><div class="table-wrap"><table class="data-table lab-scope-table v137-scope-table"><thead><tr><th>Equipment</th><th>Capability / metrology scope</th><th>Current readiness</th><th>Calibration</th><th>Maintenance</th><th>Required skills / training coverage</th><th>Evidence / planning</th></tr></thead><tbody>${rows}</tbody></table></div></details>`;
};

