  const equipment=new Map((state?.equipment||[]).map(x=>[x.id,x])),staff=new Map((state?.staff||[]).map(x=>[x.id,x])),samples=(state?.serials||[]).filter(s=>s.requestId===requestId&&!['Cancelled','Scrapped'].includes(s.status));
