const _workspaceSerialsV138Base=workspaceSerials;
workspaceSerials=function(r){let html=_workspaceSerialsV138Base(r),target=v138SampleTarget(r),count=activeSamplesForRequest(r).length;if(count<target)html=html.replace('<details class="card sample-register-fold">','<details class="card sample-register-fold" open>');return html};
const _workspaceExecutionV138Base=workspaceExecution;
