function v141OperationalNcPanel(){const flags=v141OperationalNcFlags();return `<div class="card v141-operational-watch"><div class="section-title-row"><div><span class="eyebrow">OPERATIONAL WATCH · EXCLUDED FROM AUDIT REPORT</span><h2>${flags.length?`${flags.length} in-progress nonconformity flag${flags.length===1?'':'s'}`:'No in-progress build nonconformity flags'}</h2><div class="subtle">These builds are still in progress. They remain visible for containment and disposition, but they do not affect audit findings, audit score, findings CSV or the printed audit report until the build is CLOSED.</div></div><span class="pill">Audit population: ${v141CompletedBuilds().length} completed</span></div>${flags.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Build</th><th>NC</th><th>Status</th><th>Deliverable / affected item</th><th>Owner</th></tr></thead><tbody>${flags.map(x=>`<tr><td><strong>${esc(x.buildId)}</strong><small>${esc(x.buildTitle)}</small></td><td>${esc(x.ncId)}</td><td>${x.hold?'<span class="pill bad">Release hold</span>':esc(x.status)}</td><td>${esc(x.deliverable)}</td><td>${esc(x.owner)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="callout good"><strong>✓ No quality cases are currently attached to in-progress builds.</strong></div>'}</div>`}

const _renderAuditReadinessV141Base=renderAuditReadiness;
