// Findings export: one row per cited build/deliverable where applicable.
auditFindingsCsv=function(a){const q=v=>`"${String(v??'').replace(/"/g,'""')}"`,head=['framework','audit_population','clause','area','status','score_percent','severity_class','requirement','objective_evidence','build_id','deliverable','owner','record_reference','recommended_action'],rows=[];for(const x of a.rules){const cites=v141BuildFindingCitations(x);if(cites.length){for(const c of cites)rows.push([a.label,v141CompletedBuilds().length,x.clause,x.area,x.status,auditRuleScoreV135(x),x.status==='Ready'?'':x.severity,x.title,x.evidence,c.buildId,c.deliverable,c.owner,c.reference,x.action])}else rows.push([a.label,v141CompletedBuilds().length,x.clause,x.area,x.status,auditRuleScoreV135(x),x.status==='Ready'?'':x.severity,x.title,x.evidence,'','','','',x.action])}return [head.map(q).join(','),...rows.map(r=>r.map(q).join(','))].join('\r\n')};

const _auditEvidencePackHtmlV141Base=auditEvidencePackHtmlV135;
