 let html=_auditEvidencePackHtmlV141Base(),a=auditAssessment(App.filters.auditFramework||'iatf'),completed=v141CompletedBuilds(),ids=new Set(completed.map(r=>r.id)),findings=a.rules.filter(x=>x.status!=='Ready'),cited=findings.flatMap(rule=>v141BuildFindingCitations(rule).map(c=>({rule,c}))),samples=(App.state.serials||[]).filter(s=>ids.has(s.requestId)),quality=(App.state.deviations||[]).filter(d=>ids.has(d.requestId)),approved=completed.filter(r=>P.ensureBuildReportApproval(App.state,r).status==='Approved'),cps=(App.state.controlPlans||[]).filter(cp=>(cp.requestIds||[]).some(id=>ids.has(id))||ids.has(cp.buildRequestId)),population=`<section class="report-section v141-pack-population"><h2>Audit population · completed builds only</h2><p><strong>${completed.length} CLOSED build${completed.length===1?'':'s'}</strong> form the build-record audit population. In-progress builds and their nonconformities are deliberately excluded from this report and from its score.</p>${completed.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Build</th><th>Product / title</th><th>Owner</th><th>Closed</th></tr></thead><tbody>${completed.map(r=>`<tr><td><strong>${esc(r.id)}</strong></td><td>${esc(r.title||r.productFamily||'—')}</td><td>${esc(v141BuildOwner(r))}</td><td>${esc(P.formatDate(String(r.closedAt||r.actualDeliveryDate||'').slice(0,10))||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<p>No completed builds were available for build-specific sampling.</p>'}</section>`;
