window.__LABOS_V141_AUDIT_TEST__={
 version:'1.0.144',
 population:()=>({completed:v141CompletedBuilds().map(r=>r.id),inProgressNc:v141OperationalNcFlags()}),
 summary:(framework='iatf')=>{const a=auditAssessment(framework);return {framework:a.framework,score:a.score,major:a.major,minor:a.minor,ready:a.ready,population:a.population,buildRules:a.rules.filter(v141IsBuildRule).map(r=>({area:r.area,status:r.status,evidence:r.evidence,citations:v141BuildFindingCitations(r)}))}},
 assertIsolation:()=>{const completed=new Set(v141CompletedBuilds().map(r=>r.id)),a=auditAssessment(App.filters.auditFramework||'iatf'),leaks=[];for(const r of a.rules){for(const c of v141BuildFindingCitations(r))if(!completed.has(c.buildId))leaks.push({rule:r.key,citation:c})}return {ok:leaks.length===0,leaks,completed:[...completed],operationalFlags:v141OperationalNcFlags().map(x=>x.buildId)}},
 selfTest:()=>{
  const oldState=App.state,oldFilters={...(App.filters||{})};
  try{
   App.state=P.createDemoState();App.filters={...oldFilters,auditFramework:'iatf'};
   const completed=v141CompletedBuilds(),active=v141InProgressBuilds();
   if(!completed.length||!active.length)return {ok:false,reason:`Demo state requires completed and in-progress builds; got ${completed.length}/${active.length}`};
   const base=auditAssessment('iatf'),activeReq=active[0],closedReq=completed[0];
   const activeNc={id:'V141-NC-ACTIVE-TEST',requestId:activeReq.id,status:'OPEN',releaseHold:true,owner:'V141 Operational Owner',title:'V141 active-build nonconformity',step:'V141 in-progress deliverable'};
   App.state.deviations=[...(App.state.deviations||[]),activeNc];
   const afterActive=auditAssessment('iatf'),flag=v141OperationalNcFlags().find(x=>x.ncId===activeNc.id);
   const activeIsolated=base.major===afterActive.major&&base.minor===afterActive.minor&&base.score===afterActive.score&&!!flag;
   const closedMeas={id:'V141-MEAS-CLOSED-TEST',requestId:closedReq.id,characteristic:'V141 completed-build evidence',measurement:'V141 completed-build evidence',calibrationRequired:true,equipmentCalibrationStatus:'Expired',owner:'V141 Evidence Owner',evidence:'test-evidence'};
   App.state.measurements=[...(App.state.measurements||[]),closedMeas];
   const afterClosed=auditAssessment('iatf'),traceRule=afterClosed.rules.find(r=>/measurement traceability/.test(v141RuleArea(r))),citation=traceRule?v141BuildFindingCitations(traceRule).find(c=>c.buildId===closedReq.id&&c.reference.includes(closedMeas.id)):null;
   const isolation=window.__LABOS_V141_AUDIT_TEST__.assertIsolation(),csv=auditFindingsCsv(afterClosed),pack=auditEvidencePackHtmlV135(),ops=v141OperationalNcPanel(),priorRole=App.state.identity?.role;if(App.state.identity)App.state.identity.role='auditor';const auditUi=renderAuditReadiness();if(App.state.identity)App.state.identity.role=priorRole;
   const checks={
    completedPopulation:afterClosed.population?.buildIds?.every(id=>completed.some(r=>r.id===id))&&afterClosed.population?.buildIds?.length===completed.length,
    activeNcExcludedFromAudit:activeIsolated&&!csv.includes(activeNc.id),
    activeNcOperationallyFlagged:!!flag&&ops.includes(activeNc.id)&&ops.includes('EXCLUDED FROM AUDIT REPORT'),
    completedFindingCreated:traceRule?.status!=='Ready',
    completedFindingCited:!!citation&&citation.deliverable.includes('measurement evidence')&&citation.owner==='V141 Evidence Owner',
    noInProgressCitationLeak:isolation.ok,
    csvTraceabilityColumns:/build_id.*deliverable.*owner.*record_reference/.test(csv.split('\n')[0]),
    packPopulationStatement:pack.includes('Audit population · completed builds only')&&pack.includes('Finding traceability · build / deliverable / owner'),
    packCitesClosedBuild:pack.includes(closedReq.id)&&pack.includes('V141 Evidence Owner'),
    packExcludesActiveTestNc:!pack.includes(activeNc.id),
    auditUiPopulation: auditUi.includes('Completed builds only'),
    auditUiOperationalWatch: auditUi.includes('OPERATIONAL WATCH')&&auditUi.includes(activeNc.id),
    auditUiCitationHeaders: auditUi.includes('Deliverable')&&auditUi.includes('Owner')
   };
   return {ok:Object.values(checks).every(Boolean),checks,base:{score:base.score,major:base.major,minor:base.minor},afterActive:{score:afterActive.score,major:afterActive.major,minor:afterActive.minor},closedBuild:closedReq.id,activeBuild:activeReq.id,citation,operationalFlag:flag,population:afterClosed.population};
  }catch(error){return {ok:false,error:String(error?.stack||error)}}finally{App.state=oldState;App.filters=oldFilters}
 }
};

/* ============================================================
   LabOS REV 1.0.144 — guided prototype build cockpit + liveness.
   Evidence, not duplicate acknowledgement clicks, closes a stage.
   One current executable action; green evidence behind; grey future.
   ============================================================ */

function v142EvidenceReconcile(r,{audit=false}={}){
  if(!r||r.archived||String(r.status||'').toUpperCase()==='CLOSED')return {changed:false,notes:[]};
  const notes=[];let changed=false;
  const prior=v139ReconcileRequestWorkflow(r,{audit:false});if(prior?.changed){changed=true;notes.push(...(prior.notes||[]))}
  const prior140=v140ReconcileLifecycleEvidence(r,{audit:false});if(prior140?.changed){changed=true;notes.push(...(prior140.notes||[]))}
  const review=v1077WorkflowReview(r),proc=P.processPlanningAssessment(App.state,r),route=(App.state.routes||[]).find(x=>x.requestId===r.id);
  const pendingRoute=v139PendingRouteApprovals(r),pendingControl=v139PendingControlApprovals(r),ctl=v1077ControlsTechnicalReady(r);
  // Route confirmation + planning-ready controlled methods already constitute the
  // process-definition action. Do not ask for a second "confirm" click after it.
  if(proc?.ready&&route?.confirmed===true&&!pendingRoute.length&&!review.processReviewed){
    review.processReviewed=true;review.processReviewedAt=review.processReviewedAt||P.now();review.processReviewedBy=review.processReviewedBy||'Evidence completion';review.processReviewedBasisV142='Confirmed planning-ready route + governed delta reviews complete';changed=true;notes.push('process stage closed from objective route evidence');
  }
  // This is the screenshot failure class: an approved/reused CP plus completed
  // build-specific sign-off is already the controlled action. Never leave an
  // extra acknowledgement flag behind as a stale yellow stage.
  if(ctl?.ready&&!pendingControl.length&&!review.controlsReviewed){
    review.controlsReviewed=true;review.controlsReviewedAt=review.controlsReviewedAt||P.now();review.controlsReviewedBy=review.controlsReviewedBy||'Evidence completion';review.controlsReviewedBasisV142='Applicable controls approved/ready + governed delta reviews complete';changed=true;notes.push('controls stage closed from approved control evidence');
  }
  // If an existing controlled stage is actually no longer ready, retain the audit
  // history but make the acknowledgement non-authoritative until evidence is fixed.
  if(review.controlsReviewed&&!ctl?.ready){review.controlsReviewed=false;review.controlsReopenedAt=P.now();changed=true;notes.push('controls stage reopened because controlled evidence is no longer ready')}
  if(review.processReviewed&&!proc?.ready){review.processReviewed=false;review.processReopenedAt=P.now();changed=true;notes.push('process stage reopened because route/method evidence is no longer ready')}
  if(changed&&audit)P.audit(App.state,'Guided build evidence reconciled','Request',r.id,'Partial/stale workflow metadata','Evidence-aligned workflow state',notes.join(' · '));
  return {changed,notes};
}
function v142ReconcileAll(state=App.state){const old=App.state;let changed=false,rows=[];try{App.state=state;for(const r of state?.requests||[]){const x=v142EvidenceReconcile(r);if(x.changed){changed=true;rows.push({id:r.id,notes:x.notes})}}}finally{App.state=old||state}return {changed,rows}}

const _buildGuidedStepsV142Base=buildGuidedSteps;
buildGuidedSteps=function(r){
  // Several legacy step builders lazily create/reconcile governed records while
  // calculating their result.  A single pass can therefore describe the state
  // from just before that mutation (the exact stale-yellow behavior seen in the
  // reported build).  Resolve to a bounded fixed point before exposing the stage.
  v142EvidenceReconcile(r);let steps=_buildGuidedStepsV142Base(r);
  for(let i=0;i<3;i++){const rec=v142EvidenceReconcile(r);if(!rec.changed)break;steps=_buildGuidedStepsV142Base(r)}
  return steps;
};

function v142ActualStage(steps){return steps?.find(s=>!s.done)||steps?.find(s=>s.state==='current')||null}
function v142ActionModel(r,steps,step=v142ActualStage(steps)){
  let m=v140ActionModel(r,steps,step);
  if(!step||m.complete)return m;
  // Remove passive fallback actions. If evidence is complete, reconcile and allow
  // the next stage to become yellow. If evidence is incomplete, open the exact
  // process page rather than a mystery "guided resolution" loop.
  const passive=/^(Review controls|Review process & methods|Review verification evidence|Open closeout)$/i.test(String(m.label||''));
  if(passive){
    v142EvidenceReconcile(r);
    const fresh=_buildGuidedStepsV142Base(r),next=v142ActualStage(fresh);
    if(next&&next.id!==step.id)return v140ActionModel(r,fresh,next);
    if(step.id==='controls')return {roleId:'quality',owner:`${v140UserForRole('quality')} · Quality Engineer`,label:'Open control evidence & resolve remaining item',attrs:`data-v142-resolve-step="${esc(r.id)}|controls"`};
    if(step.id==='processrisk')return {roleId:'process_engineer',owner:`${v140UserForRole('process_engineer')} · Process Engineer`,label:'Open route / method evidence & resolve remaining item',attrs:`data-v142-resolve-step="${esc(r.id)}|processrisk"`};
    if(step.id==='verify')return {roleId:'quality',owner:`${v140UserForRole('quality')} · Quality Engineer`,label:'Open verification evidence & resolve remaining item',attrs:`data-v142-resolve-step="${esc(r.id)}|verify"`};
    if(step.id==='closeout')return {roleId:step.roleId||'lab_manager',owner:step.owner||r.owner,label:'Open handover / closeout checklist',attrs:`data-v142-resolve-step="${esc(r.id)}|closeout"`};
  }
  // Planning must never point back to the page the user is already on. The yellow
  // action performs the next real planning operation; manual planning remains in
  // the planning body as an alternative.
  if(step.id==='schedule'&&String(m.attrs||'').includes('data-workspace-tab="schedule"')){
    const cs=typeof v136CurrentPlanCommitState==='function'?v136CurrentPlanCommitState(r):null;
    m=cs?.canCommit?{roleId:'lab_planner',owner:`${v140UserForRole('lab_planner')} · Prototype Lab Planner`,label:'Commit current plan',attrs:`data-commit-triage="${esc(r.id)}"`}:{roleId:'lab_planner',owner:`${v140UserForRole('lab_planner')} · Prototype Lab Planner`,label:(r.forecastDate||r.triage?.forecastDate)?'Re-optimize best-feasible plan':'Preview best-feasible plan',attrs:`data-auto-plan="${esc(r.id)}"`};
  }
  // Use the REV 1.0.144 readiness handler so the controlled sign-off is both
  // observable and navigation-safe if the user moves to another build while a
  // persistence write is still completing.
  if(step.id==='readiness'&&String(m.attrs||'').includes('data-v1115-confirm-readiness'))m={...m,attrs:`data-v142-confirm-readiness="${esc(r.id)}"`};
  if(!m.attrs||!/data-[a-z0-9-]+=/i.test(String(m.attrs)))m={...m,label:m.label||`Continue · ${step.title}`,attrs:`data-v142-resolve-step="${esc(r.id)}|${esc(step.id)}"`};
  if(m.roleId&&currentRole()!==m.roleId&&currentRole()!=='administrator'&&!String(m.attrs).includes('data-switch-role'))m={...m,originalAttrs:m.attrs,attrs:`data-switch-role="${esc(m.roleId)}"`,handoff:true};
  return m;
}

guidedNextDock=function(r,steps,step){const actual=v142ActualStage(steps),m=v142ActionModel(r,steps,actual);if(!actual||m.complete)return '<span class="workflow-dock-clear"><span>✓</span><b>Workflow complete</b></span>';return v140Button(m.handoff?`Switch to ${v140RoleName(m.roleId)} →`:`${m.label} →`,m.attrs)};

function v142SubstepRows(r,step){
  if(!step)return [];
  let raw=[];
  if(step.id==='controls'){
    const g=v1093CpGate(r),records=(App.state.approvals||[]).filter(a=>a.requestId===r.id&&a.stage==='build-change'&&a.changeArea==='Control Plan'&&a.status!=='Superseded'),profile=P.ensureAssuranceProfile(r);
    if(g.cpRequired){
      raw.push({label:'Controlled definition',done:!!g.definitionReady,detail:g.definitionReady?'Required controls are defined':'Complete characteristic/specification/method/evidence definition'});
      if(records.length)raw.push({label:'Build-specific change sign-off',done:!g.pending.length,detail:`${g.done}/${g.total} configured signer group(s) complete`});
      if(profile.requires.independentControlPlanApproval)raw.push({label:'Final Quality Engineering approval',done:g.cp?.status==='Approved',detail:g.cp?.status==='Approved'?`Approved${g.cp.approvedBy?` · ${g.cp.approvedBy}`:''}`:g.cp?.status==='Review requested'?'Quality approval requested':'Submit the controlled revision for final approval'});
    }
    if(r.productSafety){const a=(App.state.approvals||[]).find(x=>x.requestId===r.id&&x.type==='Product Safety'&&x.status!=='Superseded');raw.push({label:'Product-safety approval',done:a?.status==='Approved',detail:a?.status==='Approved'?`Approved · ${a.person||a.role||'Product Safety'}`:'Product Safety review required'})}
    if(!raw.length)raw=[{label:'Applicable controls',done:v1077ControlsTechnicalReady(r).ready,detail:'No additional controlled approval is required for this assurance profile'}];
  }else if(step.id==='processrisk'){
    const proc=P.processPlanningAssessment(App.state,r),pending=v139PendingRouteApprovals(r),records=(App.state.approvals||[]).filter(a=>a.requestId===r.id&&a.stage==='build-change'&&v139IsRouteChangeApproval(a)&&a.status!=='Superseded');
    raw=[{label:'Route & method definition',done:!!proc.ready,detail:proc.ready?'Confirmed planning-ready route and methods':(proc.issues||[])[0]||'Complete route/method definition'}];
    if(records.length)raw.push({label:'Build-specific route / work-instruction sign-off',done:!pending.length,detail:pending.length?`${pending.length} reviewer action(s) remaining`:'Configured change reviewers complete'});
  }else if(step.id==='schedule'){
    const cov=P.planningTaskCoverage?.(App.state,r),comm=P.commitmentMetrics(r);raw=[{label:'Feasible resource plan',done:!!cov?.ok,detail:cov?.ok?'All expected planning tasks have valid coverage':`${cov?.missing?.length||0} missing · ${cov?.duplicates?.length||0} duplicate · ${cov?.mismatched?.length||0} mismatched`},{label:'Committed timing',done:v140PlanEstablished(r),detail:v140PlanEstablished(r)?`Current commitment ${P.formatDate(comm.current||r.forecastDate)}`:'Preview/manual-plan, review impact and commit the accepted timing'}];
  }else if(step.id==='readiness'){
    const rs=new P.ReadinessService(App.state).evaluate(r.id);raw=rs.issues?.length?rs.issues.map(x=>({label:x.name,done:false,detail:x.action||x.why||'Resolve readiness evidence'})):[{label:'Readiness checks clear',done:true,detail:'Material, route, resources and controlled evidence satisfy the current assurance profile'}];
  }else if(step.id==='execution'){
    const target=v138SampleTarget(r),count=activeSamplesForRequest(r).length;raw=[{label:'Sample register',done:count>=target,detail:`${count}/${target} required sample records`}];
    raw.push(...(v1091Substeps(r,step)||[]));
  }else if(step.id==='approvals'){
    P.ensureApprovalRecords(App.state,r);const rows=(App.state.approvals||[]).filter(a=>a.requestId===r.id&&a.stage==='release'&&a.status!=='Superseded');raw=rows.length?rows.map(a=>({label:a.type||a.role||'Release approval',done:a.status==='Approved',detail:a.status==='Approved'?`Approved · ${a.person||a.role||'Reviewer'}`:`Owner · ${a.person||a.role||'Reviewer'}`})):[{label:'Release decision',done:['RELEASED','DELIVERED','CLOSED'].includes(r.status),detail:'Final release check'}];
  }else raw=v1091Substeps(r,step)||[];
  const first=raw.findIndex(x=>!x.done);return raw.map((x,i)=>({...x,state:x.done?'complete':i===first?'current':'future'}));
}
workspaceSubstepRailV1066=function(r,step){
  const rows=v142SubstepRows(r,step);return `<div class="workspace-substep-rail-v142"><span class="workspace-rail-label-v1066">SUBSTEPS</span><div class="workspace-substep-scroll-v142">${rows.length?rows.map((x,i)=>`<span class="workspace-substep-chip-v142 ${x.state}"><i>${x.state==='complete'?'✓':x.state==='current'?'●':'○'}</i><b>${esc(x.label)}</b></span>`).join(''):'<span class="workspace-substep-chip-v142 complete"><i>✓</i><b>No additional substeps</b></span>'}</div></div>`;
};

function v142PlanningSummary(r,steps){
  const cov=P.planningTaskCoverage?.(App.state,r),comm=P.commitmentMetrics(r),forecast=r.forecastDate||r.triage?.forecastDate||null,s=steps.find(x=>x.id==='schedule'),bookings=(App.state.bookings||[]).filter(b=>b.requestId===r.id&&!P.isHistoricalPlanningBooking?.(b));
  if(v140PlanEstablished(r))return {cls:'complete',title:comm.current?`Committed · ${P.formatDate(comm.current)}`:'Plan committed',detail:forecast?`Forecast ${P.formatDate(forecast)}`:`${bookings.length} booking(s)`,click:true};
  if(bookings.length||forecast)return {cls:s?.state==='current'?'current':'future',title:'Provisional plan',detail:forecast?`Forecast ${P.formatDate(forecast)}`:`${bookings.length} booking(s)`,click:s?.state==='current'};
  return {cls:s?.state==='current'?'current':'future',title:'Not planned',detail:s?.state==='current'?(cov?.missing?.length?`${cov.missing.length} task(s) need a slot`:'Ready to plan'):'Available after prerequisites',click:s?.state==='current'};
}
function v142ApprovalSummary(r,step){
  const pending=(App.state.approvals||[]).filter(a=>a.requestId===r.id&&a.status==='Pending'&&a.status!=='Superseded');
  if(step?.id==='controls'){
    const g=v1093CpGate(r);if(g.pending?.length)return {cls:'current',title:`Control change · ${g.done}/${g.total}`,detail:v1093CpWaitingNames(g.pending[0])||'Reviewer action required'};
    if(g.cpRequired&&g.cp?.status==='Draft')return {cls:'current',title:'Control Plan approval not started',detail:'Submit the controlled revision for Quality Engineering approval'};
    if(g.cpRequired&&g.cp?.status==='Review requested')return {cls:'current',title:'Control Plan approval pending',detail:g.ap?.switchName||g.quality?.name||'Quality Engineering'};
    if(g.cpRequired&&g.cp?.status==='Approved')return {cls:'complete',title:'Control Plan approved',detail:g.cp.approvedBy||'Quality approval recorded'};
  }
  if(step?.id==='processrisk'&&v139PendingRouteApprovals(r).length){const a=v139NextRouteApproval(r);return {cls:'current',title:'Route change approval',detail:`${a?.person||a?.role||'Reviewer'} · ${v139PendingRouteApprovals(r).length} remaining`}}
  if(step?.id==='approvals'){const release=pending.filter(a=>a.stage==='release');return release.length?{cls:'current',title:`Release · ${release.length} remaining`,detail:release[0].person||release[0].role}:{cls:'complete',title:'Release sign-off ready',detail:'Run final release check'}}
  return {cls:'future',title:'No approval due now',detail:pending.length?`${pending.length} future approval(s) prepared`:'No pending approval at this stage'};
}
function v142ActionWhy(r,step,m){
  if(step?.hasBlocker)return `${step.blockerTitle||'A required condition is open'}${step.blockerDetail?` · ${step.blockerDetail}`:''}`;
  if(m?.handoff)return `This controlled action belongs to ${m.owner||v140RoleName(m.roleId)}; switch role without leaving the build.`;
  return v1091StepPurpose(step?.id)||'Complete the current controlled action so LabOS can advance to the next workflow stage.';
}
function v142DoneWhen(r,step){const rows=v142SubstepRows(r,step),open=rows.find(x=>x.state==='current');if(open)return open.detail?`${open.label} — ${open.detail}`:open.label;return step?.next||'The controlled evidence for this stage is complete.'}

workspaceFixedCockpit=function(r,steps){
  const step=v142ActualStage(steps)||steps[steps.length-1],action=v142ActionModel(r,steps,step),pct=workflowProgressV1066(r,steps),commit=P.commitmentMetrics(r),requested=r.originalRequestedDate||r.requiredDate,original=commit.original||r.originalCommitmentDate||null,current=commit.current||r.currentCommitmentDate||null,forecast=r.forecastDate||r.triage?.forecastDate||null,planning=v142PlanningSummary(r,steps),approval=v142ApprovalSummary(r,step),complete=!v142ActualStage(steps);
  const nextOwner=complete?'—':action.owner||step?.owner||r.owner;
  const planAction=planning.click?btn('Open planning',`data-workspace-tab="schedule"`,'button tiny secondary'):'';
  return `<div class="workspace-fixed-cockpit workspace-cockpit-v142" data-v142-cockpit>
   <div class="workspace-context-strip workspace-context-v142">
    <div class="workspace-context-primary"><span>BUILD NUMBER</span><strong>${esc(r.id)} · ${esc(r.title)}</strong></div>
    <div><span>REQUESTED DELIVERY</span><strong>${requested?P.formatDate(requested):'—'}</strong></div>
    <div><span>ORIGINAL COMMITMENT</span><strong>${original?P.formatDate(original):'Not committed'}</strong></div>
    <div><span>CURRENT COMMITMENT</span><strong>${current?P.formatDate(current):'Not committed'}</strong></div>
    <div><span>LATEST FORECAST</span><strong>${forecast?P.formatDate(forecast):'Not planned'}</strong></div>
    <div class="workspace-progress-v1066"><span>OVERALL PROGRESS</span><strong>${pct}%</strong><div><i style="width:${pct}%"></i></div></div>
   </div>
   ${workspaceWorkflowRailV1066(steps)}
   ${workspaceSubstepRailV1066(r,step)}
   <div class="v142-cockpit-command-grid">
    <div class="v142-command ${planning.cls}"><span>PLANNING</span><strong>${esc(planning.title)}</strong><small>${esc(planning.detail)}</small>${planAction}</div>
    <div class="v142-command ${complete?'complete':'current'}"><span>CURRENT STAGE & OWNER</span><strong>${complete?'Workflow complete':`${step.index}. ${esc(step.title)}`}</strong><small>${complete?'All controlled stages complete':esc(action.owner||step.owner||r.owner)}</small></div>
    <div class="v142-command ${approval.cls}"><span>APPROVALS</span><strong>${esc(approval.title)}</strong><small>${esc(approval.detail)}</small></div>
    <div class="v142-command ${complete?'complete':'current'}"><span>NEXT STEP & OWNER</span><strong>${complete?'✓ Complete':esc(action.label)}</strong><small>${esc(nextOwner)}</small>${complete?'':v140Button(action.handoff?`Switch to ${v140RoleName(action.roleId)} →`:`${action.label} →`,action.attrs)}</div>
   </div>
  </div>`;
};

function v142GuidedActionCard(r,step){
  const steps=buildGuidedSteps(r),actual=v142ActualStage(steps),isActual=!!actual&&actual.id===step?.id;
  if(step?.done||(!isActual&&steps.find(x=>x.id===step?.id)?.done))return `<section class="card v142-guided-action complete"><span class="eyebrow">STEP STATUS</span><h2>✓ Completed</h2><p>The required controlled evidence for this step is complete. LabOS has moved the yellow action forward.</p></section>`;
  if(!isActual)return `<section class="card v142-guided-action future"><span class="eyebrow">FUTURE STEP</span><h2>Not actionable yet</h2><p>Complete the current yellow workflow stage first. This section remains read-only so evidence cannot be completed out of sequence.</p></section>`;
  const m=v142ActionModel(r,steps,actual),button=v140Button(m.handoff?`Switch to ${v140RoleName(m.roleId)} →`:`${m.label} →`,m.attrs);
  return `<section class="card v142-guided-action current" data-v142-guided-action><div class="v142-action-grid"><div><span class="eyebrow">DO THIS NOW · STEP ${actual.index}</span><h2>${esc(m.label)}</h2><p>${esc(v142ActionWhy(r,actual,m))}</p><div class="v142-owner"><span>OWNER</span><strong>${esc(m.owner||actual.owner||r.owner)}</strong></div><div class="v142-done-when"><span>DONE WHEN</span><strong>${esc(v142DoneWhen(r,actual))}</strong></div></div><div class="v142-action-button">${button}</div></div></section>`;
}

v1091StepScaffold=function(r,step,body){
  const rows=v142SubstepRows(r,step);return `<div class="workspace-step-layout-v142"><section class="card workspace-purpose-v142"><span class="eyebrow">STEP ${step?.index||'—'} · PURPOSE</span><h2>${esc(step?.title||'Workflow step')}</h2><p>${esc(v1091StepPurpose(step?.id))}</p></section>${v142GuidedActionCard(r,step)}<section class="card workspace-requirements-v142"><div class="section-title-row"><div><span class="eyebrow">STEP REQUIREMENTS</span><h2>Evidence progression</h2></div></div><div class="workspace-substep-list-v1091">${rows.length?rows.map(x=>`<div class="workspace-substep-row-v1091 ${x.state==='complete'?'good':x.state==='current'?'warn':'future'}"><span>${x.state==='complete'?'✓':x.state==='current'?'●':'○'}</span><div><strong>${esc(x.label)}</strong>${x.detail?`<small>${esc(x.detail)}</small>`:''}</div></div>`).join(''):'<div class="workspace-substep-row-v1091 good"><span>✓</span><div><strong>No additional checklist items</strong><small>The stage is controlled by the primary action above.</small></div></div>'}</div></section><div class="workspace-step-content-v1091">${body}</div></div>`;
};

function v142ResolveStep(requestId,stepId){
  const r=requestById(requestId);if(!r)return;v142EvidenceReconcile(r);const steps=buildGuidedSteps(r),step=steps.find(x=>x.id===stepId)||v142ActualStage(steps),m=v142ActionModel(r,steps,step),rows=v142SubstepRows(r,step),open=rows.filter(x=>x.state!=='complete');
  const content=`<div class="resolution-focus"><span class="eyebrow">GUIDED RESOLUTION · ${esc(r.id)}</span><h2>${esc(step?.title||'Current workflow step')}</h2><p>${esc(v142ActionWhy(r,step,m))}</p></div><div class="callout warn"><strong>Required now: ${esc(m.label)}</strong><p>Owner: ${esc(m.owner||step?.owner||r.owner)}</p></div>${open.length?`<div class="workspace-substep-list-v1091">${open.map((x,i)=>`<div class="workspace-substep-row-v1091 ${i===0?'warn':'future'}"><span>${i===0?'●':'○'}</span><div><strong>${esc(x.label)}</strong>${x.detail?`<small>${esc(x.detail)}</small>`:''}</div></div>`).join('')}</div>`:'<div class="callout good"><strong>Evidence is complete.</strong><p>Close this resolver; the workflow will reconcile and advance automatically.</p></div>'}`;
  openModal(`Resolve current step · ${r.id}`,content,`${btn('Close','data-modal-close','button')}${v140Button(m.handoff?`Switch to ${v140RoleName(m.roleId)} →`:`${m.label} →`,m.attrs)}`,true);
}

const _renderHelpV142Base=renderHelp;
renderHelp=function(){
  let html=String(_renderHelpV142Base());
  html=html
    .replace('Explanations and the full checklist remain in the Details & checklist foldout.','The current process page shows Purpose, the yellow executable action and Evidence progression above the detailed work.')
    .replace('Detailed rationale, checklists and compliance context are folded away unless opened.','Purpose, current action, owner and evidence progression stay visible; deeper rationale and reference detail remain progressively disclosed.')
    .replace('The yellow stage and action bar identify exactly what happens next and who owns it.','The sticky cockpit and yellow action identify exactly what happens next, who owns it and what evidence will make the step green.');
  return html;
};

function v142SerialRows(requestId){return samplesForRequest(requestId).map((s,i)=>({ref:s.serial,labId:s.sampleId||s.serial,sampleNumber:s.sampleNumber||String(i+1).padStart(2,'0'),serialNumber:(s.serialNumber===s.sampleId||s.serialNumber===s.serial)?'':(s.serialNumber||'')}))}
function v142BuildSerialSeries(count,{prefix='',start=1,pad=3,suffix=''}={}){const n=Number(start)||1,p=Math.max(1,Math.min(12,Number(pad)||3));return Array.from({length:count},(_,i)=>`${prefix}${String(n+i).padStart(p,'0')}${suffix}`)}
function v142ValidateSerialAssignments(requestId,assignments){const seen=new Set(),global=new Map((App.state.serials||[]).filter(s=>s.requestId!==requestId&&s.status!=='Cancelled'&&s.serialNumber).map(s=>[String(s.serialNumber),s]));for(const x of assignments){const v=String(x.serialNumber||'').trim();if(!v)continue;if(seen.has(v))return `Duplicate formal serial in this build: ${v}`;if(global.has(v))return `Formal serial already exists on build ${global.get(v).requestId}: ${v}`;seen.add(v)}return ''}
function v142ApplySerialAssignments(requestId,assignments,{audit=true}={}){const r=requestById(requestId),samples=samplesForRequest(requestId);if(!r)return {ok:false,error:'Build not found'};const profile=P.ensureAssuranceProfile(r),byRef=new Map(assignments.map(x=>[x.ref,String(x.serialNumber||'').trim()])),next=samples.map(s=>({ref:s.serial,serialNumber:byRef.has(s.serial)?byRef.get(s.serial):((s.serialNumber===s.sampleId||s.serialNumber===s.serial)?'':(s.serialNumber||''))}));if(profile.requires.serialisation&&next.some(x=>!x.serialNumber))return {ok:false,error:'Every sample requires a formal serial for this assurance profile.'};const err=v142ValidateSerialAssignments(requestId,next);if(err)return {ok:false,error:err};const before=JSON.stringify(samples.map(s=>({ref:s.serial,labId:s.sampleId||s.serial,serialNumber:s.serialNumber||''})));for(const s of samples)if(byRef.has(s.serial))s.serialNumber=byRef.get(s.serial);const after=JSON.stringify(samples.map(s=>({ref:s.serial,labId:s.sampleId||s.serial,serialNumber:s.serialNumber||''})));if(before!==after){P.invalidateBuildReport(App.state,r,'Formal serial identity changed');if(audit)P.audit(App.state,'Batch formal serial update','Request',requestId,before,after,'Permanent Lab Sample IDs retained; formal product serials updated in batch')};return {ok:true,changed:before!==after,count:samples.length}}
function v142ExportSampleRegister(requestId){const rows=v142SerialRows(requestId),q=v=>`"${String(v??'').replaceAll('"','""')}"`;downloadTextFile(`sample_register_${requestId}.csv`,[['sample_number','lab_sample_id','formal_serial'],...rows.map(x=>[x.sampleNumber,x.labId,x.serialNumber])].map(r=>r.map(q).join(',')).join('\r\n'),'text/csv')}
function v142ImportSampleRegister(requestId){const input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;const rows=parseCsv(await file.text());if(rows.length<2){toast('CSV has no sample rows.',true);return}const heads=rows[0].map(x=>String(x).trim().toLowerCase().replaceAll(' ','_')),idx=n=>heads.indexOf(n),iLab=idx('lab_sample_id'),iSample=idx('sample_number'),iSerial=Math.max(idx('formal_serial'),idx('serial_number'));if(iSerial<0||(iLab<0&&iSample<0)){toast('CSV needs lab_sample_id or sample_number plus formal_serial.',true);return}const samples=samplesForRequest(requestId),updates=[];for(const vals of rows.slice(1)){const lab=iLab>=0?String(vals[iLab]||'').trim():'',num=iSample>=0?String(vals[iSample]||'').trim():'',sm=samples.find(s=>lab&&(s.sampleId===lab||s.serial===lab))||samples.find(s=>num&&String(s.sampleNumber)===num);if(!sm)continue;updates.push({ref:sm.serial,serialNumber:String(vals[iSerial]||'').trim()})}const out=v142ApplySerialAssignments(requestId,updates);if(!out.ok){toast(out.error,true);return}await persist();render();toast(`Imported formal serials for ${updates.length} sample(s).`)}catch(e){toast(`Sample register import failed: ${e.message}`,true)}};input.click()}
function v142SampleRegisterModal(requestId){
  const r=requestById(requestId),profile=P.ensureAssuranceProfile(r),rows=v142SerialRows(requestId);
  const content=`<div class="callout"><h3>Permanent Lab ID + batch-editable product serial</h3><p>Lab Sample IDs are immutable traceability keys. Formal product serials can be populated individually, as a generated series, or by CSV import without breaking process/measurement links.</p></div>
  <div class="v142-serial-series">
   <div class="field"><label>Prefix</label><input data-v142-prefix placeholder="e.g. SN-"></div>
   <div class="field"><label>Start number</label><input data-v142-start type="number" value="1" min="0"></div>
   <div class="field"><label>Digits</label><input data-v142-pad type="number" value="3" min="1" max="12"></div>
   <div class="field"><label>Suffix</label><input data-v142-suffix placeholder="optional"></div>
   ${btn('Apply series to all','data-v142-apply-series','button secondary')}
  </div>
  <div class="route-toolbar">${btn('Export CSV','data-v142-export-samples-modal','button small secondary')}${btn('Import CSV','data-v142-import-samples-modal','button small secondary')}</div>
  <div class="table-wrap"><table class="data-table"><thead><tr><th>Sample</th><th>Permanent Lab Sample ID</th><th>Formal product serial ${profile.requires.serialisation?'*':'(optional)'}</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.sampleNumber)}</td><td><strong>${esc(x.labId)}</strong></td><td><input data-v142-serial="${esc(x.ref)}" value="${esc(x.serialNumber)}" placeholder="${profile.requires.serialisation?'Required':'Optional'}"></td></tr>`).join('')}</tbody></table></div>`;
  const footer=`${btn('Cancel','data-modal-close','button')}${btn('Save register','data-v142-save-serials','button primary')}`;
  openModal(`Sample & serial register · ${r.id}`,content,footer,true);
  setTimeout(()=>{
    const series=$('[data-v142-apply-series]');
    if(series)series.onclick=()=>{
      const vals=v142BuildSerialSeries(rows.length,{prefix:$('[data-v142-prefix]')?.value||'',start:$('[data-v142-start]')?.value||1,pad:$('[data-v142-pad]')?.value||3,suffix:$('[data-v142-suffix]')?.value||''});
      rows.forEach((x,i)=>{const el=$(`[data-v142-serial="${x.ref}"]`);if(el)el.value=vals[i]});
    };
    const ex=$('[data-v142-export-samples-modal]');if(ex)ex.onclick=()=>v142ExportSampleRegister(requestId);
    const im=$('[data-v142-import-samples-modal]');if(im)im.onclick=()=>v142ImportSampleRegister(requestId);
    const save=$('[data-v142-save-serials]');
    if(save)save.onclick=async()=>{
      const assignments=rows.map(x=>({ref:x.ref,serialNumber:$(`[data-v142-serial="${x.ref}"]`)?.value||''}));
      const out=v142ApplySerialAssignments(requestId,assignments);if(!out.ok){toast(out.error,true);return}
      await persist();closeModal();render();toast('Sample identity register updated; permanent Lab IDs retained.');
    };
  },0);
}

function v142BatchFillModal(requestId){const r=requestById(requestId);P.syncRequestFlowdown(App.state,r);const defs=r.sampleDataRequirements||[],samples=samplesForRequest(requestId);if(!defs.length||!samples.length){toast('Create samples and define sample data requirements first.',true);return}openModal(`Batch-fill sample parameters · ${r.id}`,`<div class="callout"><h3>Controlled fill-down</h3><p>Populate one controlled sample parameter across the batch. Choose <b>blank cells only</b> to preserve existing evidence, or <b>replace all</b> for an intentional controlled update. Every change is audit logged.</p></div><div class="form-grid"><div class="field"><label>Parameter</label><select data-v142-fill-def>${defs.map(d=>`<option value="${esc(d.id)}">${esc(d.label)}${d.unit?` · ${esc(d.unit)}`:''}</option>`).join('')}</select></div><div class="field"><label>Value</label><input data-v142-fill-value></div><div class="field"><label>Apply to</label><select data-v142-fill-mode><option value="blank">Blank cells only</option><option value="all">All samples (replace)</option></select></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Apply to batch','data-v142-fill-apply','button primary')}`);setTimeout(()=>{$('[data-v142-fill-apply]').onclick=async()=>{const id=$('[data-v142-fill-def]').value,value=$('[data-v142-fill-value]').value.trim(),mode=$('[data-v142-fill-mode]').value;if(!value){toast('Enter a value to populate.',true);return}const def=defs.find(d=>d.id===id),before=[];let n=0;for(const sm of samples){P.ensureSampleCaptureFields(sm,r);const row=sm.dataFields.find(x=>x.definitionId===id);if(!row)continue;if(mode==='blank'&&String(row.value||'').trim())continue;before.push({sample:sm.sampleId||sm.serial,value:row.value||''});row.value=value;n++}if(n){P.invalidateBuildReport(App.state,r,`Batch-filled sample parameter ${def?.label||id}`);P.audit(App.state,'Batch sample parameter populated','Request',r.id,JSON.stringify(before),`${n} sample value(s) → ${value}`,`${def?.label||id} · ${mode==='blank'?'blank cells only':'controlled replace-all'}`)}await persist();closeModal();render();toast(`${n} sample value(s) updated.`)}},0)}

const _workspaceExecutionV142Base=workspaceExecution;
