      const owner=String(d.materialSupplyOwner||'').trim(),date=d.materialSupplyDate||'';
      return {ready:!!owner&&!!date&&!!P.isStrictISODate?.(date),title:'Engineering-supplied material',detail:owner&&date?`Planning basis: ${owner} owns supply; earliest lab availability ${P.formatDate(date)}. Planning may continue, but Build Readiness remains blocked until the exact material is physically received/issued.`:'Owner and expected arrival at the lab are required before this request can be submitted. You may continue completing this draft, but it cannot enter the controlled build workflow without both.'};
