      const cpChoice=form.querySelector('.v1091-cp-choice');if(cpChoice){const small=cpChoice.querySelector('small'),p=productLabel(d.productId);if(small)small.innerHTML=`Only approved Control Plans explicitly tied to <b>${esc(p)}</b> are shown. A plan from another product cannot be reused here. ${v1091ControlPlanCandidates(d).length?'The approved product baseline is selected by default; any build-specific change is handled later as a controlled delta.':'No approved baseline for this product exists; define/select one in the Controls workflow.'}`;}
