  for(const r of state.requests||[]){if(!r.actualDeliveryDate||seen.has(r.id)||!v151InPeriod(r.actualDeliveryDate,p))continue;const m=v151ReqMeta(state,r);if(!v151Match(m,f))continue;deliveries.push({...m,id:r.id,source:'request',date:r.actualDeliveryDate,requestedDate:r.originalRequestedDate||r.requiredDate,acceptedCommitmentDate:r.originalCommitmentDate,currentCommitmentDate:r.currentCommitmentDate||r.originalCommitmentDate,forecastDate:r.forecastDate,actualDate:r.actualDeliveryDate,leadDays:r.submittedAt?v151Days(r.submittedAt,r.actualDeliveryDate):null,requestToCommitDays:r.submittedAt&&r.originalCommitmentDate?v151Days(r.submittedAt,r.originalCommitmentDate):null,rft:null,quantity:Number(r.quantity||1),estimatedCost:Number(r.costEstimate),actualCost:Number(r.actualCost),costComponents:r.costComponents||null,traceabilityComplete:null,materialReady:null,planComplete:null,engineeringChanges:Number(r.engineeringChanges||0),issues:[],lessons:[]})}
