function v151Pareto(rows,{valueKey='value',unit='',filterAttr='',max=10}={}){const data=rows.filter(x=>Number(x[valueKey])>0).sort((a,b)=>Number(b[valueKey])-Number(a[valueKey])).slice(0,max),mx=Math.max(0,...data.map(x=>Number(x[valueKey])));if(!data.length)return'<div class="v151-empty-chart">No attributed events in the selected period.</div>';return `<div class="v151-pareto">${data.map((x,i)=>`<button class="v151-pareto-row" ${filterAttr?`${filterAttr}="${v151Esc(x.key||x.name)}"`:''}><span class="v151-pareto-rank">${i+1}</span><span class="v151-pareto-label">${v151Esc(x.name||x.key)}</span><span class="v151-pareto-track"><i style="width:${mx?100*Number(x[valueKey])/mx:0}%"></i></span><strong>${v151Num(x[valueKey],Number(x[valueKey])%1?1:0)}${v151Esc(unit)}</strong></button>`).join('')}</div>`}
