function v151Donut(rows,{valueKey='value',format=v=>v151Num(v,1),attr='data-v151-bu'}={}){const data=rows.filter(x=>Number(x[valueKey])>0),total=v151Sum(data.map(x=>x[valueKey]));if(!total)return'<div class="v151-empty-chart">No allocation data in the selected period.</div>';let a=0;const paths=data.map((x,i)=>{const span=360*Number(x[valueKey])/total,s=a;a+=span;return `<path class="v151-donut-seg s${i%8}" d="${v151Arc(110,110,90,s,a)}" ${attr}="${v151Esc(x.key||x.name)}"><title>${v151Esc(x.name)} · ${format(x[valueKey])} · ${(100*x[valueKey]/total).toFixed(1)}%</title></path>`}).join('');return `<div class="v151-donut-wrap"><svg class="v151-donut" viewBox="0 0 220 220">${paths}<circle class="v151-donut-hole" cx="110" cy="110" r="53"/><text x="110" y="106" text-anchor="middle" class="v151-donut-total">${format(total)}</text><text x="110" y="126" text-anchor="middle" class="v151-donut-caption">total</text></svg><div class="v151-donut-legend">${data.map((x,i)=>`<button ${attr}="${v151Esc(x.key||x.name)}"><i class="s${i%8}"></i><span>${v151Esc(x.name)}</span><strong>${format(x[valueKey])}</strong></button>`).join('')}</div></div>`}
