function v151BucketDelivery(data,p,g){const keys=v151BucketKeys(p,g);return keys.map(k=>{const r=data.deliveries.filter(x=>v151BucketKey(x.date,g)===k),m=v151DeliveryMetrics(r);return {key:k,label:v151BucketLabel(k,g),otd:m.otd,commitment:m.commitment,daysLate:m.daysLate}})}
