function v151Drill(id){const c=App.kpiContextV151;if(!c)return;const {state,data,m}=c;let rows=[],title=P.kpiDefinitionV151(state,id)?.name||id,summary='';if(['otd_requested','total_days_late','median_lead_time'].includes(id)){rows=data.deliveries.map(x=>({Project:x.requestId||x.id,Item:x.projectName||x.project,Requested:x.requestedDate||'—','Accepted commitment':x.acceptedCommitmentDate||'—','Current commitment':x.currentCommitmentDate||'—',Forecast:x.forecastDate||'—',Actual:x.actualDate||'—','Days late':x.requestedDate&&x.actualDate?Math.max(0,v151Days(x.requestedDate,x.actualDate)||0):'—',Lab:(state.labs||[]).find(l=>l.id===x.labId)?.code||x.labId||'—'}));summary=id==='otd_requested'?`${m.population||0} items with requested dates · ${m.onReq||0} on time · ${(m.population||0)-(m.onReq||0)} late`:`${rows.length} delivery record(s)`}
  else if(id==='right_first_time'){rows=data.deliveries.filter(x=>Number.isFinite(x.rft)).map(x=>({Project:x.requestId||x.id,Item:x.projectName||x.project,RFT:`${x.rft.toFixed(1)}%`,Quantity:x.quantity,Issues:(x.issues||[]).join('; ')||'—'}));summary=`Weighted RFT ${v151Fmt(id,m.rft)}`}
  else if(id==='cost_vs_plan'){rows=data.deliveries.filter(x=>x.actualCost||x.estimatedCost).map(x=>({Project:x.requestId||x.id,Planned:v151Money(x.estimatedCost),Actual:v151Money(x.actualCost),Variance:x.estimatedCost?`${((x.actualCost-x.estimatedCost)/x.estimatedCost*100).toFixed(1)}%`:'—'}));summary=`Actual ${v151Money(m.actualCost)} vs plan ${v151Money(m.plannedCost)}`}
  else if(id==='critical_capacity_load'){rows=data.capacity.slice().sort((a,b)=>(b.committedHours/b.availableHours)-(a.committedHours/a.availableHours)).map(x=>({Date:x.date,Category:x.equipmentCategory,Available:`${x.availableHours} h`,Committed:`${x.committedHours} h`,Load:`${x.availableHours?(100*x.committedHours/x.availableHours).toFixed(1)+'%':'—'}`,'Programme days impacted':x.programmeDaysImpacted||0}));summary=`Peak load ${v151Fmt(id,m.criticalLoad)}`}
  else if(id==='network_capture'||id==='outsourcing_avoided'){rows=data.transfers.map(x=>({Project:x.requestId,Decision:x.status==='External'?'External':'Sister lab',Hours:`${x.plannedHours||0} h`,'Programme days recovered':x.programmeDaysRecovered||0,'External alternative evidence':x.externalAlternativeEvidence||'—','Avoided €':x.externalAlternativeEvidence?v151Money(x.avoidedExternalCost):'—'}));summary=id==='outsourcing_avoided'?`Evidence-backed avoided cost ${v151Money(m.outsourcingAvoided)}`:`Internal network capture ${v151Fmt('network_capture',m.networkCapture)}`}
  const cols=rows.length?Object.keys(rows[0]):[];openModal(title,`<div class="callout info"><strong>${v151Esc(summary)}</strong><p>Underlying population for the current filters and selected period. Values reconcile with the headline KPI.</p></div>${rows.length?`<div class="table-wrap"><table class="data-table compact"><thead><tr>${cols.map(x=>`<th>${v151Esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,120).map(r=>`<tr>${cols.map(k=>`<td>${v151Esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No underlying records match this selection.</div>'}`,btn('Close','data-modal-close','button primary'),true)}
function v151TargetModal(){const state=App.state,f=v151F(),defs=P.kpiDefinitionsV151(state,f.domain);openModal('Configure KPI business targets',`<div class="callout info"><strong>Editable business targets</strong><p>These thresholds support management decisions. They are not presented as universal IATF 16949 or ISO/IEC 17025 requirements.</p></div><div class="v151-target-grid">${defs.filter(d=>d.target!=null).map(d=>`<label><span>${v151Esc(d.name)} <small>${v151Esc(d.unit)}</small></span><input type="number" step="any" data-v151-target-id="${v151Esc(d.id)}" value="${v151Esc(d.target)}"><small>Favourable direction: ${v151Esc(d.favourableDirection)}</small></label>`).join('')}</div>`,`${btn('Cancel','data-modal-close','button')}${btn('Save targets','data-v151-save-targets','button primary')}`,true)}
async function v151SaveTargets(){App.state.settings=App.state.settings||{};App.state.settings.kpiTargetsV151=App.state.settings.kpiTargetsV151||{};$$('[data-v151-target-id]').forEach(i=>{const v=Number(i.value);if(Number.isFinite(v))App.state.settings.kpiTargetsV151[i.dataset.v151TargetId]=v});P.audit?.(App.state,'KPI business targets updated','KPI','TARGETS','Prior configuration','Updated configuration',App.state.identity?.name||'User');await persist();closeModal();render();toast('KPI targets updated.')}
if(!App._v151KpiInstalled){App._v151KpiInstalled=true;document.addEventListener('change',e=>{const t=e.target;if(t.matches?.('[data-v151-filter]')){v151Set(t.dataset.v151Filter,t.value);render();return}if(t.matches?.('[data-v151-compare]')){v151Set('Compare',t.checked);render();return}if(t.matches?.('[data-v151-bu-metric]')){App.filters.kpi151BuMetric=t.value;render();return}if(t.matches?.('[data-v151-dev-family]')){v151Set('DevFamily',t.value);render();return}},true);document.addEventListener('click',e=>{const t=e.target.closest?.('[data-v151-reset],[data-v151-drill],[data-v151-bu],[data-v151-cause],[data-v151-network],[data-v151-targets],[data-v151-save-targets]');if(!t)return;if(t.hasAttribute('data-v151-reset')){['Period','CustomStart','CustomEnd','Lab','Domain','Bu','Product','Programme','Project','Family','EquipmentCategory','Priority','Cause','Network','DevFamily','Granularity','CapacityEquipment','CapacitySkill','CapacityPerson'].forEach(k=>delete App.filters['kpi151'+k]);App.filters.kpi151Compare=true;render();return}if(t.dataset.v151Drill){v151Drill(t.dataset.v151Drill);return}if(t.dataset.v151Bu){v151Set('Bu',t.dataset.v151Bu);render();return}if(t.dataset.v151Cause){v151Set('Cause',t.dataset.v151Cause);render();return}if(t.dataset.v151Network){v151Set('Network',t.dataset.v151Network);render();return}if(t.hasAttribute('data-v151-targets')){v151TargetModal();return}if(t.hasAttribute('data-v151-save-targets')){v151SaveTargets();return}},true)}
window.__LABOS_V151_KPI_TEST__={version:'1.0.164',period:(k,s,e)=>v151Period(k,s,e),previous:v151PreviousPeriod,build:(p,f)=>v151BuildData(App.state,p||v151Period('last90'),f||v151F()),metrics:d=>v151Metrics(App.state,d),definitions:()=>P.kpiDefinitionsV151(App.state,'all'),render:()=>v151Render(),filters:()=>v151F(),seed:()=>P.seedKpiDemoFactsV151?.(App.state)};


/* ============================================================
   LabOS REV 1.0.164 — Validation as a first-class programmeType.
   The UI deliberately reuses the Prototype portfolio, cockpit,
   cards, status colours, Programme Logic and planning vocabulary.
   ============================================================ */
function validationProgrammeV161(id=App.validationWorkspaceId){return (App.state.validationProgrammes||[]).find(x=>x.id===id)||null}
function validationOwnerV161(role='lab_planner'){return (App.state.users||[]).find(u=>u.role===role)?.name||App.state.identity?.name||'LabOS user'}
function validationStateClassV161(p){const wf=P.validationWorkflowStateV161(App.state,p);if(wf.failed)return'bad';if(p.archived||p.status==='Closed')return'archive';if(p.forecastDate&&p.requiredDate&&p.forecastDate>p.requiredDate)return'bad';if(wf.current==='requirements'||wf.current==='programme')return'warn';return''}
function validationStateLabelV161(p){const wf=P.validationWorkflowStateV161(App.state,p);if(p.archived)return'ARCHIVED';if(p.status==='Closed')return'CLOSED';if(wf.failed)return`${wf.failed} FAILED`;return wf.current==='requirements'?'REQUIREMENTS':wf.current==='programme'?'PROGRAMME':wf.current==='planning'?'PLAN':wf.current==='execution'?'EXECUTE':'REPORT'}
function openValidationV161(id,tab='requirements'){const p=(App.state.validationProgrammes||[]).find(x=>x.id===id);if(!p){toast(`Validation programme ${id} was not found.`,true);return}P.ensureProgrammeModelV161?.(App.state,{seedDemo:false});App.validationWorkspaceId=id;App.validationWorkspaceTab=tab;App.currentView='validation-workspace';App.workspaceId=null;renderNav();render();if(innerWidth<1121)$('#sidebar')?.classList.remove('open');window.scrollTo(0,0)}
function validationStepsV161(p){const wf=P.validationWorkflowStateV161(App.state,p),phase={requirements:'REQUIRE',programme:'DESIGN',planning:'PLAN',execution:'EXECUTE',report:'VERIFY'};return wf.states.map((s,i)=>{const state=s.done?'complete':s.id===wf.current?'current':s.blocked?'pending':'pending',owner=s.id==='requirements'||s.id==='programme'?validationOwnerV161('process_engineer'):s.id==='planning'?validationOwnerV161('lab_planner'):s.id==='execution'?validationOwnerV161('technician'):validationOwnerV161('quality');return {...s,index:i+1,phase:phase[s.id],state,owner}})}
function validationCockpitV161(p,steps){const wf=P.validationWorkflowStateV161(App.state,p),sel=steps.find(x=>x.id===App.validationWorkspaceTab)||steps.find(x=>x.id===wf.current)||steps[0],product=(App.state.products||[]).find(x=>x.id===p.productId),impact=p.prototypeImpact,impactText=impact?`${impact.oldDutAvailableDate||'—'} → ${impact.newDutAvailableDate}${impact.autoReplanned?' · replanned':impact.replanError?' · needs recovery':''}`:'—';return `<div class="workspace-fixed-cockpit workspace-cockpit-v161"><div class="workspace-context-strip"><div class="workspace-context-primary"><span>VALIDATION PROGRAMME</span><strong>${esc(p.id)} · ${esc(p.title)}</strong></div><div><span>PRODUCT / DUTS</span><strong>${esc(product?.family||p.productFamily||p.productId)} · ${p.quantity||1}</strong></div><div><span>REQUIRED</span><strong>${P.formatDate(p.requiredDate)}</strong></div><div><span>FORECAST</span><strong>${p.forecastDate?P.formatDate(p.forecastDate):'Not planned'}</strong></div><div><span>OWNER</span><strong>${esc(p.owner||'Unassigned')}</strong></div></div><div class="workspace-workflow-rail-v1066 workspace-workflow-rail-v140">${steps.map(s=>`<button class="workspace-workflow-step-v1066 ${s.state} ${s.id===App.validationWorkspaceTab?'selected':''}" data-v161-tab="${s.id}"><span>${s.done?'✓':s.index}</span><b>${esc(s.title)}</b></button>`).join('')}</div><div class="workflow-command-bar"><div class="workflow-command-slot workflow-edit-slot"><span class="workflow-slot-label">EDIT</span>${btn('Programme info','data-v161-edit-programme','button small secondary workflow-dock-button')}</div><div class="workflow-command-current"><span class="workflow-step-icon ${sel.state}">${sel.done?'✓':'●'}</span><div><span class="workflow-slot-label">STEP ${sel.index} · ${esc(sel.phase)}</span><strong>${esc(sel.title)}</strong><small>${esc(sel.owner)} · ${esc(sel.next)}</small></div></div><div class="workflow-command-slot workflow-approval-slot"><span class="workflow-slot-label">LINKED PROTOTYPE</span>${p.linkedPrototypeId?`<button class="button small secondary workflow-dock-button" data-open-request="${esc(p.linkedPrototypeId)}">${esc(p.linkedPrototypeId)}</button>`:'<span class="subtle">None</span>'}</div><div class="workflow-command-slot workflow-next-slot"><span class="workflow-slot-label">NEXT STEP</span>${sel.done&&steps[sel.index]?btn(`Open ${steps[sel.index].title} →`,`data-v161-tab="${steps[sel.index].id}"`,'button small primary'):btn('Resolve current step →',`data-v161-tab="${wf.current}"`,'button small primary')}</div></div>${impact?`<div class="v161-impact-strip ${impact.replanError?'bad':'good'}"><strong>Prototype timing impact</strong><span>${esc(impactText)}</span>${impact.replanError?btn('Recovery options','data-v161-site-compare','button tiny primary'):''}</div>`:''}</div>`}
function validationGuideV161(steps){return `<div class="guided-card guided-desktop-checklist"><div class="guided-heading"><div><span class="eyebrow">GUIDED VALIDATION WORKFLOW</span><h2>${steps.length}-step workflow</h2><p>Same LabOS semantics: green complete · yellow current · grey future · red blocker.</p></div><div class="guided-progress"><strong>${steps.filter(x=>x.done).length}/${steps.length}</strong><span>steps complete</span></div></div><div class="guided-list">${steps.map(s=>`<button type="button" class="guide-row ${s.state} ${App.validationWorkspaceTab===s.id?'selected':''}" data-v161-tab="${s.id}"><span class="guide-check">${s.done?'✓':s.index}</span><span class="guide-copy"><span class="guide-phase">${esc(s.phase)}</span><strong>${esc(s.title)}</strong><span class="guide-owner">Owner: ${esc(s.owner)}</span><span class="guide-next"><b>${s.done?'Evidence:':'Next:'}</b> ${esc(s.next)}</span></span><span class="guide-state ${s.state}">${s.done?'Complete':s.state==='current'?'Current':'Future'}</span><span class="guide-chevron">›</span></button>`).join('')}</div></div>`}
function validationProgrammeCardV161(p,showType=false){const product=(App.state.products||[]).find(x=>x.id===p.productId),wf=P.validationWorkflowStateV161(App.state,p),cls=validationStateClassV161(p);return `<article class="request-search-card ${cls}"><button class="request-card-main" data-open-validation="${p.id}"><span class="request-card-state">${cls==='bad'?'!':cls==='archive'?'✓':'●'}</span><div><span class="request-mobile-id">${esc(p.id)}${showType?' · VALIDATION':''}</span><strong>${esc(p.title)}</strong><small>${esc(product?.family||p.productFamily||p.productId)} · ${esc(p.project||p.businessUnit||'Validation')}</small></div><div class="request-card-date"><b>${validationStateLabelV161(p)}</b><small>${P.formatDate(p.requiredDate)}</small></div></button><div class="request-card-meta"><span>Owner <b>${esc(p.owner||'Unassigned')}</b></span><span>Verified <b>${wf.verified}/${wf.reqs.length}</b></span><span>Lab <b>${esc((App.state.labs||[]).find(x=>x.id===p.executionSiteId)?.code||p.executionSiteId||'Home')}</b></span>${p.linkedPrototypeId?`<span>Prototype <b>${esc(p.linkedPrototypeId)}</b></span>`:''}</div><div class="request-card-actions">${btn('Open',`data-open-validation="${p.id}"`,'button tiny primary')}${btn('Requirements',`data-open-validation="${p.id}" data-validation-tab="requirements"`,'button tiny secondary')}${btn('Plan',`data-open-validation="${p.id}" data-validation-tab="planning"`,'button tiny secondary')}</div></article>`}
function prototypeProgrammeCardV161(r){const late=r.forecastDate&&r.requiredDate&&r.forecastDate>r.requiredDate,arch=r.archived||r.status==='CLOSED';return `<article class="request-search-card ${late?'bad':arch?'archive':''}"><button class="request-card-main" data-open-request="${r.id}"><span class="request-card-state">${late?'!':arch?'✓':'●'}</span><div><span class="request-mobile-id">${esc(r.id)} · PROTOTYPE</span><strong>${esc(r.title)}</strong><small>${esc(r.productFamily)} · ${esc(r.programme||'Prototype')}</small></div><div class="request-card-date"><b>${esc(r.status||'ACTIVE')}</b><small>${P.formatDate(r.requiredDate)}</small></div></button><div class="request-card-meta"><span>Owner <b>${esc(r.owner||'Unassigned')}</b></span><span>Forecast <b>${r.forecastDate?P.formatDate(r.forecastDate):'—'}</b></span></div><div class="request-card-actions">${btn('Open',`data-open-request="${r.id}"`,'button tiny primary')}</div></article>`}
function renderProgrammePortfolioV161(){const q=String(App.filters.v161PortfolioSearch||'').toLowerCase(),type=App.filters.v161PortfolioType||'All',protos=(App.state.requests||[]).filter(r=>!r.archived&&r.status!=='CLOSED'&&(type==='All'||type==='Prototype')&&(!q||`${r.id} ${r.title} ${r.productFamily} ${r.programme}`.toLowerCase().includes(q))),vals=(App.state.validationProgrammes||[]).filter(p=>!p.archived&&(type==='All'||type==='Validation')&&(!q||`${p.id} ${p.title} ${p.productFamily} ${p.project} ${p.businessUnit}`.toLowerCase().includes(q)));return pageHeader('Programme Portfolio','Prototype and Validation share one LabOS portfolio, resource system and planning truth.',btn('+ Prototype request','data-nav="intake"','button secondary')+btn('+ Validation programme','data-v161-new-programme','button primary'))+`<div class="card request-search-panel"><div class="request-search-grid v161-portfolio-filters"><label>Search<input data-v161-portfolio-search value="${esc(App.filters.v161PortfolioSearch||'')}" placeholder="Programme, product, project…"></label><label>Work type<select data-v161-portfolio-type><option ${type==='All'?'selected':''}>All</option><option ${type==='Prototype'?'selected':''}>Prototype</option><option ${type==='Validation'?'selected':''}>Validation</option></select></label><div class="v161-filter-stat"><b>${protos.length}</b><span>Prototype</span></div><div class="v161-filter-stat"><b>${vals.length}</b><span>Validation</span></div></div></div><div class="request-card-grid">${protos.map(prototypeProgrammeCardV161).join('')}${vals.map(p=>validationProgrammeCardV161(p,true)).join('')||(!protos.length?'<div class="empty">No programmes match the selected filters.</div>':'')}</div>`}
function renderValidationPortfolioV161(){const programmes=(App.state.validationProgrammes||[]).filter(p=>!p.archived);return pageHeader('Validation','Flow-first validation programmes, controlled requirement coverage, shared resource planning and evidence.',btn('+ New Validation programme','data-v161-new-programme','button primary'))+`<div class="card"><div class="section-title-row"><div><span class="eyebrow">VALIDATION PROGRAMMES</span><h2>${programmes.length} active programme${programmes.length===1?'':'s'}</h2><div class="subtle">Open a programme to define Test Legs first, then map requirements as the coverage-assurance layer.</div></div></div></div><div class="request-card-grid">${programmes.map(p=>validationProgrammeCardV161(p)).join('')||'<div class="empty">No Validation programmes yet.</div>'}</div>`}
function sharedProgrammeCanvasV161(type,entity){let lanes=[];if(type==='validation'){const legs=P.validationLegsV161(App.state,entity.id),acts=P.validationActivitiesV161(App.state,entity.id);lanes=legs.map(l=>({id:l.id,name:l.name,items:acts.filter(a=>a.legId===l.id)}))}else{const route=(App.state.routes||[]).find(x=>x.requestId===entity.id),steps=(route?.steps||[]).slice().sort((a,b)=>Number(a.order||0)-Number(b.order||0)),groups=[...new Set(steps.map(s=>s.parallelGroup||'Main build'))];lanes=groups.map((name,i)=>({id:name==='Main build'?'proto-main':`proto-${name}`,name,items:steps.filter(s=>(s.parallelGroup||'Main build')===name)}))}const zoom=Math.max(.7,Math.min(1.5,Number(App.programmeZoom||1)));const toolbar=`<div class="v161-canvas-toolbar"><div><span class="eyebrow">SHARED PROGRAMME LOGIC</span><strong>${type==='validation'?'Validation programme':'Prototype build route'}</strong></div><div class="route-toolbar">${type==='validation'?btn('+ Test leg','data-v161-add-leg','button tiny secondary'):''}${btn('−','data-v161-zoom="out"','button tiny secondary')}${btn(`${Math.round(zoom*100)}%`,'data-v161-zoom="fit"','button tiny secondary')}${btn('+','data-v161-zoom="in"','button tiny secondary')}</div></div>`;const laneHtml=lanes.map(l=>`<div class="v161-programme-lane" data-v161-lane="${esc(l.id)}" data-v161-programme-type="${type}"><div class="v161-lane-label"><strong>${esc(l.name)}</strong><small>${l.items.length} step${l.items.length===1?'':'s'}</small></div><div class="v161-lane-track" style="--v161-zoom:${zoom}">${l.items.map((a,i)=>{const complete=/complete|verified|released/i.test(String(a.status||'')),blocked=/fail|blocked/i.test(String(a.status||'')),kind=type==='validation'?(a.kind||'Validation Test'):(a.type==='standard'?'Process step':'Development step'),sub=type==='validation'?(a.standardTestId?`${a.standardTestId} · ${a.estimatedHours||'—'} h`:`${a.estimatedHours||'—'} h`):(a.processId||'Process');return `<div class="v161-programme-node ${complete?'complete':blocked?'blocked':'future'}" draggable="true" data-v161-node="${esc(a.id)}" data-v161-node-type="${type}"><span class="v161-node-seq">${i+1}</span><div><small>${esc(kind)}</small><strong>${esc(a.name)}</strong><span>${esc(sub)}</span></div>${type==='validation'?`<button type="button" class="v161-node-edit" data-v161-edit-activity="${a.id}" aria-label="Edit">⋯</button>`:''}</div>`}).join('')||'<div class="v161-lane-empty">Drop a step here</div>'}</div></div>`).join('');return `<div class="card v161-shared-canvas">${toolbar}<div class="v161-canvas-scroll">${laneHtml||'<div class="empty">No programme steps defined yet.</div>'}</div></div>`}
function validationRequirementsViewV161(p){const reqs=P.validationRequirementsV161(App.state,p.id),mapped=reqs.filter(r=>r.mapping).length;return `<div class="section-stack"><div class="card"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED SOURCE</span><h2>Requirements → verification mapping</h2><p class="subtle">Start from what must be verified. Standard Tests are reusable capability, not the source of requirements.</p></div><div class="route-toolbar">${btn('Paste / CSV import','data-v161-import-requirements','button small secondary')}${btn('+ Requirement','data-v161-add-requirement','button small primary')}</div></div><div class="v161-requirement-stats"><div><b>${reqs.length}</b><span>Controlled requirements</span></div><div><b>${mapped}</b><span>Mapped</span></div><div><b>${reqs.filter(r=>r.status==='Verified').length}</b><span>Verified</span></div><div><b>${reqs.filter(r=>r.status==='Failed').length}</b><span>Failed</span></div></div></div><div class="card"><div class="section-title-row"><div><h2>Requirement workspace</h2><div class="subtle">Reuse → adapt → combine → develop. Mapping assistance never silently approves coverage.</div></div>${reqs.length&&mapped===reqs.length?btn('Generate Validation Programme →','data-v161-generate-programme','button primary'):''}</div><div class="v161-requirement-list">${reqs.map(r=>{const m=r.mapping,linked=(r.linkedActivityIds||[]).length;return `<article class="v161-requirement-card ${r.status==='Failed'?'bad':r.status==='Verified'?'good':m?'mapped':''}"><div class="v161-req-id"><strong>${esc(r.id)}</strong><span>${esc(r.sourceReference||r.source||'Requirement')}</span></div><div class="v161-req-main"><div class="v161-req-meta"><span>${esc(r.category||'General')}</span><span>Rev ${esc(r.revision||'A')}</span><span>${esc(r.priority||'Normal')}</span></div><h3>${esc(r.description)}</h3><p>${esc(r.acceptanceCriteria||'Acceptance criteria to be confirmed.')}</p>${m?`<div class="v161-map-summary"><strong>${esc(m.mode.toUpperCase())} · ${m.coverage}% coverage</strong><span>${esc(m.basis||'Mapped verification method')}</span>${m.missingAspects?.length?`<small>Delta: ${m.missingAspects.map(esc).join(' · ')}</small>`:''}</div>`:'<div class="callout warn compact"><strong>Not Covered</strong> Map this requirement before programme generation.</div>'}</div><div class="v161-req-actions"><span class="pill">${esc(r.status||'Not Covered')}</span>${btn(m?'Review mapping':'Map to test',`data-v161-map-requirement="${r.id}"`,'button tiny primary')}${linked?`<small>${linked} linked activity${linked===1?'':'ies'}</small>`:''}</div></article>`}).join('')||'<div class="empty">Add or import customer/product requirements to begin.</div>'}</div></div></div>`}
function validationProgrammeViewV161(p){const graph=P.validationGraphCheckV161(App.state,p.id),reqs=P.validationRequirementsV161(App.state,p.id),unmapped=reqs.filter(r=>!r.mapping).length;return `<div class="section-stack">${unmapped?`<div class="callout bad"><strong>${unmapped} requirement(s) still unmapped.</strong><p>Return to Requirements and make a controlled mapping decision before changing Programme Logic.</p>${btn('Open Requirements','data-v161-tab="requirements"','button small primary')}</div>`:''}${sharedProgrammeCanvasV161('validation',p)}<div class="card"><div class="section-title-row"><div><span class="eyebrow">STRUCTURE CHECK</span><h2>${graph.ok?'Programme logic is controlled':'Programme needs attention'}</h2><div class="subtle">${graph.legs} legs · ${graph.nodes} activities · ${graph.floating} floating activities</div></div>${graph.ok?status('Ready'):status('Blocked')}</div>${graph.issues.length?`<div class="callout bad">${graph.issues.map(x=>`<div>${esc(x)}</div>`).join('')}</div>`:'<div class="callout reuse-good"><strong>No floating tests or dependency cycles.</strong> Every activity is snapped to a controlled Validation leg.</div>'}</div></div>`}
function validationPlanningSwimlaneV161(p){const reqs=App.state.requests||(App.state.requests=[]),existing=reqs.findIndex(x=>x.id===p.id),previous=existing>=0?reqs[existing]:null,synthetic=P.validationSyntheticRequestV161(App.state,p);if(existing>=0)reqs.splice(existing,1,synthetic);else reqs.push(synthetic);try{return planningSwimlane({view:'build',requestId:p.id,weeks:8,includePotential:false})}finally{const i=reqs.findIndex(x=>x.id===p.id);if(i>=0){if(existing>=0)reqs.splice(i,1,previous);else reqs.splice(i,1)}}}
