function renderArchiveManagerV161(){
  const type=App.filters.v161ArchiveType||'all',scope=App.filters.v161ArchiveState||'all',retentionDays=Math.max(30,Number(App.state.settings?.archiveRetentionDays||730)),cut=new Date(Date.now()-retentionDays*86400000);
  const proto=(App.state.requests||[]).map(x=>({type:'prototype',id:x.id,title:x.title,product:x.productFamily||x.productId,archived:!!(x.archived||x.status==='CLOSED'),archivedAt:x.archivedAt||x.closedAt||null,owner:x.owner,raw:x}));
  const val=(App.state.validationProgrammes||[]).map(x=>({type:'validation',id:x.id,title:x.title,product:x.productFamily||x.productId,archived:!!(x.archived||x.status==='Closed'),archivedAt:x.archivedAt||null,owner:x.owner,raw:x}));
  const all=[...proto,...val],rows=all.filter(x=>(type==='all'||x.type===type)&&(scope==='all'||(scope==='archived'?x.archived:!x.archived))).sort((a,b)=>Number(a.archived)-Number(b.archived)||String(a.id).localeCompare(String(b.id))),archived=all.filter(x=>x.archived);
  const canArchive=currentRole()==='administrator'||can('audit:view'),canDelete=currentRole()==='administrator';
  const cards=rows.map(x=>{const eligible=x.archived&&x.archivedAt&&new Date(x.archivedAt)<=cut,inspect=x.type==='prototype'?`data-open-request="${x.id}"`:`data-open-validation="${x.id}"`,restore=x.type==='prototype'?`data-v161-restore-prototype="${x.id}"`:`data-v161-restore-validation="${x.id}"`,archive=`data-v161-archive-item="${x.type}|${x.id}"`,del=`data-v161-delete-archive="${x.type}|${x.id}"`;return `<article class="request-search-card ${x.archived?'archive':'good'}"><div class="request-card-main"><span class="request-card-state">${x.archived?'✓':'●'}</span><div><span class="request-mobile-id">${esc(x.id)} · ${x.type==='prototype'?'PROTOTYPE':'VALIDATION'}</span><strong>${esc(x.title)}</strong><small>${esc(x.product||'—')} · Owner ${esc(x.owner||'Unassigned')}</small></div><div class="request-card-date"><b>${x.archived?'ARCHIVED':'ACTIVE'}</b><small>${x.archivedAt?P.formatDate(x.archivedAt):'Controlled programme'}</small></div></div><div class="request-card-actions">${btn('Inspect',inspect,'button tiny secondary')}${x.archived?btn('Restore',restore,'button tiny primary'):(canArchive?btn('Archive',archive,'button tiny secondary'):'')}${canDelete&&x.archived?(eligible?btn('Delete',del,'button tiny danger'):`<button class="button tiny" disabled title="Retention period not yet reached">Delete after retention</button>`):''}</div></article>`}).join('');
  return pageHeader('Archive Manager','One controlled archive for Prototype Builds and Validation Programmes.')+`<div class="card"><div class="section-title-row"><div><span class="eyebrow">CONTROLLED RETENTION</span><h2>${archived.length} archived · ${all.length-archived.length} active</h2><p class="subtle">Archive, restore and inspect both programme types here. Permanent deletion is Administrator-only after the configured ${retentionDays}-day retention period.</p></div><div class="route-toolbar"><span class="pill">Prototype ${proto.filter(x=>x.archived).length}</span><span class="pill">Validation ${val.filter(x=>x.archived).length}</span></div></div><div class="form-grid compact"><label class="field">Work type<select data-v161-archive-filter="type"><option value="all" ${type==='all'?'selected':''}>All</option><option value="prototype" ${type==='prototype'?'selected':''}>Prototype</option><option value="validation" ${type==='validation'?'selected':''}>Validation</option></select></label><label class="field">State<select data-v161-archive-filter="state"><option value="all" ${scope==='all'?'selected':''}>All</option><option value="active" ${scope==='active'?'selected':''}>Active</option><option value="archived" ${scope==='archived'?'selected':''}>Archived</option></select></label></div></div><div class="request-card-grid">${cards||'<div class="empty">No programmes match the selected archive filters.</div>'}</div>`;
}
function archiveItemModalV161(key){const [type,id]=String(key||'').split('|'),item=type==='prototype'?(App.state.requests||[]).find(x=>x.id===id):(App.state.validationProgrammes||[]).find(x=>x.id===id);if(!item)return;openModal(`Archive · ${id}`,`<div class="callout warn"><strong>Archive this ${type==='prototype'?'Prototype Build':'Validation Programme'}?</strong><p>The record becomes read-only in normal workflows. Evidence and audit history are retained and the record can be restored.</p></div><div class="field"><label>Archive reason <b>required</b></label><textarea id="v161ArchiveReason" rows="4" placeholder="Why is this programme being archived?"></textarea></div><input type="hidden" id="v161ArchiveKey" value="${esc(key)}">`,`${btn('Cancel','data-modal-close','button')}${btn('Archive programme','data-v161-confirm-archive','button danger')}`,true)}
async function archiveItemCommitV161(){const key=$('#v161ArchiveKey')?.value||'',reason=$('#v161ArchiveReason')?.value?.trim()||'';if(reason.length<5){toast('Record a clear archive reason.',true);return}const [type,id]=key.split('|'),now=P.now();if(type==='prototype'){const r=(App.state.requests||[]).find(x=>x.id===id);if(!r)return;r.archivePreviousStatus=r.status;r.archived=true;r.status='CLOSED';r.archivedAt=now;r.archiveReason=reason;r.archivedBy=App.state.identity.name;App.state.bookings=(App.state.bookings||[]).filter(b=>b.requestId!==id);P.audit?.(App.state,'Prototype Build archived','Request',id,r.archivePreviousStatus,'CLOSED',reason)}else{const p=(App.state.validationProgrammes||[]).find(x=>x.id===id);if(!p)return;p.archivePreviousStatus=p.status;p.archived=true;p.status='Closed';p.archivedAt=now;p.archiveReason=reason;p.archivedBy=App.state.identity.name;App.state.bookings=(App.state.bookings||[]).filter(b=>b.requestId!==id);P.audit?.(App.state,'Validation Programme archived','Validation Programme',id,p.archivePreviousStatus,'Closed',reason);P.syncValidationActionsV161?.(App.state)}await persist();closeModal();render();toast(`${id} archived.`)}
function deleteArchiveModalV161(key){const [type,id]=String(key||'').split('|');openModal(`Permanent deletion · ${id}`,`<div class="callout bad"><strong>This cannot be undone.</strong><p>The configured retention period has elapsed. Type DELETE to permanently remove this archived ${type==='prototype'?'Prototype Build':'Validation Programme'} and its programme-owned records.</p></div><div class="field"><label>Confirmation</label><input id="v161DeleteConfirm" autocomplete="off" placeholder="DELETE"></div><input type="hidden" id="v161DeleteKey" value="${esc(key)}">`,`${btn('Cancel','data-modal-close','button')}${btn('Delete permanently','data-v161-confirm-delete','button danger')}`,true)}
async function deleteArchiveCommitV161(){if($('#v161DeleteConfirm')?.value!=='DELETE'){toast('Type DELETE exactly to confirm.',true);return}const [type,id]=String($('#v161DeleteKey')?.value||'').split('|'),retentionDays=Math.max(30,Number(App.state.settings?.archiveRetentionDays||730)),item=type==='prototype'?(App.state.requests||[]).find(x=>x.id===id):(App.state.validationProgrammes||[]).find(x=>x.id===id),at=item?.archivedAt||item?.closedAt;if(!item||!at||new Date(at)>new Date(Date.now()-retentionDays*86400000)){toast('Retention period has not elapsed.',true);return}if(type==='prototype'){for(const k of ['routes','bookings','serials','measurements','deviations','approvals','documents','allocations','actions'])App.state[k]=(App.state[k]||[]).filter(x=>x.requestId!==id);App.state.requests=(App.state.requests||[]).filter(x=>x.id!==id)}else{for(const k of ['validationRequirements','validationLegs','validationActivities','validationResults','validationEvidence','validationReports','validationDevelopmentHistory','validationLessonCandidates','lessonApplicationsV161','lessonImprovementProposalsV161'])App.state[k]=(App.state[k]||[]).filter(x=>x.programmeId!==id);App.state.lessons=(App.state.lessons||[]).filter(x=>x.programmeId!==id);App.state.bookings=(App.state.bookings||[]).filter(x=>x.requestId!==id);App.state.actions=(App.state.actions||[]).filter(x=>x.requestId!==id);App.state.validationProgrammes=(App.state.validationProgrammes||[]).filter(x=>x.id!==id)}P.audit?.(App.state,'Archived programme permanently deleted','Archive',id,'Retained','Deleted',`${type} · retention ${retentionDays} days`);await persist();closeModal();render();toast(`${id} permanently deleted.`)}
function installArchiveEventsV161(){if(App._archiveEventsV161)return;App._archiveEventsV161=true;document.addEventListener('change',e=>{const x=e.target.closest?.('[data-v161-archive-filter]');if(!x)return;if(x.dataset.v161ArchiveFilter==='type')App.filters.v161ArchiveType=x.value;else App.filters.v161ArchiveState=x.value;render()},true);document.addEventListener('click',e=>{const t=e.target.closest?.('[data-v161-archive-item],[data-v161-confirm-archive],[data-v161-delete-archive],[data-v161-confirm-delete]');if(!t)return;if(t.dataset.v161ArchiveItem)return archiveItemModalV161(t.dataset.v161ArchiveItem);if(t.hasAttribute('data-v161-confirm-archive'))return archiveItemCommitV161();if(t.dataset.v161DeleteArchive)return deleteArchiveModalV161(t.dataset.v161DeleteArchive);if(t.hasAttribute('data-v161-confirm-delete'))return deleteArchiveCommitV161()},true)}

function newValidationProgrammeModalV161(){const products=(App.state.products||[]),protos=(App.state.requests||[]).filter(r=>!r.archived&&r.status!=='CLOSED'),bus=P.businessUnitsV127?.(App.state)||App.state.settings?.businessUnits||[];openModal('New Validation programme',`<div class="resolution-focus"><span class="eyebrow">VALIDATION REQUEST</span><h2>Start from the product and the controlled need</h2><p>Requirements are the first workflow step. The Programme Logic is generated only after engineering mapping decisions.</p></div><div class="form-grid"><div class="field"><label>Programme title</label><input id="v161ValTitle" value="Design Validation Programme"></div><div class="field"><label>Product</label><select id="v161ValProduct">${products.map(x=>`<option value="${x.id}">${esc(x.family||x.name||x.partNumber)} · ${esc(x.revision||'')}</option>`).join('')}</select></div><div class="field"><label>Required completion</label><input id="v161ValDue" type="date" value="${P.addDays?.(P.todayISO(),28)||''}"></div><div class="field"><label>DUT quantity</label><input id="v161ValQty" type="number" min="1" value="6"></div><div class="field"><label>Linked Prototype Build (optional)</label><select id="v161ValProto"><option value="">None</option>${protos.map(r=>`<option value="${r.id}">${esc(r.id)} · ${esc(r.title)}</option>`).join('')}</select></div><div class="field"><label>Business Unit / project</label><input id="v161ValBu" value="${esc(bus[0]?.name||'Product Engineering')}"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Create & add requirements','data-v161-create-programme','button primary')}`,true)}
async function createValidationProgrammeV161(){const product=(App.state.products||[]).find(x=>x.id===$('#v161ValProduct')?.value),proto=(App.state.requests||[]).find(x=>x.id===$('#v161ValProto')?.value),seq=101+(App.state.validationProgrammes||[]).length;let id=`V26-${String(seq).padStart(4,'0')}`;while((App.state.validationProgrammes||[]).some(x=>x.id===id)){id=`V26-${String(++seq).padStart(4,'0')}`}const p={id,programmeType:'validation',title:$('#v161ValTitle')?.value?.trim()||'Validation Programme',productId:product?.id,productFamily:product?.family||product?.name||product?.partNumber,productRevision:product?.revision||'A',project:$('#v161ValBu')?.value?.trim()||'Validation',businessUnit:$('#v161ValBu')?.value?.trim()||'Product Engineering',owner:validationOwnerV161('lab_planner'),requester:App.state.identity?.name,customerId:proto?.customerId||'CUST-VALIDATION',priority:'High',quantity:Math.max(1,Number($('#v161ValQty')?.value||1)),requiredDate:$('#v161ValDue')?.value||P.addDays?.(P.todayISO(),28),dutAvailableDate:proto?.forecastDate||proto?.currentCommitmentDate||P.todayISO(),homeSiteId:proto?.homeSiteId||App.state.settings?.activeLabId||App.state.settings?.primaryLabId,executionSiteId:proto?.homeSiteId||App.state.settings?.activeLabId||App.state.settings?.primaryLabId,linkedPrototypeId:proto?.id||null,status:'Requirements',createdAt:P.now(),updatedAt:P.now(),archived:false};App.state.validationProgrammes.push(p);P.audit?.(App.state,'Validation programme created','Validation Programme',id,'—',p.title,'Requirements-first controlled workflow');P.syncValidationActionsV161(App.state);await persist();closeModal();openValidationV161(id,'requirements');toast(`${id} created. Add or import requirements.`)}
function addRequirementModalV161(){const p=validationProgrammeV161();openModal('Add Validation requirement',`<div class="form-grid"><div class="field"><label>Source</label><input id="v161ReqSource" value="Customer / Product Specification"></div><div class="field"><label>Source reference</label><input id="v161ReqRef" placeholder="e.g. 5.2.1"></div><div class="field"><label>Category / test leg</label><input id="v161ReqCategory" value="Functional"></div><div class="field"><label>Priority</label><select id="v161ReqPriority"><option>Normal</option><option selected>High</option><option>Critical</option></select></div><div class="field span-2"><label>Requirement</label><textarea id="v161ReqDescription" rows="4" placeholder="Product shall…"></textarea></div><div class="field span-2"><label>Acceptance criteria</label><textarea id="v161ReqAcceptance" rows="3" placeholder="Controlled pass/fail criteria"></textarea></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Add requirement','data-v161-save-requirement','button primary')}`,true)}
async function saveRequirementV161(){const p=validationProgrammeV161(),rows=P.validationRequirementsV161(App.state,p.id),id=`${p.id}-REQ-${String(rows.length+1).padStart(3,'0')}`,desc=$('#v161ReqDescription')?.value?.trim();if(!desc){toast('Requirement text is required.',true);return}App.state.validationRequirements.push({id,programmeId:p.id,source:$('#v161ReqSource')?.value?.trim()||'Specification',sourceDocument:'',sourceReference:$('#v161ReqRef')?.value?.trim()||id,description:desc,category:$('#v161ReqCategory')?.value?.trim()||'Verification',legName:$('#v161ReqCategory')?.value?.trim()||'Verification',revision:'A',priority:$('#v161ReqPriority')?.value||'High',acceptanceCriteria:$('#v161ReqAcceptance')?.value?.trim()||'Meet controlled requirement.',status:'Not Covered',comments:'',createdAt:P.now()});P.syncValidationActionsV161(App.state);await persist();closeModal();render();toast('Requirement added.')}
function importRequirementsModalV161(){openModal('Import Validation requirements',`<div class="callout info"><strong>Paste or import CSV</strong><p>Accepted columns: ID, Source, Reference, Requirement, Category, Revision, Priority, Acceptance Criteria. CSV is Excel-compatible. Imported rows remain controlled candidates until mapped by an engineer.</p></div><div class="field"><label>Paste requirement lines or CSV</label><textarea id="v161ReqImportText" rows="10" placeholder="REQ-001,Customer Spec,5.2.1,Product shall…,Environmental,A,High,Pass criteria"></textarea></div><div class="field"><label>Or choose CSV</label><input id="v161ReqImportFile" type="file" accept=".csv,text/csv"></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Import candidates','data-v161-commit-import','button primary')}`,true);setTimeout(()=>{$('#v161ReqImportFile')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(f)$('#v161ReqImportText').value=await f.text()})},0)}
async function commitRequirementsImportV161(){const p=validationProgrammeV161(),raw=$('#v161ReqImportText')?.value||'';if(!raw.trim()){toast('Paste or choose requirement data first.',true);return}const parsed=parseCsv(raw),hasHeader=parsed[0]?.some(x=>/requirement|description/i.test(x));let data=parsed;if(!hasHeader&&parsed.length===1&&raw.includes('\n'))data=raw.split(/\r?\n/).filter(Boolean).map(x=>[x]);const header=hasHeader?parsed.shift().map(x=>String(x).trim().toLowerCase()):null;let n=0;for(const row of parsed){if(!row.some(x=>String(x).trim()))continue;const get=(names,idx)=>{if(header){const i=header.findIndex(h=>names.some(n=>h.includes(n)));return i>=0?row[i]:''}return row[idx]||''},desc=String(get(['requirement','description','text'],3)||get([],0)).trim();if(!desc)continue;const count=P.validationRequirementsV161(App.state,p.id).length+1,id=String(get(['id'],0)||`${p.id}-REQ-${String(count).padStart(3,'0')}`).trim();App.state.validationRequirements.push({id:App.state.validationRequirements.some(x=>x.id===id)?`${p.id}-REQ-${String(count).padStart(3,'0')}`:id,programmeId:p.id,source:String(get(['source'],1)||'Imported specification').trim(),sourceDocument:'',sourceReference:String(get(['reference','clause'],2)||id).trim(),description:desc,category:String(get(['category','leg'],4)||'Verification').trim(),legName:String(get(['category','leg'],4)||'Verification').trim(),revision:String(get(['revision'],5)||'A').trim(),priority:String(get(['priority'],6)||'High').trim(),acceptanceCriteria:String(get(['acceptance','criteria'],7)||'Meet controlled requirement.').trim(),status:'Not Covered',comments:'Imported candidate reviewed in LabOS',createdAt:P.now()});n++}P.syncValidationActionsV161(App.state);await persist();closeModal();render();toast(`${n} requirement${n===1?'':'s'} imported.`)}
function mappingModalV161(reqId){const r=(App.state.validationRequirements||[]).find(x=>x.id===reqId),ranked=P.rankValidationTestsV161(App.state,r,6);openModal(`Map ${r.id} to verification`, `<div class="callout info"><strong>${esc(r.description)}</strong><p>LabOS ranks released Standard Tests as assistance only. You decide reuse, adapt, combine or new development.</p></div><div class="field"><label>Mapping decision</label><select id="v161MapMode"><option value="reuse">Reuse released Standard Test</option><option value="adapt">Adapt closest Standard Test</option><option value="combine">Combine tests</option><option value="new">Develop new method</option></select></div><div class="v161-candidate-list">${ranked.map((x,i)=>`<label class="v161-candidate ${i===0?'best':''}"><input type="checkbox" data-v161-map-test value="${x.test.id}" ${i===0?'checked':''}><div><strong>${esc(x.test.id)} · ${esc(x.test.name)}</strong><span>Rev ${esc(x.test.revision||'—')} · ${x.coverage}% estimated coverage · ${x.priorUses} prior controlled use${x.missing.length?` · delta: ${x.missing.map(esc).join(', ')}`:''}</span></div></label>`).join('')||'<div class="empty">No released Standard Tests available.</div>'}</div><input type="hidden" id="v161MapReqId" value="${r.id}">`,`${btn('Cancel','data-modal-close','button')}${btn('Apply mapping decision','data-v161-apply-mapping','button primary')}`,true)}
async function applyMappingV161(){const reqId=$('#v161MapReqId')?.value,mode=$('#v161MapMode')?.value||'reuse',ids=$$('[data-v161-map-test]:checked').map(x=>x.value);if(mode==='combine'&&ids.length<2){toast('Select at least two tests for a combined mapping.',true);return}try{P.mapValidationRequirementV161(App.state,reqId,{mode,testIds:mode==='new'?[]:mode==='combine'?ids:ids.slice(0,1),actor:App.state.identity?.name});P.audit?.(App.state,'Validation requirement mapped','Validation Requirement',reqId,'Not Covered',mode,ids.join(', ')||'New method development');P.syncValidationActionsV161(App.state);await persist();closeModal();render();toast('Controlled mapping decision saved.')}catch(e){toast(e.message,true)}}
