function addValidationLegModalV161(){openModal('Add Validation test leg',`<div class="field"><label>Leg name</label><input id="v161LegName" placeholder="e.g. Environmental durability"></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Add leg','data-v161-save-leg','button primary')}`)}
