function editActivityModalV161(id){const p=validationProgrammeV161(),a=P.validationActivitiesV161(App.state,p.id).find(x=>x.id===id),legs=P.validationLegsV161(App.state,p.id),all=P.validationActivitiesV161(App.state,p.id).filter(x=>x.id!==id);openModal('Validation programme activity',`<div class="form-grid"><div class="field span-2"><label>Name</label><input id="v161ActName" value="${esc(a.name)}"></div><div class="field"><label>Programme leg</label><select id="v161ActLeg">${legs.map(l=>`<option value="${l.id}" ${l.id===a.legId?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Estimated hours</label><input id="v161ActHours" type="number" step="0.25" value="${Number(a.estimatedHours||1)}"></div><div class="field span-2"><label>Predecessors</label><div class="v161-predecessor-list">${all.map(x=>`<label><input type="checkbox" data-v161-pred value="${x.id}" ${(a.predecessorIds||[]).includes(x.id)?'checked':''}> ${esc(x.name)}</label>`).join('')}</div></div></div><input id="v161ActId" type="hidden" value="${a.id}">`,`${btn('Cancel','data-modal-close','button')}${btn('Save activity','data-v161-save-activity','button primary')}`,true)}
async function saveActivityV161(){const a=(App.state.validationActivities||[]).find(x=>x.id===$('#v161ActId')?.value);if(!a)return;a.name=$('#v161ActName')?.value?.trim()||a.name;a.legId=$('#v161ActLeg')?.value||a.legId;a.estimatedHours=Math.max(.25,Number($('#v161ActHours')?.value||a.estimatedHours));a.predecessorIds=$$('[data-v161-pred]:checked').map(x=>x.value);const graph=P.validationGraphCheckV161(App.state,a.programmeId);if(!graph.ok){toast(graph.issues[0],true);return}await persist();closeModal();render();toast('Programme activity updated.')}
