function manualPlanModalV161(){const p=validationProgrammeV161();openModal('Manual planning boundary',`<div class="callout info"><strong>Use the same constrained engine</strong><p>Choose the earliest acceptable start. LabOS searches forward for a feasible slot using equipment readiness, qualifications, calibration, closures and shared Prototype/Validation load.</p></div><div class="field"><label>Earliest allowed start</label><input id="v161ManualStart" type="date" value="${p.planningNotBefore||p.dutAvailableDate||P.todayISO()}"></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Find & commit feasible plan','data-v161-commit-manual','button primary')}`)}
function compareSitesModalV161(){const p=validationProgrammeV161(),rows=P.validationSiteOptionsV161(App.state,p.id);openModal('Lab network recovery',`<div class="callout info"><strong>Home, sister and external recovery boundary</strong><p>Internal laboratories are evaluated with the same constrained planner. A sister-lab option does not bypass equipment, competency or calendar readiness.</p></div><div class="v161-site-options">${rows.map(r=>`<article class="v161-site-option ${r.feasible?'good':'bad'}"><div><strong>${esc(r.name)}</strong><span>${r.feasible?`Forecast ${P.formatDate(r.forecastDate)} · ${r.bookings} bookings`:esc(r.reason||'Not feasible')}</span></div>${r.feasible?btn(r.siteId===p.executionSiteId?'Current lab':'Use this lab',`data-v161-use-site="${r.siteId}"`,'button tiny primary'):''}</article>`).join('')}</div><div class="callout warn"><strong>External laboratory</strong><p>Use the Standard Test external-sourcing evidence (quote/invoice, lead time and cost) when an internal feasible solution cannot meet the programme need. External routing remains tracked separately in KPIs.</p></div>`,btn('Close','data-modal-close','button'),true)}
function recordDevelopmentModalV161(id){const a=(App.state.validationActivities||[]).find(x=>x.id===id);openModal('Record method-development effort',`<div class="callout info"><strong>${esc(a.name)}</strong><p>Original estimate ${a.estimatedHours||'—'} h. The actual is retained for future estimate learning.</p></div><div class="field"><label>Actual development hours</label><input id="v161DevActual" type="number" min="0.25" step="0.25" value="${a.estimatedHours||4}"></div><div class="field"><label>Variance reason</label><textarea id="v161DevReason" rows="3" placeholder="What changed vs the estimate?"></textarea></div><input id="v161DevId" type="hidden" value="${id}">`,`${btn('Cancel','data-modal-close','button')}${btn('Complete development','data-v161-save-development','button primary')}`)}
async function saveDevelopmentV161(){const a=(App.state.validationActivities||[]).find(x=>x.id===$('#v161DevId')?.value),p=validationProgrammeV161();if(!a)return;const actual=Math.max(.25,Number($('#v161DevActual')?.value||0)),reason=$('#v161DevReason')?.value?.trim()||'Completed as planned';a.actualHours=actual;a.status='Complete';App.state.validationDevelopmentHistory=App.state.validationDevelopmentHistory||[];App.state.validationDevelopmentHistory.push({id:P.uid('VDEV'),programmeId:p.id,activityId:a.id,basisTestId:a.basisTestId||null,estimatedHours:Number(a.estimatedHours||0),actualHours:actual,varianceHours:actual-Number(a.estimatedHours||0),reason,completedAt:P.now(),actor:App.state.identity?.name});P.audit?.(App.state,'Validation method development completed','Validation Programme',p.id,`${a.estimatedHours||0} h estimate`,`${actual} h actual`,reason);P.captureValidationLessonsV161?.(App.state,p.id);await persist();closeModal();render();toast('Development actual captured for future learning.')}
function recordResultModalV161(id){const a=(App.state.validationActivities||[]).find(x=>x.id===id),p=validationProgrammeV161();openModal('Record Validation result',`<div class="callout info"><strong>${esc(a.name)}</strong><p>${esc(a.acceptanceCriteria||'Meet the controlled requirement.')}</p></div><div class="form-grid"><div class="field"><label>Outcome</label><select id="v161ResultOutcome"><option>Pass</option><option>Fail</option></select></div><div class="field"><label>Actual hours</label><input id="v161ResultHours" type="number" step="0.25" value="${a.estimatedHours||1}"></div><div class="field span-2"><label>Measured result / summary</label><input id="v161ResultValue" placeholder="Value, range or categorical result"></div><div class="field span-2"><label>Evidence reference</label><input id="v161ResultEvidence" placeholder="File/document/reference ID"></div><div class="field span-2"><label>Comments / deviation</label><textarea id="v161ResultComment" rows="3"></textarea></div></div><input id="v161ResultAct" type="hidden" value="${id}">`,`${btn('Cancel','data-modal-close','button')}${btn('Save controlled result','data-v161-save-result','button primary')}`,true)}
async function saveResultV161(){const act=(App.state.validationActivities||[]).find(x=>x.id===$('#v161ResultAct')?.value),p=validationProgrammeV161();if(!act)return;App.state.validationResults=App.state.validationResults||[];App.state.validationEvidence=App.state.validationEvidence||[];App.state.validationResults=App.state.validationResults.filter(x=>x.activityId!==act.id);const ev=$('#v161ResultEvidence')?.value?.trim(),evidenceIds=[];if(ev){const eid=P.uid('VEV');App.state.validationEvidence.push({id:eid,programmeId:p.id,activityId:act.id,type:'Result evidence',reference:ev,createdAt:P.now(),createdBy:App.state.identity?.name});evidenceIds.push(eid)}const outcome=$('#v161ResultOutcome')?.value||'Pass',actual=Math.max(.1,Number($('#v161ResultHours')?.value||act.estimatedHours||1));App.state.validationResults.push({id:P.uid('VRES'),programmeId:p.id,activityId:act.id,outcome,value:$('#v161ResultValue')?.value?.trim()||'',comment:$('#v161ResultComment')?.value?.trim()||'',evidenceIds,actualHours:actual,equipmentId:act.equipmentId||null,staffId:act.staffId||null,at:P.now(),actor:App.state.identity?.name});act.actualHours=actual;act.status='Complete';P.syncValidationRequirementStatusesV161(App.state,p.id);P.syncValidationActionsV161(App.state);P.audit?.(App.state,'Validation result recorded','Validation Programme',p.id,act.name,outcome,$('#v161ResultComment')?.value?.trim()||'Controlled result');P.captureValidationLessonsV161?.(App.state,p.id);await persist();closeModal();render();toast(`Result saved: ${outcome}.`)}
function previewValidationReportV161(){const p=validationProgrammeV161(),r=P.validationReportV161(App.state,p.id),acts=P.validationActivitiesV161(App.state,p.id);openModal(`${p.id} · Validation Report`, `<div class="v161-report-cover"><span class="eyebrow">LabOS VALIDATION REPORT</span><h1>${esc(p.title)}</h1><p>${esc(r.programme.product)} · Rev ${esc(r.programme.revision)} · Programme ${esc(p.id)}</p><div class="v161-report-meta"><span>Required <b>${P.formatDate(p.requiredDate)}</b></span><span>Generated <b>${P.formatDateTime(r.generatedAt)}</b></span><span>Status <b>${esc(r.status)}</b></span></div></div><div class="card"><h2>Conclusion</h2><p>${esc(r.conclusion)}</p></div><div class="card"><h2>Requirement verification</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Requirement</th><th>Description</th><th>Mapped test</th><th>Status</th></tr></thead><tbody>${r.requirements.map(q=>`<tr><td>${esc(q.id)}</td><td>${esc(q.description)}</td><td>${(q.linkedActivityIds||[]).map(id=>esc(acts.find(a=>a.id===id)?.name||id)).join('<br>')}</td><td>${status(q.status)}</td></tr>`).join('')}</tbody></table></div></div>`,`${btn('Close','data-modal-close','button')}${btn('Generate controlled revision','data-v161-generate-report','button primary')}`,true)}
