async function closeValidationProgrammeV161(){const p=validationProgrammeV161(),wf=P.validationWorkflowStateV161(App.state,p);if(wf.results.length<wf.tests.length){toast('Complete all planned Validation tests first.',true);return}P.captureValidationLessonsV161?.(App.state,p.id);const pending=(App.state.validationLessonCandidates||[]).filter(x=>x.programmeId===p.id&&x.status==='Proposed');if(pending.length){toast(`Review ${pending.length} evidence-based lesson${pending.length===1?'':'s'} before closeout.`,true);App.validationWorkspaceTab='report';render();return}if(wf.failed){const ok=confirm(`${wf.failed} requirement(s) are failed. Close only if the controlled failure/disposition is intentionally retained in the report. Continue?`);if(!ok)return}P.validationReportV161(App.state,p.id,{persist:true});p.status='Closed';p.actualCompletionDate=P.todayISO();p.closedAt=P.now();p.archived=false;P.syncValidationActionsV161(App.state);P.audit?.(App.state,'Validation programme closed','Validation Programme',p.id,'Open','Closed','Controlled Validation closeout with learning review complete');await persist();render();toast('Validation programme closed. Lessons remain available for future Prototype and Validation work.')}
