 function sampleRegisterCard(p){const pool=poolFor(p),withSerial=pool.rows.filter(x=>String(x.serialNumber||'').trim()).length,preview=pool.rows.slice(0,8).map(x=>`<span class="v166-sample-chip"><b>${esc(x.sampleNumber||'')}</b>${esc(x.sampleId||x.refId)}${x.serialNumber?` · SN ${esc(x.serialNumber)}`:''}</span>`).join('');return `<section class="card v166-sample-register"><div class="section-title-row"><div><span class="eyebrow">1 · DEFINE SAMPLES</span><h2>${pool.source==='prototype'?'Samples inherited from linked Prototype':'Validation sample register'}</h2><p class="subtle">Define the physical DUT/sample identities first. Those exact identities then follow the Test Flow and can be narrowed per test.</p></div>${btn(pool.source==='prototype'?'Review linked samples':'Define samples & serials','data-v166-sample-register','button small primary')}</div><div class="v166-sample-register-kpis"><span><b>${pool.rows.length}</b> samples</span><span><b>${withSerial}/${pool.rows.length}</b> formal serials</span><span><b>${pool.source==='prototype'?'Prototype':'Validation'}</b> source</span></div><div class="v166-sample-chip-list">${preview}${pool.rows.length>8?`<span class="pill">+${pool.rows.length-8} more</span>`:''}</div></section>`}
