 v164ActivityCard=function(p,a,pathLabel,seqId,index){ensureActivitySamples(p);const rows=rowsForActivity(p,a),qty=rows.length,dev=a.developmentRequired,match=Number(a.standardMatchPct||0),actual=Number(a.developmentActualHours),estimate=Number(a.developmentEstimateHours),badge=dev?(a.variantOfStandardTestId||a.basisTestId?'Adapt':'Develop'):'Standard',criteria=defaultAcceptanceForActivity(a);a.acceptanceCriteria=criteria;return `<article class="v164-test-card v166-test-card ${dev?'develop':''}" data-v164-activity-card="${esc(a.id)}"><div class="v164-test-top"><span class="v164-drag">⋮⋮</span><span class="v164-test-index">${esc(pathLabel)}</span><span class="v164-test-badge ${dev?'develop':''}">${esc(badge)}</span></div><strong>${esc(a.name)}</strong><small>${esc(v164ActivityLabel(a))} · ${qty} assigned sample${qty===1?'':'s'}</small>${match?`<small>${match}% closest-standard match</small>`:''}${dev?`<div class="v164-dev-line"><b>${actual>0?`${actual}h actual`:`${estimate||'—'}h est.`}</b><span>${esc(a.developmentEstimateConfidenceV165||a.developmentEstimateConfidence||'learning')}</span></div>`:''}<div class="v166-acceptance"><span>ACCEPTANCE CRITERIA</span><strong>${esc(criteria)}</strong><button class="button tiny secondary" data-v166-edit-criteria="${esc(a.id)}">Edit</button></div><div class="v164-sample-pill v166-sample-pill">◇ ${esc(sampleShort(rows,4))}</div><div class="v164-card-actions"><button class="button tiny primary" data-v164-next-test="${esc(a.id)}">＋ Next test</button><button class="button tiny secondary" data-v164-split="${esc(a.id)}">↳ Split</button><button class="button tiny secondary" data-v166-test-samples="${esc(a.id)}">◇ Samples / serials</button><button class="button tiny secondary" data-v164-move="${esc(a.id)}">↕ Move</button><button class="button tiny secondary" data-v164-edit="${esc(a.id)}">Edit</button><button class="button tiny danger" data-v164-delete="${esc(a.id)}">×</button></div></article>`};

 // Designer: sample register comes before the test flow; per-leg defaults remain
