 v164ValidationDesigner=function(p){const flow=v164Flow(p);P.syncValidationFlowV164?.(App.state,p.id);ensureAcceptanceCatalogue();ensureActivitySamples(p);const acts=v164Activities(p),tests=acts.filter(a=>a.kind==='Validation Test'),dev=tests.filter(a=>a.developmentRequired),bookings=(App.state.bookings||[]).filter(b=>b.requestId===p.id&&!P.isHistoricalPlanningBooking?.(b)),pool=poolFor(p),assigned=new Set(tests.flatMap(a=>a.sampleRefsV166||[]));return `<div class="v164-designer v165-validation-designer v166-validation-designer"><div class="v164-designer-head"><div><span class="eyebrow">VALIDATION TEST FLOW DEFINITION</span><h2>${esc(p.title||p.productFamily||p.productId)} · ${p.quantity||0} DUTs</h2><p>Define samples first, then build the physical Test Flow. Every Add Test starts with Standard Test vs Test Development, every test carries explicit acceptance criteria, and exact sample/serial genealogy is visible per test.</p></div><div class="route-toolbar">${btn('＋ Add Test Leg','data-v164-add-leg','button primary')}${btn(bookings.length?'Re-plan':'Plan Validation',`data-v161-tab="planning"`,'button secondary')}</div></div>${sampleRegisterCard(p)}<div class="v164-flow-summary"><div><span>Test legs</span><strong>${flow?.legs?.length||0}</strong></div><div><span>Tests</span><strong>${tests.length}</strong></div><div><span>Development / adaptations</span><strong>${dev.length}</strong></div><div><span>Samples used by tests</span><strong>${assigned.size}/${pool.rows.length}</strong></div><div><span>Shared resource plan</span><strong>${bookings.length?`${bookings.length} bookings`:'Not planned'}</strong></div></div>${v164PreventionPanel('Validation',p,{compact:true})}<div class="v166-flow-heading"><span class="eyebrow">2 · BUILD TEST FLOW</span><strong>Samples now follow the controlled test path</strong></div><div class="v164-flow-board">${(flow?.legs||[]).map((l,i)=>{const a=P.validationLegSamplesV165?.(App.state,p.id,l.id)||{rows:[]};return `<section class="v164-test-leg" data-v164-leg="${esc(l.id)}"><header><div><span>TEST LEG ${i+1}</span><strong>${esc(l.name||`Test Leg ${i+1}`)}</strong><small>${sampleShort(a.rows)} · ${(l.nodes||[]).filter(x=>x.kind==='activity').length} direct test${(l.nodes||[]).filter(x=>x.kind==='activity').length===1?'':'s'}</small></div><div class="v165-leg-head-actions">${btn('Leg sample default',`data-v165-leg-samples="${esc(l.id)}"`,'button tiny secondary')}<button class="button tiny secondary" data-v164-rename-leg="${esc(l.id)}">Rename</button></div></header><div class="v164-leg-track">${v164SequenceHtml(p,l,l.nodes||[],l.sequenceId,String(i+1))}<button class="v164-add-test dashed" data-v164-add-test="1" data-v164-sequence="${esc(l.sequenceId)}">＋ Add Test to Test Leg ${i+1}<small>Choose Standard Test or Test Development</small></button></div></section>`}).join('')}<button class="v164-add-leg-card" data-v164-add-leg><strong>＋ Add Test Leg ${(flow?.legs?.length||0)+1}</strong><small>Start another independent DUT test path</small></button></div><div class="v164-designer-foot good"><div><strong>Test Flow → Resource Plan</strong><span>Each test now has controlled acceptance criteria and exact sample/serial genealogy.</span></div>${btn('Continue to Planning →','data-v161-tab="planning"','button small primary')}</div></div>`};

 // ----- Add Test starts with the requested binary choice -----
 function chooseTestModeModal(sequenceId,index=null){const p=validationProgrammeV161(),pool=p?poolFor(p):{rows:[]};App._v164Pending={sequenceId,index};openModal('Add Test',`<div class="resolution-focus"><span class="eyebrow">ADD TEST</span><h2>Standard Test or Test Development?</h2><p>${pool.rows.length} defined sample${pool.rows.length===1?'':'s'} will follow into the new test by default. You can narrow the exact samples after adding it.</p></div><div class="v166-add-test-choice"><button class="v166-choice-card standard" data-v166-add-mode="standard"><span>STANDARD TEST</span><strong>Use released Test Library</strong><small>Choose an approved method and confirm its acceptance criteria.</small></button><button class="v166-choice-card develop" data-v166-add-mode="develop"><span>TEST DEVELOPMENT</span><strong>Develop or adapt a test</strong><small>LabOS checks the closest released method and applies the learned development estimate.</small></button></div>`,btn('Cancel','data-modal-close','button secondary'),true)}
