 function standardTestPicker(){ensureAcceptanceCatalogue();const tests=(App.state.standardTests||[]).filter(t=>t.status==='Released');openModal('Choose released Standard Test',`<div class="field"><label>Search Test Library</label><input id="v166StandardSearch" type="search" placeholder="Name, ID, capability…"></div><div class="v166-standard-list" id="v166StandardList">${tests.map(t=>`<button class="v166-standard-row" data-v166-standard="${esc(t.id)}" data-v166-search="${esc(`${t.id} ${t.name} ${t.equipmentCapability||''}`.toLowerCase())}"><div><span>${esc(t.id)} · Rev ${esc(t.revision||'—')}</span><strong>${esc(t.name)}</strong><small>${esc(t.equipmentCapability||'')} · ${esc(App.state.competencies?.find(c=>c.id===t.competency)?.name||t.competency||'')}</small><em>Acceptance: ${esc(standardAcceptance(t))}</em></div><b>Use →</b></button>`).join('')||'<div class="empty">No released Standard Tests.</div>'}</div>`,`${btn('Back','data-v166-add-back','button secondary')}`,true);setTimeout(()=>{$('#v166StandardSearch')?.addEventListener('input',e=>{const q=String(e.target.value||'').trim().toLowerCase();$$('[data-v166-standard]').forEach(x=>x.hidden=!!q&&!String(x.dataset.v166Search||'').includes(q))})},0)}
 function standardConfirm(testId){const t=(App.state.standardTests||[]).find(x=>x.id===testId);if(!t)return;App._v166StandardId=testId;openModal(`Add Standard Test · ${t.id}`,`<div class="callout reuse-good"><strong>${esc(t.name)}</strong><p>Released Rev ${esc(t.revision||'—')} · ${esc(t.equipmentCapability||'')} · ${esc(App.state.competencies?.find(c=>c.id===t.competency)?.name||t.competency||'')}</p></div><div class="field"><label>Acceptance criteria <b>· required</b></label><textarea id="v166Acceptance" rows="4">${esc(standardAcceptance(t))}</textarea><small>Copied from the released method and stored on this programme test for clear execution/reporting.</small></div>`,`${btn('Back','data-v166-mode-standard','button secondary')}${btn('Add Standard Test','data-v166-confirm-standard','button primary')}`,true)}
