  async function submitValidationReportV169(){const p=validationProgrammeV161(),a=P.validationReportApprovalV169(App.state,p.id),ready=P.validationTechnicalRecordReadinessV169(App.state,p.id),report=P.validationReportV161(App.state,p.id);if(!ready.ready||report.results.length<report.activities.filter(x=>x.kind==='Validation Test').length){toast('Complete technical records and controlled failure disposition before report approval.',true);return}a.status='Pending';a.requestedAt=P.now();a.requestedBy=App.state.identity.name;a.revision=p.reportRevision||a.revision||'A';a.comment='Controlled Validation report review requested.';P.audit(App.state,'Validation report submitted for approval','Validation Programme',p.id,'Draft','Pending',`Rev ${a.revision} · part ${report.programme.partNumber}`);await persist();render();toast(`Validation Report Rev ${a.revision} submitted for Quality approval.`)}
  async function approveValidationReportV169(){const p=validationProgrammeV161(),a=P.validationReportApprovalV169(App.state,p.id),ready=P.validationTechnicalRecordReadinessV169(App.state,p.id);if(!['quality','lab_manager','administrator'].includes(currentRole())){toast('Quality Engineer, Lab Manager or Administrator approval is required.',true);return}if(a.status!=='Pending'){toast('Submit the Validation Report for approval first.',true);return}if(!ready.ready){toast('Technical-record gaps must be resolved before approval.',true);return}a.status='Approved';a.approvedAt=P.now();a.approvedBy=App.state.identity.name;a.person=App.state.identity.name;a.revision=p.reportRevision||a.revision||'A';a.evidenceFingerprint=P.validationEvidenceFingerprintV169(App.state,p.id);a.comment='Validation technical record reviewed against current controlled evidence and approved.';P.validationReportV161(App.state,p.id,{persist:true});P.audit(App.state,'Validation report approved & made final','Validation Programme',p.id,'Pending','Approved',`${a.approvedBy} · Rev ${a.revision} · evidence ${a.evidenceFingerprint}`);await persist();render();toast(`Validation Report Rev ${a.revision} approved and made FINAL.`)}

