/* ============================================================
   LabOS REV 1.0.171 — direct Validation report launch repair.
   Reports-page buttons no longer depend on workspace-tab routing.
   ============================================================ */
(function installV170ValidationReportLauncher(){
  const _renderReportsV170Base=renderReports;
  renderReports=function(){
    return _renderReportsV170Base().replace(/data-open-validation="([^"]+)" data-validation-tab="report"/g,'data-v170-open-validation-report="$1"');
  };

  function openValidationReportV170(id){
    const p=(App.state.validationProgrammes||[]).find(x=>x.id===id);
    if(!p){toast(`Validation programme ${id} was not found.`,true);return false}
    App.validationWorkspaceId=id;
    App.validationWorkspaceTab='report';
    try{
      previewValidationReportV161();
      return true;
    }catch(err){
      console.error('Validation report open failed',id,err);
      toast(`Could not open Validation Report for ${id}: ${err?.message||err}`,true);
      return false;
    }
  }

  document.addEventListener('click',e=>{
    const t=e.target.closest?.('[data-v170-open-validation-report]');
    if(!t)return;
    e.preventDefault();
    e.stopImmediatePropagation();
    openValidationReportV170(t.dataset.v170OpenValidationReport);
  },true);

  window.__LABOS_V170_TEST__={
    reportButtons:()=>{const html=renderReports();return {direct:(html.match(/data-v170-open-validation-report=/g)||[]).length,legacyReportRoute:(html.match(/data-open-validation="[^"]+" data-validation-tab="report"/g)||[]).length}},
    openValidationReport:id=>openValidationReportV170(id)
  };
})();


