  function reportFooterButtons(p,report){const a=P.validationReportApprovalV169?.(App.state,p.id)||{},ready=report.technicalRecordReadiness||P.validationTechnicalRecordReadinessV169?.(App.state,p.id),tests=(report.activities||[]).filter(x=>x.kind==='Validation Test'),complete=tests.length>0&&tests.every(t=>(report.results||[]).some(r=>r.activityId===t.id)),canApprove=['quality','lab_manager','administrator'].includes(currentRole());let ctl='';if(a.status==='Approved'&&a.evidenceFingerprint===report.evidenceFingerprint)ctl=`<span class="pill good">FINAL · Approved by ${esc(a.approvedBy||a.person||'Quality')}</span>`;else if(!complete||!ready?.ready)ctl=`<span class="pill warn">Approval blocked · ${!complete?'execution incomplete':'technical-record gaps'}</span>`;else if(a.status==='Pending')ctl=canApprove?btn('Approve & make FINAL','data-v169-approve-validation-report','button primary'):`<span class="pill warn">Awaiting ${esc(a.person||'Quality Engineer')}</span>`;else ctl=btn('Submit for approval','data-v169-submit-validation-report','button primary');return `${btn('Close','data-modal-close','button')}${btn('Print / Save PDF','data-v169-print-validation-report','button secondary')}${ctl}`}
