  const q=norm(App.filters.validationSearch),archive=App.filters.validationArchive||'active',product=App.filters.validationProduct||'',project=App.filters.validationProject||'',owner=App.filters.validationOwner||'',lab=App.filters.validationLab||'',from=App.filters.validationFrom||'',to=App.filters.validationTo||'',sortBy=App.filters.validationSort||'required-asc',all=App.state.validationProgrammes||[],projects=[...new Set(all.map(x=>x.project||x.programme||x.businessUnit).filter(Boolean))].sort(),owners=[...new Set(all.map(x=>x.owner).filter(Boolean))].sort(),labs=(App.state.labs||[]).filter(x=>x.active!==false&&x.type!=='external'),isArchived=p=>!!(p.archived||['closed','complete','completed','archived'].includes(norm(p.status)));
