function renderPlanTiles(metrics){const defs=[['all','Open work',metrics.all,'All open programmes'],['booked','With bookings',metrics.booked,'Only programmes with live bookings'],['validation','Validation planned',metrics.validation,'Only planned Validation programmes'],['situations','Active situations',metrics.situations,'Only lanes intersecting an active planning constraint'],['late','Forecast late',metrics.late,'Only programmes forecast after the requested date'],['commitment','Commitment movement',metrics.commitment,'Only programmes with commitment/dependency movement']];return `<div class="metrics-grid canonical-plan-tiles">${defs.map(([id,label,value,desc])=>`<button type="button" class="card metric metric-action ${App.filters.planFilter===id||(!App.filters.planFilter&&id==='all')?'active':''}" data-plan-filter="${id}"><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div><div class="trend">${esc(desc)}</div></button>`).join('')}</div>`}
function timelineRange(rows,weeks){const today=weekStart(new Date()),bs=(App.state.bookings||[]).filter(b=>rows.some(r=>r.id===b.requestId)&&!P.isHistoricalPlanningBooking?.(b)),earliest=bs.length?new Date(Math.min(...bs.map(b=>+new Date(b.start)))):today,start=weekStart(earliest<today?earliest:today),days=Math.max(14,weeks*7),end=addDays(start,days);return {start,end,days}}
